-- Generated by scripts/catalogue-sql.mjs from content/*.json. Do not edit by hand.
-- 1500 questions in 15 events.
insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'accounting', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"acc-001","sub":"Foundations of Accounting","diff":1,"q":"Under the accounting equation, which expression is correct?","choices":["Assets = Liabilities + Owner''s Equity","Assets = Liabilities - Owner''s Equity","Assets + Liabilities = Owner''s Equity","Liabilities = Assets + Owner''s Equity"],"answer":0,"explain":"Assets equal liabilities plus owner equity; the other forms rearrange the terms incorrectly."},{"id":"acc-002","sub":"Foundations of Accounting","diff":1,"q":"What is the normal balance of the Unearned Revenue account?","choices":["Debit","Credit","Either debit or credit","It has no normal balance"],"answer":1,"explain":"Unearned Revenue is a liability, and liabilities increase with credits."},{"id":"acc-003","sub":"Foundations of Accounting","diff":1,"q":"A company pays $1,200 cash for one month of rent already used. Which effect is correct?","choices":["Assets rise $1,200 and equity rises $1,200","Liabilities rise $1,200 and equity falls $1,200","Assets fall $1,200 and equity falls $1,200 through rent expense","Assets and equity both rise $1,200"],"answer":2,"explain":"Cash goes down and an expense reduces equity, so the equation stays balanced."},{"id":"acc-004","sub":"Foundations of Accounting","diff":1,"q":"Under the accrual basis of accounting, when are revenues recognized?","choices":["Only when cash is received","When the customer is invoiced at year-end only","At the start of the next fiscal year","When earned, regardless of when cash is received"],"answer":3,"explain":"Accrual accounting records revenue when earned, not when cash moves."},{"id":"acc-005","sub":"Foundations of Accounting","diff":3,"q":"A company records a December sale and pays the related sales commission in January. Under the matching principle, when is the commission expense recorded?","choices":["December, in the same period as the related sale","January, when it is paid","The following year, when the contract ends","Never, because it is a cash payment"],"answer":0,"explain":"Expenses are matched to the revenue they helped produce, so the commission falls in December."},{"id":"acc-006","sub":"Foundations of Accounting","diff":2,"q":"Which assumption supports reporting long-term equipment at historical cost less accumulated depreciation rather than at liquidation value?","choices":["Monetary unit assumption","Going concern assumption","Economic entity assumption","Conservatism"],"answer":1,"explain":"The going concern assumption says the business will keep operating, so asset values are not forced to liquidation values."},{"id":"acc-007","sub":"Foundations of Accounting","diff":1,"q":"A $40 office supply purchase is expensed immediately rather than capitalized. Which concept best justifies this?","choices":["Full disclosure","Consistency","Materiality","Substance over form"],"answer":2,"explain":"Immaterial amounts may be expensed for convenience without affecting decisions."},{"id":"acc-008","sub":"Foundations of Accounting","diff":3,"q":"A trial balance has total debits of $85,400 and total credits of $85,400. Which conclusion is correct?","choices":["Equal totals prove all transactions were recorded correctly","The balance sheet must be out of balance","Totals must equal zero to be valid","Equal totals do not prove every entry is correct, since some errors leave the totals balanced"],"answer":3,"explain":"A trial balance catches some errors, but omitted entries and wrong-account postings still balance."},{"id":"acc-009","sub":"Foundations of Accounting","diff":1,"q":"Which account is a contra-asset?","choices":["Accumulated Depreciation","Depreciation Expense","Sales Returns and Allowances","Dividends Payable"],"answer":0,"explain":"A contra-asset reduces a related asset account and carries a credit balance."},{"id":"acc-010","sub":"Foundations of Accounting","diff":2,"q":"Land is bought for $300,000, with a $25,000 title search and a $5,000 legal fee to acquire it. What is the recorded cost of the land under U.S. GAAP?","choices":["$300,000","$325,000","$305,000","$330,000"],"answer":3,"explain":"All costs necessary to get the land ready for use are capitalized: $300,000 + $25,000 + $5,000 = $330,000."},{"id":"acc-011","sub":"Foundations of Accounting","diff":1,"q":"Which document is the best source for recording a credit sale?","choices":["Purchase order","Bank statement","Sales invoice","Packing slip"],"answer":2,"explain":"The sales invoice documents the sale and the amount owed on account."},{"id":"acc-012","sub":"Foundations of Accounting","diff":3,"q":"A sole proprietor owns a home that is not used in the business. Under the economic entity assumption, how is the home treated in the business accounts?","choices":["Recorded as a business asset","Included as owner''s equity","Recorded as a liability of the business","Excluded from the business books"],"answer":3,"explain":"Personal assets are kept separate from the business entity."},{"id":"acc-013","sub":"Foundations of Accounting","diff":2,"q":"At year-end, employees have earned $6,000 of wages that are unpaid. Which adjusting entry is needed?","choices":["Debit Wages Expense $6,000; credit Wages Payable $6,000","Debit Cash $6,000; credit Wages Expense $6,000","Debit Wages Payable $6,000; credit Cash $6,000","Debit Wages Expense $6,000; credit Cash $6,000"],"answer":0,"explain":"The expense belongs to this period and the unpaid amount is a liability."},{"id":"acc-014","sub":"Foundations of Accounting","diff":3,"q":"A 12-month insurance premium is paid in advance. Which treatment is correct under accrual accounting?","choices":["Expense the full premium at payment","Record a prepaid asset at payment and expense one-twelfth each month","Record revenue when the premium is paid","Defer the premium until the policy expires"],"answer":1,"explain":"The prepaid asset is consumed monthly as coverage is used."},{"id":"acc-015","sub":"Standards and Compliance","diff":2,"q":"Which body establishes U.S. GAAP for private and public companies?","choices":["Internal Revenue Service","Federal Reserve Board","Financial Accounting Standards Board","Government Accountability Office"],"answer":2,"explain":"The FASB issues the Accounting Standards Codification that forms U.S. GAAP."},{"id":"acc-016","sub":"Standards and Compliance","diff":2,"q":"Which federal law created the SEC and set up periodic reporting by companies with registered securities?","choices":["Securities Act of 1933","Sarbanes-Oxley Act of 2002","Dodd-Frank Act of 2010","Securities Exchange Act of 1934"],"answer":3,"explain":"The 1933 Act governs initial registration; the 1934 Act created the SEC and ongoing reporting."},{"id":"acc-017","sub":"Standards and Compliance","diff":1,"q":"Under Sarbanes-Oxley, which officers must certify the accuracy of periodic financial reports?","choices":["The CEO and CFO","Internal auditors only","The audit committee only","The external auditor"],"answer":0,"explain":"SOX Section 302 requires the CEO and CFO to certify periodic reports."},{"id":"acc-018","sub":"Standards and Compliance","diff":2,"q":"Which professional body issues the Code of Professional Conduct for U.S. CPAs?","choices":["FASB","AICPA","GASB","PCAOB"],"answer":1,"explain":"The AICPA sets ethical standards for its CPA members."},{"id":"acc-019","sub":"Standards and Compliance","diff":2,"q":"Which body was created by Sarbanes-Oxley to oversee audits of public companies?","choices":["AICPA Auditing Standards Board","Internal Revenue Service","PCAOB","International Accounting Standards Board"],"answer":2,"explain":"The Public Company Accounting Oversight Board was created by SOX in 2002."},{"id":"acc-020","sub":"Standards and Compliance","diff":3,"q":"Which statement about inventory costing is accurate?","choices":["IFRS permits LIFO, while U.S. GAAP prohibits it","Both U.S. GAAP and IFRS permit LIFO","Neither U.S. GAAP nor IFRS permits FIFO","U.S. GAAP permits LIFO, while IFRS prohibits it"],"answer":3,"explain":"LIFO is allowed under U.S. GAAP but not under IFRS, a common exam comparison."},{"id":"acc-021","sub":"Standards and Compliance","diff":1,"q":"Which principle requires a company to use the same accounting methods from period to period unless a change is disclosed?","choices":["Consistency","Conservatism","Relevance","Timeliness"],"answer":0,"explain":"Consistency makes statements comparable across periods."},{"id":"acc-022","sub":"Standards and Compliance","diff":2,"q":"Which statement reflects a core independence requirement for auditors?","choices":["Auditors may take contingent fees on all attest work","Auditors must be independent in fact and in appearance","Client confidentiality may be breached for personal gain","Objectivity applies only to internal accountants"],"answer":1,"explain":"Auditors must be independent in fact and appearance to keep the opinion credible."},{"id":"acc-023","sub":"Standards and Compliance","diff":2,"q":"What is the purpose of an external audit opinion?","choices":["To guarantee the company will remain solvent","To determine the company''s income tax liability","To give reasonable assurance that statements are free of material misstatement and fairly presented under GAAP","To set the next year''s operating budget"],"answer":2,"explain":"An audit gives reasonable, not absolute, assurance about the financial statements."},{"id":"acc-024","sub":"Standards and Compliance","diff":3,"q":"Which Sarbanes-Oxley section requires management to assess and report on the effectiveness of internal control over financial reporting?","choices":["Section 302","Section 802","Section 906","Section 404"],"answer":3,"explain":"Section 404 covers management assessment of internal control; 302 covers officer certification."},{"id":"acc-025","sub":"Standards and Compliance","diff":1,"q":"Which SEC form is the annual report that public U.S. companies file with audited financial statements?","choices":["Form 10-K","Form 10-Q","Form 8-K","Form S-1"],"answer":0,"explain":"The 10-K is the annual report; 10-Q is quarterly and 8-K reports events."},{"id":"acc-026","sub":"Standards and Compliance","diff":2,"q":"A CPA finds a material error in a client financial statement. What does professional ethics require?","choices":["Delay disclosure until the next audit","Not knowingly associate with materially false statements and seek correction","Issue an unqualified opinion to avoid conflict","Wait for a regulator to find the error first"],"answer":1,"explain":"A CPA must not knowingly be associated with false financial information."},{"id":"acc-027","sub":"The Accounting Cycle","diff":2,"q":"Which book records transactions in chronological order before they are posted to the ledger?","choices":["General ledger","Trial balance","General journal","Income statement"],"answer":2,"explain":"The journal is the book of original entry; the ledger holds the posted account balances."},{"id":"acc-028","sub":"The Accounting Cycle","diff":2,"q":"The owner invests $20,000 cash in the business. Which journal entry is correct?","choices":["Debit Owner''s Capital $20,000; credit Cash $20,000","Debit Cash $20,000; credit Sales Revenue $20,000","Debit Owner''s Drawings $20,000; credit Cash $20,000","Debit Cash $20,000; credit Owner''s Capital $20,000"],"answer":3,"explain":"Cash increases (debit) and owner equity increases (credit)."},{"id":"acc-029","sub":"The Accounting Cycle","diff":2,"q":"A business buys $3,500 of supplies on account. Which entry is correct?","choices":["Debit Supplies $3,500; credit Accounts Payable $3,500","Debit Cash $3,500; credit Supplies $3,500","Debit Supplies Expense $3,500; credit Cash $3,500","Debit Accounts Payable $3,500; credit Supplies $3,500"],"answer":0,"explain":"Supplies are an asset until used, and the unpaid bill is a liability."},{"id":"acc-030","sub":"The Accounting Cycle","diff":2,"q":"Which account is closed directly to Retained Earnings at year-end, rather than through Income Summary?","choices":["Sales Revenue","Dividends Declared","Interest Expense","Unearned Revenue"],"answer":1,"explain":"Dividends are not revenue or expense, so they close straight to Retained Earnings."},{"id":"acc-031","sub":"The Accounting Cycle","diff":3,"q":"A bank statement shows $12,400. Deposits in transit total $1,800 and outstanding checks total $2,300. What is the adjusted bank balance?","choices":["$12,500","$10,600","$11,900","$16,500"],"answer":2,"explain":"$12,400 + $1,800 - $2,300 = $11,900."},{"id":"acc-032","sub":"The Accounting Cycle","diff":2,"q":"A customer pays $900 on account. Which entry is correct?","choices":["Debit Accounts Receivable $900; credit Cash $900","Debit Cash $900; credit Sales Revenue $900","Debit Accounts Payable $900; credit Cash $900","Debit Cash $900; credit Accounts Receivable $900"],"answer":3,"explain":"Collecting a receivable increases cash and reduces the receivable."},{"id":"acc-033","sub":"The Accounting Cycle","diff":2,"q":"Equipment costing $60,000 has a 5-year life, no salvage value, and straight-line depreciation. What is annual depreciation expense?","choices":["$12,000","$6,000","$10,000","$15,000"],"answer":0,"explain":"$60,000 divided by 5 years equals $12,000 per year."},{"id":"acc-034","sub":"The Accounting Cycle","diff":2,"q":"The same equipment (cost $60,000, 5-year life, straight-line, no salvage) has been depreciated for two full years. What is its net book value?","choices":["$12,000","$36,000","$24,000","$48,000"],"answer":1,"explain":"Accumulated depreciation is $24,000, so $60,000 less $24,000 leaves $36,000."},{"id":"acc-035","sub":"The Accounting Cycle","diff":3,"q":"A company receives $3,600 in advance for 12 months of service beginning October 1. How much revenue is earned by December 31?","choices":["$300","$2,700","$900","$3,600"],"answer":2,"explain":"Three of the twelve months have passed: $3,600 times 3/12 is $900."},{"id":"acc-036","sub":"The Accounting Cycle","diff":3,"q":"Beginning inventory is $15,000, purchases are $62,000, and ending inventory is $18,000. What is cost of goods sold?","choices":["$65,000","$77,000","$80,000","$59,000"],"answer":3,"explain":"$15,000 + $62,000 - $18,000 = $59,000."},{"id":"acc-037","sub":"The Accounting Cycle","diff":3,"q":"A prepaid rent asset has been partly used up. Which adjusting entry is needed for the used portion?","choices":["Debit Rent Expense; credit Prepaid Rent for the portion used","Debit Prepaid Rent; credit Rent Expense","Debit Cash; credit Prepaid Rent","Debit Rent Payable; credit Prepaid Rent"],"answer":0,"explain":"The used portion moves from an asset to an expense."},{"id":"acc-038","sub":"The Accounting Cycle","diff":3,"q":"A $450 utility payment was recorded as $540 (debit Utilities Expense, credit Cash). Which correcting entry is needed?","choices":["Debit Utilities Expense $90; credit Cash $90","Debit Cash $90; credit Utilities Expense $90","Debit Cash $540; credit Utilities Expense $540","Debit Utilities Expense $450; credit Cash $450"],"answer":1,"explain":"Expense was overstated by $90, so reverse that excess: cash and expense each reduced."},{"id":"acc-039","sub":"The Accounting Cycle","diff":2,"q":"In the usual order of preparation, which financial statement is prepared first?","choices":["Balance sheet","Statement of cash flows","Income statement","Statement of retained earnings"],"answer":2,"explain":"Net income from the income statement feeds the retained earnings statement and balance sheet."},{"id":"acc-040","sub":"The Accounting Cycle","diff":1,"q":"Which account will appear on the post-closing trial balance?","choices":["Sales Revenue","Salaries Expense","Income Summary","Accounts Payable"],"answer":3,"explain":"Only permanent (balance sheet) accounts remain after closing."},{"id":"acc-041","sub":"The Accounting Cycle","diff":2,"q":"Merchandise that cost $1,400 is sold. Which entry records the cost of goods sold under the perpetual inventory system?","choices":["Debit Cost of Goods Sold $1,400; credit Merchandise Inventory $1,400","Debit Merchandise Inventory $1,400; credit Cost of Goods Sold $1,400","Debit Sales $1,400; credit Cost of Goods Sold $1,400","Debit Cost of Goods Sold $1,400; credit Accounts Payable $1,400"],"answer":0,"explain":"The cost leaves inventory and becomes an expense at the time of sale."},{"id":"acc-042","sub":"The Accounting Cycle","diff":2,"q":"A company has revenues of $90,000 and expenses of $72,000 for the year. What does the closing entry do to Retained Earnings?","choices":["$18,000 debit to Retained Earnings","$18,000 credit to Retained Earnings","$162,000 debit to Retained Earnings","$72,000 credit to Retained Earnings"],"answer":1,"explain":"Net income of $18,000 increases Retained Earnings with a credit."},{"id":"acc-043","sub":"The Accounting Cycle","diff":2,"q":"A $50,000 note bears 6% annual interest, and four months of interest is unpaid at year-end. What is the accrued interest?","choices":["$500","$3,000","$1,000","$6,000"],"answer":2,"explain":"$50,000 times 6% times 4/12 equals $1,000."},{"id":"acc-044","sub":"The Accounting Cycle","diff":3,"q":"Accounts receivable are $200,000. The allowance has a $1,500 credit balance before adjustment, and $9,000 is estimated uncollectible. What is bad debt expense?","choices":["$1,500","$9,000","$10,500","$7,500"],"answer":3,"explain":"The allowance must go from $1,500 to $9,000, so $7,500 is expensed."},{"id":"acc-045","sub":"The Accounting Cycle","diff":2,"q":"A $10,000 credit sale has terms 2/10, n/30, and the customer pays within the discount period. What cash is received?","choices":["$9,800","$10,000","$9,500","$8,000"],"answer":0,"explain":"A 2% discount on $10,000 is $200, leaving $9,800."},{"id":"acc-046","sub":"The Accounting Cycle","diff":1,"q":"Which account is debited when equipment is purchased for cash?","choices":["Cash","Equipment","Depreciation Expense","Accumulated Depreciation"],"answer":1,"explain":"The asset increases by debit; cash is the account credited."},{"id":"acc-047","sub":"Accounts Payable and Receivable","diff":1,"q":"Under the allowance method, which entry records estimated bad debts at year-end?","choices":["Debit Accounts Receivable; credit Bad Debt Expense","Debit Cash; credit Bad Debt Expense","Debit Bad Debt Expense; credit Allowance for Doubtful Accounts","Debit Allowance for Doubtful Accounts; credit Cash"],"answer":2,"explain":"The estimate is expensed in the same period as the sale, with a contra-asset credit."},{"id":"acc-048","sub":"Accounts Payable and Receivable","diff":1,"q":"Which of the following is a current liability?","choices":["Notes Payable due in 18 months","Bonds Payable due in 10 years","Mortgage Payable due in 20 years","Accounts Payable due in 30 days"],"answer":3,"explain":"Current liabilities are due within one year or the operating cycle."},{"id":"acc-049","sub":"Accounts Payable and Receivable","diff":2,"q":"Which best describes the aging of accounts receivable method?","choices":["Estimates bad debts based on the age of each receivable balance","Estimates bad debts as a percentage of credit sales","Writes off accounts only when a customer declares bankruptcy","Records bad debts only when cash is collected"],"answer":0,"explain":"Older balances are assumed to be less collectible, so a higher percentage is applied to them."},{"id":"acc-050","sub":"Accounts Payable and Receivable","diff":3,"q":"Under the direct write-off method, which statement is true?","choices":["Expenses are matched to revenue of the same period","Bad debts are expensed when a specific account is deemed uncollectible","An allowance account is always required","Receivables are reported at net realizable value"],"answer":1,"explain":"Direct write-off is simple but does not match expense to revenue, so it is not GAAP for most companies."},{"id":"acc-051","sub":"Accounts Payable and Receivable","diff":2,"q":"A $12,000, six-month note bears 8% annual interest. What interest is due at maturity?","choices":["$240","$960","$480","$120"],"answer":2,"explain":"$12,000 times 8% times 6/12 equals $480."},{"id":"acc-052","sub":"Accounts Payable and Receivable","diff":3,"q":"Merchandise costs $5,000 on terms 2/10, n/30. Under the net method, the bill is paid within the discount period. What cash is paid?","choices":["$5,000","$4,000","$100","$4,900"],"answer":3,"explain":"Under the net method the purchase is recorded net of the 2% discount: $5,000 less $100."},{"id":"acc-053","sub":"Accounts Payable and Receivable","diff":3,"q":"Net credit sales are $600,000 and average accounts receivable are $75,000. What is receivables turnover?","choices":["8.0","0.13","4.0","12.5"],"answer":0,"explain":"$600,000 divided by $75,000 equals 8.0 times."},{"id":"acc-054","sub":"Accounts Payable and Receivable","diff":3,"q":"Receivables turnover is 8.0 times on a 365-day year. What is the average collection period?","choices":["8.0 days","45.6 days","30.4 days","73.0 days"],"answer":1,"explain":"365 divided by 8.0 is about 45.6 days."},{"id":"acc-055","sub":"Accounts Payable and Receivable","diff":1,"q":"Which document confirms that goods received match the purchase order before a vendor invoice is paid?","choices":["Remittance advice","Credit memo","Receiving report","Statement of account"],"answer":2,"explain":"The receiving report is part of the three-way match used before payment."},{"id":"acc-056","sub":"Accounts Payable and Receivable","diff":1,"q":"A customer returns goods for $300 credit on account. Which entry is correct?","choices":["Debit Accounts Receivable $300; credit Sales Returns and Allowances $300","Debit Cash $300; credit Sales Returns and Allowances $300","Debit Sales Returns and Allowances $300; credit Cash $300","Debit Sales Returns and Allowances $300; credit Accounts Receivable $300"],"answer":3,"explain":"Returns reduce sales and reduce the amount the customer owes."},{"id":"acc-057","sub":"Accounts Payable and Receivable","diff":3,"q":"The allowance has a $2,000 debit balance before adjustment, and an $11,000 credit balance is needed. What is bad debt expense?","choices":["$13,000","$9,000","$11,000","$2,000"],"answer":0,"explain":"The adjustment must move the allowance by $13,000 from a debit to a $11,000 credit."},{"id":"acc-058","sub":"Accounts Payable and Receivable","diff":3,"q":"Under the allowance method, a $800 receivable is written off against the allowance. What is the effect on net realizable value?","choices":["Net realizable value decreases by $800","Net realizable value is unchanged","Net realizable value increases by $800","Net realizable value decreases by $5,000"],"answer":1,"explain":"The write-off reduces both gross receivables and the allowance by the same amount."},{"id":"acc-059","sub":"Accounts Payable and Receivable","diff":2,"q":"What is a trade discount?","choices":["A reduction for early payment, recorded as a sales discount","A refund for damaged goods","A reduction from list price offered to a class of buyers, not recorded in the accounts","Interest charged on a late payment"],"answer":2,"explain":"Trade discounts are netted into the price and never appear as separate accounts."},{"id":"acc-060","sub":"Accounts Payable and Receivable","diff":3,"q":"Accounts payable are $48,000 before $6,000 of invoices for goods received before year-end are recorded. What should accounts payable be?","choices":["$48,000","$42,000","$6,000","$54,000"],"answer":3,"explain":"Unrecorded liabilities for goods received before year-end must be accrued."},{"id":"acc-061","sub":"Accounts Payable and Receivable","diff":1,"q":"Which of the following is a current asset?","choices":["Accounts Receivable due in 60 days","Land held for future use","Patent","Long-term investments"],"answer":0,"explain":"Receivables due within a year or the operating cycle are current assets."},{"id":"acc-062","sub":"Accounts Payable and Receivable","diff":2,"q":"Accounts receivable total $150,000 and the allowance is $12,000. What is net realizable value?","choices":["$162,000","$138,000","$150,000","$12,000"],"answer":1,"explain":"$150,000 less $12,000 equals $138,000."},{"id":"acc-063","sub":"Tax Accounting","diff":1,"q":"Which form does a sole proprietor use to report business income and expenses?","choices":["Form 1120","Form 1065","Schedule C (Form 1040)","Form 941"],"answer":2,"explain":"Sole proprietors report business profit or loss on Schedule C attached to the personal return."},{"id":"acc-064","sub":"Tax Accounting","diff":1,"q":"Which form is the quarterly federal return reporting income tax withheld and FICA taxes?","choices":["Form W-2","Form 940","Form W-4","Form 941"],"answer":3,"explain":"Form 941 is the employer quarterly return; W-2 is annual and 940 is for FUTA."},{"id":"acc-065","sub":"Tax Accounting","diff":1,"q":"Which federal return does a C corporation file?","choices":["Form 1120","Form 1065","Form 1120-S","Form 1040"],"answer":0,"explain":"C corporations file Form 1120; partnerships file 1065 and S corporations file 1120-S."},{"id":"acc-066","sub":"Tax Accounting","diff":1,"q":"Which payroll tax does the employer pay that matches the employee Social Security and Medicare contribution?","choices":["Federal income tax withholding","Employer FICA contribution","Sales tax","Excise tax"],"answer":1,"explain":"Employers match the employee share of FICA."},{"id":"acc-067","sub":"Tax Accounting","diff":1,"q":"Which form reports each employee annual wages and tax withholdings?","choices":["Form W-4","Form 1099-NEC","Form W-2","Form 941"],"answer":2,"explain":"The W-2 is issued to each employee and filed with the Social Security Administration."},{"id":"acc-068","sub":"Tax Accounting","diff":3,"q":"Straight-line book depreciation differs from MACRS tax depreciation. How is this difference classified in the accounts?","choices":["Permanent difference that is never reversed","No difference, since both methods total the same","Deferred tax asset always","Temporary difference that creates a deferred tax liability"],"answer":3,"explain":"Accelerated tax depreciation early on creates a deferred tax liability that reverses over time."},{"id":"acc-069","sub":"Tax Accounting","diff":1,"q":"A store sells $800 of merchandise subject to 7% sales tax. What total does the customer pay?","choices":["$856","$824","$872","$807"],"answer":0,"explain":"$800 times 1.07 equals $856."},{"id":"acc-070","sub":"Tax Accounting","diff":3,"q":"An employee earns $2,000 gross wages. Only the 7.65% employee FICA tax is withheld. What is net pay after FICA?","choices":["$1,923","$1,847","$1,800","$1,953"],"answer":1,"explain":"$2,000 times 7.65% is $153, leaving $1,847."},{"id":"acc-071","sub":"Tax Accounting","diff":2,"q":"Under IRS rules, which describes an ordinary and necessary business expense?","choices":["A personal vacation paid by the business","A political contribution, which is always deductible","An expense that is common and accepted in the trade and helpful to the business","Any capital purchase of equipment"],"answer":2,"explain":"Ordinary means common in the trade and necessary means helpful and appropriate."},{"id":"acc-072","sub":"Tax Accounting","diff":2,"q":"Under current U.S. federal tax rules, business meal expenses are generally deductible at what percentage?","choices":["100%","25%","0%","50%"],"answer":3,"explain":"The general rule for business meals is 50 percent deductibility."},{"id":"acc-073","sub":"Financial Reports","diff":1,"q":"Which statement reports revenues and expenses for a period?","choices":["Income statement","Balance sheet","Statement of cash flows","Statement of owner''s equity"],"answer":0,"explain":"The income statement reports net income for a period of time."},{"id":"acc-074","sub":"Financial Reports","diff":1,"q":"Which balance sheet section lists assets expected to be converted to cash within one year or the operating cycle?","choices":["Long-term liabilities","Current assets","Stockholders'' equity","Other assets"],"answer":1,"explain":"Current assets are listed first and are expected to turn into cash within a year."},{"id":"acc-075","sub":"Financial Reports","diff":1,"q":"Which cash flow is an operating activity under U.S. GAAP?","choices":["Issuing bonds","Purchasing equipment","Cash paid to suppliers","Paying dividends"],"answer":2,"explain":"Operating activities relate to cash from normal business operations."},{"id":"acc-076","sub":"Financial Reports","diff":2,"q":"Which item is an investing activity?","choices":["Collecting cash from customers","Repaying loan principal","Paying interest","Purchase of equipment for cash"],"answer":3,"explain":"Buying long-term assets is investing; loan principal is financing and interest is operating."},{"id":"acc-077","sub":"Financial Reports","diff":3,"q":"Sales are $420,000, cost of goods sold is $252,000, and operating expenses are $98,000. What is the gross profit margin?","choices":["40%","60%","23.3%","58.3%"],"answer":0,"explain":"Gross profit is $168,000, and $168,000 divided by $420,000 is 40%."},{"id":"acc-078","sub":"Financial Reports","diff":1,"q":"Current assets are $180,000 and current liabilities are $120,000. What is the current ratio?","choices":["0.67","1.50","0.60","2.00"],"answer":1,"explain":"$180,000 divided by $120,000 is 1.5."},{"id":"acc-079","sub":"Financial Reports","diff":3,"q":"Current assets are $180,000, including $60,000 of inventory. Current liabilities are $120,000. What is the quick ratio?","choices":["1.50","0.67","1.00","0.50"],"answer":2,"explain":"Quick assets are $120,000, and $120,000 divided by $120,000 is 1.0."},{"id":"acc-080","sub":"Financial Reports","diff":1,"q":"Total liabilities are $400,000 and total equity is $500,000. What is the debt-to-equity ratio?","choices":["1.25","0.56","0.44","0.80"],"answer":3,"explain":"$400,000 divided by $500,000 is 0.8."},{"id":"acc-081","sub":"Financial Reports","diff":2,"q":"Net income is $75,000 and average total assets are $1,200,000. What is return on assets?","choices":["6.25%","16.0%","7.5%","0.06%"],"answer":0,"explain":"$75,000 divided by $1,200,000 is 6.25%."},{"id":"acc-082","sub":"Financial Reports","diff":3,"q":"Net income is $75,000 and average stockholders equity is $500,000. What is return on equity?","choices":["6.67%","15.00%","37.5%","1.5%"],"answer":1,"explain":"$75,000 divided by $500,000 is 15%."},{"id":"acc-083","sub":"Financial Reports","diff":1,"q":"Which statement reports assets, liabilities, and equity at a single point in time?","choices":["Income statement","Statement of cash flows","Balance sheet","Statement of retained earnings"],"answer":2,"explain":"The balance sheet is a snapshot as of a date."},{"id":"acc-084","sub":"Financial Reports","diff":3,"q":"Net income is $300,000, preferred dividends are $30,000, and 90,000 weighted average common shares are outstanding. What is basic EPS?","choices":["$3.33","$2.67","$3.67","$3.00"],"answer":3,"explain":"Earnings available to common ($270,000) divided by 90,000 shares is $3.00."},{"id":"acc-085","sub":"Financial Reports","diff":2,"q":"Which items are typically reconciled in the statement of changes in stockholders equity?","choices":["Net income and dividends","Cash from operations","Inventory turnover","Interest coverage"],"answer":0,"explain":"Equity changes come from net income, dividends, and stock transactions."},{"id":"acc-086","sub":"Financial Reports","diff":2,"q":"Which relationship describes the statement of retained earnings?","choices":["Beginning retained earnings - net income + dividends = ending retained earnings","Beginning retained earnings + net income - dividends = ending retained earnings","Net income - beginning retained earnings = ending retained earnings","Beginning retained earnings + dividends - net income = ending retained earnings"],"answer":1,"explain":"Net income increases retained earnings and dividends reduce it."},{"id":"acc-087","sub":"Financial Reports","diff":2,"q":"Beginning retained earnings are $220,000, net income is $64,000, and dividends are $20,000. What is ending retained earnings?","choices":["$176,000","$220,000","$264,000","$304,000"],"answer":2,"explain":"$220,000 + $64,000 - $20,000 = $264,000."},{"id":"acc-088","sub":"Financial Reports","diff":2,"q":"Cost of goods sold is $450,000 and average inventory is $90,000. What is inventory turnover?","choices":["4.0","0.2","6.7","5.0"],"answer":3,"explain":"$450,000 divided by $90,000 is 5.0 times."},{"id":"acc-089","sub":"Financial Reports","diff":2,"q":"EBIT is $360,000 and interest expense is $60,000. What is times interest earned?","choices":["6.0x","0.17x","5.0x","7.0x"],"answer":0,"explain":"$360,000 divided by $60,000 is 6.0 times."},{"id":"acc-090","sub":"Financial Reports","diff":2,"q":"Under the indirect method, which non-cash item is added back to net income in operating activities?","choices":["Dividends paid","Depreciation expense","Purchase of land","Issuance of common stock"],"answer":1,"explain":"Depreciation reduces net income but does not use cash, so it is added back."},{"id":"acc-091","sub":"Technology and Accounting","diff":1,"q":"Which software feature lets a transaction entered in one module update the general ledger automatically?","choices":["Encryption","Compiling","Integration","Backup"],"answer":2,"explain":"Integrated modules share data so one entry flows through to the ledger."},{"id":"acc-092","sub":"Technology and Accounting","diff":1,"q":"Which technology control limits access to accounting data to authorized users based on job duties?","choices":["Bank reconciliation","Periodic physical count","Three-way match","Role-based access controls"],"answer":3,"explain":"Role-based access restricts users to the functions their job needs."},{"id":"acc-093","sub":"Technology and Accounting","diff":1,"q":"What is the main purpose of an ERP system in accounting?","choices":["Integrating business processes and data into one system","Calculating income taxes only","Replacing the external audit","Storing only customer email addresses"],"answer":0,"explain":"ERP systems connect finance, sales, purchasing, and inventory in one database."},{"id":"acc-094","sub":"Technology and Accounting","diff":2,"q":"Which process checks that entered data meets defined rules and is accurate before it is processed?","choices":["Data mining","Data validation","Data warehousing","Data scraping"],"answer":1,"explain":"Validation rules catch errors such as invalid account numbers at entry."},{"id":"acc-095","sub":"Technology and Accounting","diff":2,"q":"What is XBRL primarily used for?","choices":["Encrypting bank wire transfers","Tracking employee hours for payroll","Tagging financial data so computers can read and compare it","Designing spreadsheet formulas"],"answer":2,"explain":"XBRL tags financial statement data in a standard machine-readable format."},{"id":"acc-096","sub":"Technology and Accounting","diff":2,"q":"Which control best reduces the risk of duplicate or unauthorized vendor payments?","choices":["Approving invoices without comparing them to receiving records","Paying all invoices immediately","Deleting vendor records after payment","Three-way match of purchase order, receiving report, and vendor invoice"],"answer":3,"explain":"The three-way match confirms the bill is for goods ordered and received before payment."},{"id":"acc-097","sub":"Career Opportunities","diff":1,"q":"Which credential is awarded to accountants who pass the Uniform CPA Examination and meet state licensing requirements?","choices":["CPA","CMA","CIA","CFP"],"answer":0,"explain":"The Certified Public Accountant credential requires the CPA exam and state licensure."},{"id":"acc-098","sub":"Career Opportunities","diff":1,"q":"Which certification focuses on management accounting and internal financial decision support?","choices":["CPA","CMA","CFP","EA"],"answer":1,"explain":"The Certified Management Accountant credential focuses on management accounting."},{"id":"acc-099","sub":"Career Opportunities","diff":1,"q":"Which career is most closely associated with evaluating internal controls within an organization?","choices":["Payroll clerk","Tax preparer for individuals only","Internal auditor","Bookkeeper for a single client"],"answer":2,"explain":"Internal auditors test controls and report on risk within the organization."},{"id":"acc-100","sub":"Career Opportunities","diff":2,"q":"What does an Enrolled Agent credential allow a person to do?","choices":["Practice law","Audit public companies only","Sell securities","Represent taxpayers before the IRS"],"answer":3,"explain":"Enrolled Agents are federally licensed to represent taxpayers before the IRS."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'business-law', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"law-001","sub":"Legal systems","diff":1,"q":"Which branch of the U.S. federal government has the main power to enact statutes?","choices":["The executive branch","The judicial branch","The legislative branch (Congress)","The regulatory branch of an executive agency"],"answer":2,"explain":"Congress enacts statutes. Courts interpret them, the executive enforces them, and agencies make regulations under delegated authority."},{"id":"law-002","sub":"Contracts and sales","diff":1,"q":"Which element of a valid contract is the bargained-for exchange of value between the parties?","choices":["Consideration","Capacity","Legality","Genuine assent"],"answer":0,"explain":"Consideration is something of legal value given in exchange for a promise. Capacity, legality and genuine assent are separate elements."},{"id":"law-003","sub":"Agency and employment laws","diff":2,"q":"An agent''s authority that arises from the principal''s conduct, leading a third party to reasonably believe the agent has power to act, is called:","choices":["Express authority","Implied authority","Incidental authority","Apparent authority"],"answer":3,"explain":"Apparent authority rests on the third party''s reasonable belief caused by the principal''s conduct. Implied authority is actual authority inferred from the agent''s duties."},{"id":"law-004","sub":"Property laws","diff":1,"q":"Which type of property is generally movable and not attached to land, such as furniture or a car?","choices":["Real property","Personal property","Fixtures","An easement"],"answer":1,"explain":"Personal property is movable. Real property is land and things permanently attached to it, and fixtures are items that have become part of the land."},{"id":"law-005","sub":"Consumer protection and product/personal liability","diff":3,"q":"Under the UCC, which warranty arises automatically when a merchant sells goods, even if the contract never mentions a warranty?","choices":["Express warranty of fitness","Implied warranty of merchantability","Full written warranty","Limited warranty of repair"],"answer":1,"explain":"The implied warranty of merchantability attaches to sales by merchants of goods of the kind sold. Express warranties must be stated by the seller."},{"id":"law-006","sub":"Legal systems","diff":1,"q":"Which dispute resolution method uses a neutral third party whose decision is binding on the parties?","choices":["Mediation","Conciliation","Negotiation","Arbitration"],"answer":3,"explain":"Arbitration produces a binding decision by a neutral arbitrator. Mediation and conciliation help parties reach their own agreement and are not binding."},{"id":"law-007","sub":"Business organization","diff":3,"q":"In a partnership where some owners have limited liability and at least one owner has unlimited liability, the business is a:","choices":["Limited partnership","General partnership","Limited liability partnership","Joint venture"],"answer":0,"explain":"A limited partnership has at least one general partner with unlimited liability and limited partners whose liability is capped. A general partnership gives every partner unlimited liability."},{"id":"law-008","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"A written, unconditional order by one party directing a second party to pay money to a third party is called a:","choices":["Promissory note","Certificate of deposit","Draft (bill of exchange)","Bearer bond"],"answer":2,"explain":"A draft has three parties (drawer, drawee and payee). A promissory note is a promise to pay made by the maker and involves only two parties."},{"id":"law-009","sub":"Domestic and private law","diff":1,"q":"Which document lets a person name an agent to handle financial matters if the person becomes incapacitated?","choices":["Durable power of attorney","Living will","Codicil","Trust deed"],"answer":0,"explain":"A durable power of attorney survives the principal''s incapacity. A living will addresses end-of-life medical care, not finances."},{"id":"law-010","sub":"Computer law","diff":2,"q":"Which federal law makes it a crime to access a computer without authorization or to exceed authorized access?","choices":["Digital Millennium Copyright Act","Electronic Communications Privacy Act","Computer Fraud and Abuse Act","Fair Credit Reporting Act"],"answer":2,"explain":"The Computer Fraud and Abuse Act (1986) is the main federal anti-hacking statute. The DMCA addresses copyright protection technology."},{"id":"law-011","sub":"Legal systems","diff":2,"q":"A court''s obligation to follow precedent from earlier decisions on similar facts is known as:","choices":["Judicial review","Stare decisis","Original jurisdiction","Due process"],"answer":1,"explain":"Stare decisis means to stand by things decided. Judicial review is the power to strike down laws that violate the Constitution."},{"id":"law-012","sub":"Contracts and sales","diff":2,"q":"Which contract must be in writing to be enforceable under the Statute of Frauds?","choices":["A contract for the sale of $400 of goods","A contract that can be performed within one year","A contract for cash services paid upfront","A contract for the sale of land"],"answer":3,"explain":"Contracts for the sale of land fall under the Statute of Frauds. Goods sales require a writing only at $500 or more under UCC 2-201."},{"id":"law-013","sub":"Contracts and sales","diff":1,"q":"Which event ends an offer by operation of law?","choices":["The offeree accepts on the stated terms","The offeror says the offer stays open for 30 days","The offeree asks a question about delivery","The death of the offeror before acceptance"],"answer":3,"explain":"An offer ends by operation of law on the death or incapacity of either party before acceptance. Acceptance forms a contract, and a question is not a counteroffer."},{"id":"law-014","sub":"Agency and employment laws","diff":1,"q":"An employee injured on the job generally receives benefits from which program?","choices":["Unemployment compensation","Workers'' compensation","Social Security retirement benefits","Medicare"],"answer":1,"explain":"Workers'' compensation is a no-fault system funded by employers that pays benefits for work-related injuries. Unemployment insurance covers job loss."},{"id":"law-015","sub":"Property laws","diff":2,"q":"Which easement lets a landowner cross a neighbor''s land to reach a public road when the land is otherwise landlocked?","choices":["Easement in gross","Easement by prescription","Easement by necessity","Negative easement"],"answer":2,"explain":"An easement by necessity arises when a parcel has no access to a road. An easement by prescription arises from open, continuous, adverse use over time."},{"id":"law-016","sub":"Legal systems","diff":1,"q":"The party who brings a civil lawsuit is called the:","choices":["Plaintiff","Defendant","Prosecutor","Grand juror"],"answer":0,"explain":"The plaintiff starts a civil suit. The defendant responds to it, and a prosecutor represents the government in criminal cases."},{"id":"law-017","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"On a promissory note, which party is the maker?","choices":["The party to whom payment is promised","The party who must present the note for payment","The party who promises to pay","The party who transfers the note by endorsement"],"answer":2,"explain":"The maker is the primary party who signs a promise to pay. The payee receives payment, and endorsers transfer the instrument."},{"id":"law-018","sub":"Contracts and sales","diff":3,"q":"A contract whose existence and terms are inferred from the parties'' conduct rather than their words is:","choices":["An implied-in-fact contract","A quasi-contract","An express contract","A void contract"],"answer":0,"explain":"An implied-in-fact contract is found from conduct. A quasi-contract is implied in law by the court to prevent unjust enrichment and is not based on agreement."},{"id":"law-019","sub":"Consumer protection and product/personal liability","diff":2,"q":"Which federal law regulates the collection of debts by third-party debt collectors?","choices":["Truth in Lending Act","Equal Credit Opportunity Act","Electronic Fund Transfer Act","Fair Debt Collection Practices Act"],"answer":3,"explain":"The FDCPA limits abusive and deceptive collection practices by third-party collectors. TILA governs credit cost disclosures."},{"id":"law-020","sub":"Business organization","diff":2,"q":"Under Subchapter S, a corporation''s income and losses are:","choices":["Taxed at the corporate level only","Passed through to shareholders and reported on their personal returns","Taxed at both the corporate and shareholder levels","Exempt from federal income tax entirely"],"answer":1,"explain":"An S corporation avoids entity-level federal income tax by passing items through to shareholders. A C corporation is taxed at the entity level and again on dividends."},{"id":"law-021","sub":"Property laws","diff":1,"q":"A tenant renting an apartment for a fixed term of one year holds which type of estate?","choices":["Fee simple","Estate for years","Life estate","Tenancy at will"],"answer":1,"explain":"An estate for years is a leasehold with a fixed start and end date. A tenancy at will has no fixed term."},{"id":"law-022","sub":"Agency and employment laws","diff":3,"q":"Under respondeat superior, an employer is liable for an employee''s torts when the employee:","choices":["Acts as an independent contractor","Acts entirely outside the employer''s business","Acts without any employer control","Commits the tort within the scope of employment"],"answer":3,"explain":"Respondeat superior makes employers liable for torts committed within the scope of employment. Independent contractors generally do not create that liability."},{"id":"law-023","sub":"Computer law","diff":2,"q":"A software license that lets users copy, modify and redistribute code on the same terms is commonly called:","choices":["A copyleft (open-source) license","A shrink-wrap license","A site license","A proprietary license"],"answer":0,"explain":"Copyleft licenses require derivative works to carry the same open terms. Shrink-wrap, site and proprietary licenses restrict redistribution."},{"id":"law-024","sub":"Domestic and private law","diff":2,"q":"A holographic will is a will that is:","choices":["Typed and notarized","Witnessed by two people and recorded","Handwritten and signed by the testator","Created by a trust officer"],"answer":2,"explain":"A holographic will is entirely in the testator''s handwriting and signed. Many states accept holographic wills without witnesses, but the handwriting must be proven."},{"id":"law-025","sub":"Legal systems","diff":1,"q":"Which area of law addresses wrongs against society that the government prosecutes?","choices":["Criminal law","Civil law","Tort law","Administrative law"],"answer":0,"explain":"Criminal law addresses offenses against society, prosecuted by the state. Civil and tort law address disputes between private parties."},{"id":"law-026","sub":"Contracts and sales","diff":2,"q":"A court order requiring a party to perform the exact promised act is:","choices":["Rescission","Restitution","Specific performance","Liquidated damages"],"answer":2,"explain":"Specific performance compels the promised act and is used when money damages are inadequate, such as for unique goods or land."},{"id":"law-027","sub":"Consumer protection and product/personal liability","diff":1,"q":"Advertising a product at a very low price with no intent to sell it, then pressuring buyers toward a costlier item, is:","choices":["Puffery","Bait and switch","Negative option billing","Loss-leader pricing"],"answer":1,"explain":"Bait and switch is a deceptive practice. Loss-leader pricing is a real sale of a discounted item, and puffery is harmless exaggeration."},{"id":"law-028","sub":"Business organization","diff":1,"q":"Which form of business is a separate legal entity that offers owners limited liability?","choices":["Sole proprietorship","General partnership","Unincorporated association","Corporation"],"answer":3,"explain":"A corporation is a separate legal entity, so owners'' personal liability is generally limited to their investment. The other forms do not provide this."},{"id":"law-029","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"To be negotiable under the UCC, an instrument must be payable:","choices":["Only with collateral attached","Only in goods","Only after an uncertain event","On demand or at a definite time"],"answer":3,"explain":"UCC 3-104 requires payment on demand or at a definite time, among other elements. Payment that depends on an uncertain event defeats negotiability."},{"id":"law-030","sub":"Agency and employment laws","diff":1,"q":"A relationship in which one party authorizes another to act on its behalf and under its control is:","choices":["Bailment","Agency","Partnership","Trust"],"answer":1,"explain":"Agency is created when a principal authorizes an agent to act for it under the principal''s control. A bailment concerns temporary possession of goods."},{"id":"law-031","sub":"Property laws","diff":1,"q":"A legal claim against property to secure payment of a debt is called a:","choices":["Easement","Covenant","Lien","License"],"answer":2,"explain":"A lien is a claim on property that secures a debt. An easement is a right to use land, and a covenant is a promise about land use."},{"id":"law-032","sub":"Computer law","diff":2,"q":"Which law gives electronic signatures the same legal effect as handwritten signatures in interstate commerce?","choices":["E-SIGN Act","Gramm-Leach-Bliley Act","Sarbanes-Oxley Act","Telephone Consumer Protection Act"],"answer":0,"explain":"The Electronic Signatures in Global and National Commerce (E-SIGN) Act gives electronic signatures and records legal effect. The others regulate financial privacy, corporate reporting and telemarketing."},{"id":"law-033","sub":"Legal systems","diff":2,"q":"Which court typically hears appeals and reviews the trial record for legal errors rather than retrying the facts?","choices":["Small claims court","Trial court of general jurisdiction","Appellate court","Probate court"],"answer":2,"explain":"Appellate courts review for legal error and generally do not retry facts or hear witnesses. Trial courts decide facts."},{"id":"law-034","sub":"Contracts and sales","diff":1,"q":"Besides offer and acceptance, what must be present for a contract to be enforceable?","choices":["Consideration","Notarization","Witness signatures","Recording with the county"],"answer":0,"explain":"Enforceable contracts generally require offer, acceptance and consideration. Notarization and recording are not general requirements."},{"id":"law-035","sub":"Domestic and private law","diff":1,"q":"A written agreement made before marriage that sets out how property will be divided is a:","choices":["Separation agreement","Divorce decree","Marital trust","Prenuptial agreement"],"answer":3,"explain":"A prenuptial agreement is made before marriage and governs property and support. A separation agreement is made after the couple decides to live apart."},{"id":"law-036","sub":"Agency and employment laws","diff":3,"q":"Under the Fair Labor Standards Act, covered non-exempt employees must receive what pay for hours worked over 40 in a workweek?","choices":["Double pay for all hours worked","Overtime pay of at least 1.5 times the regular rate","Paid time off equal to hours worked","A fixed weekly bonus"],"answer":1,"explain":"The FLSA requires at least time-and-a-half for hours over 40 in a workweek for non-exempt employees. Other options are not federal requirements."},{"id":"law-037","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":3,"q":"A holder in due course takes a negotiable instrument free of most defenses. Which of the following is still a valid defense against such a holder?","choices":["The holder paid full value in good faith","The maker''s signature was forged","The holder took the instrument by a qualified endorsement","The instrument was payable to bearer"],"answer":1,"explain":"Forgery is a real defense that survives holder-in-due-course status. Good faith value, a qualified endorsement and bearer status are all features of HDC status or negotiability, not defenses."},{"id":"law-038","sub":"Consumer protection and product/personal liability","diff":2,"q":"Which federal act requires lenders to disclose the finance charge and annual percentage rate on consumer credit?","choices":["Fair Credit Reporting Act","Equal Credit Opportunity Act","Fair Debt Collection Practices Act","Truth in Lending Act"],"answer":3,"explain":"TILA requires standardized disclosure of credit costs, including the finance charge and APR. The other laws cover credit reports, lending discrimination and debt collection."},{"id":"law-039","sub":"Legal systems","diff":1,"q":"A process in which a neutral person helps the parties reach their own agreement but cannot impose a decision is:","choices":["Mediation","Arbitration","Litigation","Adjudication"],"answer":0,"explain":"A mediator facilitates a voluntary settlement and cannot impose an outcome. An arbitrator decides the dispute."},{"id":"law-040","sub":"Property laws","diff":2,"q":"Which form of co-ownership gives the surviving owners the deceased owner''s share automatically?","choices":["Tenancy in common","Tenancy at sufferance","Joint tenancy with right of survivorship","Life estate"],"answer":2,"explain":"Joint tenancy with right of survivorship passes a deceased owner''s interest to the surviving owners automatically. Tenants in common pass their shares through their estates."},{"id":"law-041","sub":"Business organization","diff":1,"q":"The corporate officer generally responsible for day-to-day management, who reports to the board of directors, is the:","choices":["Chief executive officer","Shareholder of record","Independent auditor","Trustee"],"answer":0,"explain":"The CEO runs daily operations and reports to the board. Shareholders own the company, and auditors examine its financial statements."},{"id":"law-042","sub":"Contracts and sales","diff":3,"q":"Which contract is voidable rather than void?","choices":["A contract for an illegal purpose","A contract with no offer","A contract made by a minor","A contract requiring a crime"],"answer":2,"explain":"A minor''s contract is voidable at the minor''s option. Contracts for illegal purposes and contracts lacking an offer are void."},{"id":"law-043","sub":"Agency and employment laws","diff":2,"q":"A principal is bound to a contract made with a third party by its agent when the agent had:","choices":["No authority of any kind","Actual or apparent authority","Authority only if the contract is notarized","Authority acquired after signing"],"answer":1,"explain":"Principals are bound by acts within actual or apparent authority. Notarization is not a general requirement, and later-acquired authority does not bind retroactively."},{"id":"law-044","sub":"Computer law","diff":2,"q":"Which federal law limits the online collection of personal information from children under 13?","choices":["Health Insurance Portability and Accountability Act","Gramm-Leach-Bliley Act","Fair Credit Reporting Act","Children''s Online Privacy Protection Act"],"answer":3,"explain":"COPPA requires parental consent and limits data collection for children under 13. HIPAA covers health records, and GLBA covers financial privacy."},{"id":"law-045","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":3,"q":"An endorsement consisting only of the endorser''s signature on the back of an instrument is a:","choices":["Qualified endorsement","Restrictive endorsement","Conditional endorsement","Blank endorsement"],"answer":3,"explain":"A blank endorsement names no payee, so the instrument becomes payable to bearer. Qualified, restrictive and conditional endorsements add words or limits."},{"id":"law-046","sub":"Consumer protection and product/personal liability","diff":3,"q":"Under TILA, which right lets a consumer cancel certain loans secured by the principal dwelling within three business days?","choices":["Right of withdrawal under the FCRA","Right of rescission","Right of setoff","Right of subrogation"],"answer":1,"explain":"The TILA right of rescission applies to certain home-secured credit transactions such as refinancing. The FCRA does not give a cancellation right, and setoff and subrogation are unrelated remedies."},{"id":"law-047","sub":"Legal systems","diff":2,"q":"The doctrine requiring a party to have a sufficient personal stake in a case to bring it is:","choices":["Mootness","Ripeness","Standing","Venue"],"answer":2,"explain":"Standing requires a concrete injury tied to the defendant''s conduct. Mootness and ripeness concern timing, and venue concerns the proper place for trial."},{"id":"law-048","sub":"Property laws","diff":1,"q":"Which intellectual property right protects a new and useful machine design?","choices":["Patent","Trademark","Copyright","Service mark"],"answer":0,"explain":"Patents protect new, useful and non-obvious inventions. Trademarks protect brand identifiers, and copyrights protect creative works."},{"id":"law-049","sub":"Agency and employment laws","diff":2,"q":"Which worker is most likely an independent contractor rather than an employee?","choices":["A cashier paid hourly and supervised by a manager","A driver on set shifts using a company vehicle","A freelance designer who sets her own hours, uses her own tools and is paid per project","A factory worker enrolled in the company health plan"],"answer":2,"explain":"Control over hours, tools and method points to independent contractor status. Hourly pay, supervision and benefits point toward employment."},{"id":"law-050","sub":"Business organization","diff":1,"q":"A merger that combines companies in unrelated businesses is a:","choices":["Conglomerate merger","Horizontal merger","Vertical merger","Reverse triangular merger"],"answer":0,"explain":"A conglomerate merger joins firms in unrelated industries. A horizontal merger joins competitors, and a vertical merger joins firms at different stages of the same supply chain."},{"id":"law-051","sub":"Domestic and private law","diff":2,"q":"Which is a common no-fault ground for divorce?","choices":["Adultery in every state","Desertion for one day","Fraud before the marriage","Irreconcilable differences"],"answer":3,"explain":"No-fault divorce is generally based on irreconcilable differences or an irretrievable breakdown of the marriage. Fault grounds such as adultery are not required and are not used in every state."},{"id":"law-052","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":3,"q":"Presentment for acceptance is required for which type of instrument?","choices":["A promissory note payable on demand","A draft payable a fixed number of days after sight","A certificate of deposit","A check payable on demand"],"answer":1,"explain":"Under UCC 3-501, a draft payable a fixed number of days after sight must be presented to the drawee for acceptance, which fixes its maturity. Demand instruments and certificates of deposit do not require acceptance."},{"id":"law-053","sub":"Consumer protection and product/personal liability","diff":2,"q":"Which practice is deceptive under FTC rules?","choices":["Offering a clearly stated money-back guarantee","Claiming a product is clinically proven without supporting evidence","Listing cash and financing prices separately","Disclosing a product''s country of origin"],"answer":1,"explain":"Advertising claims must be truthful and substantiated. The other options are lawful disclosure or guarantee practices."},{"id":"law-054","sub":"Legal systems","diff":2,"q":"Which body decides whether there is enough evidence to bring a felony indictment?","choices":["Petit jury","Appellate panel","Magistrate judge acting alone","Grand jury"],"answer":3,"explain":"A grand jury hears evidence and decides whether to indict. A petit (trial) jury decides guilt or innocence at trial."},{"id":"law-055","sub":"Computer law","diff":3,"q":"Which doctrine lets a court exercise personal jurisdiction over an out-of-state online seller that targets customers in the forum state?","choices":["Long-arm jurisdiction","Venue","Subject-matter jurisdiction","Res judicata"],"answer":0,"explain":"Long-arm statutes and minimum-contacts analysis allow personal jurisdiction over nonresident defendants who purposefully reach the forum. Venue concerns the location of trial, and res judicata bars relitigation."},{"id":"law-056","sub":"Property laws","diff":1,"q":"Which document transfers title to real property?","choices":["Lease","Mortgage","Deed","Bill of sale"],"answer":2,"explain":"A deed conveys title to real property. A lease grants possession, a mortgage secures a loan, and a bill of sale transfers personal property."},{"id":"law-057","sub":"Agency and employment laws","diff":3,"q":"An agent who purports to contract for a principal that does not exist is typically personally liable under the:","choices":["Implied warranty of authority","Doctrine of respondeat superior","Statute of Frauds","Parol evidence rule"],"answer":0,"explain":"An agent impliedly warrants having authority, so misrepresenting a principal''s existence exposes the agent to liability. The other doctrines do not address this situation."},{"id":"law-058","sub":"Business organization","diff":1,"q":"Which body is elected by shareholders to oversee corporate management?","choices":["Corporate officers","Creditors'' committee","Board of directors","Trustees in bankruptcy"],"answer":2,"explain":"Shareholders elect the board of directors, which oversees management. Officers are appointed by the board to run daily operations."},{"id":"law-059","sub":"Contracts and sales","diff":3,"q":"A promise to keep an offer open for 30 days, made without payment or other consideration, is generally:","choices":["Binding for the full 30 days","Revocable by the offeror before acceptance","Binding because it was in writing","Binding only if notarized"],"answer":1,"explain":"Without consideration or a separate option contract, a promise to hold an offer open is revocable before acceptance under common law. Writing and notarization do not supply consideration."},{"id":"law-060","sub":"Domestic and private law","diff":2,"q":"Which document names someone to make health care decisions if the principal cannot communicate?","choices":["Last will and testament","Trust instrument","Codicil","Health care proxy"],"answer":3,"explain":"A health care proxy appoints an agent for medical decisions. A will governs property at death, and a codicil amends a will."},{"id":"law-061","sub":"Legal systems","diff":2,"q":"Which standard of proof applies in a typical civil case?","choices":["Beyond a reasonable doubt","Probable cause","Clear and convincing evidence","Preponderance of the evidence"],"answer":3,"explain":"Civil cases generally require a preponderance of the evidence, meaning more likely than not. Beyond a reasonable doubt is the criminal standard."},{"id":"law-062","sub":"Consumer protection and product/personal liability","diff":3,"q":"Under strict product liability, a manufacturer may be liable for a defective and unreasonably dangerous product:","choices":["Only if negligence is proven","Without proof of negligence","Only if the buyer signed a warranty","Only if the seller and manufacturer are the same party"],"answer":1,"explain":"Strict liability focuses on the product''s condition, not the manufacturer''s fault. Plaintiffs need not prove negligence."},{"id":"law-063","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":1,"q":"Which insurance principle limits recovery to the actual loss suffered?","choices":["Underwriting","Premium","Indemnity","Reinsurance"],"answer":2,"explain":"The indemnity principle restores the insured to the pre-loss position without profit. Underwriting decides whether to insure, and the premium is the price paid."},{"id":"law-064","sub":"Contracts and sales","diff":3,"q":"A contract provision that ends a party''s duties automatically when a specified event occurs is a:","choices":["Condition subsequent","Condition precedent","Liquidated damages clause","Novation"],"answer":0,"explain":"A condition subsequent terminates an existing duty when an event happens. A condition precedent must occur before a duty arises."},{"id":"law-065","sub":"Property laws","diff":2,"q":"A mechanic''s lien is a claim against:","choices":["A debtor''s wages","A corporation''s shares","Real property, for unpaid labor and materials that improved it","A landlord''s future rent"],"answer":2,"explain":"A mechanic''s lien secures payment for work or materials that improved real property. It attaches to the property itself."},{"id":"law-066","sub":"Agency and employment laws","diff":2,"q":"Which federal law prohibits employment discrimination based on race, color, religion, sex or national origin?","choices":["Title VII of the Civil Rights Act of 1964","Age Discrimination in Employment Act","Americans with Disabilities Act","Equal Pay Act of 1963"],"answer":0,"explain":"Title VII prohibits employment discrimination on those five bases. The ADEA covers age, the ADA covers disability, and the Equal Pay Act covers pay differences by sex."},{"id":"law-067","sub":"Business organization","diff":2,"q":"A combination in which one company absorbs another, and only the absorbing company survives, is a:","choices":["Consolidation","Dissolution","Recapitalization","Merger"],"answer":3,"explain":"In a merger, the surviving company absorbs the other. In a consolidation, both companies cease to exist and a new company is formed."},{"id":"law-068","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"Which filing gives public notice of a creditor''s security interest in personal property under the UCC?","choices":["Deed of trust","UCC-1 financing statement","Mortgage","Recorded deed"],"answer":1,"explain":"A UCC-1 financing statement perfects a security interest in most personal property. Deeds of trust and mortgages secure real property."},{"id":"law-069","sub":"Consumer protection and product/personal liability","diff":1,"q":"Which federal agency polices unfair or deceptive trade practices?","choices":["Securities and Exchange Commission","Federal Trade Commission","Federal Reserve","Internal Revenue Service"],"answer":1,"explain":"The FTC enforces the FTC Act''s prohibition on unfair and deceptive practices. The SEC regulates securities, and the Federal Reserve oversees monetary policy and banks."},{"id":"law-070","sub":"Contracts and sales","diff":3,"q":"A party signs a contract after being told a false fact that induced the signing. This defense is:","choices":["Duress","Undue influence","Unconscionability","Fraudulent misrepresentation"],"answer":3,"explain":"Fraudulent misrepresentation makes a contract voidable when a party relies on a knowingly false material fact. Duress involves threats, and undue influence involves a dominant relationship."},{"id":"law-071","sub":"Legal systems","diff":3,"q":"Which requirement must be met for a federal court to hear a state-law claim under diversity jurisdiction?","choices":["Complete diversity of citizenship and more than $75,000 in controversy","Both parties reside in the same state","The federal government must be a party","The claim must arise under a federal statute"],"answer":0,"explain":"Diversity requires complete diversity among parties and an amount in controversy above the statutory threshold, currently $75,000. Federal-question cases need a federal claim."},{"id":"law-072","sub":"Contracts and sales","diff":3,"q":"A doctrine excusing performance because an unforeseen event made it impossible is:","choices":["Anticipatory repudiation","Accord and satisfaction","Impossibility of performance","Novation"],"answer":2,"explain":"Impossibility of performance excuses a duty when an unforeseeable event, not the party''s own choice, makes performance impossible. Anticipatory repudiation is a breach."},{"id":"law-073","sub":"Agency and employment laws","diff":1,"q":"Which employer duty is required under the Occupational Safety and Health Act?","choices":["Providing a workplace free from recognized serious hazards","Paying a living wage","Offering paid vacation after one year","Providing unemployment insurance"],"answer":0,"explain":"OSHA requires employers to protect workers from recognized serious hazards. It does not set wages, vacation or unemployment coverage."},{"id":"law-074","sub":"Property laws","diff":2,"q":"A bailment is created when:","choices":["Title passes permanently to a buyer","A landlord leases land to a tenant","Possession of personal property is temporarily transferred and must be returned","A debtor pledges real estate as collateral"],"answer":2,"explain":"A bailment transfers possession, not title, and the bailee must return or dispose of the goods as agreed. Title transfer, leases and real estate pledges are different arrangements."},{"id":"law-075","sub":"Consumer protection and product/personal liability","diff":1,"q":"Charging an interest rate above the legal maximum on a loan is called:","choices":["Redlining","Usury","Amortization","Escrow"],"answer":1,"explain":"Usury is charging interest above the lawful limit. Redlining is discriminatory lending, amortization is repayment scheduling, and escrow holds funds for a third party."},{"id":"law-076","sub":"Legal systems","diff":1,"q":"Which is the highest court in the U.S. federal court system?","choices":["U.S. Court of Appeals","U.S. District Court","U.S. Tax Court","U.S. Supreme Court"],"answer":3,"explain":"The U.S. Supreme Court is the highest federal court and the final appellate authority on federal questions. Courts of appeals and district courts are lower federal courts."},{"id":"law-077","sub":"Contracts and sales","diff":3,"q":"Which contract term describes a claim that a contract cannot be enforced in court because a required writing is missing?","choices":["Void","Voidable","Illusory","Unenforceable"],"answer":3,"explain":"An unenforceable contract is valid between the parties but cannot be enforced, such as one lacking a required writing. A void contract has no legal effect."},{"id":"law-078","sub":"Agency and employment laws","diff":1,"q":"Which fiduciary holds property for another''s benefit under a written trust instrument?","choices":["Bailee","Trustee","Surety","Principal"],"answer":1,"explain":"A trustee holds legal title and manages property for beneficiaries under a trust instrument. A bailee holds goods temporarily, and a surety guarantees another''s debt."},{"id":"law-079","sub":"Business organization","diff":2,"q":"Which business form combines limited liability for owners with pass-through taxation and fewer formal requirements than a corporation?","choices":["Business trust","Cooperative","Limited liability company","Franchise"],"answer":2,"explain":"An LLC gives owners limited liability and can be taxed as a partnership, with fewer formalities than a corporation. A franchise is a licensing arrangement, not an entity type."},{"id":"law-080","sub":"Contracts and sales","diff":3,"q":"Under UCC 2-207, between merchants, an additional term in an acceptance generally:","choices":["Becomes part of the contract unless it materially alters it or the offer limits acceptance to its terms","Always voids the contract","Always controls over the offer","Must be notarized to take effect"],"answer":0,"explain":"Between merchants, additional terms usually become part of the contract unless they materially alter it, the offer forbids them, or objection is made. Notarization is not required."},{"id":"law-081","sub":"Agency and employment laws","diff":3,"q":"Which of the following is a duty an agent owes to the principal?","choices":["Paying the principal''s personal debts","Acting as guarantor for third-party debts","Loyalty and disclosure of material information","Providing unlimited credit to the principal"],"answer":2,"explain":"Agents owe fiduciary duties of loyalty, obedience and disclosure to the principal. The other options are not agent duties."},{"id":"law-082","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"Which party to a check is the drawee?","choices":["The bank on which the check is drawn","The person who writes the check","The person who receives the check","The person who endorses the check"],"answer":0,"explain":"The drawee is the bank that must pay the check. The drawer writes it, and the payee receives it."},{"id":"law-083","sub":"Consumer protection and product/personal liability","diff":1,"q":"Which federal statute regulates consumer credit reports?","choices":["Electronic Fund Transfer Act","Fair Packaging and Labeling Act","Telephone Consumer Protection Act","Fair Credit Reporting Act"],"answer":3,"explain":"The FCRA governs the accuracy, privacy and use of consumer credit reports. The other statutes address electronic transfers, product packaging and telemarketing."},{"id":"law-084","sub":"Contracts and sales","diff":1,"q":"A promise to make a gift with nothing given in return is generally:","choices":["Enforceable because it is in writing","Unenforceable for lack of consideration","Enforceable under the Statute of Frauds","Enforceable only if the promisor is a corporation"],"answer":1,"explain":"A gratuitous promise lacks consideration and is generally unenforceable. Writing does not supply consideration."},{"id":"law-085","sub":"Contracts and sales","diff":1,"q":"Which defense applies when a party is forced to sign a contract under threat of physical harm?","choices":["Undue influence","Duress","Mistake","Fraud"],"answer":1,"explain":"Duress is coercion by threats that overcome a party''s free will, making the contract voidable. Undue influence arises from a relationship of trust."},{"id":"law-086","sub":"Contracts and sales","diff":3,"q":"Under the parol evidence rule, which statement is correct?","choices":["It allows oral evidence to override any written term","It applies only to oral contracts","It requires contracts to be notarized","It generally bars prior or contemporaneous oral terms that contradict a fully integrated written contract"],"answer":3,"explain":"The parol evidence rule protects integrated written agreements from contradiction by earlier or contemporaneous oral terms. Exceptions exist for fraud, ambiguity and certain terms."},{"id":"law-087","sub":"Contracts and sales","diff":3,"q":"Which promise must be in writing under the Statute of Frauds?","choices":["A promise to pay the debt of another if that person defaults","A promise to deliver flowers next week","A gift of cash","A promise to pay for a meal today"],"answer":0,"explain":"Promises to answer for another''s debt, called suretyship promises, must be in writing. The other promises can be performed quickly or are gifts."},{"id":"law-088","sub":"Contracts and sales","diff":3,"q":"A mutual mistake supports rescission when:","choices":["One party was careless in reading the terms","The buyer simply regrets the contract later","Both parties were mistaken about the same material fact at formation","The mistake concerns future market prices"],"answer":2,"explain":"Mutual mistake about a material fact existing at formation can justify rescission. Carelessness, regret and mistakes about future prices do not."},{"id":"law-089","sub":"Contracts and sales","diff":1,"q":"Which remedy cancels a contract and returns the parties to their pre-contract positions?","choices":["Rescission","Specific performance","Injunction","Reformation"],"answer":0,"explain":"Rescission cancels the contract and restores the parties. Specific performance compels performance, and reformation rewrites the contract."},{"id":"law-090","sub":"Contracts and sales","diff":3,"q":"Which contract defense covers terms that are grossly unfair and oppressive, often because of unequal bargaining power?","choices":["Duress","Accord and satisfaction","Unconscionability","Novation"],"answer":2,"explain":"Unconscionability permits a court to refuse enforcement of grossly one-sided terms. Duress, accord and satisfaction, and novation are different doctrines."},{"id":"law-091","sub":"Agency and employment laws","diff":2,"q":"Which type of authority is expressly stated by the principal?","choices":["Implied authority","Express authority","Apparent authority","Inherent authority"],"answer":1,"explain":"Express authority is granted in words, orally or in writing. Implied authority is inferred from duties, and apparent authority comes from the principal''s conduct toward third parties."},{"id":"law-092","sub":"Agency and employment laws","diff":2,"q":"Under the FLSA, which employee is typically exempt from overtime?","choices":["A janitor paid hourly","A retail stock clerk paid hourly","A cashier paid by the hour","A bona fide executive earning a qualifying salary"],"answer":3,"explain":"Bona fide executive, administrative and professional employees who meet salary and duty tests are exempt from overtime. Hourly workers are generally non-exempt."},{"id":"law-093","sub":"Agency and employment laws","diff":1,"q":"Which law requires employers to provide unpaid, job-protected leave for certain family and medical reasons?","choices":["Equal Pay Act","Fair Labor Standards Act","Worker Adjustment and Retraining Notification Act","Family and Medical Leave Act"],"answer":3,"explain":"The FMLA provides up to 12 weeks of unpaid, job-protected leave for qualifying reasons. The other statutes address pay equity, minimum wage and mass layoffs."},{"id":"law-094","sub":"Property laws","diff":2,"q":"Which property interest is a right to use another''s land for a specific purpose without owning it?","choices":["Fee simple","Easement","Life estate","Tenancy by the entirety"],"answer":1,"explain":"An easement is a non-possessory right to use land for a specific purpose. Fee simple and life estates are ownership interests, and tenancy by the entirety is a form of co-ownership."},{"id":"law-095","sub":"Business organization","diff":1,"q":"Which legal form of business has unlimited personal liability for the owner and is the easiest to form?","choices":["Corporation","Limited partnership","Sole proprietorship","S corporation"],"answer":2,"explain":"A sole proprietorship requires no formal filing, and the owner is personally liable for business debts. The other forms involve formal filings or limited liability."},{"id":"law-096","sub":"Business organization","diff":2,"q":"Which corporate action creates a new company from two merging companies, which both cease to exist?","choices":["Consolidation","Merger","Dissolution","Recapitalization"],"answer":0,"explain":"In a consolidation, the combining companies cease to exist and a new entity is formed. In a merger, one company survives."},{"id":"law-097","sub":"Negotiable instruments, insurance, secured transactions, bankruptcy","diff":2,"q":"Which type of endorsement limits further negotiation, such as one that says ''For deposit only''?","choices":["Blank endorsement","Special endorsement","Restrictive endorsement","Qualified endorsement"],"answer":2,"explain":"A restrictive endorsement limits how the instrument may be used, such as requiring deposit only. A special endorsement names a payee, and a qualified endorsement disclaims liability."},{"id":"law-098","sub":"Legal systems","diff":2,"q":"Which principle requires that a court have authority over the type of dispute being heard?","choices":["Subject-matter jurisdiction","Personal jurisdiction","Venue","Standing"],"answer":0,"explain":"Subject-matter jurisdiction is the court''s authority over the kind of case. Personal jurisdiction concerns the parties, and venue concerns the location."},{"id":"law-099","sub":"Legal systems","diff":2,"q":"Which concept requires that laws give fair notice and fair procedures before the government deprives someone of life, liberty or property?","choices":["Equal protection","Judicial review","Stare decisis","Due process"],"answer":3,"explain":"The Due Process Clauses require fair procedures before deprivation. Equal protection concerns unequal treatment, and judicial review and stare decisis concern courts'' roles."},{"id":"law-100","sub":"Legal systems","diff":2,"q":"Which term describes a court''s power to review whether a law violates the Constitution?","choices":["Stare decisis","Judicial review","Original jurisdiction","Appellate jurisdiction"],"answer":1,"explain":"Judicial review, established in Marbury v. Madison, lets courts strike down unconstitutional laws. Stare decisis is the rule of following precedent."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'business-management', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"bm-001","sub":"Strategic Management","diff":1,"q":"A plant manager compares weekly output to a 5,000-unit standard, finds output 8% short, and orders a root-cause review of the shortfall. Which management function is the manager primarily performing?","choices":["Planning","Organizing","Controlling","Staffing"],"answer":2,"explain":"Comparing results to a standard and taking corrective action is the controlling function. Planning sets the standard; organizing and staffing come before performance is measured."},{"id":"bm-002","sub":"Management Types","diff":1,"q":"A software company forms a team with a fixed start date, a fixed budget, and one deliverable: a mobile app launch in nine months. Which type of management is being applied?","choices":["Project management","Knowledge management","Change management","Supply chain management"],"answer":0,"explain":"A temporary effort with a defined scope, budget, and deliverable is project management. Change management focuses on people adopting new processes."},{"id":"bm-003","sub":"Business Finance","diff":1,"q":"A company''s balance sheet shows total assets of $240,000 and total liabilities of $90,000. Using the accounting equation, what is owners'' equity?","choices":["$90,000","$240,000","$330,000","$150,000"],"answer":3,"explain":"Equity equals assets minus liabilities: $240,000 minus $90,000 is $150,000. The trap is reporting total assets or liabilities as equity."},{"id":"bm-004","sub":"Management Types","diff":1,"q":"In operations management, which term best describes the network of organizations that moves a product from raw material suppliers through manufacturers and distributors to the final customer?","choices":["Sales funnel","Supply chain","Value proposition","Business model"],"answer":1,"explain":"A supply chain is the network of suppliers, manufacturers, distributors, and retailers that moves a product to the customer. A sales funnel describes how prospects become buyers."},{"id":"bm-005","sub":"Strategic Management","diff":1,"q":"A manager must decide how many new employees to hire. Before writing job postings, HR must document what each position requires in duties, skills, and working conditions. What is this step called?","choices":["Performance appraisal","Orientation","Job analysis","Compensation planning"],"answer":2,"explain":"Job analysis gathers the duties, skills, and conditions for a position and comes before recruiting. Appraisal and orientation happen later in the employee lifecycle."},{"id":"bm-006","sub":"Business Environment","diff":1,"q":"A company sells monthly subscription boxes directly to consumers through its website and bypasses retail stores. Which business model is it using?","choices":["Direct-to-consumer model","Franchise model","Wholesale model","Licensing model"],"answer":0,"explain":"Selling straight to end users without intermediaries is a direct-to-consumer model. Wholesale sells to resellers, and franchising and licensing grant rights to others."},{"id":"bm-007","sub":"Business Finance","diff":1,"q":"A company spends $50,000 cash to buy new manufacturing equipment. On the statement of cash flows, under which activity is this outflow reported?","choices":["Operating activities","Financing activities","Non-cash activities","Investing activities"],"answer":3,"explain":"Purchases of long-term assets such as equipment are investing activities. This transaction involves cash, so it is not a non-cash activity."},{"id":"bm-008","sub":"Operations","diff":2,"q":"A bakery measures how many loaves its staff produces per labour hour and tracks the figure monthly to find efficiency gains. Which operations concept is being measured?","choices":["Liquidity","Productivity","Solvency","Profitability"],"answer":1,"explain":"Output per unit of input, such as labour hours, is productivity. Liquidity and solvency are financial measures, and profitability measures earnings."},{"id":"bm-009","sub":"Strategic Management","diff":2,"q":"A board approves a five-year plan to enter two new international markets and reallocate capital accordingly. Which type of plan is this?","choices":["Operational plan","Tactical plan","Strategic plan","Contingency plan"],"answer":2,"explain":"Long-range plans that set overall direction and allocate major resources are strategic. Tactical plans are mid-range, and operational plans are short-term and specific."},{"id":"bm-010","sub":"Management Types","diff":2,"q":"A firm buys fire insurance on its warehouse so that a loss would be covered financially. Which risk management response is this?","choices":["Risk transfer","Risk avoidance","Risk reduction","Risk acceptance"],"answer":0,"explain":"Shifting the financial consequence of a loss to an insurer is risk transfer. Avoidance would mean not operating the warehouse; reduction would mean installing sprinklers."},{"id":"bm-011","sub":"Business Environment","diff":2,"q":"A small manufacturer disputes warranty terms on machinery it sold. Which U.S. law primarily governs contracts for the sale of goods?","choices":["Fair Labor Standards Act","Sherman Antitrust Act","Occupational Safety and Health Act","Uniform Commercial Code, Article 2"],"answer":3,"explain":"UCC Article 2 governs sales of goods in the U.S. The other laws cover wages, antitrust, and workplace safety."},{"id":"bm-012","sub":"Operations","diff":2,"q":"A retailer maps every activity needed to fulfill an online order, from receiving to delivery, and looks for steps that add no value. Which concept is the retailer applying?","choices":["Strategic planning","Business process management","Capital budgeting","Market segmentation"],"answer":1,"explain":"Mapping and improving linked activities that turn inputs into outputs is business process management. The other choices are different disciplines."},{"id":"bm-013","sub":"Strategic Management","diff":2,"q":"A manager checks the quality of incoming raw materials before production begins so defective inputs never reach the line. Which type of control is this?","choices":["Feedback control","Concurrent control","Feedforward control","Discretionary control"],"answer":2,"explain":"Feedforward (preliminary) control anticipates problems before work starts. Feedback control evaluates results after the fact, and concurrent control monitors work as it happens."},{"id":"bm-014","sub":"Management Types","diff":2,"q":"An HR department is introducing a new time-tracking system and expects employee resistance. Which management approach helps people adjust to the new process?","choices":["Change management","Knowledge management","Customer relationship management","Quality management"],"answer":0,"explain":"Change management plans for and supports people through a change in processes or systems. The other choices cover different areas."},{"id":"bm-015","sub":"Business Finance","diff":2,"q":"A company''s current ratio is 0.8 and managers worry about paying bills due in 30 days. Which concept is most directly at issue?","choices":["Profitability","Leverage","Market value","Liquidity"],"answer":3,"explain":"Liquidity is the ability to meet short-term obligations. A current ratio below 1.0 means current assets do not cover current liabilities. Leverage concerns long-term debt."},{"id":"bm-016","sub":"Operations","diff":3,"q":"A furniture maker switches from one distant overseas supplier to two regional suppliers and cuts average lead time from 12 weeks to 3 weeks. Which effect on performance is most likely?","choices":["Higher inventory carrying costs","Faster response to demand and fewer stockouts","Lower product quality by definition","Higher long-term debt"],"answer":1,"explain":"Shorter lead times improve responsiveness and reduce stockouts. Lower quality and higher debt do not follow from the change described."},{"id":"bm-017","sub":"Strategic Management","diff":3,"q":"A call centre wants to know whether customers get their issue resolved on the first contact. Which metric best matches that goal?","choices":["Average handle time","Employee tenure","First-contact resolution rate","Calls received per month"],"answer":2,"explain":"First-contact resolution rate measures the goal directly. Average handle time measures speed, and pushing it down can work against resolution."},{"id":"bm-018","sub":"Business Environment","diff":3,"q":"A manufacturer sells in several countries and must change its product labelling for each market''s rules. Which environmental factor is most directly affecting its operations?","choices":["Global legal and regulatory environment","Technological environment","Demographic environment","Natural resource environment"],"answer":0,"explain":"Differing labelling rules across countries are part of the global legal and regulatory environment. Demographics and technology are not the direct driver here."},{"id":"bm-019","sub":"Management Types","diff":3,"q":"A company builds a searchable repository where employees store lessons learned from past projects and share best practices. Which management type is this?","choices":["Quality management","Supply chain management","Risk management","Knowledge management"],"answer":3,"explain":"Capturing, storing, and sharing organizational know-how is knowledge management."},{"id":"bm-020","sub":"Strategic Management","diff":3,"q":"A company sets a goal of raising market share by 4 points in 12 months and chooses the tactics to reach it. Which management function does this represent?","choices":["Organizing","Planning","Leading","Controlling"],"answer":1,"explain":"Setting objectives and choosing the means to reach them is planning. Controlling comes later when results are compared to the plan."},{"id":"bm-021","sub":"Business Finance","diff":1,"q":"A company reports net income of $120,000, yet its cash balance fell during the year. Which statement best explains the difference?","choices":["Net income always equals cash flow","Depreciation reduces cash on hand","Accrual accounting records revenue and expenses when earned or incurred, so timing differs from cash movement","Dividends are an operating expense"],"answer":2,"explain":"Under accrual accounting, net income and cash flow can differ in timing. Depreciation is a non-cash expense, and dividends are not operating expenses."},{"id":"bm-022","sub":"Operations","diff":1,"q":"Which statement about a business process is most accurate?","choices":["It transforms inputs into outputs through a sequence of linked activities","It is a one-time event with no outputs","It is a financial statement of the firm","It applies only to human resources"],"answer":0,"explain":"A business process is a set of linked activities that turns inputs into outputs. The other choices misdescribe the concept."},{"id":"bm-023","sub":"Strategic Management","diff":1,"q":"A CEO wants employees to behave ethically, so the firm adopts a written code of conduct, trains staff on it, and rewards compliance. Which element of managerial ethics is being built?","choices":["Corporate tax planning","A strategic alliance","Lean manufacturing","An ethical climate supported by a formal ethics program"],"answer":3,"explain":"A code of conduct, training, and reward systems form a formal ethics program that shapes the ethical climate. The other choices are unrelated to ethics."},{"id":"bm-024","sub":"Management Types","diff":1,"q":"A hospital standardizes its patient intake forms and tracks error rates against a target so that defects drop. Which management type is most directly involved?","choices":["Customer relationship management","Quality management","Human resources management","Information management"],"answer":1,"explain":"Standardizing processes and measuring defect rates against targets is quality management."},{"id":"bm-025","sub":"Business Environment","diff":1,"q":"A U.S. business decides to incorporate rather than remain a sole proprietorship. What is the most important legal consequence for the owners?","choices":["Owners'' personal assets are fully exposed to business debts","Owners pay taxes only at the entity level","Owners have limited liability for business debts","Owners lose the right to vote on decisions"],"answer":2,"explain":"Incorporation generally limits shareholders'' personal liability to their investment. The other choices misstate the effect of incorporating."},{"id":"bm-026","sub":"Business Finance","diff":1,"q":"A company earns revenue of $800,000, has cost of goods sold of $500,000, and operating expenses of $200,000. What is gross profit?","choices":["$300,000","$100,000","$500,000","$800,000"],"answer":0,"explain":"Gross profit is revenue minus cost of goods sold: $800,000 minus $500,000 is $300,000. Subtracting operating expenses gives operating income, not gross profit."},{"id":"bm-027","sub":"Management Types","diff":1,"q":"A company relies on a single supplier for a critical component. A flood shuts that supplier down and halts production for weeks. Which supply chain impact best describes this event?","choices":["Improved economies of scale","Reduced inventory risk","Higher quality control","Supply chain disruption from lack of supplier diversification"],"answer":3,"explain":"Depending on one source creates vulnerability to disruption. The other choices describe benefits or effects that do not match the event."},{"id":"bm-028","sub":"Strategic Management","diff":2,"q":"A manager measures staff against monthly targets and then corrects any gaps. Which sequence correctly describes the control process?","choices":["Hire staff, train staff, evaluate staff, dismiss staff","Set standards, measure performance, compare to standards, take corrective action","Forecast demand, buy inventory, sell product, close books","Draft mission, write vision, list values, publish"],"answer":1,"explain":"The control process is: set standards, measure performance, compare results to standards, and take corrective action where needed."},{"id":"bm-029","sub":"Management Types","diff":2,"q":"A company is worried about legal compliance and wants a formal approach to identify, rate, and respond to threats to its objectives. Which management type fits best?","choices":["Project management","Knowledge management","Risk management","Supply chain management"],"answer":2,"explain":"Identifying, assessing, and responding to threats to objectives is risk management."},{"id":"bm-030","sub":"Business Environment","diff":2,"q":"A company''s CEO states that the firm will be the most trusted brand in its industry within ten years. Which element of strategic management does this statement represent?","choices":["Vision statement","Code of conduct","Budget","Organizational chart"],"answer":0,"explain":"A vision statement describes the desired future state. A code of conduct governs behaviour, and a budget and organization chart serve other purposes."},{"id":"bm-031","sub":"Strategic Management","diff":2,"q":"A company compares its budgeted expenses for the year to actual expenses to find out why profits fell. Which financial tool is it using?","choices":["Ratio analysis","Break-even analysis","Discounted cash flow","Variance analysis"],"answer":3,"explain":"Comparing budget to actual results to explain differences is variance analysis."},{"id":"bm-032","sub":"Operations","diff":2,"q":"Why do companies study their business processes?","choices":["To eliminate all managers","To find waste, reduce cycle time, and improve quality and cost","To avoid all business risk","To set the company''s stock price"],"answer":1,"explain":"Process study targets waste, cycle time, quality, and cost. The other choices are not purposes of process analysis."},{"id":"bm-033","sub":"Strategic Management","diff":2,"q":"Employees have proposed a new approach that changes their daily work. The manager wants to reduce conflict and build support before implementing it. Which approach is most suitable?","choices":["Implement immediately and skip communication","Remove the employees who object","Involve employees in planning and explain the reasons for the change","Ignore the proposal until next year"],"answer":2,"explain":"Involving employees and explaining the reasons builds support and reduces resistance. The other options ignore people''s needs or act against them."},{"id":"bm-034","sub":"Management Types","diff":2,"q":"A retailer records each customer''s purchases, preferences, and service history to tailor offers. Which management type is this?","choices":["Customer relationship management","Supply chain management","Quality management","Operations management"],"answer":0,"explain":"Using customer data to manage and personalize relationships is customer relationship management."},{"id":"bm-035","sub":"Business Environment","diff":2,"q":"A multinational firm faces a sudden change in exchange rates that raises the cost of its imported parts. Which environment is most directly involved?","choices":["Technological environment","Social environment","Political environment","Economic environment"],"answer":3,"explain":"Exchange rates and input costs are part of the economic environment. The other environments do not drive this change directly."},{"id":"bm-036","sub":"Strategic Management","diff":3,"q":"Management theory lists four managerial functions. Which set is correct?","choices":["Planning, budgeting, hiring, auditing","Planning, organizing, leading, controlling","Forecasting, purchasing, selling, reporting","Recruiting, training, leading, evaluating"],"answer":1,"explain":"The four functions are planning, organizing, leading, and controlling. The other sets mix in activities that fall within these functions."},{"id":"bm-037","sub":"Business Finance","diff":3,"q":"A company has $60,000 in current assets and $40,000 in current liabilities. What is its working capital?","choices":["$60,000","$40,000","$20,000","$100,000"],"answer":2,"explain":"Working capital is current assets minus current liabilities: $60,000 minus $40,000 is $20,000."},{"id":"bm-038","sub":"Operations","diff":3,"q":"A manager wants to measure the time from receiving an order to delivering the product. Which measure is this?","choices":["Lead time","Gross margin","Debt-to-equity ratio","Return on assets"],"answer":0,"explain":"The elapsed time from order to delivery is lead time (or cycle time). The other measures are financial ratios."},{"id":"bm-039","sub":"Strategic Management","diff":3,"q":"Managers decide which tasks to group into departments and who reports to whom. Which managerial function is this?","choices":["Controlling","Leading","Planning","Organizing"],"answer":3,"explain":"Grouping tasks and setting reporting lines is organizing."},{"id":"bm-040","sub":"Business Environment","diff":3,"q":"Which statement best describes a sole proprietorship?","choices":["A business owned by shareholders with limited liability","A business owned by one person with no legal separation from the owner, who is personally liable for its debts","A business owned by a partnership of at least two investors and taxed as a corporation","A non-profit organization exempt from income tax"],"answer":1,"explain":"A sole proprietorship has one owner who is personally liable for business debts. The other choices describe corporations, partnerships, and non-profits."},{"id":"bm-041","sub":"Management Types","diff":1,"q":"A company sets a goal to cut its product defect rate from 4% to 1% within a year, using standardized measurement and continuous improvement. Which approach is this?","choices":["Just-in-time inventory","Activity-based costing","Total quality management","Zero-based budgeting"],"answer":2,"explain":"Total quality management focuses on continuous improvement and measured quality outcomes across the organization."},{"id":"bm-042","sub":"Business Finance","diff":1,"q":"A company''s accounts receivable turnover is low, so customers take a long time to pay. Which action most directly addresses the liquidity concern?","choices":["Tighten credit terms and follow up on overdue invoices","Increase the dividend payout to shareholders","Offer longer payment terms to new buyers","Buy new equipment with cash on hand"],"answer":0,"explain":"Tightening credit and collecting overdue invoices speeds cash inflows. The other choices reduce cash or slow collections."},{"id":"bm-043","sub":"Operations","diff":1,"q":"A company sets inventory levels using just-in-time principles. What is the main benefit?","choices":["It eliminates all demand uncertainty","It requires the largest warehouse space","It removes the need for suppliers","It cuts carrying costs and waste by receiving inventory close to when it is needed"],"answer":3,"explain":"JIT reduces carrying costs and waste by timing deliveries to need. It does not eliminate demand uncertainty or suppliers."},{"id":"bm-044","sub":"Strategic Management","diff":1,"q":"A company links pay to goals that each employee and manager set together. Which motivational approach is this?","choices":["Scientific management","Management by objectives","Bureaucratic management","Theory X management"],"answer":1,"explain":"Management by objectives sets jointly agreed goals and ties rewards to achieving them."},{"id":"bm-045","sub":"Business Environment","diff":1,"q":"Managers analyze the number of potential customers, their ages, and income levels before choosing store locations. Which environment is most directly analyzed?","choices":["Technological environment","Legal environment","Demographic environment","Natural environment"],"answer":2,"explain":"Population size, age, and income are demographic factors."},{"id":"bm-046","sub":"Management Types","diff":1,"q":"A company keeps a second qualified vendor for a key part because its main vendor could go bankrupt. Which risk response is this?","choices":["Risk reduction","Risk transfer","Risk avoidance","Risk acceptance"],"answer":0,"explain":"Having a backup source lowers the likelihood and impact of a supply failure, which is risk reduction."},{"id":"bm-047","sub":"Operations","diff":1,"q":"A company wants to know how intensively its machinery is used relative to what it could produce. Which measure best reflects this?","choices":["Current ratio","Debt ratio","Gross margin","Capacity utilization rate"],"answer":3,"explain":"Capacity utilization compares actual output with maximum capacity. The other measures are financial ratios."},{"id":"bm-048","sub":"Strategic Management","diff":2,"q":"A firm''s net profit margin is 6% and its sales are $2,000,000. What is its net income?","choices":["$12,000","$120,000","$33,333","$1,200,000"],"answer":1,"explain":"Net income is margin times sales: 6% of $2,000,000 is $120,000."},{"id":"bm-049","sub":"Strategic Management","diff":2,"q":"Leaders want an organizational culture that supports open communication. Which step most directly supports this in the leading function?","choices":["Restrict information to senior staff","Eliminate team meetings","Communicate openly, model the behaviour, and recognize staff who raise concerns","Standardize all job titles"],"answer":2,"explain":"Leaders build open culture by communicating, modelling the behaviour, and rewarding it. The other options restrict or remove communication."},{"id":"bm-050","sub":"Management Types","diff":2,"q":"Which human resources activity most directly determines the skills a business needs before it recruits?","choices":["Human resource planning","Payroll processing","Employee discipline","Retirement counselling"],"answer":0,"explain":"Human resource planning forecasts the skills and headcount the business needs, which guides recruiting."},{"id":"bm-051","sub":"Strategic Management","diff":2,"q":"A firm groups employees into marketing, finance, and production units, each reporting to a senior manager. Which organizational design is this?","choices":["Product structure","Team structure","Network structure","Functional structure"],"answer":3,"explain":"Grouping by business function is a functional structure. Product structures group by product line."},{"id":"bm-052","sub":"Management Types","diff":2,"q":"A company cuts its suppliers from 40 to 8 to gain volume discounts and simpler management. Which risk should managers monitor most closely?","choices":["A higher number of quality audits","Dependence on fewer suppliers that may raise disruption risk","An increase in the number of contracts","Greater logistics fragmentation"],"answer":1,"explain":"Fewer suppliers can bring discounts but increase the impact of any single disruption."},{"id":"bm-053","sub":"Strategic Management","diff":2,"q":"Results will be reviewed every week against the plan, with exceptions reported immediately. Which part of the control process is being emphasized?","choices":["Hiring new staff","Designing the company logo","Measuring performance against standards and reporting variances","Negotiating a merger"],"answer":2,"explain":"Weekly review against the plan, with exceptions reported, is measuring performance against standards and reporting variances."},{"id":"bm-054","sub":"Business Finance","diff":2,"q":"A company issues $100,000 of bonds at 5% interest. Annual interest expense is $5,000 regardless of profit. Which term describes this obligation?","choices":["Fixed financing cost","Operating expense","Dividend","Depreciation"],"answer":0,"explain":"Interest on debt is a fixed financing cost that creates leverage. It is not an operating expense, a dividend, or depreciation."},{"id":"bm-055","sub":"Management Types","diff":2,"q":"A company uses continuous improvement in its operations. Which is the best example?","choices":["Buying a single large machine once","Ending a product line permanently","Changing the company name","Regularly reviewing a process and making small changes that reduce waste over time"],"answer":3,"explain":"Continuous improvement is ongoing, incremental refinement of processes."},{"id":"bm-056","sub":"Business Environment","diff":3,"q":"A market has low entry barriers and many new firms can enter easily. Which competitive force is most directly described?","choices":["Bargaining power of buyers","Threat of new entrants","Threat of substitutes","Rivalry among existing firms"],"answer":1,"explain":"Low barriers to entry describe the threat of new entrants in Porter''s five forces."},{"id":"bm-057","sub":"Strategic Management","diff":3,"q":"A company''s stated purpose is to provide affordable healthy food to every community it serves. Which element of strategic management is this?","choices":["Budget","Organizational chart","Mission statement","Performance appraisal"],"answer":2,"explain":"A mission statement describes the organization''s purpose and what it does for whom."},{"id":"bm-058","sub":"Management Types","diff":3,"q":"A company uses a formal process to identify, evaluate, and monitor threats to its information systems, including data breaches. Which management type is most directly involved?","choices":["Risk management","Customer relationship management","Human resource management","Supply chain management"],"answer":0,"explain":"Identifying and monitoring threats to information systems and their consequences is risk management."},{"id":"bm-059","sub":"Business Finance","diff":3,"q":"A company''s gross margin is 40% on sales of $500,000. What is its cost of goods sold?","choices":["$200,000","$400,000","$500,000","$300,000"],"answer":3,"explain":"Gross margin of 40% means COGS is 60% of sales: 0.60 times $500,000 is $300,000."},{"id":"bm-060","sub":"Operations","diff":3,"q":"A company has a lead time of 10 days and average daily demand of 50 units. With no safety stock, what is the reorder point?","choices":["200 units","500 units","50 units","10 units"],"answer":1,"explain":"Reorder point is lead-time demand: 10 days times 50 units per day is 500 units."},{"id":"bm-061","sub":"Strategic Management","diff":1,"q":"Which statement best describes the four perspectives of a balanced scorecard?","choices":["Sales, marketing, finance, and legal","Revenue, cost, profit, and tax","Financial, customer, internal business process, and learning and growth","Strategy, tactics, operations, and budget"],"answer":2,"explain":"The balanced scorecard uses financial, customer, internal process, and learning and growth perspectives."},{"id":"bm-062","sub":"Business Environment","diff":1,"q":"A company faces a new technology that could replace its product entirely. Which competitive force is this?","choices":["Threat of substitutes","Bargaining power of suppliers","Rivalry among competitors","Threat of new entrants"],"answer":0,"explain":"A product that could be replaced by a different product or technology is a threat of substitutes."},{"id":"bm-063","sub":"Management Types","diff":1,"q":"A company''s data governance policy requires personal customer information to be encrypted and access logged. Which management type is most directly involved?","choices":["Supply chain management","Project management","Change management","Information management"],"answer":3,"explain":"Protecting and controlling access to information is information management."},{"id":"bm-064","sub":"Operations","diff":1,"q":"A company runs a push system, producing to forecast. Compared with a pull system that produces to actual orders, what is the typical drawback of push?","choices":["Longer order cycle times by definition","Higher risk of excess inventory when forecasts are wrong","No need for supplier coordination","Lower need for production scheduling"],"answer":1,"explain":"Producing to forecast can build excess inventory when demand falls short of the forecast."},{"id":"bm-065","sub":"Business Environment","diff":1,"q":"A company''s flattened structure now has three approval levels instead of seven. Which organizational design change is this?","choices":["Vertical integration","Horizontal merger","Flattening the organizational structure","Divestiture"],"answer":2,"explain":"Reducing layers of management is flattening the structure. The other options are strategic moves, not structural changes."},{"id":"bm-066","sub":"Business Environment","diff":1,"q":"A state law requires environmental impact reports before a company can build a plant. Which environment is this?","choices":["Legal-regulatory environment","Technological environment","Social environment","Competitive environment"],"answer":0,"explain":"Government requirements for permits and reports are part of the legal-regulatory environment."},{"id":"bm-067","sub":"Strategic Management","diff":1,"q":"A manager delegates authority to team leaders. Which managerial consideration does this illustrate?","choices":["Controlling","Forecasting","Auditing","Organizing"],"answer":3,"explain":"Delegation distributes authority and responsibility, a part of organizing."},{"id":"bm-068","sub":"Business Finance","diff":2,"q":"A consulting firm delivers $30,000 of services in December and collects the cash in January. Under accrual accounting, when is the revenue recognized?","choices":["January","December","Split equally between the two months","Only when cash is collected"],"answer":1,"explain":"Accrual accounting recognizes revenue when earned, which is when the service is delivered in December."},{"id":"bm-069","sub":"Operations","diff":2,"q":"A company''s cost of goods sold is $900,000 and its average inventory is $150,000. What is its inventory turnover?","choices":["4 times","8 times","6 times","0.17 times"],"answer":2,"explain":"Inventory turnover is COGS divided by average inventory: $900,000 divided by $150,000 is 6."},{"id":"bm-070","sub":"Strategic Management","diff":2,"q":"Which statement describes the assumptions of Theory X management?","choices":["Workers dislike work and need close supervision","Workers seek responsibility and self-direction","Workers are motivated mainly by teamwork","Workers ignore pay entirely"],"answer":0,"explain":"Theory X assumes workers avoid work and need direction and control, in contrast with Theory Y."},{"id":"bm-071","sub":"Business Environment","diff":2,"q":"A CEO promises to cut carbon emissions per unit by 20%, in response to stakeholder expectations. Which environment is this most closely linked to?","choices":["Technological environment","Economic environment","Demographic environment","Social and ethical environment"],"answer":3,"explain":"Stakeholder expectations about environmental responsibility are part of the social environment."},{"id":"bm-072","sub":"Business Environment","diff":2,"q":"Which U.S. business form gives owners limited liability and an unlimited life that continues beyond any one owner?","choices":["Sole proprietorship","Corporation","General partnership","Joint venture between two individuals"],"answer":1,"explain":"A corporation gives limited liability and perpetual existence. Sole proprietorships and general partnerships expose owners to personal liability."},{"id":"bm-073","sub":"Strategic Management","diff":2,"q":"A company''s debt-to-equity ratio is 2.0. What does this indicate?","choices":["It has twice as much equity as debt","It has no debt","It has twice as much debt as equity financing","Its assets are twice its liabilities"],"answer":2,"explain":"A debt-to-equity ratio of 2.0 means debt is twice equity."},{"id":"bm-074","sub":"Management Types","diff":2,"q":"In a Gantt chart, what does a bar represent?","choices":["The scheduled duration of a task","The cost of each resource","The number of defects","The customer''s satisfaction score"],"answer":0,"explain":"Each bar shows a task''s start, end, and duration on a timeline."},{"id":"bm-075","sub":"Strategic Management","diff":2,"q":"Which pair correctly identifies internal factors in a SWOT analysis?","choices":["Opportunities and threats","Revenue and costs","Suppliers and customers","Strengths and weaknesses"],"answer":3,"explain":"Strengths and weaknesses are internal. Opportunities and threats are external."},{"id":"bm-076","sub":"Management Types","diff":3,"q":"A board requires a formal succession plan for key executives. Which HR area is this?","choices":["Payroll accounting","Human resource planning","Labour relations","Employee benefits administration"],"answer":1,"explain":"Succession planning identifies future leaders and is part of human resource planning."},{"id":"bm-077","sub":"Business Finance","diff":3,"q":"A company sells goods on credit for $5,000. Which account is credited to record the sale?","choices":["Cash","Accounts payable","Sales revenue","Inventory"],"answer":2,"explain":"The sale is debited to accounts receivable and credited to sales revenue."},{"id":"bm-078","sub":"Management Types","diff":3,"q":"A quality team uses statistical process control charts. What is their primary purpose?","choices":["To monitor whether a process stays within expected variation","To set the annual budget","To measure employee satisfaction","To determine interest rates"],"answer":0,"explain":"Control charts track process variation over time to detect when a process goes out of control."},{"id":"bm-079","sub":"Strategic Management","diff":3,"q":"A manager uses management by exception. What does this mean?","choices":["Managers ignore all results","Managers review every transaction equally","Managers delegate all decisions","Managers focus on significant deviations from plan rather than routine results"],"answer":3,"explain":"Management by exception directs attention to significant deviations from plan."},{"id":"bm-080","sub":"Management Types","diff":3,"q":"Which human resources function most directly ensures the firm follows federal overtime and minimum-wage rules?","choices":["Supply chain management","Labour compliance within human resources management","Knowledge management","Quality management"],"answer":1,"explain":"Labour compliance in HR covers wage and hour rules such as the federal Fair Labor Standards Act."},{"id":"bm-081","sub":"Strategic Management","diff":1,"q":"A company''s return on equity is 15% and its net income is $300,000. What is its average shareholders'' equity?","choices":["$45,000","$20,000","$2,000,000","$4,500,000"],"answer":2,"explain":"ROE is net income divided by equity: $300,000 divided by 0.15 is $2,000,000."},{"id":"bm-082","sub":"Operations","diff":1,"q":"A company merges purchasing across its branches to lower unit costs. Which concept does this illustrate?","choices":["Economies of scale","Diseconomies of scope","Gross margin decline","Liquidity ratio"],"answer":0,"explain":"Spreading volume across branches lowers unit costs, which is economies of scale."},{"id":"bm-083","sub":"Strategic Management","diff":1,"q":"Which managerial activity is primarily part of the staffing function?","choices":["Setting the firm''s long-term strategy","Auditing financial statements","Designing marketing campaigns","Recruiting and selecting new employees"],"answer":3,"explain":"Staffing covers recruiting, selecting, training, and retaining employees."},{"id":"bm-084","sub":"Management Types","diff":1,"q":"An integrated system gives sales, production, and finance one view of customer orders and inventory. Which management type does this best reflect?","choices":["Risk management","Information management","Change management","Human resource management"],"answer":1,"explain":"Integrating data across functions for decisions is information management."},{"id":"bm-085","sub":"Business Environment","diff":1,"q":"A company expanding abroad faces new tariffs on its imports. Which environment is most directly affected?","choices":["Demographic environment","Technological environment","Global political and legal environment","Social environment"],"answer":2,"explain":"Tariffs are trade policy and fall within the global political and legal environment."},{"id":"bm-086","sub":"Business Finance","diff":1,"q":"A company has a current ratio of 2.5 and a quick ratio of 1.0. What does the gap suggest?","choices":["A large share of current assets is inventory","Cash is larger than receivables","Liabilities are growing faster than assets","Equity is negative"],"answer":0,"explain":"The quick ratio excludes inventory, so a big gap means inventory makes up much of current assets."},{"id":"bm-087","sub":"Operations","diff":1,"q":"A plant can produce 1,000 units per day and produces 800. What is its capacity utilization?","choices":["125%","20%","1.25","80%"],"answer":3,"explain":"Utilization is actual output divided by capacity: 800 divided by 1,000 is 80%."},{"id":"bm-088","sub":"Strategic Management","diff":2,"q":"Which step of the strategic management process comes after strategy formulation?","choices":["Environmental scanning","Strategy implementation","Mission drafting","Budget audit"],"answer":1,"explain":"Formulation is followed by implementation, then evaluation and control. Environmental scanning comes before formulation."},{"id":"bm-089","sub":"Business Finance","diff":2,"q":"Which term means the accounting standards used to prepare U.S. financial statements?","choices":["General Accounting Auditing Practices","Government Approved Accounting Policies","Generally Accepted Accounting Principles","Global Accounting and Auditing Procedures"],"answer":2,"explain":"GAAP is the body of accounting standards used in the United States."},{"id":"bm-090","sub":"Operations","diff":2,"q":"Which statement best defines a value-added activity?","choices":["An activity that increases the product''s worth to the customer","Any activity that increases cost","Any activity performed by management","Any activity performed at a supplier''s facility"],"answer":0,"explain":"A value-added activity is one the customer would pay for. Other activities are waste to reduce."},{"id":"bm-091","sub":"Strategic Management","diff":2,"q":"Which leadership style gives employees the most decision-making power?","choices":["Autocratic","Bureaucratic","Paternalistic","Laissez-faire"],"answer":3,"explain":"Laissez-faire leaders delegate most decisions to the group. Autocratic and paternalistic styles keep decisions with the leader."},{"id":"bm-092","sub":"Business Finance","diff":2,"q":"A company buys $500 of raw materials on credit. Which account increases?","choices":["Accounts receivable","Accounts payable","Retained earnings","Cash"],"answer":1,"explain":"Buying on credit increases inventory and accounts payable. Cash is unchanged."},{"id":"bm-093","sub":"Management Types","diff":2,"q":"A procurement team combines purchases across five plants to negotiate better terms with one shared supplier. Which management type is most directly applied?","choices":["Customer relationship management","Quality management","Supply chain management","Knowledge management"],"answer":2,"explain":"Coordinating purchasing across the supply network is supply chain management."},{"id":"bm-094","sub":"Management Types","diff":2,"q":"A company hires a consultant to lead the firm through a new enterprise system rollout that changes how staff work. Which management type applies?","choices":["Change management","Quality management","Risk management","Supply chain management"],"answer":0,"explain":"Leading people through a significant change in systems and work is change management."},{"id":"bm-095","sub":"Management Types","diff":2,"q":"A company hedges its foreign currency exposure with financial contracts to protect earnings. Which risk response is this?","choices":["Risk avoidance by exiting the market","Risk acceptance by doing nothing","Risk retention through reserves","Risk transfer through a financial hedge"],"answer":3,"explain":"A hedge shifts currency risk to a counterparty, which is risk transfer."},{"id":"bm-096","sub":"Operations","diff":3,"q":"A machine setup takes four hours and happens once per batch. Which improvement would best reduce waste from setups?","choices":["Increase the batch size without changing setup","Reduce setup time with quick-changeover methods","Hire additional managers","Reduce inventory counts"],"answer":1,"explain":"Quick-changeover methods such as SMED cut setup time, which lowers the cost of each batch."},{"id":"bm-097","sub":"Strategic Management","diff":3,"q":"Which section of a business plan describes what a new café will do to win and keep customers?","choices":["Balance sheet","Articles of incorporation","Marketing plan","Lease agreement"],"answer":2,"explain":"The marketing plan describes target customers, pricing, promotion, and distribution."},{"id":"bm-098","sub":"Business Finance","diff":3,"q":"An asset costs $50,000 with a $5,000 salvage value and a five-year life. Under straight-line depreciation, what is the annual expense?","choices":["$9,000","$10,000","$5,000","$45,000"],"answer":0,"explain":"Straight-line depreciation is (cost minus salvage) divided by life: $45,000 divided by 5 is $9,000."},{"id":"bm-099","sub":"Strategic Management","diff":3,"q":"A company''s operating plan sets specific monthly sales quotas for each territory. Which type of plan is this?","choices":["Strategic plan","Vision plan","Contingency plan","Operational plan"],"answer":3,"explain":"Short-term, specific targets are operational plans."},{"id":"bm-100","sub":"Management Types","diff":3,"q":"A company uses a Gantt chart and the critical path method to plan a project. What does the critical path identify?","choices":["The cheapest supplier for each task","The longest sequence of dependent tasks that sets the minimum project duration","The employees with the most overtime","The best-selling product"],"answer":1,"explain":"The critical path is the longest chain of dependent tasks, and it determines the shortest possible completion time."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'data-science-ai', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"dsa-001","sub":"Probability and Statistics Foundations","diff":1,"q":"What is the range of the dataset 4, 8, 8, 15, 21?","choices":["8","11.2","17","21"],"answer":2,"explain":"Range is the maximum minus the minimum, 21 - 4 = 17. The mean of 11.2 is a different measure, a trap for students who mix up terms."},{"id":"dsa-002","sub":"Probability and Statistics Foundations","diff":1,"q":"Which measure of central tendency is most affected by a single extreme outlier?","choices":["The median","The mode","The mean","The most frequent value"],"answer":2,"explain":"The mean uses every value, so one extreme value pulls it. The median and mode are resistant to outliers."},{"id":"dsa-003","sub":"Probability and Statistics Foundations","diff":3,"q":"The values 2, 4, and 6 are treated as a sample. What is the sample variance (divide the sum of squared deviations by n - 1)?","choices":["2","2.67","4","8"],"answer":2,"explain":"The mean is 4, the squared deviations are 4, 0, 4 (sum 8), and 8 / (3 - 1) = 4. Dividing by n gives 2.67, the population variance."},{"id":"dsa-004","sub":"Probability and Statistics Foundations","diff":1,"q":"A dataset has a standard deviation of 0. What does this mean?","choices":["The mean is zero","The dataset has no outliers","The values are evenly spaced","All values in the dataset are identical"],"answer":3,"explain":"Standard deviation measures spread. A value of zero means there is no spread at all, so every value is the same."},{"id":"dsa-005","sub":"Probability and Statistics Foundations","diff":2,"q":"In a normal (Gaussian) distribution, about what percentage of values fall within one standard deviation of the mean?","choices":["About 68%","About 95%","About 50%","About 99.7%"],"answer":0,"explain":"The 68-95-99.7 rule: about 68% within one SD, 95% within two, and 99.7% within three. The 95% figure is the two-SD trap."},{"id":"dsa-006","sub":"Probability and Statistics Foundations","diff":2,"q":"A fair six-sided die is rolled once. What is the expected value of the number shown?","choices":["3","4","6","3.5"],"answer":3,"explain":"The expected value is the average of the outcomes weighted by probability: (1+2+3+4+5+6)/6 = 3.5. It is not itself a possible roll."},{"id":"dsa-007","sub":"Probability and Statistics Foundations","diff":3,"q":"A raffle ticket costs $2. It pays $50 with probability 0.02 and pays nothing otherwise. What is the expected net gain per ticket?","choices":["-$1.00 per ticket","+$1.00 per ticket","-$0.50 per ticket","$0.00 per ticket"],"answer":0,"explain":"Expected payout is 0.02 x $50 = $1.00. Subtracting the $2 cost gives an expected net of -$1.00 per ticket."},{"id":"dsa-008","sub":"Probability and Statistics Foundations","diff":1,"q":"The number of customers who enter a store on a Monday (0, 1, 2, 3, ...) is which type of variable?","choices":["Continuous","Nominal","Ordinal","Discrete"],"answer":3,"explain":"Counts that take separate whole-number values are discrete. Continuous variables can take any value within an interval."},{"id":"dsa-009","sub":"Probability and Statistics Foundations","diff":1,"q":"A survey asks people to rate service as poor, fair, good, or excellent. What type of variable is this?","choices":["Ordinal","Nominal","Continuous","Discrete"],"answer":0,"explain":"The categories have a meaningful order but the gaps between them are not necessarily equal, which defines an ordinal variable."},{"id":"dsa-010","sub":"Probability and Statistics Foundations","diff":3,"q":"Events A and B are independent, with P(A) = 0.3 and P(B) = 0.5. What is P(A and B)?","choices":["0.80","0.65","0.35","0.15"],"answer":3,"explain":"Independent events multiply: 0.3 x 0.5 = 0.15. Adding the probabilities (0.80) is the trap for students who confuse AND with OR."},{"id":"dsa-011","sub":"Probability and Statistics Foundations","diff":3,"q":"The covariance between two variables is positive. What does this indicate?","choices":["The variables are causally linked","The correlation coefficient must equal 1","The variables have equal variances","The variables tend to move in the same direction"],"answer":3,"explain":"A positive covariance means the variables tend to rise and fall together. It does not prove causation, and its size depends on units, unlike correlation."},{"id":"dsa-012","sub":"Probability and Statistics Foundations","diff":2,"q":"What is the median of the dataset 9, 3, 7, 1, 5, 11?","choices":["6","5","7","6.5"],"answer":0,"explain":"Sorted: 1, 3, 5, 7, 9, 11. With an even count, the median is the average of the two middle values, (5 + 7) / 2 = 6."},{"id":"dsa-013","sub":"Probability and Statistics Foundations","diff":2,"q":"Which statement about the normal distribution is correct?","choices":["It is always skewed to the right","Its mean is always larger than its median","It is symmetric and bell-shaped, with mean, median, and mode equal","It applies only to discrete data"],"answer":2,"explain":"A normal distribution is symmetric about its mean, so the mean, median, and mode coincide. Skewed distributions are the ones with unequal measures."},{"id":"dsa-014","sub":"Probability and Statistics Foundations","diff":3,"q":"A bag holds 3 red and 2 blue marbles. Two marbles are drawn without replacement. What is the probability both are red?","choices":["3/10","9/25","1/5","3/5"],"answer":0,"explain":"First draw: 3/5. Second draw with one fewer marble: 2/4. Product is 6/20 = 3/10. The 9/25 answer is what you get with replacement, which is the trap."},{"id":"dsa-015","sub":"Probability and Statistics Foundations","diff":2,"q":"Which problem is the most direct cause of sampling bias?","choices":["A sample size that is too large","Reporting results to two decimal places","A sample that does not represent the population, such as surveying only online volunteers","Using a spreadsheet instead of a calculator"],"answer":2,"explain":"Sampling bias occurs when some members of the population are systematically more or less likely to be selected, so the sample is unrepresentative."},{"id":"dsa-016","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which visual is best for showing the distribution of a single continuous variable?","choices":["Histogram","Pie chart","Line chart over time","Scatterplot"],"answer":0,"explain":"A histogram bins a continuous variable and shows how often values fall in each range. A scatterplot is for two variables."},{"id":"dsa-017","sub":"Data Analysis and Statistics for AI","diff":2,"q":"What five values does a boxplot display?","choices":["Mean, median, mode, range, count","Minimum, Q1, median, Q3, maximum","Minimum, mean, maximum, variance, median","Q1, Q2, Q3, Q4, total"],"answer":1,"explain":"A boxplot shows the five-number summary: minimum, first quartile, median, third quartile, and maximum."},{"id":"dsa-018","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which diagram is best for examining the relationship between two numeric variables?","choices":["Histogram","Bar chart","Scatterplot","Pie chart"],"answer":2,"explain":"A scatterplot places each observation as a point on two numeric axes, which reveals association, trend, and outliers."},{"id":"dsa-019","sub":"Data Analysis and Statistics for AI","diff":2,"q":"When is multiple linear regression used?","choices":["To predict a yes or no category from one variable","To predict a numeric outcome from two or more predictor variables","To group unlabeled data into clusters","To find the most frequent value in a dataset"],"answer":1,"explain":"Multiple linear regression models a numeric outcome using several predictors. Predicting a binary category is logistic regression."},{"id":"dsa-020","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which technique predicts a binary outcome, such as approved or denied?","choices":["Linear regression","Logistic regression","K-means clustering","Principal component analysis"],"answer":1,"explain":"Logistic regression models the probability of a binary class. Linear regression predicts continuous values and k-means does not use labels."},{"id":"dsa-021","sub":"Data Analysis and Statistics for AI","diff":1,"q":"Which of these is an example of a data quality problem?","choices":["Duplicate customer records","A table with a clear data dictionary","Dates stored in one consistent format","A relational database with defined keys"],"answer":0,"explain":"Duplicate records, along with missing values and low-quality sources, are common quality problems that reduce analysis reliability."},{"id":"dsa-022","sub":"Data Analysis and Statistics for AI","diff":3,"q":"12% of the rows in an income column are missing. Which action is generally the most appropriate first step?","choices":["Delete the entire dataset","Replace every missing value with zero without checking","Investigate why the values are missing before deciding how to handle them","Drop the column from all future analysis"],"answer":2,"explain":"The cause of missingness (random or systematic) determines whether deletion, imputation, or flagging is valid. Acting before diagnosing can bias results."},{"id":"dsa-023","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which data-cleaning step removes exact repeated rows?","choices":["Normalization","Deduplication","Feature scaling","Encoding"],"answer":1,"explain":"Deduplication identifies and removes duplicate records. The other options transform values rather than remove repeated rows."},{"id":"dsa-024","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which algorithm groups unlabeled data into k clusters by minimizing distance to cluster centroids?","choices":["K-means","Decision tree","Linear regression","Naive Bayes"],"answer":0,"explain":"K-means is an unsupervised clustering method that assigns points to the nearest of k centroids and iteratively updates them."},{"id":"dsa-025","sub":"Data Analysis and Statistics for AI","diff":2,"q":"How does a decision tree decide where to split the data at each node?","choices":["By sorting the labels alphabetically","By averaging all features together","By choosing the feature test that best separates the outcome classes","By selecting random splits without testing them"],"answer":2,"explain":"Trees choose splits that maximize class separation, using measures such as Gini impurity or information gain."},{"id":"dsa-026","sub":"Data Analysis and Statistics for AI","diff":2,"q":"Which source is least reliable for training a model on public health data?","choices":["An anonymous forum post with no citation","A national statistics agency dataset","A peer-reviewed study with a documented method","A government health survey with a published codebook"],"answer":0,"explain":"Data quality depends on provenance. Uncited, anonymous sources cannot be verified, so they are the least reliable."},{"id":"dsa-027","sub":"Data Analysis and Statistics for AI","diff":3,"q":"A linear model is y = 2x + 5. What is the predicted y when x = 10?","choices":["20","25","15","52"],"answer":1,"explain":"Substitute: y = 2(10) + 5 = 25. The 52 answer comes from concatenating the digits, a careless error."},{"id":"dsa-028","sub":"Data Analysis and Statistics for AI","diff":2,"q":"A histogram of house prices is strongly right-skewed. Which measure is the better summary of a typical price?","choices":["Mean","Range","Sum","Median"],"answer":3,"explain":"Extreme high prices pull the mean upward. The median is resistant to those outliers and better represents a typical value in skewed data."},{"id":"dsa-029","sub":"Data Analysis and Statistics for AI","diff":1,"q":"A scatterplot shows points forming a tight upward diagonal. What does this suggest?","choices":["No relationship between the variables","A strong negative linear relationship","A strong positive linear relationship","A nonlinear pattern with no trend"],"answer":2,"explain":"Points rising together along a tight line indicate a strong positive linear association. Correlation does not by itself prove causation."},{"id":"dsa-030","sub":"Data Analysis and Statistics for AI","diff":3,"q":"A model scores 99% on its training data but 70% on new data. What is this pattern most likely showing?","choices":["Overfitting","Underfitting","Data leakage in the test set","Class imbalance only"],"answer":0,"explain":"A large gap between training and new-data performance means the model memorized training patterns that do not generalize, which is overfitting."},{"id":"dsa-031","sub":"Tools for Data and AI","diff":2,"q":"Which SQL clause filters groups after a GROUP BY aggregation?","choices":["WHERE","ORDER BY","SELECT","HAVING"],"answer":3,"explain":"WHERE filters individual rows before grouping. HAVING filters on aggregated results, such as groups whose COUNT exceeds a threshold."},{"id":"dsa-032","sub":"Tools for Data and AI","diff":1,"q":"Which SQL statement returns only distinct values from a column?","choices":["SELECT UNIQUE","SELECT ONLY","SELECT GROUP","SELECT DISTINCT"],"answer":3,"explain":"SELECT DISTINCT removes duplicate values from the result. Other keywords are not standard SQL for this purpose."},{"id":"dsa-033","sub":"Tools for Data and AI","diff":3,"q":"Which SQL query returns the average salary for each department?","choices":["SELECT dept, AVG(salary) FROM employees GROUP BY dept;","SELECT dept, SUM(salary) FROM employees GROUP BY dept;","SELECT AVG(salary) FROM employees WHERE dept;","SELECT dept, AVG(salary) FROM employees ORDER BY salary;"],"answer":0,"explain":"AVG with GROUP BY produces one average per department. SUM gives totals, and ORDER BY does not aggregate."},{"id":"dsa-034","sub":"Tools for Data and AI","diff":1,"q":"Which Python library is primarily used for working with tabular data frames?","choices":["PyTorch","Pandas","Matplotlib","Flask"],"answer":1,"explain":"Pandas provides the DataFrame structure for loading, cleaning, and analyzing tabular data. PyTorch is for deep learning and Matplotlib is for plotting."},{"id":"dsa-035","sub":"Tools for Data and AI","diff":2,"q":"Which library is most commonly used to build and train deep neural networks in Python?","choices":["Pandas","PyTorch","Matplotlib","Seaborn"],"answer":1,"explain":"PyTorch is a major deep learning framework. Pandas handles data tables, and Matplotlib and Seaborn handle visualization."},{"id":"dsa-036","sub":"Tools for Data and AI","diff":3,"q":"Which pandas method removes rows containing missing values from a DataFrame df?","choices":["df.fillna()","df.drop_duplicates()","df.dropna()","df.isnull()"],"answer":2,"explain":"dropna() removes rows with missing values by default. fillna() replaces them, drop_duplicates() removes repeats, and isnull() only flags them."},{"id":"dsa-037","sub":"Tools for Data and AI","diff":2,"q":"Which family of R packages is widely used for data manipulation and visualization?","choices":["Pandas","Tidyverse","NumPy","Keras"],"answer":1,"explain":"The tidyverse (including dplyr and ggplot2) is a core R toolkit. Pandas is a Python library, a common trap."},{"id":"dsa-038","sub":"Tools for Data and AI","diff":2,"q":"Which property ensures a foreign key value refers to an existing primary key row?","choices":["Normalization","Atomicity","Indexing","Referential integrity"],"answer":3,"explain":"Referential integrity requires that every foreign key match an existing primary key or be null. Atomicity is a transaction property."},{"id":"dsa-039","sub":"Tools for Data and AI","diff":1,"q":"In a relational database, what is a primary key?","choices":["A column that must always contain duplicates","A column or set of columns that uniquely identifies each row","Any column that holds numeric data","A table that links two other tables"],"answer":1,"explain":"A primary key uniquely identifies each record and cannot be null. A table that links others is a junction table, a different concept."},{"id":"dsa-040","sub":"Tools for Data and AI","diff":3,"q":"A table has customer_id, customer_name, and order_id, and customer names repeat across many orders. Which change best applies normalization?","choices":["Add customer_name to every order row","Move customers into their own table linked to orders by customer_id","Combine all names into one long text column","Delete the customer_id column"],"answer":1,"explain":"Normalization separates repeated entities into their own tables and links them with keys, which removes redundant storage and update anomalies."},{"id":"dsa-041","sub":"AI Basics","diff":1,"q":"Generative AI is best described as AI that:","choices":["Creates new content such as text, images, or code based on patterns in training data","Only classifies existing data into predefined labels","Stores and retrieves data from a database","Controls physical robots using fixed rules only"],"answer":0,"explain":"Generative models produce new outputs that resemble their training data. Classification alone is a different AI task."},{"id":"dsa-042","sub":"AI Basics","diff":2,"q":"Which is a documented limitation of generative AI?","choices":["It always cites its sources accurately","It cannot generate any text","It can produce confident but false statements","It never reflects bias from its training data"],"answer":2,"explain":"Generative models can hallucinate, presenting false content fluently. They can also reflect bias present in training data."},{"id":"dsa-043","sub":"AI Basics","diff":1,"q":"Which is an example of a use of generative AI in healthcare?","choices":["Measuring blood pressure with a manual cuff","Drafting summaries of clinical notes for a physician to review","Scheduling cleaning crews for hospital wings","Printing paper patient charts"],"answer":1,"explain":"Generative AI can draft text such as note summaries, which clinicians then review. The other options are not generative AI tasks."},{"id":"dsa-044","sub":"AI Basics","diff":1,"q":"Which AI subfield enables a computer to interpret images and video?","choices":["Natural language processing","Robotics","Computer vision","Expert systems"],"answer":2,"explain":"Computer vision extracts meaning from visual data such as images and video. NLP handles language."},{"id":"dsa-045","sub":"AI Basics","diff":1,"q":"Which AI subfield focuses on enabling computers to understand and generate human language?","choices":["Computer vision","Robotics","Knowledge representation","Natural language processing"],"answer":3,"explain":"Natural language processing covers tasks such as translation, sentiment analysis, and text generation."},{"id":"dsa-046","sub":"AI Basics","diff":2,"q":"What does the term large language model (LLM) refer to?","choices":["A neural network trained on very large text datasets to predict and generate language","A database that stores every word in a dictionary","A rule-based chatbot with fixed scripts","A spreadsheet tool for analyzing text"],"answer":0,"explain":"LLMs are neural networks trained on large corpora to predict the next token, which lets them generate language. They are not rule-based."},{"id":"dsa-047","sub":"AI Basics","diff":3,"q":"Which is a capability of large language models?","choices":["Guaranteeing the factual accuracy of every answer","Accessing live data without any tools or retrieval","Physically moving objects in a warehouse","Summarizing long documents and answering questions about them"],"answer":3,"explain":"LLMs are good at summarizing and answering questions from text. They do not guarantee accuracy and cannot access live data without tools."},{"id":"dsa-048","sub":"AI Basics","diff":3,"q":"An LLM is asked for a legal case citation and invents one that does not exist. What is this called?","choices":["Overfitting","Hallucination","Data leakage","Underfitting"],"answer":1,"explain":"A hallucination is fluent, plausible output that is not grounded in fact. Overfitting and underfitting describe training behavior, not individual outputs."},{"id":"dsa-049","sub":"AI Basics","diff":2,"q":"A worker pastes confidential client data into a public LLM service. What is the main risk?","choices":["The model will refuse to answer any later question","The data becomes a verified public record","The data may be retained or used for training, creating a privacy exposure","The service will automatically encrypt the data permanently"],"answer":2,"explain":"Data submitted to some services may be stored or used for improvement, so confidential information should not be shared without approval."},{"id":"dsa-050","sub":"AI Basics","diff":1,"q":"Which term describes AI that performs a single, narrowly defined task, such as spam filtering?","choices":["General AI","Narrow AI","Superintelligence","Hybrid AI"],"answer":1,"explain":"Narrow (weak) AI is designed for one task. General AI would perform across many tasks at human level, which does not yet exist."},{"id":"dsa-051","sub":"Machine Learning","diff":1,"q":"What is the core idea of machine learning?","choices":["Algorithms learn patterns from data to make predictions without a programmer writing every rule","Programmers write every decision rule by hand","Computers store data without processing it","Data is deleted after each analysis to protect privacy"],"answer":0,"explain":"Machine learning infers rules from data rather than relying on hand-coded logic."},{"id":"dsa-052","sub":"Machine Learning","diff":1,"q":"Which dataset is used to tune hyperparameters and compare candidate models during development?","choices":["Test set","Training set","Validation set","Production set"],"answer":2,"explain":"The validation set guides model selection. The test set is reserved for a final, one-time performance estimate."},{"id":"dsa-053","sub":"Machine Learning","diff":3,"q":"Which dataset is held out and used only once, at the end, to estimate performance on unseen data?","choices":["Validation set","Training set","Feature set","Test set"],"answer":3,"explain":"Using the test set repeatedly for tuning leaks information into the model. It is kept separate for the final estimate."},{"id":"dsa-054","sub":"Machine Learning","diff":1,"q":"Which learning type uses labeled examples to predict a known outcome?","choices":["Unsupervised learning","Supervised learning","Reinforcement learning","Clustering"],"answer":1,"explain":"Supervised learning trains on input-label pairs. Unsupervised learning works without labels."},{"id":"dsa-055","sub":"Machine Learning","diff":2,"q":"Which learning type improves through rewards and penalties from actions taken in an environment?","choices":["Reinforcement learning","Supervised learning","Unsupervised learning","Dimensionality reduction"],"answer":0,"explain":"Reinforcement learning learns a policy that maximizes cumulative reward through trial and error."},{"id":"dsa-056","sub":"Machine Learning","diff":2,"q":"A retailer groups customers by purchase behavior with no predefined labels. Which approach fits?","choices":["Supervised regression","Reinforcement learning","Unsupervised learning (clustering)","Supervised classification"],"answer":2,"explain":"With no labels and a goal of finding natural groups, clustering is an unsupervised method."},{"id":"dsa-057","sub":"Machine Learning","diff":3,"q":"What is the basic building block of a neural network that combines weighted inputs and applies an activation function?","choices":["A hyperplane","A neuron (node)","A decision node","A cluster centroid"],"answer":1,"explain":"Each neuron computes a weighted sum of inputs, passes it through an activation function, and sends the output to the next layer."},{"id":"dsa-058","sub":"Machine Learning","diff":2,"q":"Which description best fits deep learning?","choices":["Machine learning that never uses data","Storing large datasets in deep cloud storage","A subset of machine learning that uses neural networks with many layers to learn hierarchical features","Any algorithm that runs on a server"],"answer":2,"explain":"Deep learning uses multi-layer neural networks to learn increasingly abstract representations from data."},{"id":"dsa-059","sub":"Machine Learning","diff":2,"q":"Which description best fits a decision tree?","choices":["A method that sorts data into a binary search tree of records","A visual map of all database relationships","A neural network with exactly one layer","A model that splits data by feature tests and ends in leaf nodes that give predictions"],"answer":3,"explain":"Decision trees repeatedly split data on feature tests. Each leaf holds a prediction, which makes the model easy to interpret."},{"id":"dsa-060","sub":"Machine Learning","diff":3,"q":"A model is 98% accurate on a dataset where 98% of cases are negative because it predicts negative every time. Which measure best reveals its weakness?","choices":["Model file size","Number of hidden layers","Training runtime in seconds","Recall for the positive class"],"answer":3,"explain":"Recall measures how many true positives are found. Predicting all negatives gives zero recall on the positive class, exposing the failure that accuracy hides."},{"id":"dsa-061","sub":"Perception, Representation, and Reasoning","diff":1,"q":"In predicate logic, the symbol for ''for all'' (as in ''for all x, ...'') is called what?","choices":["Universal quantifier","Existential quantifier","Conditional operator","Negation"],"answer":0,"explain":"The universal quantifier (for all) asserts a property holds for every element. The existential quantifier means ''there exists''."},{"id":"dsa-062","sub":"Perception, Representation, and Reasoning","diff":3,"q":"Which predicate logic statement means ''some student passed the exam''?","choices":["For all x, if Student(x) then Passed(x)","There exists x such that Student(x) implies Passed(x)","For all x, Student(x) and Passed(x)","There exists x such that Student(x) and Passed(x)"],"answer":3,"explain":"''Some'' uses an existential quantifier combined with AND. Using implication with ''exists'' is a trap, since it is true for any non-student."},{"id":"dsa-063","sub":"Perception, Representation, and Reasoning","diff":1,"q":"Which of these is a predicate rather than a constant?","choices":["Alex","42","IsTaller(x, y)","The number seven"],"answer":2,"explain":"A predicate is a property or relation that takes arguments and is true or false. Alex, 42, and seven are constants denoting objects."},{"id":"dsa-064","sub":"Perception, Representation, and Reasoning","diff":3,"q":"What is the main difference between logic-based and probability-based reasoning?","choices":["Logic-based reasoning uses random sampling; probability-based reasoning uses fixed rules","Logic-based reasoning works only on numbers; probability-based reasoning works only on text","They are identical except for the programming language used","Logic-based reasoning draws certain conclusions from rules; probability-based reasoning assigns degrees of belief to uncertain conclusions"],"answer":3,"explain":"Logic-based systems derive conclusions that follow strictly from rules. Probabilistic systems quantify uncertainty."},{"id":"dsa-065","sub":"Perception, Representation, and Reasoning","diff":2,"q":"In a Bayesian network, what do the nodes represent?","choices":["Edge weights","Training examples","Random variables","Loss functions"],"answer":2,"explain":"Nodes are random variables, and directed edges encode probabilistic dependencies between them."},{"id":"dsa-066","sub":"Perception, Representation, and Reasoning","diff":2,"q":"What structural property must the graph underlying a Bayesian network have?","choices":["It must be a directed acyclic graph (DAG)","It must be a complete undirected graph","It must be fully connected with every edge bidirectional","It must contain at least one cycle to allow reasoning"],"answer":0,"explain":"A Bayesian network is a DAG, so no variable can depend on itself through a chain of edges. That acyclicity makes the joint probability factor cleanly."},{"id":"dsa-067","sub":"Perception, Representation, and Reasoning","diff":3,"q":"A Bayesian network has rain -> wet grass. P(rain) = 0.2, P(wet | rain) = 0.9, and P(wet | no rain) = 0.1. What is P(wet)?","choices":["0.18","0.90","0.10","0.26"],"answer":3,"explain":"P(wet) = 0.2 x 0.9 + 0.8 x 0.1 = 0.18 + 0.08 = 0.26. Using only the rain case (0.18) ignores the no-rain path."},{"id":"dsa-068","sub":"Perception, Representation, and Reasoning","diff":2,"q":"Which is an example of knowledge representation for an AI system?","choices":["A list of pixel colors in an image","A semantic network linking ''dog'' to ''mammal'' with an ''is-a'' relation","A random number generator seeded with 42","A table of unsorted sensor readings"],"answer":1,"explain":"Knowledge representation encodes facts and relationships in a form a system can reason over, such as semantic networks or ontologies."},{"id":"dsa-069","sub":"Perception, Representation, and Reasoning","diff":2,"q":"Which statement about logic-based AI systems is most accurate?","choices":["They always produce probabilistic answers","They require no rules to be written","They cannot represent relationships between objects","They can be explained step by step but struggle with uncertain or incomplete information"],"answer":3,"explain":"Logic systems are transparent and deductive, but they handle uncertainty poorly compared with probabilistic methods."},{"id":"dsa-070","sub":"Perception, Representation, and Reasoning","diff":3,"q":"Which predicate logic formula best captures ''Every employee who works overtime is paid extra''?","choices":["For all x, (Employee(x) and WorksOvertime(x)) implies PaidExtra(x)","There exists x such that Employee(x) implies (WorksOvertime(x) and PaidExtra(x))","For all x, (Employee(x) or WorksOvertime(x)) implies PaidExtra(x)","For all x, (Employee(x) and PaidExtra(x)) implies WorksOvertime(x)"],"answer":0,"explain":"''Every'' uses a universal quantifier with implication, and the antecedent requires both conditions. The last option reverses the implication, which is the converse error."},{"id":"dsa-071","sub":"Privacy and Ethics","diff":1,"q":"Which best describes algorithmic bias?","choices":["Systematic unfair outcomes that arise when training data or design choices favor some groups over others","Random errors that average out over large datasets","A software bug that only occurs on mobile devices","Deliberate fraud by a software vendor"],"answer":0,"explain":"Algorithmic bias is systematic and tends to disadvantage specific groups. Random error is noise, a different problem."},{"id":"dsa-072","sub":"Privacy and Ethics","diff":2,"q":"A hiring model trained on past hiring decisions learns to reject applicants from one group. What is the most likely cause?","choices":["Historical bias in the training data","Too few hidden layers in the network","A learning rate that is set too high","A test set that is too large"],"answer":0,"explain":"Models trained on biased historical decisions learn and reproduce those patterns. Architecture and hyperparameters do not create the bias."},{"id":"dsa-073","sub":"Privacy and Ethics","diff":2,"q":"Which privacy risk is specific to large language models?","choices":["Slow response times on mobile networks","Storing too many images in a cache","Using too many decimal places in output","Training data memorization that could expose personal information in responses"],"answer":3,"explain":"LLMs can memorize and regurgitate fragments of training data, which may include personal information, so this is a distinct privacy risk."},{"id":"dsa-074","sub":"Privacy and Ethics","diff":2,"q":"What is a hallucination in the credibility sense?","choices":["A deliberate attempt by the model to deceive the user","Fluent output presented as fact that is not supported by the data or sources","A display glitch in the chat interface","Any output longer than 500 words"],"answer":1,"explain":"Hallucinations are unsupported outputs that read as confident fact. The model is not intentionally deceiving anyone."},{"id":"dsa-075","sub":"Privacy and Ethics","diff":1,"q":"Which is an ethical dilemma raised by self-driving vehicles?","choices":["Which fuel type should be used for charging","How the vehicle should act in unavoidable collision scenarios","What color the vehicle body should be","Which songs the radio should play"],"answer":1,"explain":"Self-driving systems raise hard questions about harm and responsibility in unavoidable crashes, a recognized ethical dilemma."},{"id":"dsa-076","sub":"Privacy and Ethics","diff":1,"q":"Which practice best protects privacy when using personal data to train a model?","choices":["Collect all available data so the model is more accurate","Keep all data indefinitely in case it is useful later","Publish raw data publicly to allow peer review","Data minimization: collect and keep only the data needed for the purpose"],"answer":3,"explain":"Data minimization limits exposure by collecting and retaining only what is necessary, a core fair information practice."},{"id":"dsa-077","sub":"Privacy and Ethics","diff":2,"q":"What is a proxy variable in the context of algorithmic bias?","choices":["A seemingly neutral feature, such as zip code, that correlates with a protected characteristic","A duplicate copy of the training set","The variable the model is trained to predict","The output of an unsupervised algorithm"],"answer":0,"explain":"Proxies let a model reproduce discrimination without using a protected attribute directly, because the neutral feature carries the same information."},{"id":"dsa-078","sub":"Privacy and Ethics","diff":2,"q":"Which principle, in widely used fair information practices, requires that personal data be used only for the purpose it was collected for?","choices":["Data portability","The right to erasure","Anonymization","Use limitation (purpose limitation)"],"answer":3,"explain":"Use limitation restricts secondary use of personal data without consent. Portability and erasure are individual rights, and anonymization is a technique."},{"id":"dsa-079","sub":"Privacy and Ethics","diff":3,"q":"A company removes names from a dataset but keeps zip code, birth date, and sex. Why might individuals still be identifiable?","choices":["Removing names makes the data fully anonymous under U.S. law","Zip codes are always encrypted in modern datasets","Those combined quasi-identifiers can be linked to public records to re-identify people","Birth dates are never considered personal information"],"answer":2,"explain":"Combinations of quasi-identifiers can uniquely identify many people when linked to other data. Removing direct identifiers alone does not guarantee anonymity."},{"id":"dsa-080","sub":"Privacy and Ethics","diff":1,"q":"Which is a common ethical concern about AI-generated images?","choices":["They always require a larger file size than photographs","They may imitate artists'' styles or use training images without consent","They cannot be displayed in public spaces","They are always identical to their training data"],"answer":1,"explain":"Concerns include consent, attribution, and imitation of creators'' work. Generated images are not automatically copies of training data."},{"id":"dsa-081","sub":"Data Literacy and Foundations","diff":1,"q":"Which is an example of structured data?","choices":["Free-text customer reviews","Rows and columns in a sales table with fixed fields","Audio recordings from a call center","Photographs stored as JPEG files"],"answer":1,"explain":"Structured data fits a predefined schema of rows and columns with fixed fields. The others lack that fixed tabular structure."},{"id":"dsa-082","sub":"Data Literacy and Foundations","diff":1,"q":"Which is an example of unstructured data?","choices":["A table of order IDs and prices","A spreadsheet of monthly sales","A collection of customer emails with free-form text","A database of employee names and hire dates"],"answer":2,"explain":"Free-form text does not follow a fixed schema, so it is unstructured. The other options are tabular, hence structured."},{"id":"dsa-083","sub":"Data Literacy and Foundations","diff":1,"q":"Which value is categorical rather than numeric?","choices":["Eye color: blue, brown, green","Height in centimeters","Number of text messages sent","Temperature in Celsius"],"answer":0,"explain":"Eye color is a label with no numeric meaning. The others are measured or counted numbers."},{"id":"dsa-084","sub":"Data Literacy and Foundations","diff":3,"q":"What is the decimal number 255 in hexadecimal?","choices":["FF","F0","1FF","AA"],"answer":0,"explain":"255 = 15 x 16 + 15, so each digit is F, giving FF. F0 is 240, a common arithmetic slip."},{"id":"dsa-085","sub":"Data Literacy and Foundations","diff":2,"q":"What is the binary representation of decimal 10?","choices":["1100","1001","1010","0110"],"answer":2,"explain":"10 = 8 + 2, which is 1010 in binary. Other patterns represent different values."},{"id":"dsa-086","sub":"Data Literacy and Foundations","diff":1,"q":"Which source would most likely produce data for a web analytics dashboard?","choices":["A paper survey mailed once a decade","Handwritten receipts kept in a back room","A printed annual report","Server and browser log files recording page visits"],"answer":3,"explain":"Web analytics relies on automatically generated server and browser logs, which record visits in near real time."},{"id":"dsa-087","sub":"Data Literacy and Foundations","diff":1,"q":"Which stage of the data science process comes first?","choices":["Training the model","Deploying the model to users","Visualizing the final results","Defining the business question or problem"],"answer":3,"explain":"Data science projects start by defining the question, which determines what data is needed and how it will be analyzed."},{"id":"dsa-088","sub":"Data Literacy and Foundations","diff":3,"q":"Why is data wrangling important?","choices":["It replaces the need to collect data","Raw data is often messy and must be cleaned and transformed before analysis","It guarantees the model will be accurate","It is needed only after a model is deployed"],"answer":1,"explain":"Wrangling (cleaning, reshaping, and transforming) prepares raw data for analysis, and it usually takes a large share of project time."},{"id":"dsa-089","sub":"Data Literacy and Foundations","diff":1,"q":"Which stage of the data science process involves communicating insights to stakeholders?","choices":["Data collection from sensors","Communication and visualization of results","Feature engineering","Hyperparameter tuning"],"answer":1,"explain":"Communicating findings clearly is the final stage, where visualizations and summaries turn analysis into decisions."},{"id":"dsa-090","sub":"Data Literacy and Foundations","diff":2,"q":"Which column in a CSV contains continuous numeric data?","choices":["city","customer_id","purchase_total","country"],"answer":2,"explain":"Purchase totals can take any value in a range, so they are continuous. Cities and countries are categorical, and IDs are labels."},{"id":"dsa-091","sub":"Data Literacy and Foundations","diff":1,"q":"A column records whether a customer subscribed, as yes or no. What type of data is this?","choices":["Categorical (binary)","Continuous numeric","Ordinal numeric","Unstructured text"],"answer":0,"explain":"A yes/no flag has two categories and no numeric meaning, which makes it binary categorical data."},{"id":"dsa-092","sub":"Data Literacy and Foundations","diff":1,"q":"What best describes data science?","choices":["A branch of hardware engineering focused on storage chips","An interdisciplinary field that uses statistics, programming, and domain knowledge to extract insight from data","The study of probability theory alone","A method for manually recording paper surveys"],"answer":1,"explain":"Data science combines statistics, computing, and subject knowledge to turn data into insight and decisions."},{"id":"dsa-093","sub":"Data Literacy and Foundations","diff":1,"q":"Which source is the best source of retail transaction data?","choices":["Weather station readings","Satellite images of the ocean","Mobile phone camera photos","Point-of-sale system exports"],"answer":3,"explain":"Point-of-sale systems record each sale as it happens, so their exports contain the transactions a retailer needs."},{"id":"dsa-094","sub":"Data Literacy and Foundations","diff":3,"q":"Convert the binary number 1101 0110 to hexadecimal.","choices":["D6","6D","B6","D9"],"answer":0,"explain":"Group into nibbles: 1101 = D and 0110 = 6, giving D6. Reversing the nibbles gives 6D, a common mistake."},{"id":"dsa-095","sub":"Data Literacy and Foundations","diff":2,"q":"What type of data is a series of temperatures recorded every hour?","choices":["Cross-sectional data only","Unstructured text data","Nominal categorical data","Time-series data"],"answer":3,"explain":"Observations ordered over time at regular intervals form a time series, which needs time-aware analysis."},{"id":"dsa-096","sub":"Data Literacy and Foundations","diff":1,"q":"Which of these is a common data quality dimension?","choices":["Popularity","Ambient temperature","Completeness","Brightness"],"answer":2,"explain":"Completeness, accuracy, consistency, and timeliness are standard data quality dimensions."},{"id":"dsa-097","sub":"Data Literacy and Foundations","diff":2,"q":"Which data format is most common for semi-structured data exchanged between web applications?","choices":["Scanned PDF","Bitmap image","JSON","Flat Excel workbook with macros"],"answer":2,"explain":"JSON stores key-value pairs in nested structures without a rigid table schema, which makes it semi-structured and widely used in web APIs."},{"id":"dsa-098","sub":"Data Literacy and Foundations","diff":3,"q":"A dataset of 1,000 rows has 300 missing ages. Which statement is most accurate?","choices":["The dataset is unusable and must be discarded","The missing ages can safely be set to zero","The missingness rate is 30%, which should be investigated before choosing a handling method","Missing values only matter when computing the mean"],"answer":2,"explain":"A 30% missingness rate is large. Its cause determines whether imputation or other handling is valid, and zero-filling distorts results."},{"id":"dsa-099","sub":"Data Literacy and Foundations","diff":2,"q":"Which step best describes data transformation?","choices":["Storing data in a backup server","Converting values into a different form, such as scaling numbers or encoding categories","Deleting outliers by default","Publishing a report to a website"],"answer":1,"explain":"Transformation changes data representation for analysis, such as scaling numeric features or encoding categories as numbers."},{"id":"dsa-100","sub":"Data Literacy and Foundations","diff":1,"q":"Which of these is inherently unstructured data?","choices":["A table of store inventory","Video footage from a security camera","A list of employee IDs and salaries","A database of customer addresses"],"answer":1,"explain":"Video has no predefined rows and columns. Inventory, salary, and address tables are structured."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'economics', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"eco-001","sub":"Fundamental Economic Concepts","diff":1,"q":"Which best describes economic scarcity?","choices":["A temporary shortage caused by a price ceiling set below equilibrium","Only the goods a government chooses to ration during a war","The condition in which unlimited human wants exceed the limited resources available to satisfy them","The total amount of goods a country produces in one year"],"answer":2,"explain":"Scarcity is the gap between unlimited wants and limited resources. A shortage from a price ceiling is a symptom of a market problem, not the definition of scarcity."},{"id":"eco-002","sub":"Fundamental Economic Concepts","diff":1,"q":"What is the opportunity cost of a choice?","choices":["The profit a firm earns after paying all of its fixed costs","The total money spent on a purchase, including sales tax","The price paid for a good minus its cost of production","The value of the next-best alternative given up when a choice is made"],"answer":3,"explain":"Opportunity cost is the value of the next-best alternative forgone. Money spent is an explicit cost, not an opportunity cost."},{"id":"eco-003","sub":"Fundamental Economic Concepts","diff":1,"q":"Which factor of production is the risk-taking ability to combine land, labour and capital to create a new business?","choices":["Labour","Capital","Land","Entrepreneurship"],"answer":3,"explain":"Entrepreneurship is the fourth factor of production: it organizes the other three and bears the risk of doing so."},{"id":"eco-004","sub":"Fundamental Economic Concepts","diff":1,"q":"In the circular flow model, what do households provide to firms in the factor market?","choices":["Goods and services","Consumer spending","Tax revenue","Labour, land and capital"],"answer":3,"explain":"Households own the factors of production and supply them to firms for income. Goods and services flow the other way, through the product market."},{"id":"eco-005","sub":"Fundamental Economic Concepts","diff":1,"q":"A point inside a production possibilities curve indicates that the economy is:","choices":["operating at full employment with efficient allocation","unable to produce that combination of goods with current resources","operating inefficiently, with unemployed or underused resources","experiencing rapid economic growth"],"answer":2,"explain":"Points inside the curve are attainable but inefficient, because resources are idle or misallocated. Points on the curve are efficient."},{"id":"eco-006","sub":"Fundamental Economic Concepts","diff":1,"q":"Which characteristic best defines a public good?","choices":["Excludable but non-rival","Rival and excludable","Rival but non-excludable","Non-rival and non-excludable"],"answer":3,"explain":"A public good is non-rival (one person''s use does not reduce another''s) and non-excludable (no one can be barred from using it). Excludable but non-rival describes a club good."},{"id":"eco-007","sub":"Fundamental Economic Concepts","diff":1,"q":"A country has a comparative advantage in producing a good when it can produce that good at:","choices":["the lowest total cost in dollars","a higher output per worker than any other country in every good","the highest absolute productivity of any good","a lower opportunity cost than another country"],"answer":3,"explain":"Comparative advantage depends on opportunity cost, not on absolute cost or productivity. A country can lack an absolute advantage and still have a comparative one."},{"id":"eco-008","sub":"Fundamental Economic Concepts","diff":1,"q":"Marginal cost is best defined as:","choices":["total cost divided by total output","the price minus average variable cost","fixed costs spread over all units produced","the change in total cost from producing one additional unit"],"answer":3,"explain":"Marginal cost is the change in total cost from one more unit. Dividing total cost by output gives average total cost."},{"id":"eco-009","sub":"Fundamental Economic Concepts","diff":1,"q":"Which event would cause a rightward shift of the demand curve for a normal good?","choices":["A decrease in consumer income","An increase in the price of the good itself","An increase in consumer income","A decrease in the price of the good itself"],"answer":2,"explain":"A change in the good''s own price moves along the curve rather than shifting it. Rising income increases demand for normal goods."},{"id":"eco-010","sub":"Fundamental Economic Concepts","diff":1,"q":"Which change would shift the supply curve for a product to the left?","choices":["An increase in the price of the product itself","A technological improvement that lowers production costs","A subsidy paid to producers","An increase in the cost of raw materials"],"answer":3,"explain":"Higher input costs reduce the quantity firms are willing to supply at each price, shifting supply left. The other options shift supply right or move along the curve."},{"id":"eco-011","sub":"Fundamental Economic Concepts","diff":1,"q":"When the market price is above equilibrium, what happens?","choices":["A shortage occurs and the price tends to rise","Quantity demanded exceeds quantity supplied","A surplus occurs and the price tends to fall","The market clears immediately"],"answer":2,"explain":"At a price above equilibrium, quantity supplied exceeds quantity demanded, creating a surplus that pushes the price down toward equilibrium."},{"id":"eco-012","sub":"Fundamental Economic Concepts","diff":1,"q":"The price of a good rises 10% and the quantity demanded falls 20%. The absolute price elasticity of demand is closest to:","choices":["2.0, so demand is elastic","0.5, so demand is inelastic","10, so demand is perfectly elastic","0.2, so demand is unit elastic"],"answer":0,"explain":"Elasticity is 20% divided by 10%, which is 2.0. Since it is above 1, demand is elastic."},{"id":"eco-013","sub":"Fundamental Economic Concepts","diff":1,"q":"Which good is most likely to have inelastic demand?","choices":["Restaurant meals","A specific brand of cereal","Gasoline in the short run","Luxury cars"],"answer":2,"explain":"Gasoline has few close substitutes and is a modest share of most budgets in the short run, so demand is inelastic. The other options have many substitutes."},{"id":"eco-014","sub":"Fundamental Economic Concepts","diff":1,"q":"Diminishing marginal returns occur when:","choices":["total output begins to decline with any additional input","average costs fall as output increases","fixed costs rise with each unit produced","each additional unit of a variable input adds less output than the previous unit"],"answer":3,"explain":"Diminishing marginal returns mean the extra output from each added unit of a variable input falls, even while total output may still rise."},{"id":"eco-015","sub":"Fundamental Economic Concepts","diff":1,"q":"Consumer surplus is the difference between:","choices":["the market price and the cost of production","total revenue and total cost","the market price and the seller''s minimum acceptable price","the maximum a buyer is willing to pay and the price actually paid"],"answer":3,"explain":"Consumer surplus is the gain to buyers: their willingness to pay minus the market price. The option about a seller''s minimum acceptable price describes producer surplus."},{"id":"eco-016","sub":"Fundamental Economic Concepts","diff":1,"q":"A price floor set above the equilibrium price will most likely result in:","choices":["a surplus of the good","a shortage of the good","the quantity supplied falling to zero","no change in the quantity exchanged"],"answer":0,"explain":"A binding price floor above equilibrium makes quantity supplied exceed quantity demanded, creating a surplus."},{"id":"eco-017","sub":"Fundamental Economic Concepts","diff":1,"q":"The Latin phrase ceteris paribus means:","choices":["all prices change together","the economy is at full employment","all other relevant factors are held constant","consumers always act rationally"],"answer":2,"explain":"Economists use ceteris paribus to isolate the effect of one variable by holding others constant."},{"id":"eco-018","sub":"Fundamental Economic Concepts","diff":1,"q":"Which statement is normative?","choices":["Raising the minimum wage increases teen unemployment","The minimum wage is a type of price floor","Each $1 increase in the minimum wage reduces hours worked by 2%","The government should raise the minimum wage to $15 per hour"],"answer":3,"explain":"''Should'' statements express value judgments and are normative. The others are positive, testable claims."},{"id":"eco-019","sub":"Fundamental Economic Concepts","diff":1,"q":"Which is a microeconomic topic?","choices":["The national inflation rate","The federal budget deficit","Monetary policy set by the central bank","A single firm''s pricing decision"],"answer":3,"explain":"Microeconomics studies individual households, firms and markets. The other three concern the economy as a whole."},{"id":"eco-020","sub":"Fundamental Economic Concepts","diff":1,"q":"Which best describes macroeconomics?","choices":["The study of the economy as a whole, including inflation, unemployment and growth","The study of individual households and firms in a single market","The study of how a firm maximizes its profit","The study of how one government sets tariffs on a single product"],"answer":0,"explain":"Macroeconomics analyzes aggregate outcomes such as GDP, inflation and unemployment. Studying a single market or a single firm is microeconomics."},{"id":"eco-021","sub":"Fundamental Economic Concepts","diff":1,"q":"Marginal utility is:","choices":["the total satisfaction from all units consumed","the average satisfaction per unit consumed","the additional satisfaction from consuming one more unit","the price a consumer pays per unit"],"answer":2,"explain":"Marginal utility is the extra satisfaction from one more unit. Consumers maximize utility where marginal utility per dollar is equal across goods."},{"id":"eco-022","sub":"Fundamental Economic Concepts","diff":1,"q":"Which function does the price system perform?","choices":["Guarantees every buyer a fair share of scarce goods","Allocates scarce goods to those willing and able to pay","Eliminates all opportunity costs","Prevents shortages in every market"],"answer":1,"explain":"Prices ration scarce goods to those willing and able to pay. Prices do not guarantee fairness and do not eliminate opportunity costs."},{"id":"eco-023","sub":"Fundamental Economic Concepts","diff":1,"q":"If the price of tea rises and the quantity demanded of coffee rises, tea and coffee are:","choices":["complements","inferior goods","normal goods","substitutes"],"answer":3,"explain":"Substitutes are goods that can replace each other, so a rise in one price increases demand for the other."},{"id":"eco-024","sub":"Fundamental Economic Concepts","diff":1,"q":"If the price of printers falls and the quantity demanded of ink cartridges rises, ink is a complement of printers. Why?","choices":["Both goods are used together, so a fall in one price raises demand for the other","Ink is an inferior good for every buyer","Ink and printers are perfect substitutes","Ink is a luxury good whose demand rises with income"],"answer":0,"explain":"Complements are used together. Cheaper printers mean more printers are bought, which raises demand for the ink they need."},{"id":"eco-025","sub":"Fundamental Economic Concepts","diff":1,"q":"If both demand and supply increase, the equilibrium price:","choices":["rises for certain","falls for certain","is indeterminate without knowing the relative sizes of the shifts","stays the same"],"answer":2,"explain":"Both shifts raise equilibrium quantity for certain, but their opposing effects on price depend on which shift is larger."},{"id":"eco-026","sub":"Nature of Business","diff":1,"q":"Which form of business has a single owner who bears unlimited personal liability for business debts?","choices":["Sole proprietorship","C corporation","Limited liability company","Nonprofit corporation"],"answer":0,"explain":"A sole proprietor and the business are legally the same, so personal assets can be reached for business debts."},{"id":"eco-027","sub":"Nature of Business","diff":1,"q":"A key disadvantage of a C corporation for U.S. federal tax purposes is:","choices":["unlimited personal liability for all owners","owners must pay self-employment tax on all profit","owners cannot transfer their shares","double taxation of corporate profits and of dividends paid to shareholders"],"answer":3,"explain":"A C corporation pays corporate income tax, and shareholders pay tax again on dividends. S corporations and LLCs avoid this by default."},{"id":"eco-028","sub":"Nature of Business","diff":1,"q":"In a limited partnership, which partners have limited liability?","choices":["General partners only","Neither type of partner","Both general and limited partners","Limited partners"],"answer":3,"explain":"General partners manage the business and bear unlimited liability. Limited partners are generally liable only up to their investment."},{"id":"eco-029","sub":"Nature of Business","diff":1,"q":"Which section of a business plan describes the target market and the competition?","choices":["Market analysis","Income statement","Cash flow forecast","Balance sheet"],"answer":0,"explain":"Market analysis covers target customers, industry size and competitors. The financial statements come later in the plan."},{"id":"eco-030","sub":"Nature of Business","diff":1,"q":"Which group is an internal stakeholder of a business?","choices":["Suppliers","Customers","Employees","Competitors"],"answer":2,"explain":"Internal stakeholders work within or own the firm. Employees are internal; suppliers, customers and competitors are external."},{"id":"eco-031","sub":"Nature of Business","diff":1,"q":"The four functions of management are:","choices":["buying, selling, producing and distributing","hiring, firing, paying and training","budgeting, auditing, taxing and reporting","planning, organizing, leading and controlling"],"answer":3,"explain":"The classic management functions are planning, organizing, leading (directing) and controlling."},{"id":"eco-032","sub":"Nature of Business","diff":1,"q":"The four Ps of the marketing mix are:","choices":["price, place, purchase and profit","product, process, people and profit","planning, pricing, packaging and public relations","product, price, place and promotion"],"answer":3,"explain":"The marketing mix is product, price, place and promotion. Some texts add people, process and physical evidence for services."},{"id":"eco-033","sub":"Nature of Business","diff":1,"q":"The break-even point occurs when:","choices":["total revenue equals total cost","profit is maximized","marginal cost equals marginal revenue","fixed costs equal variable costs"],"answer":0,"explain":"At break-even, total revenue equals total cost and profit is zero. Marginal cost equal to marginal revenue is the profit-maximizing rule."},{"id":"eco-034","sub":"Nature of Business","diff":1,"q":"Which is the primary characteristic of an entrepreneur?","choices":["A guaranteed salary","Avoidance of all financial risk","Willingness to take calculated risks to pursue profit","Employment by a government agency"],"answer":2,"explain":"Entrepreneurs take on risk in exchange for the possibility of profit, which is the reward for bearing uncertainty."},{"id":"eco-035","sub":"Nature of Business","diff":1,"q":"A nonprofit corporation differs from a for-profit corporation mainly because:","choices":["it cannot hire employees","it cannot earn revenue","it never pays any taxes","its earnings cannot be distributed to owners as profit"],"answer":3,"explain":"Nonprofits may earn revenue and hire staff. The key difference is that surplus cannot be distributed to owners or directors as profit."},{"id":"eco-036","sub":"Nature of Business","diff":2,"q":"Which business structure gives owners limited liability while being taxed as a partnership by default for U.S. federal tax purposes?","choices":["A C corporation","A general partnership","A limited liability company (LLC)","A sole proprietorship that has filed incorporation papers"],"answer":2,"explain":"An LLC shields owners'' personal assets from business debts and, by default with multiple members, is taxed as a partnership (pass-through)."},{"id":"eco-037","sub":"Nature of Business","diff":2,"q":"The main advantage of buying a franchise over starting an independent business is:","choices":["complete control over product design","no royalty or fee obligations","an established brand and operating system","exemption from the franchisor''s standards"],"answer":2,"explain":"Franchisees trade some independence and ongoing fees for a proven brand, training and systems. Franchisees usually do pay royalties and must follow standards."},{"id":"eco-038","sub":"Nature of Business","diff":2,"q":"In a SWOT analysis, which element is an external factor the business cannot directly control?","choices":["Strength","Core competency","Weakness","Threat"],"answer":3,"explain":"Threats (and opportunities) are external. Strengths and weaknesses are internal and under the firm''s influence."},{"id":"eco-039","sub":"Nature of Business","diff":2,"q":"Which form of intellectual property protects a brand name and logo used to identify goods?","choices":["Patent","Copyright","Trade secret","Trademark"],"answer":3,"explain":"Trademarks protect names, logos and slogans that identify the source of goods. Patents cover inventions, and copyrights cover creative works."},{"id":"eco-040","sub":"Nature of Business","diff":2,"q":"A U.S. utility patent protects a novel invention or process for how long from the filing date?","choices":["10 years","Life of the inventor plus 70 years","50 years","20 years"],"answer":3,"explain":"A utility patent lasts 20 years from the filing date. Copyright for works by an individual lasts life plus 70 years, which is a common mix-up."},{"id":"eco-041","sub":"Nature of Business","diff":2,"q":"Which U.S. law governs contracts for the sale of goods between merchants?","choices":["Uniform Commercial Code, Article 2","Sherman Antitrust Act","Fair Labor Standards Act","Securities Act of 1933"],"answer":0,"explain":"UCC Article 2 governs sales of goods. The other laws cover antitrust, wages and securities."},{"id":"eco-042","sub":"Nature of Business","diff":2,"q":"Besides offer, acceptance and consideration, a legally enforceable contract generally requires:","choices":["a notary''s signature","a written document in every case","capacity of the parties and a legal purpose","witnesses to the signing"],"answer":2,"explain":"Enforceable contracts need capacity (parties able to contract) and lawful purpose. Writing is required only for certain contracts under the Statute of Frauds."},{"id":"eco-043","sub":"Nature of Business","diff":2,"q":"Which is an example of a variable cost for a bakery?","choices":["The annual insurance premium on the shop","Monthly rent on the building","Flour and sugar used in each batch of product","The salary of the owner-manager"],"answer":2,"explain":"Variable costs rise with output. Ingredients rise with each batch, while rent, insurance and salaries are generally fixed in the short run."},{"id":"eco-044","sub":"Nature of Business","diff":2,"q":"Which best describes a business''s mission statement?","choices":["Its long-term purpose and reason for existing","Its annual sales target","A list of its current products","Its daily work schedule"],"answer":0,"explain":"A mission statement states why the business exists. Sales targets are goals, which are narrower and time-bound."},{"id":"eco-045","sub":"Nature of Business","diff":2,"q":"Which best describes market segmentation?","choices":["Selling the same product to every consumer in the same way","Eliminating competitors through a merger","Setting a single price for all customers","Dividing a market into groups of buyers with shared characteristics"],"answer":3,"explain":"Segmentation groups buyers by traits such as age, income or needs so each group can be targeted with a tailored marketing mix."},{"id":"eco-046","sub":"Economic Systems","diff":2,"q":"In a pure market economy, who primarily decides what goods are produced?","choices":["Government planners","Labour unions","Consumers and producers, through prices","A central bank"],"answer":2,"explain":"In a market economy, prices signal what consumers want, and producers respond to those signals to earn profit."},{"id":"eco-047","sub":"Economic Systems","diff":2,"q":"Which best describes a command economy?","choices":["A central government makes most production and allocation decisions","Prices are set by supply and demand alone","Private property is abolished in every case","Foreign trade is entirely prohibited"],"answer":0,"explain":"In a command economy, a central authority plans what, how and for whom goods are produced. The other options describe a market economy or extreme cases."},{"id":"eco-048","sub":"Economic Systems","diff":2,"q":"The United States is best described as which type of economy?","choices":["Command economy","Traditional economy","Mixed market economy","Subsistence economy"],"answer":2,"explain":"The U.S. relies mainly on markets but has significant government regulation, taxation and public goods, which makes it a mixed economy."},{"id":"eco-049","sub":"Economic Systems","diff":2,"q":"A traditional economy relies primarily on:","choices":["custom, habit and tradition","central planning by government","auction markets","international aid"],"answer":0,"explain":"Traditional economies answer the basic economic questions through customs passed down over generations."},{"id":"eco-050","sub":"Economic Systems","diff":2,"q":"Which is a core feature of capitalism?","choices":["Government ownership of major industries","Fixed prices for all goods","Equal distribution of income","Private ownership of property and capital"],"answer":3,"explain":"Capitalism is built on private ownership of the factors of production and market-determined prices."},{"id":"eco-051","sub":"Economic Systems","diff":2,"q":"Which is most characteristic of socialist economic systems?","choices":["Widespread private ownership of land","Unrestricted foreign trade","Public ownership of major means of production","Prices set by individual firms only"],"answer":2,"explain":"Socialism generally places key productive assets in public or collective ownership, although models vary widely."},{"id":"eco-052","sub":"Economic Systems","diff":2,"q":"Which basic economic question asks ''for whom'' goods and services are produced?","choices":["What to produce","How to produce","For whom to produce","How much to save"],"answer":2,"explain":"Every economy answers three questions: what to produce, how to produce it, and for whom it is produced (how output is distributed)."},{"id":"eco-053","sub":"Economic Systems","diff":2,"q":"The ''invisible hand'' concept, associated with Adam Smith, refers to:","choices":["government price controls","foreign aid programs","a central bank managing the money supply","self-interested individuals unintentionally promoting society''s welfare through markets"],"answer":3,"explain":"Smith argued that individuals pursuing their own gain through voluntary exchange can produce socially beneficial outcomes."},{"id":"eco-054","sub":"Economic Systems","diff":2,"q":"Why are secure property rights important in a market economy?","choices":["They eliminate the need for prices","They guarantee equal incomes","They give owners incentives to invest, save and trade","They prevent all forms of competition"],"answer":2,"explain":"Secure property rights let owners keep the returns from their investment and trade, which encourages productive activity."},{"id":"eco-055","sub":"Economic Systems","diff":2,"q":"A major problem with central planning is:","choices":["too much consumer choice","excessive competition between firms","an abundance of accurate information","persistent shortages and surpluses caused by the absence of market price signals"],"answer":3,"explain":"Without prices that reflect scarcity, planners struggle to allocate resources efficiently, which leads to shortages and surpluses."},{"id":"eco-056","sub":"Economic Systems","diff":2,"q":"In economics, equity refers to:","choices":["the fairness of how income and goods are distributed","the lowest total cost of production","the speed of economic growth","the amount of money in circulation"],"answer":0,"explain":"Equity is about fairness in distribution. Efficiency is about getting the most output from scarce resources. The two often trade off."},{"id":"eco-057","sub":"Economic Systems","diff":2,"q":"An allocation of resources is Pareto efficient when:","choices":["everyone has identical income","total output is maximized regardless of cost","no one can be made better off without making someone else worse off","the government sets all prices"],"answer":2,"explain":"Pareto efficiency means no reallocation can improve one person''s position without harming another. It says nothing about equal incomes."},{"id":"eco-058","sub":"Economic Systems","diff":2,"q":"Which describes a market failure?","choices":["Market outcomes that do not achieve efficient allocation, such as pollution from production","Perfect competition among many firms","Prices that reflect all costs and benefits","Full employment with stable prices"],"answer":0,"explain":"Market failure occurs when markets misallocate resources, often because of externalities, public goods or market power."},{"id":"eco-059","sub":"Economic Systems","diff":2,"q":"Pollution from a factory that harms nearby residents, who are not compensated, is an example of:","choices":["a positive externality","a merit good","a public good","a negative externality"],"answer":3,"explain":"A negative externality imposes an uncompensated cost on third parties. Its market price does not reflect that cost, so too much is produced."},{"id":"eco-060","sub":"Economic Systems","diff":2,"q":"Which is the best example of a public good?","choices":["National defence","A private gym membership","A movie ticket","A restaurant meal"],"answer":0,"explain":"National defence is non-rival and non-excludable, so private markets tend to underprovide it and government usually supplies it."},{"id":"eco-061","sub":"Economic Systems","diff":2,"q":"Which is an example of a merit good?","choices":["Cigarettes","Public education","Luxury yachts","Designer clothing"],"answer":1,"explain":"Merit goods are considered socially desirable and are often subsidized or provided publicly, such as education and vaccines."},{"id":"eco-062","sub":"Economic Systems","diff":2,"q":"Privatization refers to:","choices":["transferring government-owned enterprises to private ownership","government purchase of private companies","an increase in public spending on services","the creation of a new public corporation"],"answer":0,"explain":"Privatization moves assets or services from public to private ownership, such as through a sale of a state-owned company."},{"id":"eco-063","sub":"Economic Systems","diff":2,"q":"Which trade-off is central to every economic system?","choices":["Price stability versus scarcity","Efficiency versus equity","Inflation versus consumer spending","Tax revenue versus deficits"],"answer":1,"explain":"Every system must balance getting the most from scarce resources (efficiency) against how fairly they are shared (equity)."},{"id":"eco-064","sub":"Economic Systems","diff":2,"q":"Division of labour increases productivity mainly because:","choices":["workers avoid all tasks they dislike","workers build skill in a task and lose less time switching between tasks","machines are no longer needed","output prices always fall"],"answer":1,"explain":"Specialization builds skill and efficiency. Adam Smith''s pin factory example illustrates the point."},{"id":"eco-065","sub":"Economic Systems","diff":2,"q":"Specialization and trade benefit nations because they allow each nation to:","choices":["eliminate scarcity entirely","consume beyond what its own production possibilities would allow","remove the need for money","guarantee equal living standards"],"answer":1,"explain":"Trade lets countries consume combinations of goods outside their own production possibilities curve, which raises total welfare."},{"id":"eco-066","sub":"Government''s Impact on Business","diff":2,"q":"Fiscal policy refers to:","choices":["setting interest rates and reserve requirements","government decisions about taxation and spending","managing the exchange rate","control of the money supply by the Federal Reserve"],"answer":1,"explain":"Fiscal policy uses taxes and government spending. Interest rates and reserve requirements are monetary policy tools."},{"id":"eco-067","sub":"Government''s Impact on Business","diff":2,"q":"In the U.S., monetary policy is conducted primarily by:","choices":["Congress","the Federal Reserve System","the Treasury Department''s tax office","the Securities and Exchange Commission"],"answer":1,"explain":"The Federal Reserve sets the federal funds target rate and manages the money supply. Congress makes fiscal decisions."},{"id":"eco-068","sub":"Government''s Impact on Business","diff":2,"q":"A per-unit tax levied on sellers shifts the supply curve:","choices":["to the right","to the left","not at all","to become perfectly elastic"],"answer":1,"explain":"A tax raises sellers'' costs, so they supply less at each price. This shifts supply to the left, raising the price buyers pay."},{"id":"eco-069","sub":"Government''s Impact on Business","diff":2,"q":"A government subsidy paid to producers generally results in:","choices":["a decrease in supply","a rightward shift of the supply curve","an increase in the price consumers pay","a shortage in the market"],"answer":1,"explain":"A subsidy lowers producers'' effective costs, so they supply more at each price, shifting supply right and typically lowering the price consumers pay."},{"id":"eco-070","sub":"Government''s Impact on Business","diff":2,"q":"A tariff is best defined as:","choices":["a tax on imported goods","a limit on the physical quantity of exports","a government payment to exporters","a fee charged by banks for currency exchange"],"answer":0,"explain":"A tariff is a tax on imports. It raises domestic prices and generates government revenue."},{"id":"eco-071","sub":"Government''s Impact on Business","diff":2,"q":"An import quota differs from a tariff because a quota:","choices":["collects revenue for the government","limits the physical quantity of imports allowed","always raises prices less than a tariff","applies only to services"],"answer":1,"explain":"A quota caps the quantity of imports, while a tariff taxes them. A quota generally does not produce government tariff revenue."},{"id":"eco-072","sub":"Government''s Impact on Business","diff":2,"q":"The Sherman Antitrust Act of 1890 primarily aims to:","choices":["regulate interest rates","prohibit monopolies and restraints of trade","set minimum wages","protect copyrights"],"answer":1,"explain":"The Sherman Act outlaws contracts and conspiracies that restrain trade and the monopolization of markets."},{"id":"eco-073","sub":"Government''s Impact on Business","diff":2,"q":"Which U.S. agency enforces federal securities laws and protects investors?","choices":["Federal Trade Commission","Securities and Exchange Commission","Federal Reserve","Department of Labor"],"answer":1,"explain":"The SEC enforces federal securities laws. The FTC focuses on consumer protection and competition, and the Fed on monetary policy."},{"id":"eco-074","sub":"Government''s Impact on Business","diff":2,"q":"A binding minimum wage set above the equilibrium wage typically causes:","choices":["a surplus of labour, meaning unemployment","a shortage of workers for every employer","lower wages for all workers","an increase in labour demand"],"answer":0,"explain":"A binding wage floor raises the quantity of labour supplied above the quantity demanded, creating unemployment among those seeking work."},{"id":"eco-075","sub":"Government''s Impact on Business","diff":2,"q":"Rent control set below the equilibrium rent most likely causes:","choices":["a shortage of rental housing","a surplus of rental housing","higher rents for all tenants","more new apartment construction"],"answer":0,"explain":"A binding price ceiling lowers quantity supplied and raises quantity demanded, leaving a housing shortage."},{"id":"eco-076","sub":"Government''s Impact on Business","diff":3,"q":"Deadweight loss from a per-unit tax is largest when:","choices":["supply and demand are both perfectly inelastic","demand and supply are relatively elastic","the tax rate is zero","the market is a monopoly with no competition"],"answer":1,"explain":"Deadweight loss grows with the responsiveness of quantity to price. Elastic supply and demand let the tax shrink trade more."},{"id":"eco-077","sub":"Government''s Impact on Business","diff":3,"q":"If demand is perfectly inelastic, the burden of a per-unit tax falls:","choices":["entirely on consumers","entirely on producers","equally on consumers and producers","on the government only"],"answer":0,"explain":"When buyers cannot reduce quantity demanded, sellers can pass the full tax on through higher prices. Tax incidence follows relative elasticity."},{"id":"eco-078","sub":"Government''s Impact on Business","diff":3,"q":"In a simple model with no taxes or imports, the marginal propensity to consume is 0.8. The government spending multiplier is:","choices":["1.25","5","0.8","0.2"],"answer":1,"explain":"The multiplier is 1 / (1 - MPC) = 1 / 0.2 = 5."},{"id":"eco-079","sub":"Government''s Impact on Business","diff":3,"q":"Which statement correctly distinguishes the federal budget deficit from the national debt?","choices":["The deficit is the cumulative total owed; the debt is the one-year shortfall","The debt is the cumulative total owed; the deficit is the one-year excess of spending over revenue","They are identical measures","The deficit is always larger than the debt"],"answer":1,"explain":"The deficit is an annual flow (spending exceeds revenue in one year). The debt is the accumulated stock of past deficits net of surpluses."},{"id":"eco-080","sub":"Government''s Impact on Business","diff":3,"q":"Which U.S. law is the main source of the FTC''s authority to act against unfair or deceptive business practices?","choices":["Section 5 of the Federal Trade Commission Act","The Clayton Act","The Glass-Steagall Act","The Fair Credit Reporting Act"],"answer":0,"explain":"Section 5 of the FTC Act prohibits unfair or deceptive acts or practices in commerce. The Clayton Act targets specific anticompetitive practices such as certain mergers."},{"id":"eco-081","sub":"Cost/Profit Relationships","diff":3,"q":"A firm faces elastic demand (elasticity of 2.0). To increase total revenue, it should:","choices":["raise its price","lower its price","keep its price constant and raise fixed costs","raise its variable costs"],"answer":1,"explain":"With elastic demand, the quantity gain from a price cut outweighs the lower price, so total revenue rises. Costs do not affect revenue."},{"id":"eco-082","sub":"Cost/Profit Relationships","diff":3,"q":"Economic profit equals:","choices":["total revenue minus accounting cost only","total revenue minus total opportunity cost, including implicit costs","the net income reported on the income statement","revenue minus variable cost only"],"answer":1,"explain":"Economic profit subtracts implicit costs such as forgone wages. Accounting profit ignores them, so it is usually higher."},{"id":"eco-083","sub":"Cost/Profit Relationships","diff":3,"q":"A firm sells 500 units at $12 each. Variable cost is $7 per unit and total fixed cost is $1,000. Its profit is:","choices":["$2,500","$1,000","$1,500","$4,000"],"answer":2,"explain":"Revenue is $6,000. Variable cost is $3,500 and fixed cost is $1,000, leaving $1,500. Ignoring fixed cost gives $2,500, a common trap."},{"id":"eco-084","sub":"Cost/Profit Relationships","diff":3,"q":"Fixed costs are $60,000, price is $50 per unit and variable cost is $30 per unit. The break-even quantity is:","choices":["1,200 units","3,000 units","2,000 units","6,000 units"],"answer":1,"explain":"Contribution margin is $20 per unit. Break-even quantity is $60,000 / $20 = 3,000 units."},{"id":"eco-085","sub":"Cost/Profit Relationships","diff":3,"q":"Total cost is $4,800 for 120 units of output. Average total cost is:","choices":["$24","$36","$40","$4,800"],"answer":2,"explain":"Average total cost is total cost divided by quantity: $4,800 / 120 = $40."},{"id":"eco-086","sub":"Cost/Profit Relationships","diff":3,"q":"Total cost rises from $500 to $560 when output increases from 10 to 12 units. The marginal cost of each added unit is:","choices":["$25","$30","$50","$60"],"answer":1,"explain":"Change in total cost is $60 and change in quantity is 2 units, so marginal cost is $30."},{"id":"eco-087","sub":"Cost/Profit Relationships","diff":3,"q":"In the short run, a firm should keep operating if the market price is at least:","choices":["its average variable cost","its average total cost","its marginal cost of zero","its fixed cost per unit"],"answer":0,"explain":"Covering variable costs lets the firm pay part of its fixed costs. Below average variable cost, it should shut down in the short run."},{"id":"eco-088","sub":"Cost/Profit Relationships","diff":3,"q":"In a perfectly competitive market in long-run equilibrium, firms earn:","choices":["large economic profits","zero economic profit","persistent losses","unlimited profit"],"answer":1,"explain":"Entry and exit drive economic profit to zero in the long run. Accounting profit may still be positive."},{"id":"eco-089","sub":"Cost/Profit Relationships","diff":3,"q":"Which cost is an implicit cost?","choices":["Wages paid to employees","Rent paid for a store","The salary the owner gives up by not working elsewhere","Monthly utility bills"],"answer":2,"explain":"Implicit costs are the value of resources the owner supplies that are not paid in cash, such as forgone wages. The other three are explicit payments."},{"id":"eco-090","sub":"Cost/Profit Relationships","diff":3,"q":"Long-run average cost falls as output increases because of:","choices":["diminishing returns","economies of scale","rising fixed costs","excise taxes"],"answer":1,"explain":"Economies of scale lower average cost as output grows, such as through bulk purchasing and specialization. Diminishing returns is a short-run concept."},{"id":"eco-091","sub":"Economic Indicators","diff":3,"q":"Gross domestic product measures:","choices":["the market value of all final goods and services produced within a country in a given period","total government spending only","the total value of all stocks traded","the total money supply"],"answer":0,"explain":"GDP counts final goods and services produced domestically in a period. It excludes intermediate goods to avoid double counting."},{"id":"eco-092","sub":"Economic Indicators","diff":3,"q":"The Consumer Price Index measures:","choices":["the price of gold","wholesale prices of raw materials only","the average change over time in prices paid by urban consumers for a basket of goods and services","the interest rate on government bonds"],"answer":2,"explain":"CPI tracks the cost of a fixed basket of consumer goods and services over time, and is the most common inflation gauge."},{"id":"eco-093","sub":"Economic Indicators","diff":3,"q":"A person who is actively looking for work but currently has no job is counted as:","choices":["employed","not in the labour force","unemployed","underemployed only"],"answer":2,"explain":"The BLS counts people who have no job, have searched for work recently, and are available for work as unemployed."},{"id":"eco-094","sub":"Economic Indicators","diff":3,"q":"Real GDP differs from nominal GDP because real GDP:","choices":["ignores government spending","adjusts for changes in the price level","includes only exports","counts only household consumption"],"answer":1,"explain":"Real GDP removes the effect of price changes, so it reflects actual changes in output. Nominal GDP uses current prices."},{"id":"eco-095","sub":"Economic Indicators","diff":3,"q":"A common definition of a recession in the business cycle is:","choices":["two consecutive quarters of declining real GDP","a rise in the CPI above 5%","a fall in the unemployment rate","a period of rising stock prices"],"answer":0,"explain":"The two-consecutive-quarters rule is a common rule of thumb. The official U.S. call is made by the NBER and considers several indicators."},{"id":"eco-096","sub":"Global Trade","diff":3,"q":"If the U.S. dollar appreciates against the euro, U.S. exports to Europe become:","choices":["cheaper for Europeans","more expensive for Europeans","unchanged in price to Europeans","exempt from tariffs"],"answer":1,"explain":"A stronger dollar means each dollar buys fewer euros, so U.S. goods cost European buyers more in euros."},{"id":"eco-097","sub":"Global Trade","diff":3,"q":"Which principle explains why nations benefit from trade even if one nation is more productive in every good?","choices":["Absolute advantage","Comparative advantage","Mercantilism","Protectionism"],"answer":1,"explain":"Comparative advantage, based on opportunity cost, shows that both nations gain by specializing where their opportunity cost is lowest."},{"id":"eco-098","sub":"Global Trade","diff":3,"q":"The current account of the U.S. balance of payments includes:","choices":["trade in goods and services, plus net income and transfers","only foreign direct investment","changes in central bank reserves only","government bond sales only"],"answer":0,"explain":"The current account covers trade in goods and services, net primary income and net transfers. Capital and financial accounts track investment flows."},{"id":"eco-099","sub":"Global Trade","diff":3,"q":"A trade deficit means:","choices":["exports exceed imports","imports exceed exports","government spending exceeds tax revenue","the currency is fixed to another currency"],"answer":1,"explain":"A trade deficit means the country buys more from abroad than it sells. Government spending exceeding tax revenue is a budget deficit."},{"id":"eco-100","sub":"Global Trade","diff":3,"q":"The USMCA is a trade agreement among the United States, Canada and which other country?","choices":["Brazil","Mexico","Japan","the European Union"],"answer":1,"explain":"USMCA (United States-Mexico-Canada Agreement) replaced NAFTA in 2020. It is a regional free trade agreement among these three countries."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'entrepreneurship', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"ent-001","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"A bakery owner wants to know whether customers will pay a premium for gluten-free bread before buying equipment. What is the best first step?","choices":["Run a small pre-order or pilot test to measure demand","Buy a commercial oven and sign a 10-year storefront lease","Hire two full-time bakers before knowing demand","Sign a distribution contract with a national grocery chain"],"answer":0,"explain":"Validating demand cheaply before major spending reduces the risk of the business plan. Friends-and-family praise is not a demand test."},{"id":"ent-002","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"In a SWOT analysis, which category describes an internal advantage the business has over its competitors?","choices":["Opportunity","Strength","Threat","Weakness"],"answer":1,"explain":"Strengths and weaknesses are internal; opportunities and threats are external. Strength is the internal advantage."},{"id":"ent-003","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"A company gives its basic app away for free and charges only for premium features. Which business model is this?","choices":["Franchising","Cost leadership","Freemium","Subscription-only pricing"],"answer":2,"explain":"Freemium pairs a free base offering with paid upgrades. Subscription-only would charge for all access from the start."},{"id":"ent-004","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"Which is the best description of a target market?","choices":["All consumers who might ever buy any product","Competitors'' existing customers only","Customers who have already bought from a competitor in the past year","A specific group of customers with shared needs that the business chooses to serve"],"answer":3,"explain":"A target market is a chosen, defined group. Trying to serve everyone is a common planning mistake."},{"id":"ent-005","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"Which type of feasibility study asks whether the owner has the equipment, skills and suppliers needed to deliver the product?","choices":["Operational (technical) feasibility","Market feasibility","Financial feasibility","Legal feasibility"],"answer":0,"explain":"Operational feasibility tests capability to produce and deliver. Market feasibility tests demand; financial feasibility tests funding and returns."},{"id":"ent-006","sub":"Business Plan and Opportunity Assessment","diff":3,"q":"A product sells for $25 per unit, has a variable cost of $15 per unit and fixed costs of $12,000 per year. How many units must be sold to break even?","choices":["480 units","1,200 units","600 units","1,800 units"],"answer":1,"explain":"Contribution per unit is $25 minus $15, or $10, so $12,000 divided by $10 is 1,200 units. Dividing by the $25 price gives the wrong answer of 480."},{"id":"ent-007","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"Why is the executive summary of a business plan usually written last, even though it appears first?","choices":["It is a legal requirement that must be signed last","It replaces the financial projections for lenders","It summarizes the key findings and the funding request from every other section","It lists every employee and job title in order of seniority"],"answer":2,"explain":"The summary can only be accurate once the rest of the plan is complete. It does not replace any section."},{"id":"ent-008","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"A new coffee shop opens near two national chains that charge less. Which strategy best supports a sustainable position?","choices":["Match the chains'' prices to win price-sensitive customers","Offer the widest possible menu to appeal to everyone","Copy the chains'' menu and open a location next to each one","Focus on an unmet need, such as locally roasted specialty drinks, and charge for the difference"],"answer":3,"explain":"Differentiation on a need the chains do not serve is more defensible than a price war the shop cannot win."},{"id":"ent-009","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"Which best describes a value proposition?","choices":["The specific benefit a customer receives that makes the offer worth choosing","The total value of the company''s assets on its balance sheet","The price printed on the product label","The company''s mission statement written for employees"],"answer":0,"explain":"A value proposition states why a customer should choose this offer over alternatives, which is about benefit rather than price or assets."},{"id":"ent-010","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"A founder builds a simple landing page to test sign-ups before building the full product. This approach is best described as:","choices":["Full-scale production planning","Testing a minimum viable product","Franchise feasibility analysis","Vertical integration"],"answer":1,"explain":"A minimum viable product is the simplest version that tests whether customers want the idea, before full investment."},{"id":"ent-011","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"Which term describes the portion of the total market a new business can realistically capture in its first few years?","choices":["Total addressable market (TAM)","Serviceable available market (SAM)","Serviceable obtainable market (SOM)","The gross domestic product share of the industry"],"answer":2,"explain":"TAM is the whole market, SAM is the part the business can serve, and SOM is the realistic share it can win. The word realistically points to SOM."},{"id":"ent-012","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"The threat that customers can easily switch to a substitute product is part of which analysis framework?","choices":["Maslow''s hierarchy of needs","The marketing mix (4 Ps)","The Balanced Scorecard","Porter''s Five Forces"],"answer":3,"explain":"Porter''s model includes the threat of substitutes among five competitive forces; the others are not competitive-analysis frameworks."},{"id":"ent-013","sub":"Business Plan and Opportunity Assessment","diff":3,"q":"In the BCG growth-share matrix, a product with high market share in a low-growth market is classified as a:","choices":["Cash cow","Star","Question mark","Dog"],"answer":0,"explain":"Cash cows generate more cash than they need in a mature market. Stars have high share and high growth."},{"id":"ent-014","sub":"Business Plan and Opportunity Assessment","diff":2,"q":"A bakery plans a second location two kilometres from its first. Much of the new location''s projected sales would come from customers who would otherwise buy at the first. This risk is called:","choices":["Vertical integration","Cannibalization","Supplier saturation","Price skimming"],"answer":1,"explain":"Cannibalization is when a new outlet takes sales from an existing one, so total gain is smaller than the new location''s sales suggest."},{"id":"ent-015","sub":"Business Plan and Opportunity Assessment","diff":3,"q":"A startup holds a patent but has few customers and needs capital. Which element of the business plan most directly shows investors how the patent turns into revenue?","choices":["Organizational chart","Lease terms for office space","Revenue model and go-to-market strategy","An employee handbook with the vacation policy"],"answer":2,"explain":"Investors need to see how the technology becomes income. The org chart and lease matter but do not answer the revenue question."},{"id":"ent-016","sub":"Business Plan and Opportunity Assessment","diff":1,"q":"Which is the best example of a mission statement?","choices":["We sell sandwiches, salads and soup at lunch","Our revenue last year was $240,000","Our competitors are located on Main Street","To make healthy lunches affordable for every student at our school"],"answer":3,"explain":"A mission states purpose and who benefits. Describing products, financials or competitors does not state the purpose."},{"id":"ent-017","sub":"Business Plan and Opportunity Assessment","diff":3,"q":"Which factor most makes a competitive advantage sustainable over time?","choices":["It is difficult for competitors to copy, such as a strong brand or a proprietary process","It relies on a low price that competitors can easily match","It depends on a single supplier who could leave","It is based on a temporary trend that fades quickly"],"answer":0,"explain":"Advantages last when rivals cannot easily imitate them. Easily matched prices or fragile supplier ties do not protect the business."},{"id":"ent-018","sub":"Marketing Management","diff":1,"q":"Which element of the marketing mix refers to where the product is sold?","choices":["Price","Place","Promotion","Product"],"answer":1,"explain":"Place covers distribution channels and locations. Price, promotion and product are the other three of the 4 Ps."},{"id":"ent-019","sub":"Marketing Management","diff":1,"q":"Which is an example of sales promotion?","choices":["Changing the size of the package","Lowering the wholesale cost paid to suppliers","A coupon mailed to nearby households","Opening a warehouse in another state"],"answer":2,"explain":"Coupons are a sales promotion tool. Packaging, cost and distribution decisions belong to other mix elements."},{"id":"ent-020","sub":"Marketing Management","diff":2,"q":"A 10 percent price increase causes quantity demanded to fall by 20 percent. What is the price elasticity of demand?","choices":["0.5, which is inelastic","0.2, which is inelastic","10.0, which is elastic","2.0, which is elastic"],"answer":3,"explain":"Elasticity is the percent change in quantity divided by the percent change in price, 20 divided by 10, which is 2.0. Demand is elastic because the magnitude exceeds 1."},{"id":"ent-021","sub":"Marketing Management","diff":2,"q":"Dividing a market by customers'' lifestyles, values and interests is which type of segmentation?","choices":["Psychographic segmentation","Geographic segmentation","Demographic segmentation","Behavioural segmentation"],"answer":0,"explain":"Psychographic segmentation uses attitudes and lifestyle. Demographic uses measurable traits such as age and income."},{"id":"ent-022","sub":"Marketing Management","diff":2,"q":"A company launches a new smartphone at a high price and lowers it over time as competitors enter. This strategy is called:","choices":["Penetration pricing","Price skimming","Loss leader pricing","Going-rate pricing"],"answer":1,"explain":"Skimming starts high to capture early adopters and drops later. Penetration starts low to gain share fast."},{"id":"ent-023","sub":"Marketing Management","diff":3,"q":"A small firm has a $2,000 marketing budget and wants the lowest-cost awareness among local customers. Which choice fits best?","choices":["A full-page print ad in a national magazine","A television commercial during prime time","Local social media ads and a Google Business Profile that collects reviews","Billboards on a highway 300 kilometres away"],"answer":2,"explain":"Local targeting and free profile listings give the most awareness per dollar for a small local budget."},{"id":"ent-024","sub":"Marketing Management","diff":3,"q":"A customer spends $60 per month and stays for 5 years at a 40 percent gross margin. What is the approximate lifetime gross-margin value of this customer?","choices":["$3,600","$720","$2,400","$1,440"],"answer":3,"explain":"Annual spend is $720, five years is $3,600 of revenue, and 40 percent of that is $1,440. The $3,600 figure ignores margin."},{"id":"ent-025","sub":"Marketing Management","diff":1,"q":"A brand name, logo or design that identifies a product and distinguishes it from others is called a:","choices":["Trademark","Patent","Copyright","Franchise"],"answer":0,"explain":"Trademarks protect brand identifiers. Patents protect inventions, copyrights protect creative works, and a franchise is a business model."},{"id":"ent-026","sub":"Marketing Management","diff":3,"q":"A business asks 300 customers to rate a new flavour on a 1-to-5 scale. This is which type of research?","choices":["Secondary qualitative research","Primary quantitative research","Primary qualitative research","Secondary quantitative research"],"answer":1,"explain":"Primary means new data collected directly, and quantitative means numerical ratings. Focus groups would be qualitative."},{"id":"ent-027","sub":"Marketing Management","diff":2,"q":"In which stage of the product life cycle do sales grow fastest and competitors enter?","choices":["Introduction","Maturity","Growth","Decline"],"answer":2,"explain":"Growth is marked by rapid sales increases and new entrants. Introduction has slow sales and maturity has flattening sales."},{"id":"ent-028","sub":"Marketing Management","diff":3,"q":"Which is an example of publicity rather than paid advertising?","choices":["A paid radio spot during the morning drive","A sponsored social media post","A printed flyer distributed for a fee","A local newspaper writing a story about the grand opening"],"answer":3,"explain":"Publicity is unpaid media coverage the business does not control. Any paid placement is advertising."},{"id":"ent-029","sub":"Marketing Management","diff":1,"q":"A manufacturer sells directly to consumers through its own website. Which distribution channel is this?","choices":["Direct channel","Indirect channel through one retailer","Two-tier wholesale channel","Franchise channel with independent owners"],"answer":0,"explain":"A direct channel skips intermediaries. The others all include at least one middleman."},{"id":"ent-030","sub":"Marketing Management","diff":2,"q":"A customer buys a product mainly because a friend recommended it. This is most influenced by:","choices":["Perceived price","Social influence","Packaging design","Brand loyalty program"],"answer":1,"explain":"Peer recommendation is social influence. Price, packaging and loyalty programs are other drivers."},{"id":"ent-031","sub":"Marketing Management","diff":2,"q":"Which is the main risk of relying on frequent discounts?","choices":["It increases fixed costs immediately","It always raises the cost of goods sold","It trains customers to wait for sales and erodes brand value","It is illegal under federal consumer law"],"answer":2,"explain":"Frequent discounting changes buying patterns and weakens perceived quality, though it does not directly change fixed costs."},{"id":"ent-032","sub":"Marketing Management","diff":2,"q":"A perceptual map shows a brand positioned as premium and eco-friendly. This is best described as:","choices":["Market segmentation","Product mix","Distribution intensity","Brand positioning"],"answer":3,"explain":"Positioning is how a brand is perceived relative to competitors. Segmentation divides the market; the others are different mix decisions."},{"id":"ent-033","sub":"Marketing Management","diff":3,"q":"A retailer buys a jacket for $40 and sells it for $60. What is the gross margin percentage?","choices":["33.3%","50.0%","40.0%","66.7%"],"answer":0,"explain":"Gross margin is $20 divided by the $60 selling price, about 33.3 percent. The 50 percent figure is markup on cost, a common trap."},{"id":"ent-034","sub":"Marketing Management","diff":1,"q":"Which promotional tool is most effective at quickly increasing short-term sales?","choices":["Corporate image advertising","Sales promotion, such as a limited-time discount","A public relations press release","Community sponsorship"],"answer":1,"explain":"Sales promotions create immediate purchase incentives. The others build awareness or reputation over time."},{"id":"ent-035","sub":"Financial Management and Initial Capital","diff":1,"q":"Which is an equity source of financing?","choices":["Taking out a bank term loan","Using a bank line of credit","Selling an ownership stake to an angel investor","Negotiating supplier trade credit"],"answer":2,"explain":"Equity means giving up ownership. Loans and trade credit are debt financing."},{"id":"ent-036","sub":"Financial Management and Initial Capital","diff":1,"q":"Which equation is the basis of the balance sheet?","choices":["Assets = Revenue - Expenses","Net income = Assets - Liabilities","Equity = Revenue + Expenses","Assets = Liabilities + Owner''s Equity"],"answer":3,"explain":"The accounting equation states that assets equal liabilities plus equity, and the balance sheet must balance on this basis."},{"id":"ent-037","sub":"Financial Management and Initial Capital","diff":2,"q":"A business has revenue of $180,000, cost of goods sold of $70,000, operating expenses of $55,000 and income taxes of $10,000. What is net income?","choices":["$45,000","$55,000","$65,000","$110,000"],"answer":0,"explain":"Gross profit is $110,000, less $55,000 operating expenses gives $55,000, less $10,000 taxes gives $45,000. Stopping before taxes gives $55,000."},{"id":"ent-038","sub":"Financial Management and Initial Capital","diff":2,"q":"Under accrual accounting, when is a sale recorded?","choices":["Only when the customer pays in cash","When it is earned, regardless of when cash is received","Only when the year ends regardless of activity","At the moment the purchase order is issued"],"answer":1,"explain":"Accrual accounting recognizes revenue when earned, under the matching and revenue-recognition principles, not when cash moves."},{"id":"ent-039","sub":"Financial Management and Initial Capital","diff":3,"q":"Current assets are $90,000 and current liabilities are $60,000. What is the current ratio?","choices":["0.67","2.0","1.5","0.5"],"answer":2,"explain":"The current ratio is current assets divided by current liabilities, $90,000 divided by $60,000, which is 1.5. Inverting the ratio gives 0.67."},{"id":"ent-040","sub":"Financial Management and Initial Capital","diff":3,"q":"A business has fixed costs of $40,000 and a contribution margin ratio of 40 percent. What are the break-even sales in dollars?","choices":["$16,000","$40,000","$160,000","$100,000"],"answer":3,"explain":"Break-even sales equal fixed costs divided by the contribution margin ratio, $40,000 divided by 0.40, which is $100,000."},{"id":"ent-041","sub":"Financial Management and Initial Capital","diff":1,"q":"A business has $50,000 in current assets and $38,000 in current liabilities. What is its working capital?","choices":["$12,000","$88,000","$38,000","$50,000"],"answer":0,"explain":"Working capital is current assets minus current liabilities, $50,000 less $38,000."},{"id":"ent-042","sub":"Financial Management and Initial Capital","diff":2,"q":"A $50,000 truck has a $5,000 salvage value and a 5-year life. What is annual straight-line depreciation?","choices":["$10,000 per year","$9,000 per year","$45,000 per year","$5,000 per year"],"answer":1,"explain":"Straight-line depreciation is cost minus salvage value over useful life, $45,000 divided by 5, which is $9,000. Ignoring salvage gives $10,000."},{"id":"ent-043","sub":"Financial Management and Initial Capital","diff":2,"q":"Which category on the statement of cash flows includes cash paid to buy new equipment?","choices":["Operating activities","Financing activities","Investing activities","Balance sheet reconciliation"],"answer":2,"explain":"Purchases of long-term assets are investing activities. Operating covers day-to-day income and expenses, and financing covers debt and equity."},{"id":"ent-044","sub":"Financial Management and Initial Capital","diff":2,"q":"A bank loan requires a personal guarantee from the owner. What is the main added risk?","choices":["The business''s tax rate increases automatically","The owner must give up voting control","The loan interest becomes tax-exempt","The owner''s personal assets could be at risk if the business defaults"],"answer":3,"explain":"A personal guarantee makes the owner personally liable for the debt, which is a personal exposure rather than a tax or control change."},{"id":"ent-045","sub":"Financial Management and Initial Capital","diff":1,"q":"Which statement shows a business''s financial position at a specific point in time?","choices":["Balance sheet","Income statement","Statement of cash flows","Budget variance report"],"answer":0,"explain":"The balance sheet is a snapshot at one date. The income statement and cash flow statement cover a period."},{"id":"ent-046","sub":"Financial Management and Initial Capital","diff":2,"q":"Revenue is $250,000 and cost of goods sold is $150,000. What is the gross profit margin?","choices":["60%","40%","66.7%","150%"],"answer":1,"explain":"Gross profit is $100,000, and $100,000 divided by $250,000 is 40 percent. The 60 percent figure is the cost ratio."},{"id":"ent-047","sub":"Financial Management and Initial Capital","diff":2,"q":"A supplier offers terms of 2/10, net 30. A $1,000 invoice is paid on day 10. How much is paid?","choices":["$1,000 with no discount","$1,020","$980","$1,030"],"answer":2,"explain":"Paying within the 10-day window takes a 2 percent discount, so $1,000 less $20 is $980."},{"id":"ent-048","sub":"Financial Management and Initial Capital","diff":3,"q":"During a period of rising costs, which inventory method usually reports the highest net income?","choices":["LIFO","Specific identification","Specific identification always gives the lowest income","FIFO"],"answer":3,"explain":"FIFO assigns the older, cheaper costs to cost of goods sold when prices rise, so income is higher. LIFO does the opposite and is the trap."},{"id":"ent-049","sub":"Financial Management and Initial Capital","diff":1,"q":"A budget that compares planned figures with actual results is used to identify:","choices":["Variances","Depreciation schedules","Break-even points","Equity ratios"],"answer":0,"explain":"The gap between planned and actual amounts is the variance, which managers investigate."},{"id":"ent-050","sub":"Financial Management and Initial Capital","diff":3,"q":"A $20,000 investment returns $5,000 of net profit in one year. What is the return on investment?","choices":["20%","25%","4%","5,000%"],"answer":1,"explain":"ROI is net profit divided by the investment, $5,000 divided by $20,000, which is 25 percent."},{"id":"ent-051","sub":"Financial Management and Initial Capital","diff":2,"q":"A $100,000 loan carries 6 percent simple annual interest for 3 years. What is the total interest?","choices":["$6,000","$16,000","$18,000","$20,000"],"answer":2,"explain":"Annual interest is $6,000, and over 3 years on simple interest that is $18,000. The $6,000 figure is only one year."},{"id":"ent-052","sub":"Legal Issues and Business Structure","diff":1,"q":"What is the main legal drawback of a sole proprietorship?","choices":["The business cannot hire employees","The business must file a corporate tax return","The business must have at least three owners","The owner has unlimited personal liability for business debts"],"answer":3,"explain":"A sole proprietor and the business are legally one person, so personal assets are exposed. Hiring and tax filing are allowed."},{"id":"ent-053","sub":"Legal Issues and Business Structure","diff":1,"q":"Which business structure gives owners limited liability and pass-through taxation by default?","choices":["Limited liability company (LLC)","C corporation","General partnership","Sole proprietorship"],"answer":0,"explain":"An LLC shields owners from most business debts and, by default, its profits flow to owners'' returns. A C corporation taxes entity profits separately."},{"id":"ent-054","sub":"Legal Issues and Business Structure","diff":2,"q":"How is income of a C corporation taxed?","choices":["Taxed only once at the shareholder level","Taxed at the entity level, and dividends are taxed again to shareholders","Not taxed if all profits are reinvested","Taxed only on capital gains realized by the owners"],"answer":1,"explain":"This is double taxation: corporate income tax, then tax on dividends. Pass-through entities avoid the first layer."},{"id":"ent-055","sub":"Legal Issues and Business Structure","diff":1,"q":"Which intellectual property protects a company''s logo and slogan used to identify its goods?","choices":["Patent","Copyright","Trademark","Trade secret"],"answer":2,"explain":"Trademarks protect brand identifiers used in commerce. Patents cover inventions and copyrights cover creative works."},{"id":"ent-056","sub":"Legal Issues and Business Structure","diff":2,"q":"Under U.S. law, how long does a standard utility patent generally last from the filing date?","choices":["10 years from the date granted","50 years after the author''s death","5 years, renewable indefinitely","20 years from the filing date"],"answer":3,"explain":"U.S. utility patents run 20 years from filing. Copyright is the one tied to the author''s life."},{"id":"ent-057","sub":"Legal Issues and Business Structure","diff":1,"q":"Which is NOT generally required for a valid contract?","choices":["Notarized signatures","Offer","Acceptance","Consideration"],"answer":0,"explain":"A contract needs offer, acceptance and consideration, plus capacity and lawful purpose. Notarization is not required for most contracts."},{"id":"ent-058","sub":"Legal Issues and Business Structure","diff":3,"q":"Under the U.S. Uniform Commercial Code, a contract for the sale of goods priced at or above which amount generally must be in writing?","choices":["$50","$500","$5,000","$50,000"],"answer":1,"explain":"UCC section 2-201, the statute of frauds for goods, applies at $500 or more."},{"id":"ent-059","sub":"Legal Issues and Business Structure","diff":2,"q":"Which federal law sets minimum wage and overtime rules in the United States?","choices":["Sherman Antitrust Act","Clayton Act","Fair Labor Standards Act","Securities Act of 1933"],"answer":2,"explain":"The FLSA governs minimum wage, overtime and child labour. The others cover antitrust and securities."},{"id":"ent-060","sub":"Legal Issues and Business Structure","diff":3,"q":"A business owner signs a contract through an agent without revealing the principal. Which legal concept describes this?","choices":["Apparent authority","Warranty of title","Promissory estoppel","Undisclosed principal"],"answer":3,"explain":"An undisclosed principal is bound and can enforce the agent''s contract. Apparent authority is a different agency concept."},{"id":"ent-061","sub":"Legal Issues and Business Structure","diff":2,"q":"A customer is injured by a defective product sold by a retailer. Under strict product liability, who can be held liable?","choices":["The manufacturer and the retailer in the chain of distribution","Only the customer who used the product","Only the shipping company","The insurance company that wrote the policy"],"answer":0,"explain":"Strict product liability reaches every seller in the distribution chain for a defective product, regardless of fault."},{"id":"ent-062","sub":"Legal Issues and Business Structure","diff":3,"q":"In a general partnership, what is each partner''s liability for partnership debts?","choices":["Limited to their capital contribution","Joint and several, so each partner may be personally liable for all of it","Zero, because the partnership is separate","Only for debts they personally signed"],"answer":1,"explain":"General partners have unlimited joint and several liability. Limited liability is the feature of LLCs and some other structures."},{"id":"ent-063","sub":"Legal Issues and Business Structure","diff":1,"q":"Which form of intellectual property protects confidential formulas such as a secret recipe, without registration?","choices":["Trademark","Copyright","Trade secret","Patent"],"answer":2,"explain":"Trade secrets are protected by keeping the information confidential. Registration would destroy that secrecy."},{"id":"ent-064","sub":"Legal Issues and Business Structure","diff":3,"q":"A sole proprietor operates under a business name other than the owner''s legal name. What must the owner typically do?","choices":["Obtain a federal patent for the name","Register a copyright with the Library of Congress","Incorporate immediately to avoid the filing","File a doing-business-as (DBA) or assumed name certificate"],"answer":3,"explain":"A DBA or assumed name filing discloses the owner behind a trade name. A patent or copyright does not cover business names."},{"id":"ent-065","sub":"Legal Issues and Business Structure","diff":2,"q":"A tenant signs a commercial lease with a personal guarantee. What is the main personal risk?","choices":["The owner may lose personal assets if the business defaults on rent","The landlord takes ownership of the company","The lease ends automatically after one year","The business loses its trademark rights"],"answer":0,"explain":"A personal guarantee makes the owner liable for the lease obligations, which reaches personal assets."},{"id":"ent-066","sub":"Legal Issues and Business Structure","diff":2,"q":"Which federal law requires companies offering securities to the public to register them and disclose material information?","choices":["Sherman Antitrust Act of 1890","Securities Act of 1933","Fair Credit Reporting Act","Robinson-Patman Act"],"answer":1,"explain":"The 1933 Act governs public offerings and disclosure. The others cover antitrust and credit reporting."},{"id":"ent-067","sub":"Legal Issues and Business Structure","diff":3,"q":"Which doctrine protects directors who make good-faith business decisions that later prove wrong?","choices":["Promissory estoppel","Respondeat superior","Business judgment rule","Statute of frauds"],"answer":2,"explain":"The business judgment rule presumes good-faith, informed decisions are not second-guessed for poor outcomes."},{"id":"ent-068","sub":"Operations and Personnel Management","diff":2,"q":"Which inventory system places a new order when stock falls to a preset level?","choices":["Just-in-case stockpiling","Consignment inventory","ABC analysis","Reorder point system"],"answer":3,"explain":"A reorder point is a set quantity that triggers an order. ABC analysis ranks items by value and does not trigger orders."},{"id":"ent-069","sub":"Operations and Personnel Management","diff":1,"q":"What is the first step in recruiting new employees?","choices":["Analyze the job and write a job description","Make a job offer to a candidate","Run background checks","Conduct interviews"],"answer":0,"explain":"A clear job analysis and description define what to recruit for. Offers, checks and interviews come later."},{"id":"ent-070","sub":"Operations and Personnel Management","diff":3,"q":"Which formula calculates the economic order quantity (EOQ), where D is annual demand, S is ordering cost and H is holding cost per unit?","choices":["D times S times H","The square root of (2DS divided by H)","(D plus S) divided by H","2DH divided by S"],"answer":1,"explain":"EOQ balances ordering and holding costs and equals the square root of 2DS/H."},{"id":"ent-071","sub":"Operations and Personnel Management","diff":1,"q":"In Maslow''s hierarchy of needs, which need is at the bottom?","choices":["Self-actualization","Esteem","Physiological needs","Social belonging"],"answer":2,"explain":"The hierarchy starts with basic physiological needs and moves up to self-actualization at the top."},{"id":"ent-072","sub":"Operations and Personnel Management","diff":1,"q":"A manager makes decisions alone with minimal employee input. Which leadership style is this?","choices":["Laissez-faire leadership","Democratic leadership","Transformational leadership","Autocratic leadership"],"answer":3,"explain":"Autocratic leaders decide alone. Laissez-faire gives employees broad freedom and democratic leaders seek input."},{"id":"ent-073","sub":"Operations and Personnel Management","diff":2,"q":"What is the primary purpose of a Gantt chart?","choices":["To visualize a project timeline and the dependencies between tasks","To calculate break-even units","To measure employee satisfaction","To track customer demographics over time"],"answer":0,"explain":"A Gantt chart shows task durations, sequence and overlap over time. Break-even and satisfaction are different tools."},{"id":"ent-074","sub":"Operations and Personnel Management","diff":2,"q":"A bakery''s oven runs at full capacity during peak hours and customers wait. What is the best short-term operations response?","choices":["Permanently double the number of ovens immediately","Shift some production to off-peak hours and take pre-orders for peak items","Reduce product quality to speed up production","Raise prices by 50 percent during peak hours"],"answer":1,"explain":"Shifting load and pre-ordering smooths demand at low cost. Doubling capacity is a long-term capital decision."},{"id":"ent-075","sub":"Operations and Personnel Management","diff":3,"q":"Which quality tool uses a fishbone-shaped diagram to organize possible causes of a defect?","choices":["Pareto chart","Control chart","Cause-and-effect (Ishikawa) diagram","Histogram"],"answer":2,"explain":"The Ishikawa diagram organizes causes by category around an effect. Pareto charts rank problems by frequency."},{"id":"ent-076","sub":"Operations and Personnel Management","diff":1,"q":"What term describes the number of employees a manager directly supervises?","choices":["Chain of command","Line authority","Unity of direction","Span of control"],"answer":3,"explain":"Span of control is the count of direct reports, which shapes how many layers an organization needs."},{"id":"ent-077","sub":"Operations and Personnel Management","diff":2,"q":"A business with 12 employees loses 3 in a year. What is the annual turnover rate?","choices":["25%","12%","33%","3%"],"answer":0,"explain":"Turnover rate is separations divided by average headcount, 3 divided by 12, which is 25 percent."},{"id":"ent-078","sub":"Operations and Personnel Management","diff":1,"q":"Which training method has a new employee learn the job while working under a skilled coworker?","choices":["Classroom lecture","On-the-job training with mentoring","Online self-paced course","Simulation"],"answer":1,"explain":"On-the-job training with a mentor builds skills in the real work setting. The others happen away from the job."},{"id":"ent-079","sub":"Operations and Personnel Management","diff":3,"q":"A worker sets their own hours, uses their own tools and is paid per project. How is this worker most likely classified?","choices":["W-2 employee","Part-time apprentice","Independent contractor","Salaried manager"],"answer":2,"explain":"Control over how and when work is done and ownership of tools point to an independent contractor, which has tax and legal consequences."},{"id":"ent-080","sub":"Operations and Personnel Management","diff":2,"q":"What is the main goal of just-in-time (JIT) inventory?","choices":["Build large safety stocks to avoid any shortage","Increase warehouse space to hold more stock","Eliminate all supplier relationships","Reduce holding costs by receiving goods close to when they are needed"],"answer":3,"explain":"JIT cuts holding costs by timing deliveries to need. Large safety stocks are the opposite approach."},{"id":"ent-081","sub":"Operations and Personnel Management","diff":3,"q":"Orders wait 8 minutes at the kitchen pass in a restaurant. Which tool best sets priorities among the causes of slow service?","choices":["Pareto analysis","Net present value","Break-even analysis","Ratio analysis of the balance sheet"],"answer":0,"explain":"Pareto analysis ranks causes so the few that drive most delays get fixed first. The others evaluate money or profit, not causes."},{"id":"ent-082","sub":"Operations and Personnel Management","diff":1,"q":"Which is a benefit of delegation?","choices":["It removes all accountability from the manager","It frees managers for strategic work and develops employees'' skills","It eliminates the need for training","It guarantees higher profits immediately"],"answer":1,"explain":"Delegation spreads work and builds capability while the manager keeps overall accountability."},{"id":"ent-083","sub":"Operations and Personnel Management","diff":2,"q":"A new employee arrives late repeatedly. What is the best first step under progressive discipline?","choices":["Terminate the employee immediately without notice","Post the employee''s attendance record publicly","Document the issue and hold a private coaching conversation","Ignore the issue until the annual review"],"answer":2,"explain":"Documentation and a private conversation are the fair first steps. Immediate termination skips the progressive process."},{"id":"ent-084","sub":"Operations and Personnel Management","diff":1,"q":"A plant can produce 5,000 units per week and currently produces 4,000. What is its capacity utilization?","choices":["125%","20%","75%","80%"],"answer":3,"explain":"Capacity utilization is actual output divided by capacity, 4,000 divided by 5,000, which is 80 percent."},{"id":"ent-085","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"A retailer collects sales tax from customers and sends it to the state. In this role, the retailer is acting as:","choices":["A collection agent for the government","An employee of the state","The beneficiary of the tax","A tax-exempt organization"],"answer":0,"explain":"Sales tax is paid by the customer but collected and remitted by the seller on the government''s behalf."},{"id":"ent-086","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which tax is withheld from employee paychecks for Social Security and Medicare?","choices":["Federal Unemployment Tax Act (FUTA) taxes","Federal Insurance Contributions Act (FICA) taxes","Corporate income tax","Self-employment tax"],"answer":1,"explain":"FICA funds Social Security and Medicare and is split between employer and employee. FUTA is an employer-only unemployment tax."},{"id":"ent-087","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"A manager finds that a supplier is falsifying safety certificates. Which action is most ethical?","choices":["Keep buying because the product is cheaper","Tell customers privately that the product is safe","Report the issue internally and stop purchasing until the supplier is verified","Ignore it since it is not the company''s fault"],"answer":2,"explain":"Reporting and pausing purchases addresses the safety risk and is transparent. Ignoring it or misleading customers is unethical."},{"id":"ent-088","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"Corporate social responsibility is best defined as:","choices":["Compliance with mandatory tax filing","Paying only the legal minimum wage","Limiting liability through incorporation","Voluntary actions beyond legal requirements that benefit society"],"answer":3,"explain":"CSR is voluntary action beyond what the law requires, such as environmental or community programs."},{"id":"ent-089","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which federal law prohibits contracts, combinations and conspiracies that unreasonably restrain trade?","choices":["Sherman Antitrust Act","Clayton Act","Robinson-Patman Act","Federal Trade Commission Act"],"answer":0,"explain":"The Sherman Act is the foundational antitrust statute on restraints of trade. The others address specific practices or agency powers."},{"id":"ent-090","sub":"Ethics, Taxes and Government Regulation","diff":3,"q":"Which expense is generally fully deductible in the year it is paid by a small business?","choices":["Purchase of land","Ordinary and necessary business rent","An owner''s personal vacation","A 15-year building improvement"],"answer":1,"explain":"Ordinary and necessary business expenses are deductible when paid. Land is not depreciable, and capital improvements are depreciated over time."},{"id":"ent-091","sub":"Ethics, Taxes and Government Regulation","diff":3,"q":"A business advertises that a product is ''clinically proven'' without any supporting study. Which federal agency is most likely to act?","choices":["Securities and Exchange Commission","Federal Reserve","Federal Trade Commission","Internal Revenue Service"],"answer":2,"explain":"The FTC polices deceptive advertising. The SEC covers securities and the Fed covers monetary policy."},{"id":"ent-092","sub":"Ethics, Taxes and Government Regulation","diff":3,"q":"Sole proprietors report business income and expenses on which IRS schedule attached to Form 1040?","choices":["Schedule A","Form 1120","Schedule K-1","Schedule C"],"answer":3,"explain":"Schedule C is the profit or loss from business form for sole proprietors. Form 1120 is a corporate return."},{"id":"ent-093","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which federal law is the primary statute governing air pollution emissions?","choices":["Clean Air Act","Clean Water Act","Endangered Species Act","Resource Conservation and Recovery Act"],"answer":0,"explain":"The Clean Air Act regulates air emissions. The others cover water, species and waste."},{"id":"ent-094","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"A business owner awards a contract to a company owned by a relative without disclosing it. This is a:","choices":["Breach of warranty","Conflict of interest","Patent infringement","Sales tax violation"],"answer":1,"explain":"A conflict of interest exists when personal ties could compromise business decisions, and undisclosed ties make it worse."},{"id":"ent-095","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which business form generally passes its profits and losses through to the owners'' personal tax returns?","choices":["C corporation","Publicly traded corporation","Partnership","Cooperative taxed at the entity level"],"answer":2,"explain":"Partnerships are pass-through entities that report income on partners'' returns. C corporations and cooperatives can be taxed at the entity level."},{"id":"ent-096","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"A small business collects customers'' emails for a newsletter. What is the best practice?","choices":["Share the list with partners without notice","Buy extra lists from unknown sellers","Store all data in a public folder","Obtain consent and provide an easy opt-out"],"answer":3,"explain":"Consent and an easy opt-out respect customer privacy and anti-spam rules. Sharing or buying lists without consent breaks both."},{"id":"ent-097","sub":"Ethics, Taxes and Government Regulation","diff":1,"q":"A stakeholder is best defined as:","choices":["Any person or group affected by the business''s decisions","Only the business''s owners and shareholders","Only the company''s competitors","Only government regulators"],"answer":0,"explain":"Stakeholders include employees, customers, communities and others affected, not only owners."},{"id":"ent-098","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which tax concept requires a business to pay tax during the year rather than only at filing?","choices":["Withholding exemption","Estimated tax payments","Tax credit carryforward","Capital loss carryback"],"answer":1,"explain":"Estimated tax payments are made quarterly by businesses and self-employed owners who do not have withholding."},{"id":"ent-099","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which accounting principle requires reporting all information that could affect a user''s decision?","choices":["Conservatism","Historical cost","Full disclosure","Matching"],"answer":2,"explain":"Full disclosure requires material information to be reported. Historical cost, conservatism and matching are other principles."},{"id":"ent-100","sub":"Ethics, Taxes and Government Regulation","diff":2,"q":"Which federal agency sets and enforces workplace safety standards?","choices":["Environmental Protection Agency","Federal Communications Commission","Wage and Hour Division","Occupational Safety and Health Administration (OSHA)"],"answer":3,"explain":"OSHA sets and enforces workplace safety standards. The EPA covers environmental rules and the Wage and Hour Division covers pay."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'healthcare-administration', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"hca-001","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which type of managed care plan requires members to select a primary care provider and generally requires referrals to see specialists?","choices":["Indemnity plan","Health maintenance organization (HMO)","Preferred provider organization (PPO)","High-deductible health plan with HSA"],"answer":1,"explain":"HMOs use a primary care gatekeeper and typically require referrals; PPOs allow self-referral and out-of-network care at higher cost."},{"id":"hca-002","sub":"Healthcare Finances and Budgeting","diff":2,"q":"A hospital receives a fixed amount per member per month to cover all necessary care for a defined population, regardless of how many services each member uses. What is this payment method called?","choices":["Fee-for-service","Per diem","Case rate","Capitation"],"answer":3,"explain":"Capitation shifts financial risk to the provider. The trap is case rate, which pays a fixed amount per episode rather than per member."},{"id":"hca-003","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which type of hospital ownership is operated by a state or local government?","choices":["Public (government) hospital","Investor-owned hospital","Voluntary nonprofit hospital","Faith-based hospital"],"answer":0,"explain":"Public hospitals are owned and run by government entities; investor-owned hospitals are for-profit, and voluntary hospitals are nonprofit."},{"id":"hca-004","sub":"Healthcare Organizations and Structure","diff":2,"q":"An accountable care organization (ACO) differs from traditional fee-for-service primarily because ACO participants:","choices":["Are paid only for each procedure they perform","Must accept no Medicare beneficiaries","Share savings or losses based on total cost and quality of care for an attributed population","Are exempt from quality reporting"],"answer":2,"explain":"ACOs are accountable for total cost and quality for a population, so they can share savings or losses. Quality reporting is required, not waived."},{"id":"hca-005","sub":"Healthcare Organizations and Structure","diff":3,"q":"A hospital''s case mix index (CMI) is used primarily to:","choices":["Measure patient satisfaction with the discharge process","Calculate the percentage of beds occupied","Compare the average resource intensity of the patient mix against a standard, to inform payment and staffing","Track the number of emergency visits per year"],"answer":2,"explain":"CMI reflects the relative resource use of a patient mix. It is often confused with occupancy, which measures bed use."},{"id":"hca-006","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which term describes a hospital''s complete list of standard charges for every item and service, used as the starting point for billing?","choices":["Chargemaster","Remittance advice","Explanation of benefits","Superbill"],"answer":0,"explain":"The chargemaster is the hospital''s master price list. A superbill is a superficially similar form used by physician offices."},{"id":"hca-007","sub":"Healthcare Organizations and Structure","diff":2,"q":"A community health center that receives federal grants, serves patients regardless of ability to pay, and is reimbursed under a special Medicare payment system is most likely a:","choices":["Ambulatory surgical center","Critical access hospital","Skilled nursing facility","Federally qualified health center (FQHC)"],"answer":3,"explain":"FQHCs receive HRSA grants, serve underserved populations, and are paid under a Medicare prospective payment system for clinic visits."},{"id":"hca-008","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which level of long-term care provides 24-hour skilled nursing and rehabilitation for patients who no longer need hospital care?","choices":["Assisted living facility","Skilled nursing facility","Hospice","Adult day care center"],"answer":1,"explain":"Skilled nursing facilities provide daily skilled nursing and therapy. Assisted living focuses on custodial help with daily activities."},{"id":"hca-009","sub":"Healthcare Finances and Budgeting","diff":2,"q":"Which payment method pays providers for each unit of service delivered, so revenue rises with the volume of services?","choices":["Fee-for-service","Capitation","Bundled payment","Pay-for-performance"],"answer":0,"explain":"Fee-for-service rewards volume. Bundled payments and pay-for-performance tie payment to episodes or outcomes instead."},{"id":"hca-010","sub":"Healthcare Organizations and Structure","diff":3,"q":"A hospital has an average daily census of 180 patients and 240 staffed beds. What is its occupancy rate?","choices":["60%","67%","75%","133%"],"answer":2,"explain":"Occupancy = 180 / 240 = 75%. Dividing the other way gives 133%, a common error."},{"id":"hca-011","sub":"Staffing and Training","diff":1,"q":"What does the abbreviation FTE stand for in healthcare staffing?","choices":["Fixed-term employee","Full-time equivalent","Facility-tracked expense","Financial team evaluation"],"answer":1,"explain":"FTE converts part-time and full-time hours into full-time units, commonly 40 hours per week or 2,080 hours per year."},{"id":"hca-012","sub":"Strategic Management","diff":2,"q":"In a SWOT analysis, which factor is internal to the organization?","choices":["Opportunities","Threats","Competitor pricing","Strengths"],"answer":3,"explain":"Strengths and weaknesses are internal; opportunities and threats are external. Competitor pricing is an external threat."},{"id":"hca-013","sub":"Healthcare Policy and Regulation","diff":2,"q":"Under OSHA''s Bloodborne Pathogens Standard, what must an employer provide to employees with occupational exposure to blood?","choices":["Protective equipment purchased by each employee","Training only after an exposure incident occurs","A notice posted in the emergency room only","Annual training and the hepatitis B vaccine at no cost to the employee"],"answer":3,"explain":"The standard requires annual training, free hepatitis B vaccination, and protective equipment for exposed employees. The other choices contradict it."},{"id":"hca-014","sub":"Communication and Leadership","diff":1,"q":"In SBAR communication, what does the letter B stand for?","choices":["Balance","Background","Billing","Baseline"],"answer":1,"explain":"SBAR stands for Situation, Background, Assessment, Recommendation."},{"id":"hca-015","sub":"Communication and Leadership","diff":2,"q":"Which leadership style involves making decisions after gathering input from staff while the leader keeps final authority?","choices":["Autocratic","Laissez-faire","Participative (consultative)","Bureaucratic"],"answer":2,"explain":"Participative leaders consult staff before deciding. Autocratic leaders decide alone, and laissez-faire leaders step back."},{"id":"hca-016","sub":"Healthcare Technology","diff":3,"q":"Which interoperability standard uses RESTful APIs and modular resources to exchange health data and is the modern successor to HL7 version 2 messaging?","choices":["FHIR (Fast Healthcare Interoperability Resources)","DICOM","NCPDP SCRIPT","X12 837"],"answer":0,"explain":"FHIR is the HL7 standard built on web APIs. DICOM handles imaging, NCPDP SCRIPT handles prescriptions, and X12 837 handles claims."},{"id":"hca-017","sub":"Healthcare Technology","diff":3,"q":"A PACS system is primarily used to:","choices":["Schedule patient appointments","Store, retrieve, and display medical images","Process insurance eligibility checks","Track inventory of surgical supplies"],"answer":1,"explain":"PACS (picture archiving and communication system) manages medical images such as X-rays and CT scans."},{"id":"hca-018","sub":"Healthcare Technology","diff":1,"q":"What is the main purpose of an electronic health record (EHR)?","choices":["A centralized digital record of a patient''s health information across care","A patient''s personal diary of symptoms only","Billing-only software for insurance claims","A scheduling tool for surgeons"],"answer":0,"explain":"An EHR holds the clinical record and can be shared across care settings. Billing and scheduling are functions it may support, not its main purpose."},{"id":"hca-019","sub":"Healthcare Technology","diff":2,"q":"Which telehealth modality involves recording a patient''s images or data and sending them to a specialist for later review?","choices":["Synchronous video visit","Remote patient monitoring","Store-and-forward","Real-time audio call"],"answer":2,"explain":"Store-and-forward is asynchronous. Remote patient monitoring sends ongoing device readings, which is different."},{"id":"hca-020","sub":"Healthcare Billing and Insurance","diff":3,"q":"A claim is denied because the diagnosis code does not support medical necessity for the procedure billed. Which denial category best describes this?","choices":["Eligibility","Timely filing","Duplicate claim","Medical necessity"],"answer":3,"explain":"A medical necessity denial means the documented diagnosis does not justify the service. Eligibility denials concern coverage status."},{"id":"hca-021","sub":"Healthcare Billing and Insurance","diff":1,"q":"What is a deductible?","choices":["The fee paid each time a service is received","The percentage of costs shared after the plan pays","The amount the insured pays before the plan begins paying covered services","The maximum an insurer pays in a year"],"answer":2,"explain":"The deductible is the out-of-pocket amount paid before coverage starts paying. Coinsurance is the percentage share, and copayment is the fixed fee."},{"id":"hca-022","sub":"Healthcare Billing and Insurance","diff":2,"q":"Coinsurance is best defined as:","choices":["A flat fee per visit","A deductible paid in installments","The insured''s percentage share of covered costs after the deductible","A premium paid by the employer"],"answer":2,"explain":"Coinsurance is a percentage the insured pays of allowed charges after the deductible. Copayment is a fixed amount."},{"id":"hca-023","sub":"Healthcare Billing and Insurance","diff":1,"q":"What is a copayment?","choices":["A percentage of allowed charges","A fixed amount paid at the time of service","The annual maximum the insured must pay","A discount from the provider''s chargemaster"],"answer":1,"explain":"A copayment is a fixed dollar amount, often due at the visit. Coinsurance is a percentage."},{"id":"hca-024","sub":"Healthcare Organizations and Structure","diff":2,"q":"Which federal law requires hospitals with emergency departments to screen and stabilize patients regardless of ability to pay?","choices":["EMTALA","HITECH","CLIA","ERISA"],"answer":0,"explain":"EMTALA is the Emergency Medical Treatment and Labor Act. HITECH covers health IT and breach rules, CLIA covers lab testing, and ERISA covers employee benefit plans."},{"id":"hca-025","sub":"Healthcare Billing and Insurance","diff":3,"q":"Modifier 25 appended to an E/M code indicates:","choices":["A significant, separately identifiable E/M service on the same day as a procedure","The patient was seen by an anesthesiologist","The service was performed in an emergency room","The visit was a telehealth service"],"answer":0,"explain":"Modifier 25 lets a physician bill a separate E/M visit on the same day as a procedure when the visit is significant and separately identifiable."},{"id":"hca-026","sub":"Staffing and Training","diff":1,"q":"Which HR process verifies a clinician''s licenses, certifications, and training before hiring or privileging?","choices":["Onboarding","Performance appraisal","Exit interview","Credentialing"],"answer":3,"explain":"Credentialing verifies qualifications. Onboarding is the later process of integrating a new hire."},{"id":"hca-027","sub":"Staffing and Training","diff":2,"q":"Employee turnover rate is calculated as:","choices":["Total hires divided by total employees","Separations during the period divided by average number of employees, times 100","Number of employees hired per year","Terminations divided by hires"],"answer":1,"explain":"Turnover rate = separations divided by average headcount, multiplied by 100. Hires are not part of the formula."},{"id":"hca-028","sub":"Staffing and Training","diff":2,"q":"Which training method is most effective for teaching staff a new electronic health record system?","choices":["Self-study of the vendor manual only","Hands-on training in a practice environment with super-users","A single annual lecture","No training; staff learn on the job"],"answer":1,"explain":"Hands-on practice with peer support builds skills. Reading alone or a single lecture does not transfer well."},{"id":"hca-029","sub":"Staffing and Training","diff":2,"q":"Performance appraisal feedback is most effective when it is:","choices":["Delivered once a year only","Based on vague impressions","Shared only with the employee''s supervisor","Specific, timely, and tied to documented goals"],"answer":3,"explain":"Effective feedback is specific, timely, and linked to measurable goals rather than impressions."},{"id":"hca-030","sub":"Healthcare Policy and Regulation","diff":3,"q":"Which federal law requires covered employers with at least 50 employees to provide eligible employees up to 12 weeks of unpaid, job-protected leave per year?","choices":["Fair Labor Standards Act","Americans with Disabilities Act","Family and Medical Leave Act","Consolidated Omnibus Budget Reconciliation Act"],"answer":2,"explain":"The FMLA sets the 50-employee threshold and 12-week leave. The ADA applies at 15 employees, which is a common mix-up."},{"id":"hca-031","sub":"Staffing and Training","diff":1,"q":"What does the abbreviation PTO stand for in staffing benefits?","choices":["Paid time off","Patient tracking order","Physician training outline","Pre-tax operations"],"answer":0,"explain":"PTO (paid time off) combines vacation and sick time in one bank."},{"id":"hca-032","sub":"Staffing and Training","diff":2,"q":"Orientation for new clinical staff typically includes which element that accreditation standards expect?","choices":["Only a dress code review","Competency verification for the assigned role","A mandatory vacation request","Social media training only"],"answer":1,"explain":"Accreditors expect staff competency to be verified for their role during orientation."},{"id":"hca-033","sub":"Strategic Management","diff":2,"q":"A hospital''s mission statement primarily answers which question?","choices":["Where do we want to be in ten years?","Why does the organization exist?","What are our quarterly sales targets?","Which competitors should we acquire?"],"answer":1,"explain":"Mission describes purpose; vision describes the desired future state."},{"id":"hca-034","sub":"Strategic Management","diff":1,"q":"The PDSA cycle stands for:","choices":["Plan, Design, Start, Assess","Prepare, Do, Share, Adjust","Plan, Do, Study, Act","Propose, Develop, Standardize, Apply"],"answer":2,"explain":"PDSA (Plan-Do-Study-Act) is a continuous improvement cycle used in quality work."},{"id":"hca-035","sub":"Strategic Management","diff":2,"q":"The balanced scorecard evaluates organizational performance across which four perspectives?","choices":["Revenue, cost, staffing, billing","Strengths, weaknesses, opportunities, threats","Plan, do, study, act","Financial, customer, internal processes, learning and growth"],"answer":3,"explain":"Kaplan and Norton''s balanced scorecard uses those four perspectives. SWOT and PDSA are different tools."},{"id":"hca-036","sub":"Strategic Management","diff":3,"q":"A hospital wants to reduce process variation in a surgical checklist using the DMAIC phases. Which quality approach uses DMAIC?","choices":["Six Sigma","Management by walking around","Zero-based budgeting","Management by objectives"],"answer":0,"explain":"Six Sigma uses Define, Measure, Analyze, Improve, Control (DMAIC) to reduce defects and variation."},{"id":"hca-037","sub":"Strategic Management","diff":3,"q":"In Lean methodology, which of the following is an example of waste?","choices":["Waiting for test results","Standard work documentation","Cross-training staff","Value stream mapping"],"answer":0,"explain":"Waiting is one of the classic Lean wastes. The other options are tools or practices that support flow."},{"id":"hca-038","sub":"Strategic Management","diff":1,"q":"Which term describes a clear statement of what an organization hopes to become in the future?","choices":["Mission","Vision","Objective","Policy"],"answer":1,"explain":"Vision is the future aspiration. Mission is current purpose and objectives are measurable targets."},{"id":"hca-039","sub":"Strategic Management","diff":2,"q":"Porter''s five forces analysis is used to assess:","choices":["Internal staffing levels","Employee satisfaction","Patient transportation","Industry competitive intensity and profitability"],"answer":3,"explain":"The five forces assess rivalry, new entrants, substitutes, supplier power, and buyer power within an industry."},{"id":"hca-040","sub":"Strategic Management","diff":3,"q":"Kotter''s eight-step change model begins with which step?","choices":["Consolidating gains","Anchoring changes in culture","Creating a sense of urgency","Generating short-term wins"],"answer":2,"explain":"Urgency comes first in Kotter''s model. Consolidating gains and anchoring change come later."},{"id":"hca-041","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which accrediting body surveys and accredits U.S. hospitals and other healthcare organizations?","choices":["Centers for Medicare & Medicaid Services","Food and Drug Administration","The Joint Commission","Office of Inspector General"],"answer":2,"explain":"The Joint Commission is a private accreditor. CMS sets Medicare rules, and the OIG investigates fraud."},{"id":"hca-042","sub":"Healthcare Organizations and Structure","diff":2,"q":"Which type of hospital is a rural facility with fewer than 25 inpatient beds that is paid on a cost-based reimbursement basis?","choices":["Long-term acute care hospital","Critical access hospital","Psychiatric hospital","Children''s hospital"],"answer":1,"explain":"Critical access hospitals are designated rural facilities with limited beds and cost-based Medicare payment."},{"id":"hca-043","sub":"Healthcare Organizations and Structure","diff":1,"q":"A physician group in which members share patient care responsibilities and bill under one tax ID is best described as a:","choices":["Group practice","Solo practice","Staff model HMO","Retail clinic"],"answer":0,"explain":"A group practice shares overhead and often a single billing identity. A solo practice has one physician owner."},{"id":"hca-044","sub":"Healthcare Organizations and Structure","diff":2,"q":"In a hospital''s organizational chart, which role reports directly to the board of directors and is responsible for overall operations?","choices":["Chief financial officer","Director of nursing","Chief of medical staff","Chief executive officer"],"answer":3,"explain":"The CEO is the top executive and reports to the board. Other executives report to the CEO."},{"id":"hca-045","sub":"Healthcare Organizations and Structure","diff":3,"q":"A patient who may self-refer to specialists and use out-of-network providers, at a higher cost-sharing rate, most likely has which plan type?","choices":["HMO","EPO","POS","PPO"],"answer":3,"explain":"PPOs allow self-referral and out-of-network care at higher cost. EPOs and HMOs generally do not cover out-of-network care."},{"id":"hca-046","sub":"Healthcare Organizations and Structure","diff":1,"q":"Which type of hospital primarily serves patients with mental illness?","choices":["Psychiatric hospital","Rehabilitation hospital","Maternity center","Hospice"],"answer":0,"explain":"Psychiatric hospitals focus on mental health care. Rehabilitation hospitals focus on recovery from injury or illness."},{"id":"hca-047","sub":"Healthcare Technology","diff":2,"q":"Which system tracks patient flow, bed availability, and discharge planning in real time?","choices":["Electronic remittance system","Bed management system","Payroll system","Pharmacy compounding system"],"answer":1,"explain":"Bed management systems track capacity and patient movement. The other systems serve different functions."},{"id":"hca-048","sub":"Healthcare Technology","diff":1,"q":"What does the abbreviation HIE stand for?","choices":["Health Insurance Exchange","Hospital Information Exchange","Health Information Exchange","Human Interface Engine"],"answer":2,"explain":"HIE is the health information exchange, which allows secure sharing of records across organizations."},{"id":"hca-049","sub":"Healthcare Technology","diff":2,"q":"Computerized provider order entry (CPOE) primarily reduces which risk?","choices":["Insurance denials","Patient no-shows","Medication errors from illegible handwriting","Staff turnover"],"answer":2,"explain":"CPOE replaces handwritten orders, reducing transcription and medication errors."},{"id":"hca-050","sub":"Healthcare Technology","diff":3,"q":"Under the HIPAA Security Rule, which category of safeguards includes unique user IDs, audit controls, and automatic logoff?","choices":["Technical safeguards","Administrative safeguards","Physical safeguards","Organizational safeguards"],"answer":0,"explain":"Technical safeguards control access to electronic PHI. Administrative and physical safeguards cover policies and facilities."},{"id":"hca-051","sub":"Healthcare Policy and Regulation","diff":1,"q":"Which federal law is the primary privacy rule protecting individually identifiable health information?","choices":["ERISA","HIPAA","COBRA","FDCPA"],"answer":1,"explain":"HIPAA sets the Privacy, Security, and Breach Notification rules for protected health information."},{"id":"hca-052","sub":"Healthcare Policy and Regulation","diff":2,"q":"Under HIPAA, what is the minimum necessary standard?","choices":["Patients must receive a minimum of 30 days notice","Providers must keep records for a minimum of 3 years","Staff must complete a minimum of 8 hours of training","Only the minimum amount of PHI needed for a permitted purpose should be used or disclosed"],"answer":3,"explain":"Minimum necessary limits PHI use and disclosure to what is needed for the purpose, with exceptions such as treatment."},{"id":"hca-053","sub":"Healthcare Policy and Regulation","diff":2,"q":"Which HIPAA rule requires covered entities to notify affected individuals, HHS, and sometimes the media after a breach of unsecured PHI?","choices":["Privacy Rule","Security Rule","Enforcement Rule","Breach Notification Rule"],"answer":3,"explain":"The Breach Notification Rule (under HITECH) sets the notice requirements. The Privacy Rule covers permitted uses and disclosures."},{"id":"hca-054","sub":"Healthcare Policy and Regulation","diff":1,"q":"What is a Notice of Privacy Practices?","choices":["A billing statement itemizing charges","A consent form for surgery","A document describing how a covered entity uses and discloses PHI and patient rights","A payer''s list of covered drugs"],"answer":2,"explain":"HIPAA requires covered entities to give patients a notice describing privacy practices and rights."},{"id":"hca-055","sub":"Healthcare Policy and Regulation","diff":2,"q":"Which federal program provides health coverage for low-income children and families and is jointly funded by federal and state governments?","choices":["Medicare Part D","Medicaid","TRICARE","Medicare Advantage"],"answer":1,"explain":"Medicaid is jointly funded and run by states under federal rules. Medicare serves mainly people 65 and older and people with certain disabilities."},{"id":"hca-056","sub":"Healthcare Policy and Regulation","diff":3,"q":"Which federal law prohibits offering or receiving remuneration to induce referrals of business payable by federal healthcare programs?","choices":["Anti-Kickback Statute","Stark Law","Sherman Act","Clayton Act"],"answer":0,"explain":"The Anti-Kickback Statute is a criminal law. Stark is a civil self-referral law for physicians."},{"id":"hca-057","sub":"Healthcare Policy and Regulation","diff":3,"q":"Under MACRA, which program combines quality, cost, and improvement activities into a single payment adjustment for clinicians?","choices":["Merit-based Incentive Payment System (MIPS)","Hospital Readmissions Reduction Program","Bundled Payments for Care Improvement","Meaningful Use"],"answer":0,"explain":"MIPS is the MACRA program that adjusts Medicare payments based on a composite performance score."},{"id":"hca-058","sub":"Healthcare Policy and Regulation","diff":1,"q":"Which federal act, signed in 2010, expanded health insurance coverage through Medicaid expansion and state marketplaces?","choices":["Medicare Modernization Act","Social Security Act","Affordable Care Act","Health Information Technology Act"],"answer":2,"explain":"The Affordable Care Act, signed in 2010, expanded coverage and created marketplaces. The Medicare Modernization Act added Part D in 2003."},{"id":"hca-059","sub":"Healthcare Policy and Regulation","diff":2,"q":"Which federal law requires employer group health plans to offer continued coverage after a qualifying job loss?","choices":["ERISA","HIPAA","FMLA","COBRA"],"answer":3,"explain":"COBRA allows continuation of group coverage for a period after qualifying events such as job loss."},{"id":"hca-060","sub":"Healthcare Policy and Regulation","diff":3,"q":"The Clinical Laboratory Improvement Amendments (CLIA) regulate which activity?","choices":["Prescription drug manufacturing","Laboratory testing of human specimens","Medical device sterilization","Radiation safety in imaging"],"answer":1,"explain":"CLIA sets quality standards for laboratory testing on human specimens. FDA handles drugs and devices."},{"id":"hca-061","sub":"Healthcare Billing and Insurance","diff":1,"q":"Which CMS-adopted code set is used to report diagnoses for U.S. healthcare encounters?","choices":["CPT","ICD-10-CM","HCPCS Level II","NDC"],"answer":1,"explain":"ICD-10-CM is the U.S. diagnosis code set. CPT codes procedures, HCPCS Level II covers supplies and some services, and NDC identifies drugs."},{"id":"hca-062","sub":"Healthcare Billing and Insurance","diff":2,"q":"Which code set describes medical procedures and services and is maintained by the American Medical Association?","choices":["CPT (Current Procedural Terminology)","ICD-10-PCS","HCPCS Level II","NDC"],"answer":0,"explain":"CPT is maintained by the AMA. ICD-10-PCS is used for inpatient procedures, and HCPCS Level II is maintained by CMS."},{"id":"hca-063","sub":"Healthcare Billing and Insurance","diff":1,"q":"Which claim form is used primarily by physicians and other professional providers?","choices":["UB-04","EOB","Remittance advice","CMS-1500"],"answer":3,"explain":"The CMS-1500 is the professional claim form. The UB-04 is used by institutional providers such as hospitals."},{"id":"hca-064","sub":"Healthcare Billing and Insurance","diff":2,"q":"An explanation of benefits (EOB) is:","choices":["A bill sent to the patient for a copayment","A request for prior authorization","A statement from the payer explaining what was covered and paid","A list of a provider''s fees"],"answer":2,"explain":"An EOB is a payer statement. It is not a bill, and the provider does not send it."},{"id":"hca-065","sub":"Healthcare Finances and Budgeting","diff":3,"q":"Which term describes a claim that contains all necessary information and can be adjudicated without further investigation?","choices":["Pended claim","Adjusted claim","Clean claim","Coordinated claim"],"answer":2,"explain":"A clean claim passes edits without manual review. Pended claims need follow-up before processing."},{"id":"hca-066","sub":"Healthcare Finances and Budgeting","diff":1,"q":"Which term refers to the amount a provider has agreed to accept from a payer for a service, which may be less than the billed charge?","choices":["Usual and customary","Gross charge","Chargemaster rate","Allowed amount"],"answer":3,"explain":"The allowed amount is the contracted payment. Gross charges and chargemaster rates are the billed amounts."},{"id":"hca-067","sub":"Healthcare Billing and Insurance","diff":2,"q":"Prior authorization is:","choices":["Approval from the payer before certain services are provided","A payment made after a claim denial","A patient''s written consent to treatment","A waiver of the deductible"],"answer":0,"explain":"Prior authorization is payer approval before a service, often for high-cost procedures. Informed consent is a different concept."},{"id":"hca-068","sub":"Healthcare Billing and Insurance","diff":1,"q":"What does COB stand for in insurance billing?","choices":["Cost of benefits","Coordination of benefits","Claim order billing","Certified outpatient billing"],"answer":1,"explain":"Coordination of benefits determines which payer is primary when a patient has more than one plan."},{"id":"hca-069","sub":"Healthcare Finances and Budgeting","diff":2,"q":"Days in accounts receivable is calculated as:","choices":["(Accounts receivable divided by net credit revenue) times 365","Net credit revenue divided by accounts receivable","(Cash collected divided by gross charges) times 100","Accounts payable divided by operating expenses"],"answer":0,"explain":"Days in AR shows how long it takes to collect. Inverting the ratio gives a meaningless number."},{"id":"hca-070","sub":"Healthcare Finances and Budgeting","diff":3,"q":"A clinic has fixed costs of $120,000 per year, a price of $80 per visit, and a variable cost of $40 per visit. How many visits are needed to break even?","choices":["1,500","2,000","2,400","3,000"],"answer":3,"explain":"Break-even = fixed costs divided by contribution margin: 120,000 / (80 - 40) = 3,000 visits."},{"id":"hca-071","sub":"Healthcare Finances and Budgeting","diff":1,"q":"Which accounting basis records revenue when earned and expenses when incurred, regardless of when cash changes hands?","choices":["Cash basis","Accrual basis","Modified cash basis","Tax basis"],"answer":1,"explain":"Accrual accounting matches revenue and expenses to the period. Cash basis records only when cash moves."},{"id":"hca-072","sub":"Healthcare Finances and Budgeting","diff":2,"q":"Which budget type is prepared from zero each year, requiring every expense to be justified?","choices":["Incremental budget","Continuous budget","Zero-based budget","Flexible budget"],"answer":2,"explain":"Zero-based budgets require justification for each expense. Incremental budgets start from last year''s amounts."},{"id":"hca-073","sub":"Healthcare Finances and Budgeting","diff":1,"q":"A hospital reports gross patient charges of $5,000,000 and contractual allowances of $2,000,000. What is net patient service revenue before bad debt?","choices":["$2,300,000","$2,700,000","$5,000,000","$3,000,000"],"answer":3,"explain":"Net patient revenue = gross charges minus contractual allowances, or $3,000,000. Bad debt is handled separately."},{"id":"hca-074","sub":"Healthcare Finances and Budgeting","diff":2,"q":"Which financial statement shows an organization''s assets, liabilities, and net assets at a point in time?","choices":["Statement of activities","Statement of financial position (balance sheet)","Statement of cash flows","Income statement"],"answer":1,"explain":"The balance sheet is a snapshot. The income statement and statement of activities cover a period."},{"id":"hca-075","sub":"Strategic Management","diff":3,"q":"Which term describes a payment model where a provider receives one predetermined payment for all services in an episode of care, including related follow-up?","choices":["Bundled payment","Fee schedule","Per diem","Cost-plus"],"answer":0,"explain":"Bundled payments cover an episode as a package. A fee schedule prices each service separately."},{"id":"hca-076","sub":"Healthcare Finances and Budgeting","diff":1,"q":"What does a budget variance measure?","choices":["Total patient volume","Staff turnover","The difference between budgeted and actual amounts","Insurance claim denial rate"],"answer":2,"explain":"A variance is actual minus budget, showing where spending or revenue differed from plan."},{"id":"hca-077","sub":"Communication and Leadership","diff":2,"q":"Which technique asks a patient to restate in their own words what they understood, to confirm comprehension?","choices":["Closed questioning","Teach-back","Sentinel review","Reflective listening only"],"answer":1,"explain":"Teach-back checks understanding without quizzing the patient. Closed questions often produce only yes or no answers."},{"id":"hca-078","sub":"Communication and Leadership","diff":1,"q":"What is the best first step when a patient becomes upset about a bill?","choices":["Ignore the concern until the patient calms down","Refer the patient to a lawyer","Listen actively and acknowledge the concern","Tell the patient the policy is non-negotiable"],"answer":2,"explain":"Acknowledging and listening de-escalates the situation before problem-solving."},{"id":"hca-079","sub":"Communication and Leadership","diff":2,"q":"Which communication barrier occurs when medical jargon is used with a patient who does not understand the terms?","choices":["Technical (jargon) barrier","Physical barrier","Emotional barrier","Organizational barrier"],"answer":0,"explain":"Jargon is a technical barrier. Plain language and teach-back reduce it."},{"id":"hca-080","sub":"Communication and Leadership","diff":3,"q":"A manager wants to resolve a conflict between two staff members with a solution that meets both parties'' core interests. Which conflict-handling approach does this describe?","choices":["Avoidance","Accommodation","Competition","Collaboration"],"answer":3,"explain":"Collaboration seeks a win-win solution. Competition wins at the other party''s expense, and accommodation gives in."},{"id":"hca-081","sub":"Communication and Leadership","diff":1,"q":"Which document names a person to make healthcare decisions if the patient becomes unable to communicate?","choices":["Notice of privacy practices","Consent to release information","Durable power of attorney for healthcare","Explanation of benefits"],"answer":2,"explain":"A healthcare power of attorney appoints a healthcare agent. A notice of privacy practices describes HIPAA rights."},{"id":"hca-082","sub":"Healthcare Technology","diff":2,"q":"Which standard defines the structure of electronic medical claims submitted to payers in the United States?","choices":["DICOM","X12 837","NCPDP","HL7 ADT"],"answer":1,"explain":"The X12 837 transaction is the HIPAA standard for electronic healthcare claims."},{"id":"hca-083","sub":"Healthcare Policy and Regulation","diff":1,"q":"What does HIPAA stand for?","choices":["Hospital Information Privacy and Access Act","Health Information Protection and Administration Act","Healthcare Insurance Payment and Access Act","Health Insurance Portability and Accountability Act"],"answer":3,"explain":"HIPAA is the Health Insurance Portability and Accountability Act of 1996."},{"id":"hca-084","sub":"Strategic Management","diff":2,"q":"A hospital is planning service expansion. Which of the following is an external threat in a SWOT analysis?","choices":["A new competitor opening nearby","Strong nursing reputation","Available grant funding","Experienced leadership team"],"answer":0,"explain":"Threats are external. Reputation and leadership are internal strengths, and grant funding is an opportunity."},{"id":"hca-085","sub":"Healthcare Policy and Regulation","diff":3,"q":"Under the Patient Self-Determination Act, healthcare providers must:","choices":["Ask adult patients whether they have an advance directive and document the answer","Refuse treatment to patients without insurance","Share patient records with the media","Provide free care to all patients"],"answer":0,"explain":"PSDA requires providers to inform adults of advance directive rights and document whether one exists."},{"id":"hca-086","sub":"Communication and Leadership","diff":1,"q":"Which type of listening involves restating the speaker''s message in your own words to confirm understanding?","choices":["Passive listening","Reflective listening","Selective listening","Defensive listening"],"answer":1,"explain":"Reflective listening paraphrases and confirms the message, which supports empathy."},{"id":"hca-087","sub":"Communication and Leadership","diff":2,"q":"Under the Joint Commission''s National Patient Safety Goals, which action is used to verify patient identity?","choices":["Checking the insurance card only","Asking family members","Asking the patient to state full name and date of birth","Using the room number"],"answer":2,"explain":"Patients are identified with two identifiers, such as full name and date of birth, stated by the patient."},{"id":"hca-088","sub":"Communication and Leadership","diff":3,"q":"Which leadership theory suggests the best leadership style depends on the situation and the readiness of followers?","choices":["Trait theory","Great man theory","Transactional theory","Situational leadership theory"],"answer":3,"explain":"Situational leadership adapts directive and supportive behaviour to follower readiness."},{"id":"hca-089","sub":"Strategic Management","diff":1,"q":"Which goal-setting method involves managers and employees jointly setting objectives and reviewing results?","choices":["Management by exception","Gantt charting","Benchmarking","Management by objectives"],"answer":3,"explain":"Management by objectives (MBO) sets shared goals and evaluates performance against them."},{"id":"hca-090","sub":"Healthcare Billing and Insurance","diff":2,"q":"Which revenue cycle step involves checking a patient''s coverage before a visit?","choices":["Eligibility verification","Claim adjudication","Denial management","Remittance posting"],"answer":0,"explain":"Eligibility verification confirms active coverage and benefits before service, reducing denials."},{"id":"hca-091","sub":"Healthcare Finances and Budgeting","diff":3,"q":"A hospital has annual operating expenses of $36 million and 90 days cash on hand. What is its approximate cash on hand?","choices":["$3.6 million","$5.0 million","$8.9 million","$12.0 million"],"answer":2,"explain":"Cash = 36,000,000 / 365 times 90, which is about $8.9 million."},{"id":"hca-092","sub":"Staffing and Training","diff":1,"q":"What is the main purpose of an orientation checklist for new hires?","choices":["Reduce payroll taxes","Ensure required tasks, policies, and training are completed","Set vacation schedules","Eliminate the need for supervision"],"answer":1,"explain":"Checklists confirm that required onboarding steps and training are documented."},{"id":"hca-093","sub":"Staffing and Training","diff":1,"q":"A nurse-to-patient ratio is best defined as:","choices":["The number of nurses hired per patient admitted","The number of patients assigned to each nurse on a shift","The total hours worked by nurses per week","The ratio of nursing salaries to revenue"],"answer":1,"explain":"Nurse-to-patient ratio is a staffing standard for assignments per shift, which affects safety and quality."},{"id":"hca-094","sub":"Strategic Management","diff":1,"q":"Cross-training staff primarily helps a healthcare organization by:","choices":["Eliminating the need for policies","Reducing all wages","Replacing supervisors","Increasing staffing flexibility when coverage gaps occur"],"answer":3,"explain":"Cross-training lets staff cover roles during absences or surges, so it does not replace supervisors or policies."},{"id":"hca-095","sub":"Healthcare Finances and Budgeting","diff":2,"q":"Which term describes money a healthcare organization expects to collect from patients and payers for services already provided?","choices":["Accounts receivable","Accounts payable","Retained earnings","Depreciation"],"answer":0,"explain":"Accounts receivable are amounts owed to the organization. Accounts payable are amounts it owes."},{"id":"hca-096","sub":"Healthcare Billing and Insurance","diff":1,"q":"What is a remittance advice?","choices":["A patient''s request to change providers","A list of approved drugs","A payer''s document explaining payment details for claims","A provider''s appointment reminder"],"answer":2,"explain":"The remittance advice (ERA or paper) shows what was paid and why adjustments were made."},{"id":"hca-097","sub":"Healthcare Billing and Insurance","diff":2,"q":"A claim is denied for timely filing. This means the:","choices":["Patient was not eligible on the date of service","Duplicate services were billed","Claim was submitted after the payer''s filing deadline","Service is not covered by the plan"],"answer":2,"explain":"Timely filing denials occur when claims arrive after the payer''s deadline."},{"id":"hca-098","sub":"Healthcare Technology","diff":2,"q":"Which technology helps a hospital track the real-time location of mobile medical equipment?","choices":["RFID tagging","Telephony routing","Batch processing","Data mining"],"answer":0,"explain":"RFID tags let staff locate equipment such as infusion pumps and reduce search time."},{"id":"hca-099","sub":"Healthcare Policy and Regulation","diff":3,"q":"Under HIPAA, how soon must a covered entity notify HHS of a breach affecting 500 or more individuals?","choices":["Within 30 days","Within 90 days","Within 1 year","Within 60 calendar days after discovery"],"answer":3,"explain":"Breaches affecting 500 or more individuals must be reported to HHS without unreasonable delay and no later than 60 days after discovery."},{"id":"hca-100","sub":"Communication and Leadership","diff":1,"q":"Which action best demonstrates empathy when communicating with a grieving family?","choices":["Interrupting to offer quick solutions","Acknowledging their loss and allowing them to speak without rushing","Changing the subject to paperwork","Explaining the billing policy first"],"answer":1,"explain":"Empathy involves acknowledging emotion and listening. The other options prioritize the organization''s needs over the family''s."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'hospitality-event-management', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"hem-001","sub":"Event Planning and Logistics","diff":1,"q":"A chapter has eight weeks to plan a 300-guest awards banquet. Which task should the event coordinator complete first?","choices":["Define the event goals, guest count and budget, then confirm the date","Order centerpieces for each table","Hire a DJ for the reception","Print the event programs"],"answer":0,"explain":"Goals, audience size and budget drive every later decision, including venue size, catering and vendor choices, so they come before any purchase."},{"id":"hem-002","sub":"Event Planning and Logistics","diff":2,"q":"Which planning tool shows the sequence of dependent tasks and identifies the longest chain of tasks that sets the minimum time needed to finish the project?","choices":["A Gantt chart with no dependency lines","A critical path method (CPM) network diagram","A SWOT analysis","A guest satisfaction survey"],"answer":1,"explain":"CPM links dependent tasks; any delay on the critical path delays the whole event, which is why it is tracked closely."},{"id":"hem-003","sub":"Event Planning and Logistics","diff":1,"q":"A run-of-show document is best described as:","choices":["A list of vendor contract terms","A budget variance report","A minute-by-minute timeline of every activity, speaker, cue and staff assignment on event day","A guest registration form"],"answer":2,"explain":"The run-of-show is the operational script the team uses during the event itself."},{"id":"hem-004","sub":"Event Planning and Logistics","diff":2,"q":"A planner learns that an outdoor reception has a 40 percent chance of rain. What is the most effective step?","choices":["Ignore the forecast until the morning of the event","Cancel the event as soon as any rain is forecast","Buy umbrellas for all guests in advance","Reserve an indoor backup space and set a decision date for choosing between the two sites"],"answer":3,"explain":"A contingency plan with a backup space and a decision deadline protects the event without cancelling early on a forecast alone."},{"id":"hem-005","sub":"Event Planning and Logistics","diff":1,"q":"Which objective is written as a SMART objective?","choices":["Recruit 40 volunteers and raise $1,500 for the food bank by March 15","Make the banquet fun","Try to get more people involved this year","Improve the chapter''s reputation"],"answer":0,"explain":"SMART objectives are specific, measurable, achievable, relevant and time-bound; only one choice has a number and a deadline."},{"id":"hem-006","sub":"Event Planning and Logistics","diff":2,"q":"What is the primary purpose of a floor plan in event planning?","choices":["To list vendor invoices","To show seating, stage, service and exit locations so the layout can be checked for flow and fire-code compliance","To record guest dietary needs","To track ticket sales"],"answer":1,"explain":"A scaled floor plan lets the planner check aisle widths, exits and service routes before the event."},{"id":"hem-007","sub":"Event Planning and Logistics","diff":3,"q":"A three-day conference expects a breakout room to exceed its capacity on day two. Which action best solves the problem while protecting the schedule?","choices":["Cancel the session","Ask attendees to share seats informally","Move the session to a larger room in the same venue and update signage and the event app","Shorten all sessions to 15 minutes"],"answer":2,"explain":"Relocating within the same venue and updating every channel fixes capacity without losing content or breaking the schedule."},{"id":"hem-008","sub":"Event Planning and Logistics","diff":2,"q":"Which element belongs in a complete day-of event timeline?","choices":["Final invoice payment dates only","Post-event survey results","Long-term brand strategy","Load-in and setup times, rehearsal, guest arrival and breakdown, with a named staff owner for each"],"answer":3,"explain":"A day-of timeline assigns times and owners to every phase, not just the main program."},{"id":"hem-009","sub":"Event Planning and Logistics","diff":1,"q":"What does a rain date or backup date protect against?","choices":["Loss of the event date due to weather or other disruption","Price increases from vendors","Guests forgetting to RSVP","Inflation in catering costs"],"answer":0,"explain":"A pre-set backup date keeps the event alive if the original date is disrupted."},{"id":"hem-010","sub":"Event Planning and Logistics","diff":2,"q":"A planner''s schedule sets the final catering headcount for day 20, but the RSVP deadline is day 25. What is the best fix?","choices":["Keep the schedule, since the caterer can add guests later at no cost","Move the RSVP deadline before the catering headcount deadline, with a buffer for late requests","Remove the catering headcount step","Ask the caterer to guess the number"],"answer":1,"explain":"The headcount must be locked after RSVPs close; reversing the order creates an unplanned cost or waste."},{"id":"hem-011","sub":"Venue Selection and Layout","diff":1,"q":"Which factor should be assessed first when selecting a venue for a 200-person conference?","choices":["The color of the walls","Whether the parking lot has a coffee cart","Capacity for the planned layout, including exits and the fire-code occupancy limit","The brand of the projector"],"answer":2,"explain":"Capacity and legal occupancy are non-negotiable, so they screen venues before any preference is considered."},{"id":"hem-012","sub":"Venue Selection and Layout","diff":2,"q":"A banquet needs seating for 200 guests at round tables of 10. How many tables are needed?","choices":["25","10","200","20"],"answer":3,"explain":"200 divided by 10 is 20. Using 8 seats per table (25 tables) is a common error that wastes space."},{"id":"hem-013","sub":"Venue Selection and Layout","diff":3,"q":"Which room setup is best for a lecture-style session where attendees take notes and no meals are served?","choices":["Theater style","Banquet rounds","Cabaret","Hollow square"],"answer":0,"explain":"Theater style uses rows facing the front, which maximizes seats for a presentation without tables for dining."},{"id":"hem-014","sub":"Venue Selection and Layout","diff":1,"q":"Before signing an outdoor venue contract, which question is most important to ask the site manager?","choices":["Does the building have a restaurant on site?","What is the backup plan, and what are the rules on permits, noise limits and weather cancellation?","What is the price of the house wine?","Is the building painted in neutral colors?"],"answer":1,"explain":"Permits, noise rules and weather policy can cancel or disrupt an outdoor event, so they must be settled up front."},{"id":"hem-015","sub":"Venue Selection and Layout","diff":1,"q":"Which term describes the maximum number of people a room may hold under fire-safety rules?","choices":["Net revenue","Attendance quota","Occupancy load","Floor ratio"],"answer":2,"explain":"The occupancy load is set by the local fire authority and must not be exceeded."},{"id":"hem-016","sub":"Venue Selection and Layout","diff":2,"q":"A venue charges $3,000 for room rental, $25 per guest for 150 guests, and a $500 setup fee. What is the total venue cost?","choices":["$6,750","$7,000","$7,750","$7,250"],"answer":3,"explain":"3,000 plus (25 times 150 = 3,750) plus 500 equals 7,250. Forgetting the setup fee gives $6,750."},{"id":"hem-017","sub":"Venue Selection and Layout","diff":3,"q":"Which layout decision best supports smooth guest flow at registration?","choices":["Placing check-in tables at the main entrance with signage and extra lanes for peak arrival","Placing registration at the far end of the hall from the entrance","Using a single table with no signage","Moving check-in to the stage"],"answer":0,"explain":"Registration at the entrance with clear signage and extra lanes prevents bottlenecks at peak arrival times."},{"id":"hem-018","sub":"Venue Selection and Layout","diff":3,"q":"A venue contract includes a minimum food and beverage spend of $4,000, but projected catering spend is $2,800. What is the best action?","choices":["Ignore it, since minimums are not enforceable","Negotiate a lower minimum or add items to reach it, and confirm the final terms in writing before signing","Cancel the venue","Reduce the guest count to save money"],"answer":1,"explain":"Minimum spend clauses are negotiable, and the shortfall is a real cost that must be resolved before the contract is signed."},{"id":"hem-019","sub":"Venue Selection and Layout","diff":1,"q":"In U.S. event planning, what does ADA compliance require of a venue layout?","choices":["A dance floor in every room","Only round tables","Accessible routes, entrances and restrooms, including for wheelchair users","A stage in every room"],"answer":2,"explain":"The Americans with Disabilities Act requires accessible routes and facilities in public accommodations, including event venues."},{"id":"hem-020","sub":"Venue Selection and Layout","diff":2,"q":"What is the main purpose of a site inspection before a major event?","choices":["To sign the contract for the first time","To choose the menu","To send invitations","To confirm sightlines, power, load-in access, restrooms and exits match the plan"],"answer":3,"explain":"A site visit verifies that the plan works in the actual space, catching problems before they become day-of failures."},{"id":"hem-021","sub":"Budgeting and Financial Management","diff":1,"q":"What is a budget variance?","choices":["The difference between budgeted and actual amounts for a line item","The total of all guest payments","The number of vendors used","The ticket price"],"answer":0,"explain":"A variance measures how far actual results are from the budget, favorable or unfavorable."},{"id":"hem-022","sub":"Budgeting and Financial Management","diff":1,"q":"Which of these is a fixed cost for a conference?","choices":["A per-plate meal charge","A venue rental fee paid regardless of attendance","A per-guest printed badge","A commission on sponsorship sales"],"answer":1,"explain":"Fixed costs do not change with attendance; per-guest and commission costs are variable."},{"id":"hem-023","sub":"Budgeting and Financial Management","diff":1,"q":"A chapter sells 120 tickets at $25 each and has $2,400 in total expenses. What is the net profit?","choices":["$2,400","$3,000","$600","$5,400"],"answer":2,"explain":"Revenue is 120 times 25, which is 3,000. Subtracting expenses of 2,400 leaves 600."},{"id":"hem-024","sub":"Budgeting and Financial Management","diff":2,"q":"Break-even attendance is found by dividing total fixed costs by which value?","choices":["Total variable costs","Total revenue","The number of vendors","Contribution margin per guest (ticket price minus variable cost per guest)"],"answer":3,"explain":"Each guest contributes the ticket price less variable cost toward fixed costs; dividing gives the guests needed to cover them."},{"id":"hem-025","sub":"Budgeting and Financial Management","diff":3,"q":"Fixed costs are $1,800, the ticket price is $30, and variable cost is $12 per guest. What is the break-even attendance?","choices":["100","60","150","180"],"answer":0,"explain":"The contribution margin is 30 minus 12, which is 18. Then 1,800 divided by 18 equals 100 guests."},{"id":"hem-026","sub":"Budgeting and Financial Management","diff":1,"q":"What is a contingency reserve in an event budget?","choices":["Money spent on the main speaker","Money set aside, usually as a percentage of the budget, for unexpected costs","Money from sponsors that is spent immediately","Profit paid out to the chapter"],"answer":1,"explain":"The reserve absorbs surprises such as price increases or weather costs without breaking the budget."},{"id":"hem-027","sub":"Budgeting and Financial Management","diff":3,"q":"A sponsor donates $1,000 of printed banners instead of cash. How should the chapter record the donation?","choices":["As zero, since no cash changed hands","As a cash expense","As in-kind revenue with an equal expense at fair value when the banners are used","As a long-term liability"],"answer":2,"explain":"Under U.S. GAAP for nonprofits, donated goods are recorded at fair value as revenue, with an expense when used."},{"id":"hem-028","sub":"Budgeting and Financial Management","diff":2,"q":"Which is the best way to control spending during an event?","choices":["Let each committee spend freely and reconcile at the end","Pay all vendors in cash without receipts","Skip the budget for small events","Track actual spending against each budget line daily and approve any change in writing"],"answer":3,"explain":"Daily tracking against budget lines catches overruns while there is still time to correct them."},{"id":"hem-029","sub":"Budgeting and Financial Management","diff":3,"q":"A food budget is $900 for 150 guests. The caterer quotes $8.50 per guest. What is the result?","choices":["$1,275, over budget","$900, within budget","$1,050, within budget","$1,175, over budget"],"answer":0,"explain":"150 times 8.50 equals 1,275, which is 375 over the $900 budget."},{"id":"hem-030","sub":"Budgeting and Financial Management","diff":3,"q":"Which statement about accrual and cash accounting for an event is correct?","choices":["Cash basis records revenue when it is earned, regardless of payment","Accrual basis records revenue when earned and expenses when incurred, regardless of when cash moves","Accrual basis tracks only cash received","Cash basis is required by GAAP for all events"],"answer":1,"explain":"Accrual accounting matches income and costs to the period they relate to, which is why it is preferred for multi-period comparison."},{"id":"hem-031","sub":"Vendor and Contract Management","diff":1,"q":"Which document defines the scope, price and responsibilities between an event planner and a caterer?","choices":["A run-of-show","A floor plan","A signed contract or letter of agreement","An invoice"],"answer":2,"explain":"A signed agreement sets what is delivered, when, at what price, and who is responsible if something goes wrong."},{"id":"hem-032","sub":"Vendor and Contract Management","diff":1,"q":"A vendor contract includes a force majeure clause. What does it address?","choices":["Late payment penalties","Guest ticket refunds","Trademark use","Unforeseen events beyond either party''s control, such as severe weather or government orders, that may excuse performance"],"answer":3,"explain":"Force majeure clauses allocate risk for events outside the parties'' control; their scope depends on the exact wording."},{"id":"hem-033","sub":"Vendor and Contract Management","diff":3,"q":"Which is the strongest reason to get three bids before hiring an audio-visual vendor?","choices":["It allows comparison of price, scope, reliability and references before awarding the job","Bids are always cheaper than single quotes","It removes the need for a contract","Vendors must provide free equipment"],"answer":0,"explain":"Comparing scope and references matters as much as price; the cheapest bid is not always the best value."},{"id":"hem-034","sub":"Vendor and Contract Management","diff":1,"q":"What is a deposit in a vendor agreement?","choices":["The final payment due after the event","A partial payment that secures the date and is usually non-refundable or subject to a cancellation schedule","A penalty for late cancellation only","A tip paid to staff"],"answer":1,"explain":"Deposits reserve the vendor''s time; the refund terms should be spelled out in the contract."},{"id":"hem-035","sub":"Vendor and Contract Management","diff":2,"q":"A caterer requires a final guest count seven days before the event, and later changes are billed at 100 percent of the per-plate price. RSVPs are still changing. What is the best action?","choices":["Ignore the deadline and pay later","Ask the caterer to cancel","Confirm the count with a sensible buffer and clarify the change policy in writing before the deadline","Order for 500 guests to avoid all risk"],"answer":2,"explain":"Locking a count with a buffer, while knowing the cost of changes, avoids paying for unused meals without risking shortages."},{"id":"hem-036","sub":"Vendor and Contract Management","diff":1,"q":"What is the main purpose of a certificate of insurance requested from a vendor?","choices":["To prove the vendor is profitable","To register the vendor''s trademark","To set the vendor''s price","To confirm the vendor carries liability coverage that protects the chapter"],"answer":3,"explain":"A certificate shows the vendor''s coverage limits and names the chapter as additional insured if the contract requires it."},{"id":"hem-037","sub":"Vendor and Contract Management","diff":1,"q":"Which term describes an outside business that supplies services under a written agreement with defined deliverables?","choices":["Contractor","Volunteer","Sponsor","Guest"],"answer":0,"explain":"A contractor delivers defined services for a fee; the contract, not the relationship, defines the obligations."},{"id":"hem-038","sub":"Vendor and Contract Management","diff":2,"q":"Which statement best describes a verbal agreement for a one-day event service?","choices":["Verbal agreements are never enforceable","Verbal agreements can be enforceable, but a written agreement makes the terms easier to prove","Verbal agreements are enforceable only if notarized","Verbal agreements must be filed with the state"],"answer":1,"explain":"Oral contracts can bind parties, but proof of terms is the problem; a written agreement avoids disputes."},{"id":"hem-039","sub":"Vendor and Contract Management","diff":2,"q":"Which practice best protects a chapter when a vendor fails to deliver a rented sound system?","choices":["Pay the full balance before the event","Accept any substitute without notice","Enforce the contract''s delivery and remedy terms, and document the failure in writing","Cancel all other vendors"],"answer":2,"explain":"Written documentation and the contract''s remedy clause are what support a refund or credit claim."},{"id":"hem-040","sub":"Vendor and Contract Management","diff":2,"q":"A venue contract says a cancellation within 60 days costs 50 percent of the rental fee, and within 14 days costs 100 percent. The chapter cancels on day 30. What must it pay?","choices":["Nothing, because it cancelled more than 14 days out","100 percent of the rental fee","25 percent of the rental fee","50 percent of the rental fee"],"answer":3,"explain":"Day 30 falls inside the 60-day window but outside 14 days, so the 50 percent tier applies."},{"id":"hem-041","sub":"Marketing and Promotion","diff":1,"q":"Which promotion method is most effective for a small chapter''s bake sale at low cost?","choices":["Social media posts, school announcements and posters in high-traffic areas","A paid television ad","A billboard on the highway","A direct mail campaign to every household"],"answer":0,"explain":"Free and targeted channels reach the chapter''s real audience at minimal cost."},{"id":"hem-042","sub":"Marketing and Promotion","diff":2,"q":"What is a target audience?","choices":["Everyone who might ever attend","The specific group the event is designed for and most likely to attend","The sponsors who pay for the event","The venue staff"],"answer":1,"explain":"Targeting narrows messaging, channel choice and pricing to the people most likely to say yes."},{"id":"hem-043","sub":"Marketing and Promotion","diff":2,"q":"Flyers produced 25 percent of attendees, and social media produced none. What is the most useful next step?","choices":["Stop all marketing","Spend more on the same flyers","Track the source of each registration and shift budget toward the channels producing attendees","Hire a celebrity speaker"],"answer":2,"explain":"Source tracking shows which channels work, so spending follows results instead of habit."},{"id":"hem-044","sub":"Marketing and Promotion","diff":2,"q":"Which metric best measures the reach of a social media campaign?","choices":["Number of event staff","Venue capacity","Price per plate","Impressions and unique accounts reached"],"answer":3,"explain":"Reach measures how many people saw the content; engagement and conversion are separate metrics."},{"id":"hem-045","sub":"Marketing and Promotion","diff":1,"q":"Which content is most effective for a promotional flyer?","choices":["A clear headline with the event name, date, time, location and a call to action","A long paragraph about chapter history","A list of every vendor","A photo with no text"],"answer":0,"explain":"A flyer must answer the basic questions in seconds because it is read briefly."},{"id":"hem-046","sub":"Marketing and Promotion","diff":2,"q":"Last month 50 of 1,000 website visitors registered. This month 80 of 1,200 registered. Which conclusion is correct?","choices":["Conversion fell from 6.7 to 5.0 percent","Conversion improved from 5.0 to 6.7 percent","Conversion was unchanged at 5 percent","Conversion cannot be compared across months"],"answer":1,"explain":"Conversion is registrations divided by visitors: 50/1,000 is 5.0 percent and 80/1,200 is 6.7 percent."},{"id":"hem-047","sub":"Marketing and Promotion","diff":2,"q":"Which approach best uses sponsorship benefits to attract sponsors?","choices":["Offering free admission with no recognition","Hiding the sponsor''s logo","Offering a defined package with measurable visibility, such as logo placement and social mentions","Charging the sponsor after the event"],"answer":2,"explain":"Sponsors buy defined, measurable exposure; vague promises rarely close."},{"id":"hem-048","sub":"Marketing and Promotion","diff":1,"q":"What is a call to action in promotional material?","choices":["The venue''s name","The sponsor''s slogan","A list of event rules","A specific instruction telling the audience what to do next, such as register by a date"],"answer":3,"explain":"A call to action converts interest into behavior, such as registering or buying a ticket."},{"id":"hem-049","sub":"Marketing and Promotion","diff":3,"q":"What is a key benefit of early-bird ticket pricing?","choices":["It encourages early commitment and gives the chapter an early head count for planning","It lowers the event''s fixed costs","It removes the need for registration","It guarantees sponsorship money"],"answer":0,"explain":"Early sales improve planning accuracy and cash flow, though they reduce average ticket revenue."},{"id":"hem-050","sub":"Marketing and Promotion","diff":3,"q":"A chapter wants to know whether its Instagram promotion drove the event. Which pair of metrics best shows impact on the event itself?","choices":["Likes and follower count","Registrations or ticket sales from tracked links, and attendance at check-in","Post length and emoji count","Impressions and comment count"],"answer":1,"explain":"Impressions and comments measure the post; only tracked registrations and check-ins measure the event outcome."},{"id":"hem-051","sub":"Guest Services and Experience","diff":1,"q":"Which action best improves the guest experience at check-in?","choices":["Requiring guests to wait for a manual sign-up","Having one volunteer handle all tasks","Pre-printed name badges, alphabetical lanes and trained greeters","Asking guests to find their own badges"],"answer":2,"explain":"Pre-printed badges and split lanes shorten waits and make the first impression smooth."},{"id":"hem-052","sub":"Guest Services and Experience","diff":2,"q":"A guest with a severe food allergy is seated where the meal contains the allergen. What is the best first step?","choices":["Tell the guest to eat it anyway","Ignore it, since the allergy was on the RSVP","Move the guest out of the event","Inform the kitchen and servers, and confirm the item is safe before service"],"answer":3,"explain":"Allergy safety is the first priority; confirming with the kitchen prevents a medical emergency."},{"id":"hem-053","sub":"Guest Services and Experience","diff":3,"q":"What does service recovery mean?","choices":["Restoring a guest''s trust after a service failure through an apology and corrective action","Reducing service staff to save money","Recovering lost deposits","Recording guest complaints for marketing"],"answer":0,"explain":"Good recovery turns a failure into a retained guest, often more loyal than before."},{"id":"hem-054","sub":"Guest Services and Experience","diff":1,"q":"Which is an example of a guest touchpoint?","choices":["An accounting ledger entry","The venue''s registration desk, the event app or a follow-up email","A vendor invoice","A tax form"],"answer":1,"explain":"A touchpoint is any moment a guest interacts with the event, which is where the experience is shaped."},{"id":"hem-055","sub":"Guest Services and Experience","diff":3,"q":"A conference survey averages 4.6 out of 5, but 30 percent of attendees skipped the food question. What is the most accurate interpretation?","choices":["The event was an overall failure","Food was clearly the best element","The average is strong, but skipped questions can hide a problem, so the chapter should follow up with a targeted question","The survey is invalid and should be deleted"],"answer":2,"explain":"High averages can mask gaps; nonresponse on a topic is a signal worth investigating."},{"id":"hem-056","sub":"Guest Services and Experience","diff":2,"q":"A guest complains about a long line at registration. Which response is best?","choices":["Tell the guest to wait without comment","Argue that the line is normal","Ask the guest to leave","Acknowledge the wait, give an updated time estimate, and open another lane or point to a shorter line"],"answer":3,"explain":"Acknowledging the problem and offering a concrete fix changes the guest''s experience immediately."},{"id":"hem-057","sub":"Guest Services and Experience","diff":1,"q":"What is the main purpose of a post-event guest feedback survey?","choices":["To measure satisfaction and identify improvements for future events","To sell next year''s tickets","To set vendor prices","To collect sponsor payments"],"answer":0,"explain":"Feedback is most useful as an input for improving the next event."},{"id":"hem-058","sub":"Guest Services and Experience","diff":2,"q":"A hotel guest reports noise from a nearby ballroom event. Which response reflects good hospitality practice?","choices":["Ignore it until checkout","Offer a room change and log the issue so the event team can address the noise","Charge the guest for the inconvenience","Tell the guest it is not their concern"],"answer":1,"explain":"Solving the guest''s problem and passing the root cause to the event team is standard hospitality practice."},{"id":"hem-059","sub":"Guest Services and Experience","diff":3,"q":"In service quality models, what is the service gap?","choices":["The difference between a venue''s cost and its price","The gap between two event dates","The difference between what guests expect and what they perceive they received","The difference between cash and card payments"],"answer":2,"explain":"Service quality is measured by the difference between expectations and perceived performance, which is why expectations must be managed."},{"id":"hem-060","sub":"Guest Services and Experience","diff":2,"q":"Which practice matters most for guests with mobility needs?","choices":["Accessible seating placed in a separate area with no route","Asking guests to bring a helper","Holding the event only on an upper floor","Reserved accessible seating with step-free routes, communicated in advance"],"answer":3,"explain":"Accessibility requires both the seating and a usable route to it, and it should be confirmed before the event."},{"id":"hem-061","sub":"Food and Beverage Operations","diff":1,"q":"What does FIFO mean in food storage?","choices":["First in, first out, meaning older stock is used before newer stock","Fresh items are only ordered on Fridays","Food is inventoried only when finished","Frozen items are only sold outside"],"answer":0,"explain":"FIFO reduces spoilage by rotating stock so older items are used first."},{"id":"hem-062","sub":"Food and Beverage Operations","diff":2,"q":"What is the food temperature danger zone?","choices":["32 to 40 degrees F","40 to 140 degrees F (about 4 to 60 degrees C)","0 to 10 degrees F","180 to 212 degrees F"],"answer":1,"explain":"Bacteria multiply fastest in this range, so hot and cold holding must stay outside it."},{"id":"hem-063","sub":"Food and Beverage Operations","diff":2,"q":"A caterer expects 1.1 buffet plates per guest for 150 guests. How many plates should be prepared?","choices":["150","180","165","200"],"answer":2,"explain":"150 times 1.1 is 165. The 10 percent buffer covers second helpings without wild over-production."},{"id":"hem-064","sub":"Food and Beverage Operations","diff":2,"q":"What is the main purpose of a HACCP plan?","choices":["To set menu prices","To schedule staff breaks","To track guest preferences","To identify and control food hazards at critical control points to keep food safe"],"answer":3,"explain":"HACCP is a systematic food-safety method built around critical control points."},{"id":"hem-065","sub":"Food and Beverage Operations","diff":1,"q":"What is a standard recipe used for in event catering?","choices":["Consistent portions and per-guest costing","Setting the venue rental fee","Choosing the guest room layout","Assigning seating"],"answer":0,"explain":"A standard recipe lets the caterer predict cost and quality per guest, the basis for accurate quotes."},{"id":"hem-066","sub":"Food and Beverage Operations","diff":3,"q":"A plated dinner has $18 of food cost per guest, and the target food cost percentage is 30 percent. What menu price per guest meets the target?","choices":["$25.40","$60.00","$36.00","$54.00"],"answer":1,"explain":"Food cost percentage is food cost divided by price, so price is 18 divided by 0.30, which is 60."},{"id":"hem-067","sub":"Food and Beverage Operations","diff":2,"q":"Which beverage practice most reduces liability when alcohol is served at an event?","choices":["Serving unlimited drinks to all guests","Letting guests self-serve from open bottles","Checking IDs, serving responsibly, and using a licensed bartender under an approved permit","Serving anyone who asks"],"answer":2,"explain":"Liability for over-service falls on the host, so licensing, ID checks and responsible service are essential."},{"id":"hem-068","sub":"Food and Beverage Operations","diff":1,"q":"In banquet pricing, what is a cover?","choices":["A tablecloth fee","A reservation deposit","Sales tax on food","A guest or place setting charged for a meal"],"answer":3,"explain":"Per-cover pricing charges by the number of guests served, not by the number of dishes."},{"id":"hem-069","sub":"Food and Beverage Operations","diff":1,"q":"Which is the best way to reduce food waste after a buffet?","choices":["Forecast guest counts from RSVPs and plan smaller, refilled batches","Order double the food to be safe","Throw out all leftovers without tracking","Serve only dessert"],"answer":0,"explain":"Good forecasting and refill planning cut waste while keeping the buffet full."},{"id":"hem-070","sub":"Food and Beverage Operations","diff":3,"q":"A food truck arrives with a permit that expired two days before the event. What should the planner do first?","choices":["Accept the truck and ask for the permit later","Verify the permit''s dates and require a current permit before approving the truck to operate","Assume the permit renewed automatically","Charge the truck a fee and let it operate"],"answer":1,"explain":"Operating without a valid permit creates legal and health exposure for the host, so verification comes first."},{"id":"hem-071","sub":"Risk Management and Safety","diff":1,"q":"What is the purpose of a risk assessment in event planning?","choices":["To set the ticket price","To assign seating","To identify hazards, rate their likelihood and impact, and plan controls","To record guest reviews"],"answer":2,"explain":"A risk assessment ranks hazards so the most serious ones get the most planning effort."},{"id":"hem-072","sub":"Risk Management and Safety","diff":2,"q":"Which insurance covers a claim that a guest was injured at an event because of the organizer''s negligence?","choices":["Auto insurance","Workers'' compensation for event staff only","Business interruption insurance","General liability insurance"],"answer":3,"explain":"General liability covers third-party bodily injury and property damage claims arising from the organizer''s operations."},{"id":"hem-073","sub":"Risk Management and Safety","diff":3,"q":"What is an incident report used for?","choices":["Documenting injuries, property damage or unsafe conditions for follow-up and claims","Ranking vendors","Scheduling speakers","Setting the next year''s budget"],"answer":0,"explain":"Prompt, factual incident reports support insurance claims and prevent repeat hazards."},{"id":"hem-074","sub":"Risk Management and Safety","diff":2,"q":"The fire marshal sets the room''s occupancy at 400, but the chapter sells 450 tickets. What is the correct response?","choices":["Sell all 450, since the tickets are paid","Cap ticket sales at the lawful occupancy limit and manage the overflow","Ask guests to stand","Remove the fire exits to create space"],"answer":1,"explain":"Exceeding occupancy is a life-safety violation; the lawful limit governs sales."},{"id":"hem-075","sub":"Risk Management and Safety","diff":3,"q":"A chapter hires a DJ who is paid in cash under no contract, and the DJ is later injured on site. Which risk is most significant?","choices":["Loss of a tax deduction","Marketing confusion","Unclear liability and workers'' compensation exposure","Copyright on the music played"],"answer":2,"explain":"Without a contract or proper classification, responsibility for an injury is disputed and costly."},{"id":"hem-076","sub":"Risk Management and Safety","diff":1,"q":"What is the first priority in an emergency at an event?","choices":["Protect the sponsors'' logos","Count the cash","Finish the program","Protect life and safety by following the emergency plan and calling 911 when needed"],"answer":3,"explain":"Life safety comes first; the emergency plan defines who calls for help and who directs guests."},{"id":"hem-077","sub":"Risk Management and Safety","diff":3,"q":"Which license allows copyrighted music to be played at a public event?","choices":["A public performance license from a performing rights organization such as ASCAP, BMI or SESAC","A driver''s license","A sales tax exemption","A trademark registration"],"answer":0,"explain":"Public performance of copyrighted music requires permission, typically through a performing rights organization."},{"id":"hem-078","sub":"Risk Management and Safety","diff":2,"q":"What is the purpose of a waiver or release form for event participants?","choices":["To guarantee attendance","To document the participant''s acknowledgment of known risks and agreement to terms, which may limit claims","To set ticket prices","To replace liability insurance entirely"],"answer":1,"explain":"A waiver can limit some claims, but it does not replace insurance and may not bar every claim."},{"id":"hem-079","sub":"Risk Management and Safety","diff":3,"q":"Which action best protects a chapter from volunteer injury claims?","choices":["Have volunteers sign no documents","Assume volunteers are never covered","Confirm volunteer accident or liability coverage and provide safety training before setup","Hire volunteers so insurance is not needed"],"answer":2,"explain":"Coverage and training reduce both the risk and the chapter''s exposure if an injury occurs."},{"id":"hem-080","sub":"Risk Management and Safety","diff":2,"q":"A severe storm warning is issued two hours before an outdoor event. Which action is most appropriate?","choices":["Hold the event as planned","Tell guests to bring umbrellas only","Let each vendor decide individually","Follow the pre-set weather decision plan, notify guests and vendors, and move to backup or postpone"],"answer":3,"explain":"A pre-agreed trigger and communication plan avoids panic decisions in the final hours."},{"id":"hem-081","sub":"Staffing and Leadership","diff":1,"q":"What is the main purpose of a volunteer job description?","choices":["To define duties, time commitment and expectations so volunteers know their roles","To set the venue rental price","To record guest feedback","To track sponsor payments"],"answer":0,"explain":"Clear role descriptions reduce confusion and make accountability possible."},{"id":"hem-082","sub":"Staffing and Leadership","diff":2,"q":"Three committee chairs are not communicating. Which leadership approach is best?","choices":["Let them compete for the lead role","Set a regular check-in schedule, a shared timeline and clear decision authority for each area","Remove one chair from the team","Take over every task personally"],"answer":1,"explain":"Structure and clear authority fix coordination failures without removing people or creating a bottleneck."},{"id":"hem-083","sub":"Staffing and Leadership","diff":1,"q":"What is a shift schedule used for during an event?","choices":["Recording vendor invoices","Setting the program theme","Assigning staff to times and locations so coverage is clear","Tracking marketing impressions"],"answer":2,"explain":"Shift schedules guarantee coverage at every station and make absences visible quickly."},{"id":"hem-084","sub":"Staffing and Leadership","diff":2,"q":"Which method is best for training event staff quickly?","choices":["Hand out a manual with no walkthrough","Tell staff to figure it out during the event","Train only the manager","Run a short briefing with a run-of-show walkthrough, role cards and a practice session"],"answer":3,"explain":"A walkthrough and practice build familiarity fast, and role cards keep staff focused on their own tasks."},{"id":"hem-085","sub":"Staffing and Leadership","diff":3,"q":"Under the Fair Labor Standards Act (FLSA), which situation most likely requires overtime pay for a paid staff member?","choices":["Working 45 hours in a week at a non-exempt hourly rate","Working 45 hours as a volunteer","Working 45 hours as an unpaid nonprofit volunteer","Working 45 hours as an independent contractor"],"answer":0,"explain":"Non-exempt employees must receive time-and-a-half for hours over 40 in a workweek; volunteers and contractors are treated differently."},{"id":"hem-086","sub":"Staffing and Leadership","diff":1,"q":"Which statement about nonprofit volunteers is most accurate?","choices":["Volunteers must be paid minimum wage","Volunteers generally receive no wages but still need safety training and clear role expectations","Volunteers cannot be given any training","Volunteers must be employees"],"answer":1,"explain":"Volunteer status does not remove the duty to keep volunteers safe and informed."},{"id":"hem-087","sub":"Staffing and Leadership","diff":1,"q":"What does a volunteer sign-in sheet support?","choices":["Vendor pricing","Ticket sales","Attendance tracking, accountability and emergency headcount","Sponsor recognition only"],"answer":2,"explain":"Sign-in records support accountability and a reliable headcount if an evacuation is needed."},{"id":"hem-088","sub":"Staffing and Leadership","diff":2,"q":"A staff member with a personal stake in one caterer is assigned to choose the caterer. What is the best action?","choices":["Hide the conflict","Let the staff member choose anyway","Remove all vendors from the process","Disclose the conflict and have another person make the vendor decision"],"answer":3,"explain":"A conflict of interest must be disclosed and managed by reassigning the decision."},{"id":"hem-089","sub":"Staffing and Leadership","diff":3,"q":"Which leadership style fits a new volunteer team that needs clear direction?","choices":["Directive leadership with clear instructions and frequent check-ins, shifting to supportive leadership as skills grow","Laissez-faire with no check-ins","Delegating all decisions to the newest member","Consensus voting on every task"],"answer":0,"explain":"Teams that are new need direction first; autonomy is earned as competence develops."},{"id":"hem-090","sub":"Staffing and Leadership","diff":3,"q":"A volunteer is consistently late for shifts. Which response is most constructive?","choices":["Remove the volunteer immediately without discussion","Talk privately, restate expectations, and document the issue and the agreed plan","Ignore it because volunteers are unpaid","Raise the issue publicly with the group"],"answer":1,"explain":"A private, documented conversation addresses the problem fairly and creates a record if the issue continues."},{"id":"hem-091","sub":"Evaluation and Post-Event Review","diff":1,"q":"What is the main purpose of a post-event debrief?","choices":["To pay all vendors","To market the next event","To review results against goals, document lessons and recommend changes","To collect sponsor logos"],"answer":2,"explain":"A debrief turns one event''s experience into improvements for the next."},{"id":"hem-092","sub":"Evaluation and Post-Event Review","diff":2,"q":"A chapter''s goal was 200 attendees and 180 attended. What is the attainment rate?","choices":["80 percent","110 percent","95 percent","90 percent"],"answer":3,"explain":"Attainment is actual divided by goal: 180 divided by 200 is 0.90, or 90 percent."},{"id":"hem-093","sub":"Evaluation and Post-Event Review","diff":3,"q":"How is cost per attendee calculated?","choices":["Total event cost divided by the number of attendees","Total revenue divided by the number of sponsors","Ticket price multiplied by the number of attendees","Venue capacity divided by the number of attendees"],"answer":0,"explain":"Cost per attendee shows the efficiency of spending and is useful for comparing events."},{"id":"hem-094","sub":"Evaluation and Post-Event Review","diff":3,"q":"Which metric best evaluates whether a change to the registration process succeeded?","choices":["Number of event shirts sold","Completion rate of registrations and the time from starting a registration to a confirmed ticket","Number of social media followers","Size of the venue"],"answer":1,"explain":"Process changes should be judged on the process outcome, such as completion rate and time to confirm."},{"id":"hem-095","sub":"Evaluation and Post-Event Review","diff":1,"q":"What is a post-mortem in event management?","choices":["A pre-event sales pitch","A venue inspection","A structured review of what went well and what to improve after the event","A vendor''s final invoice"],"answer":2,"explain":"A post-mortem focuses on learning, not blame, and feeds the next planning cycle."},{"id":"hem-096","sub":"Evaluation and Post-Event Review","diff":2,"q":"Which data point best evaluates the financial result of a fundraising event?","choices":["Number of photos taken","Number of social media posts","Number of programs printed","Net proceeds after all costs, compared to the budget"],"answer":3,"explain":"Net proceeds after costs are the financial result; gross receipts alone overstate the success."},{"id":"hem-097","sub":"Evaluation and Post-Event Review","diff":3,"q":"Which approach gives a fair picture of attendee satisfaction?","choices":["Send a short survey to all attendees and track the response rate","Survey only the VIP guests","Survey only people who complained","Survey only the sponsors"],"answer":0,"explain":"A representative, well-reported survey avoids biased samples, and the response rate shows how far the results can be trusted."},{"id":"hem-098","sub":"Evaluation and Post-Event Review","diff":3,"q":"A survey of 60 responses shows 70 percent rated the venue good or better, but only 60 of 200 attendees responded. What is the most important caution?","choices":["70 percent is always representative","The response rate is 30 percent, so the results may not represent all attendees","The survey should be discarded entirely","The venue should be rated by staff only"],"answer":1,"explain":"Only 30 percent responded, so non-responders may differ; the result is informative but not conclusive."},{"id":"hem-099","sub":"Evaluation and Post-Event Review","diff":2,"q":"How should lessons learned from a debrief be used?","choices":["Filed without reading","Deleted after one month","Built into planning templates, timelines and vendor checklists for the next event","Shared only with sponsors"],"answer":2,"explain":"Lessons only matter when they change the templates and checklists the team actually uses."},{"id":"hem-100","sub":"Evaluation and Post-Event Review","diff":3,"q":"Projected net income was $4,000 ($13,000 revenue minus $9,000 expenses). Actual revenue was $12,000 and actual expenses were $10,000. What is the variance on net income?","choices":["$2,000 favorable","$1,000 unfavorable","$6,000 favorable","$2,000 unfavorable"],"answer":3,"explain":"Actual net income is $2,000 against a $4,000 budget, a $2,000 unfavorable variance."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'international-business', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"ib-001","sub":"Global Business Environment","diff":1,"q":"A U.S. software firm''s home market is saturated and grows about 1 percent a year, but its board wants 15 percent annual growth. Which motive for going global best fits?","choices":["Market-seeking motive: access new customers in faster-growing foreign markets","Resource-seeking motive: secure lower-cost raw materials abroad","Efficiency-seeking motive: consolidate production in a low-cost country","Strategic-asset-seeking motive: acquire a rival''s patents"],"answer":0,"explain":"Market-seeking firms expand to reach new demand when the home market is mature. The other motives are real but do not solve a demand-growth problem."},{"id":"ib-002","sub":"International Trade Theory and Agreements","diff":1,"q":"Country X can make 10 tons of wheat or 5 tons of cloth per year. Country Y can make 4 tons of wheat or 8 tons of cloth. Which statement is correct?","choices":["X has a comparative advantage in cloth because it makes more cloth per year","Y has an absolute advantage in wheat because it can grow wheat on less land","X has a comparative advantage in wheat, and Y has one in cloth","Both countries should produce only wheat because wheat is the larger output"],"answer":2,"explain":"X gives up 0.5 tons of cloth per ton of wheat and Y gives up 2 tons, so X has the comparative advantage in wheat. Comparative advantage depends on opportunity cost, not total output."},{"id":"ib-003","sub":"International Trade Theory and Agreements","diff":1,"q":"Which trade agreement replaced NAFTA in July 2020?","choices":["CAFTA-DR","USMCA","CPTPP","Mercosur"],"answer":1,"explain":"USMCA (called CUSMA in Canada) took effect July 1, 2020, and replaced NAFTA among the United States, Canada and Mexico."},{"id":"ib-004","sub":"Trade Barriers and Documentation","diff":1,"q":"A government limits imports of bicycles to 10,000 units a year and blocks any shipments above that amount. This is an example of a(n):","choices":["ad valorem tariff","countervailing duty","export subsidy","import quota"],"answer":3,"explain":"A quota is a quantity limit. A tariff taxes the good rather than capping how many can enter."},{"id":"ib-005","sub":"Trade Barriers and Documentation","diff":1,"q":"Which tariff is charged as a percentage of the good''s declared value?","choices":["Specific tariff","Tariff-rate quota","Ad valorem tariff","Embargo"],"answer":2,"explain":"Ad valorem means according to value. A specific tariff is a fixed amount per unit, and an embargo is a complete ban on trade."},{"id":"ib-006","sub":"Foreign Exchange and International Finance","diff":1,"q":"Which exchange rate applies to currency delivered immediately, typically within two business days?","choices":["Spot rate","Forward rate","Cross rate","Pegged rate"],"answer":0,"explain":"The spot rate is for near-immediate settlement. A forward rate is agreed today for a future date."},{"id":"ib-007","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"In the 4Ps of the marketing mix, the P that is not product, price or place stands for:","choices":["Positioning","Packaging","Process","Promotion"],"answer":3,"explain":"The four Ps are product, price, place and promotion. Positioning is a strategy concept, not one of the four Ps."},{"id":"ib-008","sub":"Legal, Ethical and Political Risk","diff":2,"q":"A U.S. construction firm''s agent pays $5,000 in cash to a foreign official to win a contract. Which U.S. law governs this payment?","choices":["Sherman Antitrust Act","Foreign Corrupt Practices Act","Robinson-Patman Act","Clayton Act"],"answer":1,"explain":"The FCPA prohibits paying foreign officials to obtain or keep business, including payments made through agents. The antitrust statutes address competition, not bribery."},{"id":"ib-009","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A U.S. running-shoe brand is positioned as fast and affordable in Canada. The same message reads as cheap in Japan, where buyers equate price with quality. What is the best explanation?","choices":["Culture shapes how buyers read price and quality signals, so positioning must be localized","Japanese tariffs make affordable products impossible to import","Canadian consumers have higher incomes, so the message fits there","Hofstede''s power distance is too high for any advertising to work"],"answer":0,"explain":"Cultural cues about what low price signals determine how a message lands, so the positioning has to be adapted. Tariffs and incomes do not explain how the message is read."},{"id":"ib-010","sub":"Global Business Environment","diff":2,"q":"In a PESTEL scan, a target country passes a new national data-privacy law that affects how foreign firms store customer data. Which category does this belong to?","choices":["Economic","Social","Legal","Technological"],"answer":2,"explain":"Laws and regulations fall under the Legal factor of PESTEL. Data handling affects technology, but the source of the constraint is the law."},{"id":"ib-011","sub":"Global Business Environment","diff":2,"q":"Which framework compares a firm''s internal strengths and weaknesses with external opportunities and threats before entering a foreign market?","choices":["Porter''s five forces only","SWOT analysis","Break-even analysis","Hofstede''s cultural model"],"answer":1,"explain":"SWOT pairs internal factors (strengths, weaknesses) with external ones (opportunities, threats). Porter''s five forces looks only at industry structure."},{"id":"ib-012","sub":"Global Business Environment","diff":2,"q":"A target market has high per-capita income, slow population growth and a rapidly aging population. Which PESTEL category most directly captures the aging population?","choices":["Political","Environmental","Technological","Social"],"answer":3,"explain":"Demographic trends such as age structure are Social factors. Income levels would be Economic."},{"id":"ib-013","sub":"International Trade Theory and Agreements","diff":2,"q":"Which principle explains why countries benefit from specializing in goods they produce at lower opportunity cost, even when one country is more efficient at everything?","choices":["Absolute advantage","Mercantilism","Comparative advantage","Infant industry theory"],"answer":2,"explain":"Comparative advantage rests on opportunity cost, so trade still benefits both sides even when one country has an absolute advantage in every good."},{"id":"ib-014","sub":"International Trade Theory and Agreements","diff":2,"q":"Which statement best defines a free trade area?","choices":["Members remove tariffs among themselves but keep their own external tariffs","Members adopt a common external tariff and free movement of labour","Members use one currency and one central bank","Members set quotas on all imports from outside the group"],"answer":0,"explain":"In a free trade area, internal tariffs are removed but each member sets its own tariffs on outside countries. A customs union adds the common external tariff."},{"id":"ib-015","sub":"International Trade Theory and Agreements","diff":2,"q":"Which stage of economic integration has a common external tariff, free trade among members, and free movement of labour and capital, but no harmonized economic or monetary policy?","choices":["Free trade area","Customs union","Economic union","Common market"],"answer":3,"explain":"A common market adds free movement of factors of production to a customs union. A customs union covers goods only. An economic union also harmonizes economic and monetary policy."},{"id":"ib-016","sub":"Foreign Exchange and International Finance","diff":3,"q":"A country exports $220 billion of goods and services and imports $260 billion. Net primary income is +$10 billion and net transfers are -$5 billion. What is the current account balance?","choices":["-$30 billion","-$35 billion","-$40 billion","-$45 billion"],"answer":1,"explain":"Goods and services balance is -40, plus net income of +10 gives -30, then net transfers of -5 give -35."},{"id":"ib-017","sub":"International Trade Theory and Agreements","diff":3,"q":"Under the Heckscher-Ohlin model, a country with abundant skilled labour will tend to export:","choices":["Skill-intensive goods","Land-intensive goods","Unskilled-labour-intensive goods","Raw-material-intensive goods"],"answer":0,"explain":"Heckscher-Ohlin predicts a country exports goods that intensively use its abundant factor. Abundant skilled labour points to skill-intensive exports."},{"id":"ib-018","sub":"Foreign Exchange and International Finance","diff":3,"q":"A tariff cut lowers the price of a U.S. product in a foreign market, but the foreign currency depreciates 10 percent against the dollar. Which is the most accurate description of the net effect on U.S. price competitiveness there?","choices":["Competitiveness improves fully, since both changes lower the price","Competitiveness falls, since tariff cuts never affect demand","Competitiveness is ambiguous: the tariff cut helps, but the weaker foreign currency raises the dollar price in local currency","Competitiveness is unchanged because the two changes cancel exactly in every case"],"answer":2,"explain":"A weaker buyer currency makes a dollar price more expensive in local terms, which offsets part or all of the tariff benefit. The net effect depends on the size of each change."},{"id":"ib-019","sub":"International Trade Theory and Agreements","diff":3,"q":"Which argument for trade protection is most consistent with the infant industry concept?","choices":["Protecting mature industries from competition for permanent job security","Temporarily protecting a new domestic industry until it can compete","Imposing tariffs to raise government revenue from all imports","Banning imports to conserve foreign exchange reserves permanently"],"answer":1,"explain":"The infant industry argument is temporary protection for a new industry expected to become competitive. Permanent protection of mature industries is not the concept."},{"id":"ib-020","sub":"International Trade Theory and Agreements","diff":3,"q":"Which WTO mechanism settles trade disputes through a binding, rules-based process?","choices":["Peer review by the IMF","Currency swap lines","Trade Policy Review Board","Dispute Settlement Body panels"],"answer":3,"explain":"WTO disputes go to Dispute Settlement Body panels, which issue rulings. Trade Policy Reviews monitor policy but do not settle disputes."},{"id":"ib-021","sub":"International Trade Theory and Agreements","diff":1,"q":"Which U.S. trade agreement covers the United States, the Dominican Republic and several Central American countries?","choices":["NAFTA","TPP","CAFTA-DR","APEC"],"answer":2,"explain":"CAFTA-DR is the Central America-Dominican Republic Free Trade Agreement with the United States."},{"id":"ib-022","sub":"International Trade Theory and Agreements","diff":1,"q":"Which group uses the euro as its common currency for most of its members?","choices":["Eurozone","Mercosur","ASEAN","NAFTA"],"answer":0,"explain":"The eurozone is the group of European Union members that have adopted the euro. Not every EU member uses it."},{"id":"ib-023","sub":"International Trade Theory and Agreements","diff":1,"q":"What is ASEAN?","choices":["A European currency union","A North American free trade pact","A Latin American customs union","The Association of Southeast Asian Nations, a regional bloc"],"answer":3,"explain":"ASEAN is a regional bloc of Southeast Asian nations that promotes economic and political cooperation."},{"id":"ib-024","sub":"International Trade Theory and Agreements","diff":1,"q":"Which principle requires a member to extend any trade advantage it gives one trading partner to all WTO members?","choices":["National treatment","Most-favoured-nation treatment","Reciprocity clause","Dumping margin"],"answer":1,"explain":"Most-favoured-nation treatment makes non-discrimination the default among WTO members. National treatment concerns how imports are treated after they enter."},{"id":"ib-025","sub":"International Trade Theory and Agreements","diff":1,"q":"What does the acronym WTO stand for?","choices":["World Trade Organization","World Tariff Office","Western Trade Office","World Treaty Organization"],"answer":0,"explain":"The World Trade Organization is the international body that sets rules for trade among nations."},{"id":"ib-026","sub":"Trade Barriers and Documentation","diff":1,"q":"Which document must a U.S. exporter file to report shipment details for export control and trade statistics?","choices":["Letter of credit","Certificate of insurance","Electronic Export Information (EEI) filing through AES","Bill of exchange"],"answer":2,"explain":"U.S. exporters file Electronic Export Information through the Automated Export System for shipments above the reporting thresholds."},{"id":"ib-027","sub":"Trade Barriers and Documentation","diff":1,"q":"Which document certifies where goods were produced and is often needed for preferential tariff treatment?","choices":["Commercial invoice","Certificate of origin","Packing list","Bill of lading"],"answer":1,"explain":"A certificate of origin states the country where goods were made, which determines whether trade agreement rates apply."},{"id":"ib-028","sub":"Foreign Exchange and International Finance","diff":2,"q":"A U.S. exporter ships machinery and wants the buyer to pay only after the buyer''s bank releases the shipping documents against payment. Which payment method fits?","choices":["Open account","Consignment","Cash in advance","Documentary collection (documents against payment)"],"answer":3,"explain":"Documentary collection lets the exporter keep control of documents until payment, with less bank commitment than a letter of credit."},{"id":"ib-029","sub":"Foreign Exchange and International Finance","diff":2,"q":"Which payment method gives the exporter the strongest payment guarantee, because a bank commits to pay on compliant documents?","choices":["Open account","Documentary collection","Irrevocable letter of credit","Consignment"],"answer":2,"explain":"An irrevocable letter of credit is the bank''s own promise to pay once the seller presents compliant documents. Documentary collection involves no such bank commitment."},{"id":"ib-030","sub":"Foreign Exchange and International Finance","diff":2,"q":"Under a letter of credit, which bank is obligated to pay the seller once compliant documents are presented?","choices":["The issuing bank or a confirming bank","The seller''s insurer","The freight forwarder","The customs broker"],"answer":0,"explain":"The issuing bank (for the buyer) or a confirming bank that adds its own promise must pay against compliant documents."},{"id":"ib-031","sub":"Trade Barriers and Documentation","diff":2,"q":"Which tariff type is a fixed amount per unit, such as $2 per kilogram?","choices":["An ad valorem tariff","A tariff that changes with exchange rates","A tariff that rises and falls with world prices","A specific tariff"],"answer":3,"explain":"A specific tariff is a fixed dollar amount per physical unit. Ad valorem tariffs are percentages of value."},{"id":"ib-032","sub":"Trade Barriers and Documentation","diff":2,"q":"A country allows 50,000 imported cars a year at a 5 percent tariff and charges 40 percent on any cars above that amount. Which policy is this?","choices":["Pure tariff","Tariff-rate quota","Embargo","Export subsidy"],"answer":1,"explain":"A tariff-rate quota combines a lower in-quota tariff with a higher out-of-quota tariff. A pure tariff applies one rate to all units."},{"id":"ib-033","sub":"Trade Barriers and Documentation","diff":2,"q":"A country imposes a special duty on imports sold below fair value that injure its domestic producers. What is this duty called?","choices":["Antidumping duty","Countervailing duty","Safeguard duty","Ad valorem tariff"],"answer":0,"explain":"Antidumping duties offset sales below normal value. Countervailing duties offset foreign government subsidies."},{"id":"ib-034","sub":"Trade Barriers and Documentation","diff":2,"q":"Which nontariff barrier requires products to meet specific technical, labelling or safety standards that favour domestic producers?","choices":["Quota","Embargo","Technical barrier to trade","Export credit"],"answer":2,"explain":"Technical barriers to trade are standards and conformity rules that can be used to protect domestic producers, even when they are not meant as tariffs."},{"id":"ib-035","sub":"Trade Barriers and Documentation","diff":2,"q":"Which is an example of an export subsidy?","choices":["A tariff on imported steel","A government grant that lowers a domestic firm''s cost of shipping goods abroad","A quota on imported textiles","A licence requirement for dual-use goods"],"answer":1,"explain":"An export subsidy lowers the cost of selling abroad. Tariffs, quotas and licence requirements restrict imports or exports rather than support them."},{"id":"ib-036","sub":"Trade Barriers and Documentation","diff":3,"q":"A U.S. exporter''s commercial invoice shows $50,000 FOB. Under U.S. customs transaction-value rules, which price is generally the basis for duty?","choices":["Price including ocean freight and insurance","The buyer''s resale price in the United States","The seller''s cost of production","The $50,000 FOB transaction price"],"answer":3,"explain":"U.S. transaction value is generally the price actually paid or payable, with international freight and insurance usually excluded when the goods are valued FOB."},{"id":"ib-037","sub":"Trade Barriers and Documentation","diff":3,"q":"Which statement about the Harmonized System (HS) is correct?","choices":["Classification determines only the country of origin","Each buyer sets its own classification for convenience","HS codes set a product''s standard international classification, which countries extend with national tariff detail","HS codes apply only to services"],"answer":2,"explain":"The HS is a standard international product nomenclature used for tariffs and statistics. Countries add their own subdivisions for duty rates."},{"id":"ib-038","sub":"Foreign Exchange and International Finance","diff":3,"q":"A U.S. exporter will receive EUR 250,000 in 180 days and fears the euro will weaken. Which hedge locks in the dollar value of the receivable?","choices":["Sell euros forward for dollars at the 180-day forward rate","Buy euros spot and hold them in a bank account","Buy a euro-denominated bond maturing in 30 days","Raise prices to European customers by 5 percent"],"answer":0,"explain":"A forward sale of euros fixes the future conversion rate. Holding spot euros keeps the currency risk, and a price increase does not guarantee a dollar amount."},{"id":"ib-039","sub":"Foreign Exchange and International Finance","diff":3,"q":"A currency is quoted at a forward premium against the dollar, meaning its forward rate is above its spot rate. Under covered interest parity, which statement is correct?","choices":["The currency is expected to depreciate against the dollar","The currency''s interest rates are typically lower than U.S. rates","U.S. interest rates must be lower than the foreign rate","The forward rate must equal the spot rate"],"answer":1,"explain":"A forward premium reflects an interest-rate gap: the currency with the lower interest rate trades at a forward premium against the higher-rate currency."},{"id":"ib-040","sub":"Foreign Exchange and International Finance","diff":3,"q":"A U.S. importer owes EUR 500,000 in 60 days and expects the euro to appreciate. Which action best hedges the payable?","choices":["Sell euros forward","Delay payment until the euro weakens","Convert dollars to euros now and hold them in a non-interest account","Buy euros forward at the 60-day forward rate"],"answer":3,"explain":"An importer owing euros is short euros, so it buys them forward to fix its dollar cost. Converting early earns no interest and delaying is speculation."},{"id":"ib-041","sub":"Foreign Exchange and International Finance","diff":1,"q":"The exchange rate moves from USD 1.10 per EUR to USD 1.20 per EUR. What happened to the euro?","choices":["The euro depreciated against the dollar","The dollar appreciated against the euro","The euro appreciated against the dollar","The rate is unchanged in real terms"],"answer":2,"explain":"More dollars per euro means each euro buys more dollars, so the euro strengthened."},{"id":"ib-042","sub":"Foreign Exchange and International Finance","diff":1,"q":"A U.S. firm pays EUR 100,000 for parts. The rate moves from 1.10 to 1.20 USD per EUR. How many more dollars does the firm pay?","choices":["$10,000 more","$12,000 more","$8,333 more","$20,000 more"],"answer":0,"explain":"EUR 100,000 costs $110,000 at 1.10 and $120,000 at 1.20, a difference of $10,000."},{"id":"ib-043","sub":"Foreign Exchange and International Finance","diff":1,"q":"A basket of goods costs $5 in the United States and 500 yen in Japan. What is the purchasing power parity exchange rate?","choices":["$1 = 5 yen","$1 = 50 yen","$1 = 500 yen","$1 = 100 yen"],"answer":3,"explain":"Purchasing power parity sets the rate equal to the price ratio: 500 yen divided by $5 gives 100 yen per dollar."},{"id":"ib-044","sub":"Foreign Exchange and International Finance","diff":1,"q":"Which is the most accurate definition of a forward exchange rate?","choices":["The rate for immediate delivery of currency","A rate agreed today for exchanging currency on a set future date","The official rate set by a central bank","The average spot rate over the past year"],"answer":1,"explain":"A forward rate is locked today for a future exchange date, which is why it is used to hedge."},{"id":"ib-045","sub":"Foreign Exchange and International Finance","diff":1,"q":"A U.S. multinational sends profits from its German subsidiary back to the parent company. What is this called?","choices":["Repatriation of profits","Transfer pricing","Dumping","Translation exposure"],"answer":0,"explain":"Repatriation is moving earnings from a foreign operation to the home country."},{"id":"ib-046","sub":"Foreign Exchange and International Finance","diff":1,"q":"Which account in the balance of payments records a country''s exports and imports of goods and services?","choices":["Capital account","Financial account","Current account","Reserve account"],"answer":2,"explain":"The current account covers trade in goods and services, plus income and transfers. The financial account records investment flows."},{"id":"ib-047","sub":"Market Entry and Expansion Strategies","diff":1,"q":"Which is an example of foreign direct investment?","choices":["A U.S. pension fund buys shares of a Japanese company on the Tokyo exchange","A U.S. manufacturer builds a new plant in Mexico that it fully owns","A Canadian bank lends money to a U.S. retailer","An American investor buys U.S. Treasury bonds"],"answer":1,"explain":"FDI means lasting control or a significant stake in a foreign business. Buying shares as a passive investment is portfolio investment."},{"id":"ib-048","sub":"Foreign Exchange and International Finance","diff":2,"q":"A U.S. firm invoices a Brazilian customer in U.S. dollars, and the real weakens 15 percent before payment. Who bears the currency risk?","choices":["The U.S. firm, because the real weakened","Neither party, because the invoice is in dollars","The U.S. firm gains, because reais are cheaper","The customer, whose dollar cost rises and so raises default risk"],"answer":3,"explain":"Dollar invoicing shifts currency risk to the buyer, who needs more reais per dollar. The seller''s dollar receivable is fixed, but nonpayment risk rises."},{"id":"ib-049","sub":"Foreign Exchange and International Finance","diff":2,"q":"Which situation most clearly describes translation exposure rather than transaction exposure?","choices":["A payment due in 30 days in pounds","A bid priced in euros","A foreign subsidiary''s balance sheet converted to dollars for consolidation","An import order already paid in yen"],"answer":2,"explain":"Translation exposure arises when foreign-currency financial statements are restated in the parent''s currency. Transaction exposure involves actual future cash flows."},{"id":"ib-050","sub":"Foreign Exchange and International Finance","diff":2,"q":"A firm''s peso receipts are converted at 18 pesos per dollar today and 20 pesos per dollar in six months. What does this mean for a U.S. firm holding pesos?","choices":["The peso weakened, so each peso converts to fewer dollars","The peso strengthened, so each peso converts to more dollars","The dollar weakened against the peso","The peso and dollar are unchanged in value"],"answer":0,"explain":"Needing more pesos per dollar means the peso lost value. A holder of pesos gets fewer dollars for each peso."},{"id":"ib-051","sub":"Market Entry and Expansion Strategies","diff":2,"q":"A U.S. firm licenses its brand to a Korean company for a 6 percent royalty on net sales. Korean net sales are $4,000,000 this year. What royalty does the U.S. firm earn?","choices":["$24,000","$2,400,000","$640,000","$240,000"],"answer":3,"explain":"6 percent of $4,000,000 is $240,000. Licensing earns royalties without the firm bearing the investment in production."},{"id":"ib-052","sub":"Market Entry and Expansion Strategies","diff":2,"q":"A firm builds a plant from scratch in Vietnam rather than buying an existing one. Which term fits, and what is its main trade-off?","choices":["Acquisition; quick market access","Greenfield investment; full control but slower start-up and higher risk","Licensing; no capital needed","Brownfield merger; faster start-up"],"answer":1,"explain":"A greenfield investment builds new facilities, giving control but taking longer and carrying more risk than buying an existing operation."},{"id":"ib-053","sub":"Market Entry and Expansion Strategies","diff":2,"q":"Which entry mode gives the firm the most control but requires the most investment?","choices":["Wholly owned subsidiary","Exporting through agents","Licensing","Strategic alliance"],"answer":0,"explain":"A wholly owned subsidiary gives full control of operations and profits, but the firm carries all the investment and risk."},{"id":"ib-054","sub":"Market Entry and Expansion Strategies","diff":2,"q":"Two firms in different countries pool research on one product but remain separate companies. This is best described as:","choices":["Licensing","Acquisition","Strategic alliance","Export management company"],"answer":2,"explain":"A strategic alliance is a cooperative agreement between independent firms, with no new legal entity and no ownership transfer."},{"id":"ib-055","sub":"Market Entry and Expansion Strategies","diff":2,"q":"Which entry mode creates a new legal entity jointly owned by a foreign firm and a local partner, sharing profits and control?","choices":["Franchise agreement","Joint venture","Contract manufacturing","Direct export"],"answer":1,"explain":"A joint venture is a new entity owned by two or more parents, usually used to share risk and gain local knowledge."},{"id":"ib-056","sub":"Market Entry and Expansion Strategies","diff":3,"q":"A firm wants to enter a foreign market with little capital and is willing to share profits with a local company that knows the market. Which entry mode fits best?","choices":["Joint venture","Wholly owned greenfield plant","Direct exporting","Portfolio investment"],"answer":0,"explain":"A joint venture shares the investment and the local know-how, at the cost of shared control and profits."},{"id":"ib-057","sub":"Market Entry and Expansion Strategies","diff":3,"q":"A firm''s entry plan has fixed costs of $600,000 and a contribution margin of $30 per unit. How many units must it sell to break even?","choices":["12,000","15,000","20,000","30,000"],"answer":2,"explain":"Break-even units equal fixed costs divided by contribution margin per unit: $600,000 divided by $30 is 20,000."},{"id":"ib-058","sub":"Market Entry and Expansion Strategies","diff":3,"q":"A U.S. firm enters Japan by buying an existing Japanese distributor to gain its channels quickly. Which mode is this, and what is the main risk?","choices":["Greenfield; the main risk is slow construction","Licensing; the main risk is low royalty income","Exporting; the main risk is tariffs","Acquisition; the main risk is overpaying and inheriting hidden liabilities"],"answer":3,"explain":"Acquisitions give quick access but carry valuation and due-diligence risk, including liabilities the buyer did not expect."},{"id":"ib-059","sub":"Market Entry and Expansion Strategies","diff":3,"q":"Which factor most favours a wholly owned subsidiary over a joint venture?","choices":["The host country requires a local majority partner","The firm lacks local market knowledge","The firm wants to share start-up costs","Strong intellectual property and firm-specific know-how the firm wants to protect"],"answer":3,"explain":"Protecting valuable know-how is the main reason to keep full control. The other factors all push toward sharing ownership."},{"id":"ib-060","sub":"Market Entry and Expansion Strategies","diff":3,"q":"A U.S. firm exports to Canada through a distributor that buys the goods outright. Who owns the goods and carries the sales risk?","choices":["The U.S. firm, until the goods are sold to end customers","The distributor, once it takes title and pays for the goods","Both share equally under consignment","The Canadian end customer, at the port of entry"],"answer":1,"explain":"When a distributor buys outright, title and risk pass to it. Under consignment the exporter keeps title until resale."},{"id":"ib-061","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"Which marketing approach uses the same product, message and packaging in every country?","choices":["Standardization","Adaptation","Segmentation by culture","Price skimming"],"answer":0,"explain":"Standardization keeps the marketing mix the same across markets. Adaptation changes it to fit each market."},{"id":"ib-062","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"Which Hofstede dimension measures how much less powerful members of a society accept an unequal distribution of power?","choices":["Individualism","Uncertainty avoidance","Power distance","Masculinity"],"answer":2,"explain":"Power distance is the degree to which less powerful members accept and expect unequal power. Uncertainty avoidance measures tolerance for ambiguity."},{"id":"ib-063","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"Which staffing approach fills key management posts with the parent company''s nationals?","choices":["Polycentric","Ethnocentric","Geocentric","Regiocentric"],"answer":1,"explain":"An ethnocentric approach relies on home-country nationals for key posts. Polycentric uses host-country managers."},{"id":"ib-064","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"Which term describes a home-country employee sent to work abroad?","choices":["Host-country national","Third-country national","Repatriate","Expatriate"],"answer":3,"explain":"An expatriate is an employee working outside the country of citizenship, usually sent from headquarters."},{"id":"ib-065","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"Which pricing approach sets a low introductory price to gain market share quickly in a new market?","choices":["Price skimming","Cost-plus pricing","Penetration pricing","Prestige pricing"],"answer":2,"explain":"Penetration pricing starts low to win share. Price skimming starts high and lowers the price over time."},{"id":"ib-066","sub":"Trade Barriers and Documentation","diff":1,"q":"A product is sold in a foreign market below its home-market price or cost, which may trigger trade remedies. What is this called?","choices":["Dumping","Transfer pricing","Price skimming","Tariff escalation"],"answer":0,"explain":"Dumping is selling abroad below normal value. It can lead to antidumping duties if it injures domestic producers."},{"id":"ib-067","sub":"Global Marketing and Cultural Adaptation","diff":1,"q":"A brand changes its name for Chinese consumers, using characters with a similar sound and a positive meaning. This is an example of:","choices":["Standardization","Back translation","Dumping","Localization"],"answer":3,"explain":"Localization adapts a product or message to local language and cultural meaning. Standardization keeps it the same everywhere."},{"id":"ib-068","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A U.S. snack brand must reduce sugar and offer vegetarian-friendly flavours in India, while keeping its brand name. Which strategy is this?","choices":["Standardization","Adaptation of the product and marketing mix","Ethnocentric staffing","Export licensing"],"answer":1,"explain":"Changing the product to meet local tastes and rules, while keeping the brand, is product adaptation."},{"id":"ib-069","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A marketing team runs the same campaign in five countries but adjusts the language and imagery in each. Which term best fits this approach?","choices":["Glocalization","Ethnocentrism","Dumping","Polycentrism"],"answer":0,"explain":"Glocalization combines a global core strategy with local adaptation in execution."},{"id":"ib-070","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"Which reason most directly explains why a message that signals quality in one country may read as overpricing in another?","choices":["Different tariff rates","Different exchange rates","Different cultural cues about what price signals","Different interest rates"],"answer":2,"explain":"Culture shapes how buyers read price, which is why a message must be tested in each market rather than assumed to transfer."},{"id":"ib-071","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A U.S. toy company is considering entering Mexico. Which step should come first in its global marketing research?","choices":["Set prices for the Mexican market","Define the research problem and objectives","Choose a distributor","Launch a pilot campaign"],"answer":1,"explain":"The research process starts by defining the problem and objectives. Pricing, distribution and launch decisions depend on that work."},{"id":"ib-072","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A product must sell at a lower purchase price in lower-income markets, with its features and packaging left unchanged. Which element of the 4Ps needs the most adjustment?","choices":["Product","Place","Promotion","Price"],"answer":3,"explain":"With the product held constant, the price element is the one that must change to lower the purchase price. Promotion and place do not set the amount paid."},{"id":"ib-073","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A product costs $40 per unit to make. The firm wants a 50 percent markup on cost. What is the target price?","choices":["$20","$50","$60","$80"],"answer":2,"explain":"A 50 percent markup on $40 adds $20, for a target price of $60."},{"id":"ib-074","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"Which description best fits the Hofstede dimension of individualism?","choices":["The degree to which people expect to look after themselves and their immediate family","The degree of tolerance for uncertainty","The degree of gender role separation","The degree of long-term orientation"],"answer":0,"explain":"Individualism contrasts with collectivism, where people rely more on group loyalty and extended family."},{"id":"ib-075","sub":"Global Marketing and Cultural Adaptation","diff":2,"q":"A U.S. fast-food chain changes its menu in Japan to suit local tastes. Which concept best explains the decision?","choices":["Ethnocentric staffing","Standardization","Dumping avoidance","Adaptation to local tastes"],"answer":3,"explain":"Adapting the product to local preferences is the adaptation strategy, which contrasts with standardization."},{"id":"ib-076","sub":"Global Operations and Supply Chain","diff":3,"q":"A manufacturer relies on a single Asian supplier for a critical component, holds almost no buffer stock, and a port closure halts production. Which risk is this?","choices":["Exchange rate risk","Supply chain concentration risk from single sourcing and lean inventory","Translation exposure","Tariff escalation"],"answer":1,"explain":"Single sourcing combined with just-in-time inventory leaves the firm exposed to any disruption at one point in the chain."},{"id":"ib-077","sub":"Global Operations and Supply Chain","diff":3,"q":"A manufacturer moves some production from China to Mexico to shorten lead times and reduce tariff exposure under USMCA. This is called:","choices":["Nearshoring","Offshoring","Reshoring","Outsourcing to a third party"],"answer":0,"explain":"Nearshoring moves production closer to the home market. Reshoring brings it back home, and offshoring moves it farther away."},{"id":"ib-078","sub":"Global Operations and Supply Chain","diff":3,"q":"Under which Incoterm does the seller make goods available at its own premises, while the buyer bears all costs and risks from there?","choices":["FOB","CIF","EXW","DDP"],"answer":2,"explain":"Ex Works (EXW) puts the buyer in charge of export clearance and all transport from the seller''s premises, which is the seller''s minimum obligation."},{"id":"ib-079","sub":"Global Operations and Supply Chain","diff":3,"q":"Under FOB shipping point terms, when does the risk of loss pass to the buyer?","choices":["When goods arrive at the buyer''s warehouse","When goods are loaded on board the vessel at the origin port","When the buyer pays the invoice","When customs clears the goods at the destination"],"answer":1,"explain":"Under FOB shipping point, risk passes once goods are on board the ship at the origin port, even though the seller pays the freight to that point."},{"id":"ib-080","sub":"Global Operations and Supply Chain","diff":3,"q":"Under CIF terms, what does the seller pay for beyond the goods themselves?","choices":["Only export clearance","Import duties in the destination country","Warehousing at the buyer''s dock","Cost, insurance and freight to the named destination port"],"answer":3,"explain":"CIF means the seller pays cost, insurance and freight to the destination port. Import duties and clearance remain the buyer''s responsibility."},{"id":"ib-081","sub":"Global Operations and Supply Chain","diff":1,"q":"Which practice keeps inventory low by having parts arrive just as they are needed?","choices":["Batch production","Economic order quantity stockpiling","Just-in-time","Safety-stock hoarding"],"answer":2,"explain":"Just-in-time inventory delivers materials when needed, which cuts carrying costs but increases dependence on reliable supply."},{"id":"ib-082","sub":"Global Operations and Supply Chain","diff":1,"q":"What is the bullwhip effect?","choices":["Order variability grows as it moves upstream in a supply chain","Currency values swinging sharply after a trade deal","Tariffs rising in steps over several years","A shipping lane being shut by weather"],"answer":0,"explain":"Small changes in customer demand are amplified as orders move back through distributors, manufacturers and suppliers."},{"id":"ib-083","sub":"Global Operations and Supply Chain","diff":1,"q":"A U.S. company uses a freight forwarder to book ocean space and prepare documents. What is the forwarder''s main role?","choices":["Set the tariff rate","Insure the cargo for the buyer","Issue letters of credit","Arrange transport and handle shipping documents"],"answer":3,"explain":"Freight forwarders organize transport and paperwork for shippers. They do not set tariffs or issue bank credit."},{"id":"ib-084","sub":"Global Operations and Supply Chain","diff":1,"q":"Which document is a receipt for goods shipped and evidence of the contract of carriage?","choices":["Commercial invoice","Bill of lading","Certificate of origin","Packing list"],"answer":1,"explain":"The bill of lading is issued by the carrier. It is also a document of title that controls who may claim the goods."},{"id":"ib-085","sub":"Global Operations and Supply Chain","diff":1,"q":"Which document is the seller''s bill to the buyer, stating the goods, quantities and price, and is used for customs valuation?","choices":["Commercial invoice","Bill of lading","Export license","Letter of credit"],"answer":0,"explain":"The commercial invoice is the basic transaction document customs uses to value goods."},{"id":"ib-086","sub":"Legal, Ethical and Political Risk","diff":1,"q":"Which agency administers U.S. economic sanctions programs against certain countries and individuals?","choices":["Federal Trade Commission","Securities and Exchange Commission","Office of Foreign Assets Control (OFAC)","Consumer Financial Protection Bureau"],"answer":2,"explain":"OFAC within the Treasury Department administers and enforces sanctions programs, which bar transactions with designated parties."},{"id":"ib-087","sub":"Legal, Ethical and Political Risk","diff":1,"q":"A government takes over privately owned foreign assets, paying compensation. Which political risk is this?","choices":["Dumping","Expropriation","Quota","Countertrade"],"answer":1,"explain":"Expropriation is government seizure of foreign-owned assets. Compensation does not change the classification as a political risk."},{"id":"ib-088","sub":"Legal, Ethical and Political Risk","diff":2,"q":"A U.S. firm''s Chinese distributor offers a consulting payment to a provincial official who controls permits, worth $25,000 in total. What is the main U.S. legal concern?","choices":["Sherman Act price-fixing","Robinson-Patman price discrimination","Missing export license paperwork","Potential FCPA violation through a third party paying an official"],"answer":3,"explain":"The FCPA covers improper payments made through intermediaries, and the firm can be liable for what its agent does."},{"id":"ib-089","sub":"Trade Barriers and Documentation","diff":2,"q":"Which trade remedy offsets a foreign government''s subsidy to its exporters?","choices":["Antidumping duty","Section 232 tariff","Countervailing duty","Safeguard quota"],"answer":2,"explain":"A countervailing duty offsets subsidies. An antidumping duty offsets sales below fair value."},{"id":"ib-090","sub":"Legal, Ethical and Political Risk","diff":2,"q":"Which protection is most typical for a large mining investment in an unstable country?","choices":["Political risk insurance from a public or private insurer","Increasing dumping margins","Reducing tariffs on imported equipment","Shifting to countertrade in all markets"],"answer":0,"explain":"Political risk insurance covers losses from expropriation, currency inconvertibility and political violence."},{"id":"ib-091","sub":"Legal, Ethical and Political Risk","diff":2,"q":"Which description best fits ethical relativism in international business?","choices":["Ethics are identical in every country","Ethics apply only to home-country laws","Ethics depend only on profit targets","Right and wrong are judged by local cultural norms"],"answer":3,"explain":"Ethical relativism holds that moral standards vary by culture. Critics argue it can excuse practices that are wrong everywhere."},{"id":"ib-092","sub":"Legal, Ethical and Political Risk","diff":2,"q":"A foreign subsidiary must follow host-country labour laws even when the parent''s home-country standards are higher. Which principle explains this?","choices":["Extraterritorial reach of home-country law only","Host-country laws apply to operations within that country","Most-favoured-nation treatment","Reciprocity clause"],"answer":1,"explain":"Operations are generally governed by the laws of the country where they take place, though some home-country rules such as the FCPA also apply abroad."},{"id":"ib-093","sub":"International Trade Theory and Agreements","diff":2,"q":"Which WTO-permitted measure lets a member temporarily restrict imports when a sudden surge seriously injures a domestic industry?","choices":["Safeguard measure","Dumping margin","Export subsidy","Reciprocal tariff cut"],"answer":0,"explain":"Safeguards are temporary and non-discriminatory responses to import surges, and they are different from antidumping or countervailing action."},{"id":"ib-094","sub":"Legal, Ethical and Political Risk","diff":2,"q":"Which principle requires that imported goods be treated no less favourably than domestic like goods once they cross the border?","choices":["Most-favoured-nation","Reciprocity","National treatment","Single undertaking"],"answer":2,"explain":"National treatment bars discrimination against foreign goods after entry, including internal taxes and regulations."},{"id":"ib-095","sub":"Foreign Exchange and International Finance","diff":2,"q":"A firm sets the price of goods sold between its own subsidiaries so that profit shows up in a low-tax country. What is this called?","choices":["Dumping","Transfer pricing","Countertrade","Hedging"],"answer":1,"explain":"Transfer pricing sets internal prices, and tax authorities require them to reflect arm''s-length values."},{"id":"ib-096","sub":"Legal, Ethical and Political Risk","diff":3,"q":"A subsidiary in Brazil must buy a share of its inputs from local suppliers and reinvest 60 percent of profits locally. What kind of host-government measure is this?","choices":["Quota","Anti-dumping action","Countervailing duty","Local content or performance requirement"],"answer":3,"explain":"Local content and reinvestment rules are performance requirements that tie market access or operation to specific local actions."},{"id":"ib-097","sub":"Legal, Ethical and Political Risk","diff":3,"q":"Under the Export Administration Regulations (EAR), which situation most requires a license check?","choices":["Exporting controlled dual-use technology to a restricted foreign party","Exporting ordinary consumer goods to Canada","Shipping books to a university in France","Sending a sales catalogue abroad"],"answer":0,"explain":"Dual-use technology sent to restricted parties needs a license or a license exception. Routine consumer goods and publications usually do not."},{"id":"ib-098","sub":"Legal, Ethical and Political Risk","diff":3,"q":"A firm learns that its foreign agent has been making payments to customs officials. What is the firm''s best immediate step?","choices":["Continue the payments, since they are standard in the country","End the agent immediately without any review","Launch an internal investigation with counsel and consider voluntary disclosure","Move the payments to a different subsidiary"],"answer":2,"explain":"Counsel-led investigation and possible voluntary disclosure limit FCPA exposure. Ignoring the problem or moving it does not."},{"id":"ib-099","sub":"International Trade Theory and Agreements","diff":3,"q":"Which statement about USMCA rules of origin is correct?","choices":["Goods qualify for zero tariffs regardless of where their parts originate","Goods must meet regional value content rules to receive preferential tariff treatment","Any product made in Canada qualifies automatically","Rules of origin apply only to agricultural goods"],"answer":1,"explain":"Preferential treatment requires goods to meet regional value content and origin rules, so simply being assembled in a member country is not enough."},{"id":"ib-100","sub":"Legal, Ethical and Political Risk","diff":3,"q":"A U.S. firm sells to a country whose currency cannot be converted into dollars. Which option best protects its ability to collect payment?","choices":["Open account terms with 90-day payment","Consignment shipments","Cash on delivery in local currency","Countertrade or a letter of credit confirmed by a bank able to transfer funds"],"answer":3,"explain":"A confirmed letter of credit or countertrade gives payment assurance even when currency convertibility is blocked. Open account and consignment leave the firm exposed."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'intro-business-concepts', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"ibc-001","sub":"Fundamental Economic Concepts","diff":1,"q":"Which term describes the condition in which unlimited human wants exceed limited resources?","choices":["Scarcity","Surplus","Equilibrium","Inflation"],"answer":0,"explain":"Scarcity is the basic economic problem: resources are limited relative to wants, which forces choices. Surplus is a market condition, not the underlying problem."},{"id":"ibc-002","sub":"Fundamental Economic Concepts","diff":3,"q":"Maria can either work a shift that pays $80 or attend a training course. She chooses the course. What is her opportunity cost of the course?","choices":["The full cost of the training course","The $80 of pay she gave up by not working the shift","Zero, since the course is free","The total of all her possible earnings for the year"],"answer":1,"explain":"Opportunity cost is the value of the next best alternative forgone, not the price paid. The trap is confusing it with out-of-pocket cost."},{"id":"ibc-003","sub":"Fundamental Economic Concepts","diff":1,"q":"A product''s price rises from $20 to $25. What is the percentage increase?","choices":["5%","20%","25%","80%"],"answer":2,"explain":"The change is $5 on a base of $20, so $5 / $20 = 25%. A common error is dividing by the new price."},{"id":"ibc-004","sub":"Fundamental Economic Concepts","diff":3,"q":"Which change would shift the demand curve for a normal good to the right?","choices":["A decrease in the good''s own price","An increase in the good''s own price","A rise in the cost of raw materials","An increase in consumer incomes"],"answer":3,"explain":"Income changes shift demand; a change in the good''s own price only moves along the existing curve. Raw material costs affect supply, not demand."},{"id":"ibc-005","sub":"Fundamental Economic Concepts","diff":3,"q":"Which change would shift the supply curve for a product to the right?","choices":["A decrease in the cost of raw materials","An increase in consumer preference for the product","A rise in the product''s own price","An increase in consumer income"],"answer":0,"explain":"Lower input costs let firms produce more at every price, shifting supply right. Consumer preferences and income affect demand."},{"id":"ibc-006","sub":"Fundamental Economic Concepts","diff":1,"q":"Which factor of production is human effort, both physical and mental, used to produce goods and services?","choices":["Capital","Labor","Land","Entrepreneurship"],"answer":1,"explain":"Labor is the human work input. Capital is human-made goods, land is natural resources, and entrepreneurship is risk-taking and organizing."},{"id":"ibc-007","sub":"Fundamental Economic Concepts","diff":1,"q":"Which factor of production is the willingness to take on risk and combine the other resources to pursue profit?","choices":["Labor","Capital","Entrepreneurship","Land"],"answer":2,"explain":"Entrepreneurship is the fourth factor of production, and it is the factor that organizes and bears risk."},{"id":"ibc-008","sub":"Fundamental Economic Concepts","diff":3,"q":"In economics, which of the following best describes capital as a factor of production?","choices":["Money held in a bank account","Natural resources such as timber and water","Workers'' skills and education","Human-made goods, such as machinery and tools, used to produce other goods"],"answer":3,"explain":"Economic capital means produced goods used in production. Money is financial capital and is not counted as a factor of production in the classic model."},{"id":"ibc-009","sub":"Fundamental Economic Concepts","diff":3,"q":"Which measure best describes gross domestic product (GDP)?","choices":["The total market value of all final goods and services produced within a country in a period","The total income earned by citizens living abroad","The total value of all goods a country imports","The total money supply in circulation"],"answer":0,"explain":"GDP measures production within the borders of a country over a time period. Income earned abroad and imports are different measures."},{"id":"ibc-010","sub":"Fundamental Economic Concepts","diff":1,"q":"What term describes a sustained, general increase in the price level of goods and services?","choices":["Deflation","Inflation","Recession","Depreciation"],"answer":1,"explain":"Inflation is a broad, persistent rise in prices. Deflation is the opposite, and depreciation refers to an asset losing value."},{"id":"ibc-011","sub":"Fundamental Economic Concepts","diff":3,"q":"A basket of goods costs $400 last year and $420 this year. What is the rate of inflation?","choices":["4.76%","20%","5%","95%"],"answer":2,"explain":"The change is $20 divided by last year''s $400 base, which equals 5%. Dividing by this year''s $420 gives the 4.76% trap."},{"id":"ibc-012","sub":"Fundamental Economic Concepts","diff":1,"q":"At market equilibrium, which condition holds?","choices":["Price is at its highest possible level","Supply exceeds demand","The government has set a price ceiling","Quantity demanded equals quantity supplied"],"answer":3,"explain":"Equilibrium is where the supply and demand curves intersect, so quantity demanded equals quantity supplied and there is no pressure to change price."},{"id":"ibc-013","sub":"Fundamental Economic Concepts","diff":3,"q":"When the price of a good is above its equilibrium level, what typically happens?","choices":["A surplus forms, which puts downward pressure on price","A shortage forms, which puts upward pressure on price","A surplus forms, which puts upward pressure on price","A shortage forms with no pressure on price"],"answer":0,"explain":"At a price above equilibrium, sellers offer more than buyers want, creating a surplus. The unsold stock pushes the price down toward equilibrium."},{"id":"ibc-014","sub":"Fundamental Economic Concepts","diff":3,"q":"A business owner can earn $50,000 running her current company or $35,000 teaching. If she runs the company, what is her opportunity cost?","choices":["$50,000 in company earnings","$35,000 in teaching income forgone","$15,000, the difference between the two","$85,000, the sum of both options"],"answer":1,"explain":"Opportunity cost is the value of the next best alternative, here $35,000. The $50,000 is what she gains, not what she gives up."},{"id":"ibc-015","sub":"Fundamental Economic Concepts","diff":3,"q":"Country A can make a unit of cloth at a lower opportunity cost than Country B. Which statement is correct?","choices":["Country A has an absolute advantage in every good","Country A has no advantage in cloth","Country A has a comparative advantage in producing cloth","Country A always wins in trade due to lower wages"],"answer":2,"explain":"Comparative advantage depends on opportunity cost, not on absolute output or wages. A country can hold a comparative advantage even if it is not the most productive at everything."},{"id":"ibc-016","sub":"Fundamental Economic Concepts","diff":3,"q":"A 10% increase in price causes a 20% decrease in quantity demanded. Demand for this good is:","choices":["Inelastic, because quantity fell by more than price rose","Unit elastic, because the two percentages are close","Perfectly inelastic, because quantity changed","Elastic, because the elasticity ratio is greater than 1"],"answer":3,"explain":"Elasticity is the percent change in quantity divided by the percent change in price, here 20% / 10% = 2. A ratio above 1 means demand is elastic."},{"id":"ibc-017","sub":"Fundamental Economic Concepts","diff":1,"q":"Which market structure has many sellers, identical products, and free entry and exit?","choices":["Perfect competition","Monopoly","Oligopoly","Monopolistic competition"],"answer":0,"explain":"Perfect competition assumes identical products and free entry. Monopolistic competition has differentiated products, so it is the closest distractor."},{"id":"ibc-018","sub":"Fundamental Economic Concepts","diff":3,"q":"Which phase of the business cycle is characterized by falling real GDP and rising unemployment?","choices":["Expansion","Contraction","Recovery","Peak"],"answer":1,"explain":"Contraction is the downturn phase. Recovery is the rise after a trough, and expansion is the growth phase, so both are traps."},{"id":"ibc-019","sub":"Fundamental Economic Concepts","diff":3,"q":"A worker quits a job to look for a better position and is between jobs for two months. This is an example of which type of unemployment?","choices":["Structural unemployment","Cyclical unemployment","Frictional unemployment","Seasonal unemployment"],"answer":2,"explain":"Frictional unemployment is short-term and comes from workers moving between jobs. Structural unemployment comes from skill mismatches, and cyclical comes from downturns."},{"id":"ibc-020","sub":"Fundamental Economic Concepts","diff":3,"q":"When the Federal Reserve raises the federal funds rate, which outcome is most likely?","choices":["The money supply rises and spending increases","Inflation automatically rises to offset the change","Unemployment falls permanently","Borrowing becomes more expensive and spending tends to slow"],"answer":3,"explain":"A higher policy rate raises borrowing costs across the economy, which slows spending and can cool inflation. Its effects are indirect and take time."},{"id":"ibc-021","sub":"Nature of Business","diff":1,"q":"Which form of business ownership offers no legal separation between the owner''s personal and business liabilities?","choices":["Sole proprietorship","Limited liability company","Corporation","Limited partnership"],"answer":0,"explain":"A sole proprietor and the business are one legal person, so the owner is personally liable for business debts."},{"id":"ibc-022","sub":"Nature of Business","diff":1,"q":"What is a key advantage of a corporation over a sole proprietorship?","choices":["Owners are personally liable for all business debts","Limited liability for shareholders","It is the simplest and cheapest form to form","Profits are taxed only once at the owner''s personal rate"],"answer":1,"explain":"Shareholders are generally not personally liable for corporate debts. Corporations are more costly to form and may face double taxation."},{"id":"ibc-023","sub":"Nature of Business","diff":3,"q":"Which business structure is most associated with double taxation of profits?","choices":["Sole proprietorship","General partnership","C corporation","S corporation"],"answer":2,"explain":"A C corporation pays tax on profits, and shareholders pay tax again on dividends. An S corporation passes income through to owners and avoids this."},{"id":"ibc-024","sub":"Nature of Business","diff":3,"q":"In a general partnership, what is the usual liability of each partner for business debts?","choices":["Shielded by limited liability","Liable only up to the amount they invested","Not liable for debts incurred by other partners","Jointly and severally liable, so a creditor can pursue any partner for the full amount"],"answer":3,"explain":"General partners are personally liable for partnership debts, and each partner can be held responsible for the full amount. Limited liability is a feature of LLCs and corporations."},{"id":"ibc-025","sub":"Nature of Business","diff":3,"q":"Which group is a stakeholder in a business but is not necessarily a shareholder?","choices":["Employees","Major shareholders","Owners of common stock","Investors holding preferred shares"],"answer":0,"explain":"Stakeholders include anyone affected by the business, such as employees, customers, and communities. Shareholders are only one stakeholder group."},{"id":"ibc-026","sub":"Nature of Business","diff":1,"q":"What is the primary purpose of a company''s mission statement?","choices":["To forecast revenue for the next five years","To communicate the organization''s core purpose and reason for existing","To list the company''s main competitors","To set the quarterly financial targets"],"answer":1,"explain":"A mission statement explains why the organization exists. Forecasts, competitors, and targets belong in other planning documents."},{"id":"ibc-027","sub":"Nature of Business","diff":1,"q":"In a SWOT analysis, which element refers to external factors that could help the business?","choices":["Strengths","Weaknesses","Opportunities","Threats"],"answer":2,"explain":"Opportunities are external conditions the business can exploit. Strengths are internal, and threats are external but harmful."},{"id":"ibc-028","sub":"Nature of Business","diff":1,"q":"How is net profit calculated?","choices":["Gross sales minus cost of goods sold","Total assets minus total liabilities","Total revenue divided by total expenses","Total revenue minus total expenses"],"answer":3,"explain":"Net profit is the bottom line after all expenses. Gross sales minus cost of goods sold gives gross profit, and assets minus liabilities gives equity."},{"id":"ibc-029","sub":"Nature of Business","diff":2,"q":"Which action best demonstrates corporate social responsibility?","choices":["Voluntarily cutting the factory''s emissions below what the law requires","Hiding a product defect to protect sales","Moving operations overseas solely to avoid all local laws","Paying the lowest wage the market will bear without any review"],"answer":0,"explain":"CSR means taking responsibility for social and environmental impact beyond legal minimums. Hiding defects and evading laws are unethical choices."},{"id":"ibc-030","sub":"Nature of Business","diff":1,"q":"A person buys the right to operate a business using an established company''s brand and operating system. This person is a:","choices":["Franchisor","Franchisee","Licensor","Business partner"],"answer":1,"explain":"The franchisee pays fees and royalties to use the franchisor''s brand and system. The franchisor is the company granting the rights."},{"id":"ibc-031","sub":"Nature of Business","diff":2,"q":"What distinguishes a limited liability company (LLC) from a general partnership?","choices":["LLCs cannot have more than one owner","LLCs must issue shares of stock to the public","LLC members generally have limited liability for business debts","LLC profits are always taxed at the corporate rate"],"answer":2,"explain":"An LLC combines limited liability with flexible tax treatment. A general partnership has no such shield, and LLCs can have multiple owners and do not issue public stock by default."},{"id":"ibc-032","sub":"Nature of Business","diff":2,"q":"In a business plan, which section describes target customers and competitors?","choices":["Executive summary","Financial plan","Operations plan","Market analysis"],"answer":3,"explain":"The market analysis section covers the target market, customer needs, and competition. The executive summary is an overview placed at the front."},{"id":"ibc-033","sub":"Nature of Business","diff":1,"q":"Which term describes a person who organizes, operates, and assumes the risks of a business?","choices":["Entrepreneur","Investor","Manager","Stakeholder"],"answer":0,"explain":"An entrepreneur starts and runs a business and bears its risk. An investor provides capital but may not operate the business."},{"id":"ibc-034","sub":"Nature of Business","diff":3,"q":"A company has $240,000 in revenue and $180,000 in total expenses. What is its net profit margin?","choices":["33.3%","25%","75%","$60,000"],"answer":1,"explain":"Net profit is $60,000 and the margin is $60,000 / $240,000 = 25%. Dividing by expenses gives the 33.3% trap, and $60,000 is profit, not a margin."},{"id":"ibc-035","sub":"Nature of Business","diff":2,"q":"Which is a benefit of buying a franchise for the franchisee?","choices":["Full control over menu and pricing decisions","No royalty or fee payments","Access to an established brand and a proven business system","Freedom from any franchisor rules"],"answer":2,"explain":"Franchisees gain brand recognition and a tested system, but they pay fees and follow standards. Full control and fee-free operation are not typical benefits."},{"id":"ibc-036","sub":"Economic Systems","diff":1,"q":"Which economic system uses customs, beliefs, and history to decide what is produced?","choices":["Command economy","Market economy","Mixed economy","Traditional economy"],"answer":3,"explain":"A traditional economy relies on long-standing customs and roles. Command economies use central planning, and market economies use prices."},{"id":"ibc-037","sub":"Economic Systems","diff":1,"q":"In a command economy, who primarily decides what goods are produced?","choices":["The central government","Consumers through their spending","Producers competing for profit","The market through price signals"],"answer":0,"explain":"In a command economy, a central authority plans production and allocation. The other options describe market mechanisms."},{"id":"ibc-038","sub":"Economic Systems","diff":1,"q":"A mixed economy is best described as:","choices":["Equal government ownership of every business","A combination of market forces and government intervention","A system with no private property at all","Production based entirely on tradition"],"answer":1,"explain":"Mixed economies combine private enterprise with government regulation or public services. Pure systems are rare."},{"id":"ibc-039","sub":"Economic Systems","diff":1,"q":"Which characteristic is most central to a market economy?","choices":["Central planning of all production","Government ownership of major industries","Private ownership of resources, with prices set by supply and demand","Production based on tradition"],"answer":2,"explain":"Market economies rely on private ownership and price signals. The other options describe command or traditional systems."},{"id":"ibc-040","sub":"Economic Systems","diff":2,"q":"The transfer of a government-owned business to private ownership is called:","choices":["Nationalization","Deregulation","Subsidization","Privatization"],"answer":3,"explain":"Privatization moves a public enterprise into private hands. Nationalization is the reverse, and deregulation removes rules without changing ownership."},{"id":"ibc-041","sub":"Economic Systems","diff":2,"q":"Which U.S. federal law is the primary statute prohibiting monopolies and restraints of trade?","choices":["Sherman Antitrust Act of 1890","Securities Act of 1933","Fair Labor Standards Act of 1938","Consumer Credit Protection Act of 1968"],"answer":0,"explain":"The Sherman Act is the foundational U.S. antitrust law. The other laws cover securities, wages, and consumer credit."},{"id":"ibc-042","sub":"Economic Systems","diff":1,"q":"Which concept, introduced by Adam Smith, describes self-interested individuals unintentionally advancing society''s welfare?","choices":["The law of diminishing returns","The invisible hand","The tragedy of the commons","Marginal utility"],"answer":1,"explain":"Smith''s invisible hand describes how self-interest in competitive markets can benefit society. The other concepts describe different economic ideas."},{"id":"ibc-043","sub":"Economic Systems","diff":1,"q":"Which characteristic is most associated with socialism?","choices":["Unrestricted private ownership of all businesses","Prices set only by bidding between consumers","Significant collective or government ownership of major means of production","No public services provided to citizens"],"answer":2,"explain":"Socialism emphasizes collective ownership of major industries. Private ownership and limited public services are the opposite."},{"id":"ibc-044","sub":"Economic Systems","diff":2,"q":"When shared, unowned resources are overused and depleted, economists call this:","choices":["The free rider problem","Moral hazard","Adverse selection","The tragedy of the commons"],"answer":3,"explain":"Shared resources with no clear owner tend to be overused. Free riding, moral hazard, and adverse selection are different market problems."},{"id":"ibc-045","sub":"Economic Systems","diff":1,"q":"Which government action is a consumer-protection regulation?","choices":["Requiring food labels to list ingredients and allergens","Subsidizing a domestic industry","Imposing a tariff on imported steel","Giving a tax credit to solar panel manufacturers"],"answer":0,"explain":"Labeling rules protect consumers from harm and deception. Subsidies and tariffs are economic policy tools, not consumer protection."},{"id":"ibc-046","sub":"Economic Systems","diff":1,"q":"A tax on imported goods is called a:","choices":["Quota","Tariff","Subsidy","Embargo"],"answer":1,"explain":"A tariff is a tax on imports. A quota limits quantity, a subsidy pays producers, and an embargo bans trade."},{"id":"ibc-047","sub":"Economic Systems","diff":1,"q":"A government payment to a producer to lower its production costs is called a:","choices":["Tariff","Excise tax","Subsidy","Price ceiling"],"answer":2,"explain":"Subsidies reduce a producer''s costs or increase its revenue. Tariffs and excise taxes raise money, and a price ceiling caps prices."},{"id":"ibc-048","sub":"Economic Systems","diff":2,"q":"Command economies are most likely to experience which problem?","choices":["Prices that change every minute","Excessive competition among firms","Too many private property rights","Shortages and surpluses caused by planners misjudging demand"],"answer":3,"explain":"Without price signals, central planners often misallocate goods, causing shortages or surpluses. Private property and competition are features of market systems."},{"id":"ibc-049","sub":"Economic Systems","diff":3,"q":"Which statement best explains why pure market economies rarely exist in practice?","choices":["Governments usually provide public goods, regulate externalities, and redistribute income","Consumers never have enough information to buy anything","Markets always produce too many goods","Private firms are legally barred from earning profits"],"answer":0,"explain":"Public goods, externalities, and inequality are market failures that most governments address, so real systems are mixed."},{"id":"ibc-050","sub":"Economic Systems","diff":2,"q":"Which term describes a cost or benefit imposed on people who are not part of a transaction?","choices":["Public good","Externality","Monopsony","Elasticity"],"answer":1,"explain":"An externality affects third parties, such as pollution from a factory. A public good is non-excludable, and monopsony is a single buyer."},{"id":"ibc-051","sub":"Cost/Profit Relationships","diff":1,"q":"Which cost does NOT change with the level of production in the short run?","choices":["Raw materials","Hourly wages for production workers","Factory rent","Packaging"],"answer":2,"explain":"Fixed costs such as rent stay the same regardless of output. The other costs rise as production rises."},{"id":"ibc-052","sub":"Cost/Profit Relationships","diff":1,"q":"Which cost is a variable cost for a bakery?","choices":["Annual insurance premium","Monthly rent for the shop","The owner''s fixed salary","Flour used in each batch"],"answer":3,"explain":"Variable costs change with output, and flour per batch rises with production. The others are fixed in the short run."},{"id":"ibc-053","sub":"Cost/Profit Relationships","diff":3,"q":"A business has fixed costs of $12,000, a price of $40 per unit, and variable cost of $25 per unit. How many units must it sell to break even?","choices":["800 units","300 units","480 units","1,200 units"],"answer":0,"explain":"Contribution margin is $40 - $25 = $15, and $12,000 / $15 = 800 units. Dividing fixed costs by price (300) is a common mistake."},{"id":"ibc-054","sub":"Cost/Profit Relationships","diff":1,"q":"Sales are $150,000 and cost of goods sold is $90,000. What is gross profit?","choices":["$90,000","$60,000","$40,000","$150,000"],"answer":1,"explain":"Gross profit is sales minus cost of goods sold, so $150,000 - $90,000 = $60,000."},{"id":"ibc-055","sub":"Cost/Profit Relationships","diff":3,"q":"A retailer buys an item for $50 and sells it for $75. What is the markup as a percentage of cost?","choices":["33.3%","25%","50%","150%"],"answer":2,"explain":"Markup on cost is ($75 - $50) / $50 = 50%. The 33.3% figure is the gross margin, which divides by the selling price."},{"id":"ibc-056","sub":"Cost/Profit Relationships","diff":1,"q":"Fixed costs are $5,000, and variable cost is $8 per unit. What is total cost of producing 1,000 units?","choices":["$8,000","$5,008","$40,000","$13,000"],"answer":3,"explain":"Total cost = fixed costs + (variable cost per unit x units) = $5,000 + $8,000 = $13,000."},{"id":"ibc-057","sub":"Cost/Profit Relationships","diff":3,"q":"A product sells for $30 and has variable cost of $18 per unit. What is its contribution margin per unit?","choices":["$12 per unit","$30 per unit","$18 per unit","$48 per unit"],"answer":0,"explain":"Contribution margin is price minus variable cost per unit, here $30 - $18 = $12. It is the amount each sale contributes toward fixed costs."},{"id":"ibc-058","sub":"Cost/Profit Relationships","diff":2,"q":"Which term refers to total revenue minus all costs, including taxes and interest?","choices":["Gross profit","Net income","Operating income","Owner''s equity"],"answer":1,"explain":"Net income is the bottom line after every expense. Gross profit excludes operating costs, and operating income excludes interest and taxes."},{"id":"ibc-059","sub":"Cost/Profit Relationships","diff":2,"q":"Marginal cost is best defined as:","choices":["The average cost across all units produced","Total fixed cost divided by output","The additional cost of producing one more unit","The cost of the most recent inventory purchase"],"answer":2,"explain":"Marginal cost is the change in total cost from one more unit. Average cost spreads total cost over all units."},{"id":"ibc-060","sub":"Cost/Profit Relationships","diff":1,"q":"At the break-even point, a business''s:","choices":["Profit is at its maximum","Fixed costs are zero","Variable costs exceed revenue","Total revenue equals total cost"],"answer":3,"explain":"Break-even occurs where revenue covers all costs, so profit is zero. Fixed costs never fall to zero at this point."},{"id":"ibc-061","sub":"Cost/Profit Relationships","diff":2,"q":"Which costs are included in cost of goods sold for a manufacturer?","choices":["Direct materials, direct labor, and factory overhead","Sales commissions and advertising","Office rent and executive salaries","Interest on long-term debt"],"answer":0,"explain":"COGS covers costs of making the product sold. Selling, administrative, and financing costs are reported separately as operating or other expenses."},{"id":"ibc-062","sub":"Cost/Profit Relationships","diff":1,"q":"Which pricing strategy sets a low introductory price to gain market share quickly?","choices":["Skimming pricing","Penetration pricing","Psychological pricing","Premium pricing"],"answer":1,"explain":"Penetration pricing starts low to attract buyers and build share. Skimming starts high and lowers price over time."},{"id":"ibc-063","sub":"Cost/Profit Relationships","diff":2,"q":"As a firm increases output, its average cost per unit falls because of:","choices":["Diseconomies of scale","Diminishing marginal returns","Economies of scale","Price discrimination"],"answer":2,"explain":"Spreading fixed costs over more units and using efficient processes lowers average cost. Diseconomies raise it, and diminishing returns are a short-run production concept."},{"id":"ibc-064","sub":"Cost/Profit Relationships","diff":3,"q":"Operating expenses are $35,000 and gross profit is $80,000. What is operating income?","choices":["$115,000","$35,000","$80,000","$45,000"],"answer":3,"explain":"Operating income = gross profit - operating expenses = $80,000 - $35,000 = $45,000."},{"id":"ibc-065","sub":"Cost/Profit Relationships","diff":3,"q":"Fixed costs are $60,000 and the contribution margin ratio is 40%. What are break-even sales in dollars?","choices":["$150,000","$24,000","$100,000","$60,000"],"answer":0,"explain":"Break-even sales = fixed costs / contribution margin ratio = $60,000 / 0.40 = $150,000. Multiplying instead of dividing gives the $24,000 trap."},{"id":"ibc-066","sub":"Cost/Profit Relationships","diff":2,"q":"Which change would LOWER a firm''s break-even point in units?","choices":["An increase in fixed costs","A higher selling price with costs unchanged","An increase in variable cost per unit","A decrease in selling price"],"answer":1,"explain":"A higher price raises the contribution margin per unit, so fewer units are needed to cover fixed costs. The other options raise the break-even point."},{"id":"ibc-067","sub":"Owning a Business","diff":2,"q":"What is a key disadvantage of raising money through equity rather than debt?","choices":["The business must make fixed loan payments","Lenders can claim business assets if payments are missed","Owners give up part of the ownership and future profits","Interest payments reduce taxable income"],"answer":2,"explain":"Equity investors share ownership and profits, which dilutes the owner''s control. The other options describe disadvantages of debt."},{"id":"ibc-068","sub":"Owning a Business","diff":1,"q":"Which equation is the basic accounting equation?","choices":["Revenue - Expenses = Assets","Assets + Liabilities = Equity","Equity = Revenue + Expenses","Assets = Liabilities + Owner''s equity"],"answer":3,"explain":"The accounting equation states that a company''s assets are financed by liabilities and owner''s equity. The other forms are incorrect."},{"id":"ibc-069","sub":"Owning a Business","diff":1,"q":"Which financial statement reports revenues and expenses over a period of time?","choices":["Income statement","Balance sheet","Trial balance","Statement of owner''s equity"],"answer":0,"explain":"The income statement summarizes performance over a period. The balance sheet is a snapshot at one date."},{"id":"ibc-070","sub":"Owning a Business","diff":2,"q":"A business is profitable on paper but runs out of money and fails. What is the most likely cause?","choices":["A high stock price","Poor cash flow","Excessive liquidity","A low debt-to-equity ratio"],"answer":1,"explain":"Profit is an accounting measure, and cash flow is the timing of actual money. A profitable firm can still fail if cash runs out."},{"id":"ibc-071","sub":"Owning a Business","diff":2,"q":"What does the U.S. Small Business Administration (SBA) typically do for small business loans?","choices":["Lends directly to all small businesses at zero interest","Buys shares in small businesses on the public market","Guarantees a portion of loans made by approved lenders","Sets interest rates on all commercial loans"],"answer":2,"explain":"SBA loan programs reduce lender risk by guaranteeing part of a loan made by a bank. The SBA is not the direct lender in most programs."},{"id":"ibc-072","sub":"Owning a Business","diff":2,"q":"Which description best fits an angel investor?","choices":["A bank that offers government-backed loans","A firm pooling money to buy shares of mature public companies","A government agency that provides grants","An individual who invests personal funds in early-stage businesses"],"answer":3,"explain":"Angel investors are individuals funding young companies, often in exchange for equity. The other options describe lenders or public market investors."},{"id":"ibc-073","sub":"Owning a Business","diff":1,"q":"The primary purpose of a business plan is to:","choices":["Guide the business and communicate its strategy and financial projections","Meet legal requirements for incorporation","Report past taxes to the government","Replace the need for an accounting system"],"answer":0,"explain":"A business plan is a planning and communication tool for owners, lenders, and investors. It does not replace accounting or legal filings."},{"id":"ibc-074","sub":"Owning a Business","diff":2,"q":"Which insurance covers claims that a customer was injured by the business''s product?","choices":["Business interruption insurance","Product liability insurance","Key person insurance","Workers'' compensation insurance"],"answer":1,"explain":"Product liability insurance covers claims from product-related injuries. The others cover lost income, a key employee''s loss, or employee injuries."},{"id":"ibc-075","sub":"Owning a Business","diff":3,"q":"A company has current assets of $180,000 and current liabilities of $90,000. What is its current ratio?","choices":["0.5 to 1","1.5 to 1","2.0 to 1","2.5 to 1"],"answer":2,"explain":"The current ratio is current assets divided by current liabilities, so $180,000 / $90,000 = 2.0. Inverting the ratio gives 0.5 to 1."},{"id":"ibc-076","sub":"Owning a Business","diff":1,"q":"Working capital is calculated as:","choices":["Total assets minus total liabilities","Total revenue minus cost of goods sold","Long-term debt plus owner''s equity","Current assets minus current liabilities"],"answer":3,"explain":"Working capital measures short-term liquidity. Total assets minus total liabilities is net worth, and the other options are different measures."},{"id":"ibc-077","sub":"Owning a Business","diff":2,"q":"A small business needs $25,000 for equipment to be repaid over five years. Which financing is most appropriate?","choices":["A term loan","A line of credit for daily expenses","Issuing common stock in an initial public offering","A 30-day trade credit arrangement"],"answer":0,"explain":"A term loan provides a lump sum repaid on a fixed schedule, which matches a long-term asset. Lines of credit and trade credit suit short-term needs."},{"id":"ibc-078","sub":"Owning a Business","diff":3,"q":"A company buys equipment for $50,000 with a five-year life and no salvage value, using straight-line depreciation. What is the annual depreciation expense?","choices":["$12,500","$10,000","$5,000","$50,000"],"answer":1,"explain":"Straight-line depreciation spreads the cost evenly: $50,000 / 5 = $10,000 per year."},{"id":"ibc-079","sub":"Owning a Business","diff":2,"q":"Which is the best description of a business line of credit?","choices":["A fixed loan repaid in equal installments over ten years","An investment in exchange for an ownership stake","A revolving loan up to a set limit, borrowed and repaid as needed","A grant that never has to be repaid"],"answer":2,"explain":"A line of credit lets the business draw and repay within a limit, which suits fluctuating cash needs. Fixed installment loans and equity investments work differently."},{"id":"ibc-080","sub":"Owning a Business","diff":2,"q":"Which metric shows how much of a company''s financing comes from creditors relative to owners?","choices":["Current ratio","Gross margin","Return on assets","Debt-to-equity ratio"],"answer":3,"explain":"Debt-to-equity compares total liabilities to owner''s equity. The other ratios measure liquidity, profitability, or efficiency."},{"id":"ibc-081","sub":"Types of Business Activities","diff":1,"q":"A farm that grows wheat is part of which sector of the economy?","choices":["Primary sector","Secondary sector","Tertiary sector","Quaternary sector"],"answer":0,"explain":"The primary sector extracts or grows natural resources, such as farming, mining, and fishing."},{"id":"ibc-082","sub":"Types of Business Activities","diff":1,"q":"A factory that assembles cars is classified in which sector?","choices":["Primary sector","Secondary sector","Tertiary sector","Quaternary sector"],"answer":1,"explain":"The secondary sector transforms raw materials into finished goods through manufacturing."},{"id":"ibc-083","sub":"Types of Business Activities","diff":2,"q":"A bank that makes loans to customers is part of which sector?","choices":["Primary sector","Secondary sector","Tertiary sector","Quaternary sector"],"answer":2,"explain":"The tertiary sector provides services. Banking, retail, and transportation all fall here."},{"id":"ibc-084","sub":"Types of Business Activities","diff":2,"q":"A business buys goods in bulk from manufacturers and sells them to retailers. It is a:","choices":["Retailer","Franchisor","Exporter","Wholesaler"],"answer":3,"explain":"Wholesalers sell to businesses rather than final consumers. Retailers sell directly to consumers."},{"id":"ibc-085","sub":"Types of Business Activities","diff":2,"q":"A software company sells accounting software to other businesses. Its activity is primarily:","choices":["Business-to-business (B2B)","Business-to-consumer (B2C)","Consumer-to-consumer (C2C)","Government-to-business (G2B)"],"answer":0,"explain":"B2B means selling to other businesses. B2C is selling to individual consumers."},{"id":"ibc-086","sub":"Types of Business Activities","diff":2,"q":"Which description best defines e-commerce?","choices":["Offline sales of goods in physical stores","Buying and selling goods or services over the internet","Digital advertising without any sales","Online-only charitable donations"],"answer":1,"explain":"E-commerce is any commercial transaction conducted electronically. It does not require a physical store."},{"id":"ibc-087","sub":"Types of Business Activities","diff":2,"q":"What defines a nonprofit organization?","choices":["It is not allowed to earn any revenue","It is owned by shareholders who receive dividends","It reinvests surplus revenue into its mission instead of paying profits to owners","It is automatically exempt from all taxes"],"answer":2,"explain":"Nonprofits can earn revenue but cannot distribute profits to owners. Tax-exempt status must be applied for and is not automatic."},{"id":"ibc-088","sub":"Types of Business Activities","diff":2,"q":"Members of a cooperative are typically:","choices":["Employees paid fixed wages only","Outside investors with no voting rights","Government appointees who run the business","Owners who share in the business''s profits or benefits"],"answer":3,"explain":"Cooperatives are owned and governed by their members, who share in the benefits. The other options describe other structures."},{"id":"ibc-089","sub":"Types of Business Activities","diff":2,"q":"Which of the following is a pure service business?","choices":["A tax preparation firm","A steel mill","A corn farm","A shoe factory"],"answer":0,"explain":"A pure service business sells expertise or labor rather than physical goods. The others are primary or secondary producers."},{"id":"ibc-090","sub":"Types of Business Activities","diff":2,"q":"What does a franchisor typically earn from its franchise system?","choices":["Profit from reselling inventory to franchisees at cost","Royalties and franchise fees paid by franchisees","Full sales revenue from every outlet it owns","Membership charges paid directly by customers"],"answer":1,"explain":"Franchisors earn ongoing royalties and initial fees rather than the sales of each outlet. The other options describe models the franchisor does not usually use."},{"id":"ibc-091","sub":"Career Planning","diff":2,"q":"Which section of a resume lists relevant work history, usually in reverse chronological order?","choices":["Objective statement","References","Professional experience","Hobbies"],"answer":2,"explain":"Professional experience shows what the candidate has done, with the most recent job first. References are listed separately."},{"id":"ibc-092","sub":"Career Planning","diff":2,"q":"What is the main purpose of a cover letter?","choices":["To list every duty from your past roles","To provide a complete record of your education","To request a salary before the interview","To introduce yourself and explain your fit for a specific job"],"answer":3,"explain":"A cover letter tailors the application to one role and highlights the most relevant qualifications. It does not repeat the resume."},{"id":"ibc-093","sub":"Career Planning","diff":2,"q":"Which is an example of professional networking?","choices":["Connecting with an alumnus in your field to ask for an informational interview","Posting personal photos on social media for employers to see","Asking a classmate to write a fake reference","Sending unsolicited mass emails to every company in a state"],"answer":0,"explain":"Networking builds relationships for career information and opportunities. Fabricated references and mass unsolicited emails are not effective or ethical networking."},{"id":"ibc-094","sub":"Career Planning","diff":2,"q":"What should come FIRST when creating a career plan?","choices":["Applying to every posted job","Assessing your interests, skills, and values","Accepting the first offer you receive","Memorizing answers to common interview questions"],"answer":1,"explain":"Self-assessment comes first, because goals and job targets depend on interests, skills, and values. The other steps come later."},{"id":"ibc-095","sub":"Career Planning","diff":2,"q":"Which characteristic makes a career goal a SMART goal?","choices":["Vague but ambitious","Based only on salary","Specific, measurable, achievable, relevant, and time-bound","Set once and never revised"],"answer":2,"explain":"SMART goals are specific, measurable, achievable, relevant, and time-bound, which makes progress trackable. The other options do not match the acronym."},{"id":"ibc-096","sub":"Job-Search Skills","diff":2,"q":"In the STAR interview method, what does the letter ''A'' stand for?","choices":["Answer","Attitude","Achievement","Action"],"answer":3,"explain":"STAR stands for Situation, Task, Action, and Result. Candidates describe what they did, then the outcome."},{"id":"ibc-097","sub":"Job-Search Skills","diff":2,"q":"How soon after an interview should a candidate typically send a thank-you note?","choices":["Within 24 hours","Within one month","Only if the employer asks for one","Before the interview takes place"],"answer":0,"explain":"A prompt thank-you note, usually within 24 hours, reinforces interest. Waiting a month or sending it beforehand is ineffective."},{"id":"ibc-098","sub":"Job-Search Skills","diff":2,"q":"When listing references on a job application, what should you do first?","choices":["List only family members","Ask each person''s permission before listing them","Include home addresses for every reference","Submit a new list only after the employer asks for one"],"answer":1,"explain":"Asking permission ensures references are willing and prepared to speak. Listing people without asking can harm the application."},{"id":"ibc-099","sub":"Job-Search Skills","diff":2,"q":"Why do many employers use applicant tracking systems (ATS) to screen resumes?","choices":["To verify applicants'' social security numbers","To rank applicants by age","To scan for keywords that match the job description","To eliminate any resume without a photo"],"answer":2,"explain":"An ATS filters resumes by matching keywords from the job posting, so tailoring resumes to the description matters. It does not check identity or age."},{"id":"ibc-100","sub":"Job-Search Skills","diff":2,"q":"Which element of a job posting describes the duties and expectations of the role?","choices":["Company logo","Application deadline","Job title","Job description"],"answer":3,"explain":"The job description lists responsibilities and expectations. The title names the role, but it does not describe duties in detail."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'marketing', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"mkt-001","sub":"Marketing Fundamentals","diff":2,"q":"Which element of the marketing mix is most directly concerned with the amount a customer pays for a product?","choices":["Price","Place","Promotion","Product"],"answer":0,"explain":"Price is the mix variable that sets the amount a customer pays. Place covers distribution, not cost."},{"id":"mkt-002","sub":"Marketing Fundamentals","diff":2,"q":"A company splits a city''s coffee drinkers into groups by age, income, and lifestyle, then chooses which groups to serve. Dividing the total market into groups with shared needs is called:","choices":["Positioning","Market segmentation","Mass marketing","Test marketing"],"answer":1,"explain":"Segmentation divides the market; targeting is the later choice of which segments to serve."},{"id":"mkt-003","sub":"Marketing Fundamentals","diff":2,"q":"Which statement best reflects the marketing concept?","choices":["Maximize production volume regardless of demand","Sell whatever inventory the firm already holds","Satisfy customer needs in a way that also earns a profit","Minimize advertising spending to protect margins"],"answer":2,"explain":"The marketing concept treats customer needs as the route to profit."},{"id":"mkt-004","sub":"Marketing Fundamentals","diff":3,"q":"A manufacturer cuts unit costs and makes more units, assuming buyers will purchase whatever it produces. This reflects which business orientation?","choices":["Marketing orientation","Societal orientation","Selling orientation","Production orientation"],"answer":3,"explain":"A production orientation focuses on efficiency and volume. Selling orientation pushes existing goods and is the near-miss trap."},{"id":"mkt-005","sub":"Marketing Fundamentals","diff":2,"q":"Services are often marketed with samples, testimonials, and tangible cues because services have which characteristic?","choices":["Intangibility","Perishability","Inseparability","Heterogeneity"],"answer":0,"explain":"Intangibility means a service cannot be inspected before purchase, so marketers add tangible cues."},{"id":"mkt-006","sub":"Marketing Fundamentals","diff":2,"q":"A firm sells one product with one message to the entire market. This approach is best called:","choices":["Niche marketing","Undifferentiated (mass) marketing","Micromarketing","Relationship marketing"],"answer":1,"explain":"Undifferentiated marketing treats the whole market as one segment."},{"id":"mkt-007","sub":"Marketing Fundamentals","diff":2,"q":"Brand equity refers to:","choices":["The cost of registering a trademark","The total revenue from licensing a logo","The added value a brand name gives a product beyond its functional features","The number of retail stores that carry a brand"],"answer":2,"explain":"Brand equity is the value a name adds, such as trust and recognition, beyond what the product does."},{"id":"mkt-008","sub":"Marketing Fundamentals","diff":2,"q":"Which of the following is a need rather than a want?","choices":["A red leather handbag","A sports car","A premium coffee","Food to relieve hunger"],"answer":3,"explain":"Needs are basic requirements; wants are specific ways of meeting needs."},{"id":"mkt-009","sub":"Marketing Fundamentals","diff":2,"q":"Maya realizes she needs a new laptop for school. Which stage of the consumer decision process comes first?","choices":["Problem recognition","Information search","Evaluation of alternatives","Post-purchase evaluation"],"answer":0,"explain":"The process starts when the buyer recognizes a gap between the current and desired state."},{"id":"mkt-010","sub":"Marketing Fundamentals","diff":2,"q":"Which business buyer purchases goods to resell without significant change?","choices":["Industrial user","Reseller","Government agency","Institutional buyer"],"answer":1,"explain":"Resellers are wholesalers and retailers that buy for resale. Industrial users buy for use in production."},{"id":"mkt-011","sub":"Marketing Fundamentals","diff":3,"q":"A company drops a profitable product that harms the environment, weighing long-term community well-being alongside profit. Which concept does this reflect?","choices":["Selling concept","Production concept","Societal marketing concept","Transactional concept"],"answer":2,"explain":"The societal marketing concept balances customer wants, company profit, and public welfare."},{"id":"mkt-012","sub":"Marketing Fundamentals","diff":3,"q":"Why should a firm evaluate customer lifetime value rather than the profit from one sale?","choices":["Single sales are always less profitable than repeat sales in every industry","Lifetime value measures inventory turnover","Lifetime value matters only for nonprofit organizations","Lifetime value captures expected profit across the whole relationship, guiding how much to spend on acquisition and retention"],"answer":3,"explain":"CLV estimates total future profit from a customer and informs acquisition and retention budgets."},{"id":"mkt-013","sub":"Marketing Fundamentals","diff":2,"q":"Which statement best distinguishes a marketing strategy from a marketing tactic?","choices":["A strategy is the long-range plan for reaching goals; a tactic is a specific action used to carry it out","A strategy is a short-term promotional offer; a tactic is a multi-year plan","A strategy is set by sales staff; a tactic is set by finance","The two terms mean the same thing"],"answer":0,"explain":"Strategy is the overall plan; tactics are the specific actions that execute it."},{"id":"mkt-014","sub":"Market Planning","diff":2,"q":"A firm''s SWOT analysis notes a strong brand reputation. Where does this belong?","choices":["Opportunities","Strengths","Threats","Weaknesses"],"answer":1,"explain":"A brand reputation is an internal advantage, so it is a strength."},{"id":"mkt-015","sub":"Market Planning","diff":1,"q":"A competitor announces it will leave the market, and the firm expects demand to shift toward it. In a SWOT, this is best classified as a(n):","choices":["Strength","Weakness","Opportunity","Threat"],"answer":2,"explain":"An external factor that favors the firm is an opportunity."},{"id":"mkt-016","sub":"Market Planning","diff":1,"q":"A plan states the firm will raise market share by 3 points within 12 months. This statement is a(n):","choices":["Mission statement","Situation analysis","Tactic","Objective"],"answer":3,"explain":"An objective is a measurable target with a time frame."},{"id":"mkt-017","sub":"Market Planning","diff":2,"q":"Which goal best follows the SMART criteria?","choices":["Increase online orders by 15% by June 30","Improve customer happiness","Be the best coffee shop in town","Grow when the market allows"],"answer":0,"explain":"SMART goals are specific, measurable, achievable, relevant, and time-bound."},{"id":"mkt-018","sub":"Market Planning","diff":2,"q":"Market share is calculated as:","choices":["Total industry sales divided by company sales","Company sales divided by total industry sales for the same period","Company profit divided by company sales","Company sales minus industry sales"],"answer":1,"explain":"Market share is the firm''s portion of total industry sales."},{"id":"mkt-019","sub":"Market Planning","diff":3,"q":"A firm holds 12% market share in an industry with $50 million in total sales. What are the firm''s sales?","choices":["$4 million","$5.5 million","$6 million","$12 million"],"answer":2,"explain":"0.12 x $50 million = $6 million."},{"id":"mkt-020","sub":"Market Planning","diff":2,"q":"Which tool plots products by market share and market growth rate?","choices":["Gantt chart","Break-even chart","Perceptual map","BCG growth-share matrix"],"answer":3,"explain":"The BCG matrix classifies products as stars, cash cows, question marks, or dogs."},{"id":"mkt-021","sub":"Market Planning","diff":2,"q":"A product has high market share in a slow-growing market. Under the BCG matrix, it is a:","choices":["Cash cow","Star","Question mark","Dog"],"answer":0,"explain":"High share and low growth define a cash cow."},{"id":"mkt-022","sub":"Market Planning","diff":2,"q":"A firm sells its existing product to new customers in a new region. Under the Ansoff matrix, this is:","choices":["Market penetration","Market development","Product development","Diversification"],"answer":1,"explain":"Market development applies existing products to new markets."},{"id":"mkt-023","sub":"Market Planning","diff":2,"q":"A firm lowers prices to sell more of its current product to its current customers. This Ansoff strategy is:","choices":["Diversification","Market development","Market penetration","Product development"],"answer":2,"explain":"Market penetration grows existing products in existing markets."},{"id":"mkt-024","sub":"Market Planning","diff":3,"q":"A firm pursues low costs but only within one narrow customer segment. Which of Porter''s generic strategies is this?","choices":["Broad differentiation","Broad cost leadership","Vertical integration","Focused cost strategy"],"answer":3,"explain":"Porter''s focus strategy targets a narrow segment. Pairing it with low cost makes it a focused cost strategy."},{"id":"mkt-025","sub":"Market Planning","diff":2,"q":"A firm sets its marketing budget as a fixed percentage of forecast sales. This is the:","choices":["Percentage-of-sales method","Objective-and-task method","Competitive parity method","All-you-can-afford method"],"answer":0,"explain":"The percentage-of-sales method ties the budget to sales, so it can shrink when sales fall."},{"id":"mkt-026","sub":"Market Planning","diff":1,"q":"In which product life cycle stage do sales growth slow and competition intensify, pushing firms to differentiate?","choices":["Introduction","Maturity","Growth","Decline"],"answer":1,"explain":"Maturity is when growth flattens and competition is strongest."},{"id":"mkt-027","sub":"Market Planning","diff":3,"q":"In a PESTEL analysis, a new federal rule restricting how sugar content can be labeled falls under which factor?","choices":["Economic","Social","Political-legal","Technological"],"answer":2,"explain":"A regulation is a political-legal factor."},{"id":"mkt-028","sub":"Marketing-Information Management","diff":1,"q":"Data that already exists from another source, such as census figures, is called:","choices":["Primary research","Experimental research","Focus group research","Secondary research"],"answer":3,"explain":"Secondary data was collected for another purpose. Primary data is gathered firsthand."},{"id":"mkt-029","sub":"Marketing-Information Management","diff":1,"q":"A company surveys 500 customers with a standardized questionnaire to measure satisfaction numerically. This is:","choices":["Quantitative primary research","Qualitative primary research","Secondary research","Ethnographic research"],"answer":0,"explain":"Standardized, numerical, firsthand survey data is quantitative primary research."},{"id":"mkt-030","sub":"Marketing-Information Management","diff":1,"q":"A moderator leads eight consumers through an open discussion of a new snack. This is a:","choices":["Consumer panel","Focus group","Mystery shop","Test market"],"answer":1,"explain":"A focus group is a small moderated discussion aimed at qualitative insight."},{"id":"mkt-031","sub":"Marketing-Information Management","diff":2,"q":"Which sampling method gives every member of the population an equal chance of selection?","choices":["Quota sampling","Convenience sampling","Simple random sampling","Judgment sampling"],"answer":2,"explain":"Simple random sampling gives each member an equal probability of selection."},{"id":"mkt-032","sub":"Marketing-Information Management","diff":2,"q":"A marketer compares sales at two stores, one with a new display and one without, holding other factors constant. This is:","choices":["A focus group","A Delphi study","An observational audit","A controlled experiment"],"answer":3,"explain":"Changing one variable against a comparison group while controlling the rest is an experiment."},{"id":"mkt-033","sub":"Marketing-Information Management","diff":2,"q":"An online retailer analyzes purchase histories to predict what customers will buy next. This is best described as:","choices":["Data mining for customer patterns","Competitive benchmarking","Price elasticity testing","Channel audit"],"answer":0,"explain":"Data mining finds patterns in large databases to support predictions."},{"id":"mkt-034","sub":"Marketing-Information Management","diff":2,"q":"A survey gives the same results when repeated under the same conditions. This describes which research quality?","choices":["Validity","Reliability","Representativeness","Relevance"],"answer":1,"explain":"Reliability means consistent results across repeated measurements."},{"id":"mkt-035","sub":"Marketing-Information Management","diff":3,"q":"A survey asks, ''Don''t you agree our fresh menu is far better than competitors?'' Which problem most affects the results?","choices":["Sampling frame error","Nonresponse error","Leading question bias","Recall error"],"answer":2,"explain":"The wording pushes respondents toward one answer, which is leading question bias."},{"id":"mkt-036","sub":"Marketing-Information Management","diff":3,"q":"A firm must choose between a $500 secondary-data review and a $25,000 primary survey. Which factor best supports starting with secondary research?","choices":["Secondary data is always more accurate","Secondary data cannot inform decisions","Primary data is never needed","Secondary data is cheaper and faster for a first look at the problem"],"answer":3,"explain":"Secondary research is a low-cost first step. It does not replace primary research when the question needs firsthand data."},{"id":"mkt-037","sub":"Marketing-Information Management","diff":1,"q":"Which metric asks customers how likely they are to recommend a brand?","choices":["Net Promoter Score","Customer lifetime value","Gross margin return","Customer acquisition cost"],"answer":0,"explain":"Net Promoter Score is built on a likelihood-to-recommend question."},{"id":"mkt-038","sub":"Marketing-Information Management","diff":3,"q":"A marketing team wants to know whether a new ad caused awareness to rise. Which design best isolates the ad''s effect?","choices":["Annual report review","Pre- and post-campaign awareness survey with a comparison group not exposed to the ad","Balance sheet analysis","Break-even chart"],"answer":1,"explain":"Comparing before and after, against a group that did not see the ad, isolates the campaign''s effect."},{"id":"mkt-039","sub":"Product/Service Management","diff":1,"q":"Brand positioning is best defined as:","choices":["The legal registration of a brand name","The number of licenses a firm holds on its brand","The place a brand holds in customers'' minds relative to competitors","The cost of a brand''s advertising"],"answer":2,"explain":"Positioning is the perceived place of a brand relative to rivals."},{"id":"mkt-040","sub":"Product/Service Management","diff":1,"q":"A product''s core benefit is best described as:","choices":["Its packaging design","Its warranty terms","Its brand name","The fundamental need the product satisfies"],"answer":3,"explain":"The core benefit is the problem the product solves for the buyer."},{"id":"mkt-041","sub":"Product/Service Management","diff":3,"q":"A company sells a basic phone and a premium phone, built on the same platform and sold as one family of related models. This is best described as:","choices":["Product line management","Product mix pruning","Co-branding","Vertical integration"],"answer":0,"explain":"A product line is a group of related products; managing the lines within the mix is product line management."},{"id":"mkt-042","sub":"Product/Service Management","diff":2,"q":"In new product development, which stage tests the product idea with target customers before full development?","choices":["Idea generation","Concept testing","Commercialization","Business analysis"],"answer":1,"explain":"Concept testing gauges target customers'' reaction to the idea."},{"id":"mkt-043","sub":"Product/Service Management","diff":2,"q":"A sportswear brand uses its name on a new line of kitchen appliances. This is a:","choices":["Line extension","Repositioning","Brand extension","Private label"],"answer":2,"explain":"Brand extension uses an established name in a different product category."},{"id":"mkt-044","sub":"Product/Service Management","diff":1,"q":"A soup company adds a new flavor to its existing soup line. This is a:","choices":["Brand extension","Repositioning","Diversification","Line extension"],"answer":3,"explain":"A line extension adds items within the same category."},{"id":"mkt-045","sub":"Product/Service Management","diff":1,"q":"The sequence of introduction, growth, maturity, and decline describes the:","choices":["Product life cycle","Buyer decision process","Diffusion curve","Marketing mix"],"answer":0,"explain":"Those four stages make up the product life cycle."},{"id":"mkt-046","sub":"Product/Service Management","diff":2,"q":"In the diffusion of innovations, which adopter group tries new products first?","choices":["Late majority","Innovators","Laggards","Early majority"],"answer":1,"explain":"Innovators are the first group to adopt a new product."},{"id":"mkt-047","sub":"Product/Service Management","diff":3,"q":"A firm drops a product with falling sales, high costs, and a negative contribution margin. This is:","choices":["Harvesting","Penetration","Pruning","Repositioning"],"answer":2,"explain":"Pruning removes weak products from the product mix."},{"id":"mkt-048","sub":"Product/Service Management","diff":1,"q":"Which is a benefit of a consistent brand identity?","choices":["It eliminates the need for quality control","It lowers the price customers will pay","It replaces market research","It makes a brand easier to recognize and recall"],"answer":3,"explain":"Consistency builds recognition and recall."},{"id":"mkt-049","sub":"Product/Service Management","diff":1,"q":"Which packaging function is mainly about keeping the product safe while it is shipped and stored?","choices":["Protection","Promotion","Positioning","Pricing"],"answer":0,"explain":"Protection is the packaging function for transport and storage."},{"id":"mkt-050","sub":"Product/Service Management","diff":3,"q":"In the United States, which legal instrument primarily protects a brand''s name, logo, and tagline?","choices":["Patent","Trademark","Copyright","Trade secret"],"answer":1,"explain":"Trademarks protect brand identifiers. Patents cover inventions and copyrights cover creative works."},{"id":"mkt-051","sub":"Channel Management","diff":1,"q":"Intermediaries that take title to goods and resell them to retailers are called:","choices":["Agents","Brokers","Wholesalers","Facilitators"],"answer":2,"explain":"Wholesalers take title and resell, typically to retailers or business users."},{"id":"mkt-052","sub":"Channel Management","diff":1,"q":"A manufacturer sells directly to consumers through its own website. This is a:","choices":["Indirect channel with one intermediary","Reverse channel","Dual channel with wholesalers","Direct channel"],"answer":3,"explain":"No intermediaries are used, so it is a direct channel."},{"id":"mkt-053","sub":"Channel Management","diff":1,"q":"Intensive distribution means the product is sold in:","choices":["As many outlets as possible","One exclusive store per region","A selected few outlets","Only company-owned stores"],"answer":0,"explain":"Intensive distribution maximizes outlets, which suits convenience goods."},{"id":"mkt-054","sub":"Channel Management","diff":3,"q":"A luxury watch brand grants one authorized jeweler sole rights to sell its watches in each city. Which distribution strategy is this?","choices":["Intensive","Exclusive","Mass","Selective"],"answer":1,"explain":"Exclusive distribution gives a limited number of dealers sole rights in a territory."},{"id":"mkt-055","sub":"Channel Management","diff":3,"q":"A manufacturer sells directly online at prices below its retail partners, causing friction with them. This is:","choices":["Horizontal conflict","Supplier conflict over raw material costs","Multichannel conflict","Lateral conflict"],"answer":2,"explain":"Multichannel conflict arises when a producer''s direct channel competes with its existing channels."},{"id":"mkt-056","sub":"Channel Management","diff":3,"q":"Which statement correctly distinguishes an agent from a broker?","choices":["An agent takes title to goods; a broker does not","Both take title to goods","Brokers work only for manufacturers","An agent represents a buyer or seller on an ongoing basis without taking title; a broker brings parties together for a transaction"],"answer":3,"explain":"Agents usually hold ongoing representation without taking title; brokers match parties for a transaction."},{"id":"mkt-057","sub":"Channel Management","diff":1,"q":"Which channel function means a retailer holds goods so they are available when customers want them?","choices":["Storage and inventory holding","Sorting","Financing","Risk taking"],"answer":0,"explain":"Storage and inventory holding keeps goods on hand for customers."},{"id":"mkt-058","sub":"Channel Management","diff":3,"q":"A firm removes an intermediary and sells straight to customers. This is called:","choices":["Reintermediation","Disintermediation","Franchising","Backward integration"],"answer":1,"explain":"Disintermediation removes middlemen from a channel."},{"id":"mkt-059","sub":"Channel Management","diff":3,"q":"A company''s outlets are run by independent operators under a contract that sets the business model. This is a:","choices":["Corporate vertical marketing system","Administered vertical marketing system","Contractual vertical marketing system","Horizontal marketing system"],"answer":2,"explain":"A franchise is a contractual vertical marketing system."},{"id":"mkt-060","sub":"Channel Management","diff":3,"q":"A retailer''s inventory turnover ratio is calculated as:","choices":["Average inventory divided by cost of goods sold","Gross profit divided by net sales","Inventory divided by total assets","Cost of goods sold divided by average inventory"],"answer":3,"explain":"Turnover uses cost of goods sold over average inventory at cost."},{"id":"mkt-061","sub":"Channel Management","diff":2,"q":"Which is a benefit of using a wholesaler?","choices":["It reduces the number of contacts a manufacturer must make with retailers","It eliminates all transportation costs","It guarantees the manufacturer full control over retail prices","It removes the need for promotion"],"answer":0,"explain":"Wholesalers consolidate contacts and distribution work for the manufacturer."},{"id":"mkt-062","sub":"Pricing","diff":1,"q":"A firm sets price by adding a fixed percentage to its unit cost. This is:","choices":["Penetration pricing","Cost-plus pricing","Going-rate pricing","Skimming pricing"],"answer":1,"explain":"Cost-plus pricing adds a markup to cost."},{"id":"mkt-063","sub":"Pricing","diff":1,"q":"A new high-tech product launches at a high price, which is lowered over time. This describes:","choices":["Penetration pricing","Loss-leader pricing","Price skimming","Odd-even pricing"],"answer":2,"explain":"Skimming starts high and steps down to reach successive groups of buyers."},{"id":"mkt-064","sub":"Pricing","diff":3,"q":"A product costs $20 per unit, and the firm applies a 25% markup on cost. What is the selling price?","choices":["$22.50","$24.00","$30.00","$25.00"],"answer":3,"explain":"0.25 x $20 = $5; $20 + $5 = $25."},{"id":"mkt-065","sub":"Pricing","diff":3,"q":"A retailer sells an item for $80 that cost $48. What is the gross margin percentage based on selling price?","choices":["40%","60%","67%","32%"],"answer":0,"explain":"($80 - $48) / $80 = 40%."},{"id":"mkt-066","sub":"Pricing","diff":3,"q":"Fixed costs are $12,000 per month. Price is $30 and variable cost is $18 per unit. How many units break even?","choices":["400 units","1,000 units","600 units","2,000 units"],"answer":1,"explain":"$12,000 / ($30 - $18) = 1,000 units."},{"id":"mkt-067","sub":"Pricing","diff":1,"q":"Which approach sets a low introductory price to gain market share quickly?","choices":["Price skimming","Prestige pricing","Penetration pricing","Target-return pricing"],"answer":2,"explain":"Penetration pricing starts low to win share."},{"id":"mkt-068","sub":"Pricing","diff":1,"q":"Prices such as $9.99 are an example of:","choices":["Bundle pricing","Customary pricing","Dynamic pricing","Odd-even pricing"],"answer":3,"explain":"Odd-even pricing uses prices ending in odd numbers to appear lower."},{"id":"mkt-069","sub":"Pricing","diff":3,"q":"If demand for a product is elastic, a 10% price increase will most likely cause:","choices":["Quantity demanded to fall by more than 10%","Quantity demanded to rise","Quantity demanded to fall by less than 10%","No change in quantity demanded"],"answer":0,"explain":"Elastic demand means quantity falls by a larger percentage than price rises."},{"id":"mkt-070","sub":"Pricing","diff":2,"q":"A retailer discounts a printer and earns profit on the ink cartridges buyers must purchase. This is:","choices":["Going-rate pricing","Captive product pricing","Price bundling","Price lining"],"answer":1,"explain":"Captive product pricing discounts the base product and earns on required supplies."},{"id":"mkt-071","sub":"Pricing","diff":1,"q":"A business sets its price at the level competitors charge for similar products. This is:","choices":["Customary pricing","Prestige pricing","Going-rate pricing","Value-based pricing"],"answer":2,"explain":"Going-rate pricing follows the prevailing market rate."},{"id":"mkt-072","sub":"Pricing","diff":2,"q":"What is the main risk of relying on cost-based pricing alone?","choices":["It always produces a loss","It cannot be used by manufacturers","It requires no cost data","It ignores customer demand and the value customers perceive"],"answer":3,"explain":"Cost-based pricing can misprice when demand and perceived value differ from cost."},{"id":"mkt-073","sub":"Pricing","diff":3,"q":"A product sells for $40 with a variable cost of $25 per unit. What is its contribution margin per unit?","choices":["$15","$40","$25","$65"],"answer":0,"explain":"$40 - $25 = $15 per unit toward fixed costs."},{"id":"mkt-074","sub":"Pricing","diff":2,"q":"A firm offers a product in three versions at $19, $29, and $39. What is the main purpose of this price lining?","choices":["To raise prices across all products","To simplify choices across defined quality tiers","To eliminate competition","To avoid all discounts"],"answer":1,"explain":"Price lining sets clear tiers for the customer to choose from."},{"id":"mkt-075","sub":"Promotion","diff":1,"q":"Which promotional mix element is paid, nonpersonal communication from an identified sponsor?","choices":["Publicity","Personal selling","Advertising","Sales promotion"],"answer":2,"explain":"Advertising is paid and nonpersonal, with an identified sponsor."},{"id":"mkt-076","sub":"Promotion","diff":1,"q":"Free news coverage of a company''s new product is:","choices":["Advertising","Direct marketing","Sponsorship","Publicity"],"answer":3,"explain":"Publicity is unpaid media coverage."},{"id":"mkt-077","sub":"Promotion","diff":1,"q":"A coupon giving 20% off the next purchase is an example of:","choices":["Sales promotion","Publicity","Advertising","Public relations"],"answer":0,"explain":"Sales promotions are short-term incentives."},{"id":"mkt-078","sub":"Promotion","diff":2,"q":"In the AIDA model, which stage requires the ad to create a strong wish to own the product?","choices":["Attention","Desire","Interest","Action"],"answer":1,"explain":"Desire follows interest and builds the want to own."},{"id":"mkt-079","sub":"Promotion","diff":1,"q":"In the AIDA model, which stage aims to get the consumer to buy now?","choices":["Attention","Desire","Action","Interest"],"answer":2,"explain":"Action is the final stage."},{"id":"mkt-080","sub":"Promotion","diff":1,"q":"Which promotional mix element has a company''s salespeople presenting directly to buyers?","choices":["Advertising","Publicity","Sales promotion","Personal selling"],"answer":3,"explain":"Personal selling is two-way and direct."},{"id":"mkt-081","sub":"Promotion","diff":2,"q":"A brand decides to reach 18 to 24-year-olds through influencer posts on one platform. This choice is most directly a:","choices":["Media selection decision","Pricing decision","Channel decision","Product decision"],"answer":0,"explain":"Choosing the medium and vehicle to reach an audience is a media selection decision."},{"id":"mkt-082","sub":"Promotion","diff":2,"q":"An email offering loyalty rewards to customers who purchased in the past year is an example of:","choices":["Publicity","Direct marketing","Mass advertising","Public relations"],"answer":1,"explain":"Direct marketing targets known customers to prompt a response."},{"id":"mkt-083","sub":"Promotion","diff":2,"q":"A media plan says the average consumer will see an ad three times. This measure is:","choices":["Reach","Impressions","Frequency","Cost per thousand"],"answer":2,"explain":"Frequency counts repeated exposures per person."},{"id":"mkt-084","sub":"Promotion","diff":3,"q":"An ad campaign costs $12,000 and reaches 2,000,000 people. What is its cost per thousand (CPM)?","choices":["$12.00","$60.00","$0.006","$6.00"],"answer":3,"explain":"$12,000 / 2,000 thousand people = $6.00."},{"id":"mkt-085","sub":"Promotion","diff":1,"q":"A ''buy one, get one free'' offer is mainly used to:","choices":["Stimulate immediate sales or trial","Build long-term brand equity","Improve public image","Reduce production costs"],"answer":0,"explain":"Sales promotions drive short-term action."},{"id":"mkt-086","sub":"Promotion","diff":2,"q":"Which method best measures whether a campaign raised brand awareness?","choices":["Annual report review","Pre- and post-campaign awareness survey","Balance sheet analysis","Break-even chart"],"answer":1,"explain":"Comparing awareness before and after the campaign measures the change."},{"id":"mkt-087","sub":"Promotion","diff":1,"q":"Public relations primarily helps a firm by:","choices":["Guaranteeing sales volume","Setting product prices","Managing its image and relationships with stakeholders","Reducing shipping time"],"answer":2,"explain":"Public relations manages image and stakeholder relationships."},{"id":"mkt-088","sub":"Selling","diff":1,"q":"Identifying qualified potential customers is which selling step?","choices":["Closing","Demonstrating","Follow-up","Prospecting"],"answer":3,"explain":"Prospecting finds and qualifies leads."},{"id":"mkt-089","sub":"Selling","diff":1,"q":"A salesperson asks open-ended questions to learn needs before presenting. This is:","choices":["Needs assessment","Closing","Objection handling","Follow-up"],"answer":0,"explain":"Needs assessment uncovers the buyer''s problems."},{"id":"mkt-090","sub":"Selling","diff":2,"q":"A customer says, ''Your price is higher than a competitor''s.'' What is the best response?","choices":["Argue that the competitor''s product is worse","Acknowledge the concern and explain value and total cost of ownership","Lower the price immediately without discussion","Ignore the comment and continue the presentation"],"answer":1,"explain":"Acknowledge the concern, then reframe around value."},{"id":"mkt-091","sub":"Selling","diff":2,"q":"Which closing technique offers two options, both of which lead to a sale?","choices":["Assumptive close","Trial close","Alternative choice close","Summary close"],"answer":2,"explain":"The alternative choice close offers two acceptable paths to a sale."},{"id":"mkt-092","sub":"Selling","diff":1,"q":"A rep sends a thank-you note two days after a purchase. This is which step?","choices":["Prospecting","Approach","Closing","Follow-up"],"answer":3,"explain":"Follow-up supports retention after the sale."},{"id":"mkt-093","sub":"Selling","diff":1,"q":"Which selling approach aims at a long-term partnership rather than one transaction?","choices":["Relationship selling","Transactional selling","Hard sell","Scripted presentation"],"answer":0,"explain":"Relationship selling builds ongoing trust."},{"id":"mkt-094","sub":"Selling","diff":2,"q":"A rep''s commission rate rises once sales exceed a set level. This is a(n):","choices":["Straight salary","Accelerated commission plan","Salary-plus-commission plan","Draw against commission"],"answer":1,"explain":"Accelerated plans raise the commission rate above a threshold."},{"id":"mkt-095","sub":"Selling","diff":1,"q":"Which behavior is consultative selling?","choices":["Reading a scripted pitch word-for-word","Offering the same discount to every buyer","Asking diagnostic questions and tailoring the solution","Avoiding questions to save time"],"answer":2,"explain":"Consultative selling diagnoses needs before recommending."},{"id":"mkt-096","sub":"Selling","diff":2,"q":"A manager tracks calls made per week to evaluate a rep. This is a:","choices":["Lagging indicator","Profitability ratio","Market share measure","Leading activity metric"],"answer":3,"explain":"Activity metrics such as calls made predict future sales."},{"id":"mkt-097","sub":"Selling","diff":2,"q":"What is the best use of a trial close?","choices":["To check the customer''s readiness to buy before the final close","To end the sales call immediately","To lower the price","To avoid objections"],"answer":0,"explain":"A trial close tests readiness before asking for the order."},{"id":"mkt-098","sub":"Selling","diff":2,"q":"How should customer objections be viewed?","choices":["Signals of rejection that end the sale","Requests for information and reassurance that can advance the sale","Reasons to reassign the customer","Proof the product is defective"],"answer":1,"explain":"Objections are openings to clarify value and move the sale forward."},{"id":"mkt-099","sub":"Selling","diff":3,"q":"A buyer''s purchase requires a committee. What is the rep''s best next step?","choices":["Sign the contract without meeting others","Discount the price by 40%","Ask who else influences the decision and map the buying group","Stop communicating"],"answer":2,"explain":"Mapping the buying group is the key next step in a multi-stakeholder sale."},{"id":"mkt-100","sub":"Selling","diff":1,"q":"Which metric measures a sales team''s conversion efficiency?","choices":["Gross margin","Days sales outstanding","Inventory turnover","Conversion rate"],"answer":3,"explain":"Conversion rate is the share of leads that become customers."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'organizational-leadership', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"ol-001","sub":"Leadership Concepts and Traits","diff":2,"q":"Which leadership style is characterized by the leader making decisions alone with little input from group members?","choices":["Autocratic leadership","Democratic leadership","Laissez-faire leadership","Transformational leadership"],"answer":0,"explain":"Autocratic leaders decide alone and direct followers. Democratic leaders seek member input, which is the common confusion."},{"id":"ol-002","sub":"Motivation and Leadership Theories","diff":2,"q":"According to Maslow''s hierarchy of needs, which level sits at the top of the pyramid?","choices":["Safety needs","Belonging needs","Self-actualization","Physiological needs"],"answer":2,"explain":"Self-actualization is the highest level, reached after physiological, safety, and belonging and esteem needs are met."},{"id":"ol-003","sub":"Leadership Concepts and Traits","diff":2,"q":"A manager openly admits a missed deadline and takes responsibility for fixing it with the team. Which core leadership trait is shown?","choices":["Charisma","Accountability","Authoritarianism","Delegation"],"answer":1,"explain":"Accountability means owning results, including failures. Delegation is assigning work, which is not what the scenario describes."},{"id":"ol-004","sub":"Managerial Functions","diff":2,"q":"Which management function involves setting goals and deciding the course of action needed to reach them?","choices":["Organizing","Controlling","Staffing","Planning"],"answer":3,"explain":"Planning sets objectives and the actions to reach them. Organizing arranges resources once the plan exists."},{"id":"ol-005","sub":"Decision Making and Problem Solving","diff":3,"q":"A manager picks the first option that meets minimum requirements instead of searching for the best possible option. Which decision approach is this?","choices":["Satisficing","Maximizing","Brainstorming","Benchmarking"],"answer":0,"explain":"Satisficing accepts an option that is good enough. Maximizing would require evaluating all alternatives for the best one."},{"id":"ol-006","sub":"Communication and Teamwork","diff":2,"q":"Which communication barrier occurs when a receiver filters a message through personal biases and experiences?","choices":["Noise","Feedback delay","Perception","Channel overload"],"answer":2,"explain":"Perception barriers distort meaning based on the receiver''s own frame of reference. Noise refers to physical or environmental interference."},{"id":"ol-007","sub":"Ethics and Social Responsibility","diff":2,"q":"Which ethical framework judges an action by whether it produces the greatest good for the greatest number of people?","choices":["Deontology","Utilitarianism","Egoism","Virtue ethics"],"answer":1,"explain":"Utilitarianism weighs outcomes for the largest group. Deontology judges actions by duties and rules regardless of outcomes."},{"id":"ol-008","sub":"Organizational Structure and Culture","diff":2,"q":"In a functional organizational structure, employees are grouped primarily by:","choices":["Customer served","Geographic region","Product line","Area of specialty, such as marketing or finance"],"answer":3,"explain":"Functional structures group staff by specialty. Divisional structures group by product, region, or customer."},{"id":"ol-009","sub":"Change Management and Conflict Resolution","diff":2,"q":"Which conflict management style gives up some of one''s own goals to preserve the relationship?","choices":["Accommodating","Competing","Avoiding","Collaborating"],"answer":0,"explain":"Accommodating yields to the other party''s wishes. Competing pursues one''s own goals at the other party''s expense."},{"id":"ol-010","sub":"Motivation and Leadership Theories","diff":2,"q":"In Herzberg''s two-factor theory, which of the following is a motivator rather than a hygiene factor?","choices":["Salary","Job security","Recognition for achievement","Working conditions"],"answer":2,"explain":"Motivators such as achievement and recognition drive satisfaction. Hygiene factors such as salary and security prevent dissatisfaction but do not motivate on their own."},{"id":"ol-011","sub":"Communication and Teamwork","diff":2,"q":"Which type of communication flows from subordinates up to managers?","choices":["Downward","Upward","Grapevine","Horizontal"],"answer":1,"explain":"Upward communication carries feedback, questions, and reports from staff to management. Grapevine is informal and moves in all directions."},{"id":"ol-012","sub":"Managerial Functions","diff":3,"q":"Controlling as a management function primarily involves:","choices":["Hiring and training staff","Designing the organizational chart","Setting the long-range vision","Comparing actual performance to standards and correcting deviations"],"answer":3,"explain":"Controlling measures performance against standards and takes corrective action. The other options describe staffing, organizing, and planning."},{"id":"ol-013","sub":"Decision Making and Problem Solving","diff":2,"q":"A decision matrix is used to:","choices":["Rank alternatives by weighted criteria","Forecast market demand","Map communication channels","Track employee attendance"],"answer":0,"explain":"A decision matrix scores each option against weighted criteria so the totals can be compared. It is not a forecasting tool."},{"id":"ol-014","sub":"Ethics and Social Responsibility","diff":2,"q":"Corporate social responsibility refers to:","choices":["Maximizing shareholder returns only","Avoiding all government regulation","A company''s obligations to society beyond what the law requires","Charitable donations made only during tax season"],"answer":2,"explain":"CSR covers voluntary responsibilities to employees, communities, and the environment beyond legal minimums."},{"id":"ol-015","sub":"Organizational Structure and Culture","diff":2,"q":"Organizational culture is best described as:","choices":["The legal structure of the business","Shared values, beliefs, and norms that guide behavior","The written job descriptions of employees","The budget allocated to each department"],"answer":1,"explain":"Culture is the shared set of values and unwritten norms that shape how people act. Legal structure and job descriptions are formal, not cultural."},{"id":"ol-016","sub":"Change Management and Conflict Resolution","diff":3,"q":"The first step in Kotter''s eight-step change model is:","choices":["Consolidating gains","Anchoring changes in the culture","Generating short-term wins","Creating a sense of urgency"],"answer":3,"explain":"Kotter begins by establishing urgency. Consolidating gains and anchoring changes come near the end of the model."},{"id":"ol-017","sub":"Leadership Concepts and Traits","diff":2,"q":"Servant leadership focuses primarily on:","choices":["Serving the needs of followers and the community","Maximizing the leader''s personal authority","Strict enforcement of rules","Rapid individual promotion"],"answer":0,"explain":"Servant leaders put the growth and needs of followers first, which is the opposite of an authority-centered style."},{"id":"ol-018","sub":"Motivation and Leadership Theories","diff":2,"q":"McGregor''s Theory X assumes that employees:","choices":["Seek responsibility and creativity","Are self-directed and enjoy their work","Dislike work and must be closely supervised","Are motivated mainly by peer belonging"],"answer":2,"explain":"Theory X is the pessimistic view that workers avoid work and need control. Theory Y is the optimistic counterpart."},{"id":"ol-019","sub":"Communication and Teamwork","diff":2,"q":"Which nonverbal cue most often signals openness and engagement during a presentation?","choices":["Crossed arms","Eye contact and an open posture","Looking at a phone","Hands kept in pockets"],"answer":1,"explain":"Eye contact and open posture show confidence and engagement. Crossed arms and distracted behavior signal the opposite."},{"id":"ol-020","sub":"Managerial Functions","diff":2,"q":"Span of control refers to:","choices":["The number of levels in an organization","The total budget of a department","The distance between headquarters and branch offices","The number of subordinates a manager directly supervises"],"answer":3,"explain":"Span of control is the number of direct reports. A narrow span usually creates more management levels."},{"id":"ol-021","sub":"Decision Making and Problem Solving","diff":3,"q":"An analysis shows that 80 percent of customer complaints come from 20 percent of causes. This pattern is known as:","choices":["The 80/20 rule, or Pareto principle","The Gantt principle","The Hawthorne effect","The bell curve rule"],"answer":0,"explain":"The Pareto principle says a small share of causes drives most results. It is used to prioritize problems."},{"id":"ol-022","sub":"Ethics and Social Responsibility","diff":2,"q":"Which of the following best describes a conflict of interest?","choices":["Disagreement over project timelines","Two employees with different working styles","A situation where a personal interest could improperly influence professional judgment","Shared responsibility for a joint task"],"answer":2,"explain":"A conflict of interest exists when a personal interest could compromise professional duties, even if no wrong is done."},{"id":"ol-023","sub":"Organizational Structure and Culture","diff":2,"q":"A matrix organizational structure is characterized by:","choices":["A single chain of command with no shared authority","Employees reporting to both a functional manager and a project manager","All decisions made by one owner","Departments organized by geography only"],"answer":1,"explain":"Matrix structures give staff two reporting lines, which supports cross-functional projects but can create role confusion."},{"id":"ol-024","sub":"Change Management and Conflict Resolution","diff":2,"q":"Which is the most effective first step in resolving a workplace conflict?","choices":["Escalate it to the board of directors","Ignore the issue until the next performance review","Publicly criticize the other party","Meet privately with each party to understand the issue"],"answer":3,"explain":"A private, direct conversation with each party gathers facts and keeps the issue contained before escalation is considered."},{"id":"ol-025","sub":"Leadership Concepts and Traits","diff":2,"q":"Which trait describes a leader''s ability to remain effective when priorities change suddenly?","choices":["Adaptability","Rigidity","Authoritarianism","Indecision"],"answer":0,"explain":"Adaptability is the capacity to adjust approach and priorities as conditions change."},{"id":"ol-026","sub":"Motivation and Leadership Theories","diff":3,"q":"Vroom''s expectancy theory states that motivation depends on which three factors?","choices":["Need, drive, and incentive","Ethics, equity, and effort","Expectancy, instrumentality, and valence","Salary, status, and security"],"answer":2,"explain":"Expectancy (effort leads to performance), instrumentality (performance leads to reward), and valence (value of the reward) multiply to produce motivation."},{"id":"ol-027","sub":"Communication and Teamwork","diff":2,"q":"Which approach best encourages participation from quieter team members during a meeting?","choices":["Calling on the most senior person first only","Using round-robin turns for input","Ending the meeting early if discussion slows","Letting one person speak uninterrupted"],"answer":1,"explain":"Round-robin turns give every member a structured chance to contribute, which draws out quieter voices."},{"id":"ol-028","sub":"Managerial Functions","diff":2,"q":"Which management function involves assigning people and resources to tasks and positions?","choices":["Planning","Controlling","Leading","Organizing"],"answer":3,"explain":"Organizing arranges people, tasks, and resources into a structure. Leading is about influencing and motivating people."},{"id":"ol-029","sub":"Decision Making and Problem Solving","diff":3,"q":"Groupthink is best described as:","choices":["A group decision process that suppresses dissent in pursuit of consensus","Brainstorming without any evaluation","Independent decision making by each team member","A formal voting procedure"],"answer":0,"explain":"Groupthink happens when the desire for harmony overrides critical evaluation of alternatives."},{"id":"ol-030","sub":"Ethics and Social Responsibility","diff":2,"q":"Which principle means treating all employees fairly and giving each the opportunity to succeed based on merit and need?","choices":["Efficiency","Hierarchy","Equity","Specialization"],"answer":2,"explain":"Equity focuses on fair treatment and outcomes. Equality gives everyone the same resources, which is a related but different idea."},{"id":"ol-031","sub":"Organizational Structure and Culture","diff":2,"q":"Which is an example of an informal organization?","choices":["The official organizational chart","A group of coworkers who regularly lunch together and share information","The written employee handbook","The formal board of directors"],"answer":1,"explain":"The informal organization is the network of relationships that exists alongside the formal structure."},{"id":"ol-032","sub":"Change Management and Conflict Resolution","diff":2,"q":"Lewin''s three-stage model of change consists of:","choices":["Plan, act, observe","Start, develop, close","Define, measure, control","Unfreeze, change, refreeze"],"answer":3,"explain":"Unfreeze prepares people to let go of old behavior, change moves them to the new state, and refreeze locks in the new norm."},{"id":"ol-033","sub":"Leadership Concepts and Traits","diff":2,"q":"Transformational leaders primarily influence followers by:","choices":["Inspiring a shared vision and encouraging personal growth","Relying on rewards and punishments for compliance","Avoiding decisions until consensus forms","Restricting information to protect their authority"],"answer":0,"explain":"Transformational leaders motivate through vision, inspiration, and development. Rewards and punishments describe transactional leadership."},{"id":"ol-034","sub":"Motivation and Leadership Theories","diff":2,"q":"In Maslow''s hierarchy, which need comes directly above safety needs?","choices":["Self-actualization","Esteem","Belonging and love","Physiological needs"],"answer":2,"explain":"The order from bottom to top is physiological, safety, belonging and love, esteem, and self-actualization."},{"id":"ol-035","sub":"Communication and Teamwork","diff":2,"q":"Which communication channel is best for sensitive, complex, or emotionally charged messages?","choices":["Mass email","Face-to-face conversation","Text message","Posted memo"],"answer":1,"explain":"Face-to-face communication carries tone and nonverbal cues that reduce misunderstanding in difficult messages."},{"id":"ol-036","sub":"Managerial Functions","diff":3,"q":"A manager sets a quarterly budget and then compares actual spending to it each month. Which two functions are involved?","choices":["Leading and staffing","Organizing and planning only","Staffing and communicating","Planning and controlling"],"answer":3,"explain":"Setting the budget is planning. Monitoring and comparing against it is controlling."},{"id":"ol-037","sub":"Decision Making and Problem Solving","diff":2,"q":"Which step comes first in the rational decision-making model?","choices":["Identify the problem","Implement the chosen solution","Evaluate the alternatives","Monitor the results"],"answer":0,"explain":"The rational model begins with defining the problem clearly before generating or evaluating options."},{"id":"ol-038","sub":"Ethics and Social Responsibility","diff":3,"q":"A manager discovers that a subordinate has falsified expense reports. The most ethical first response is to:","choices":["Ignore it to avoid conflict","Reduce the employee''s pay privately","Investigate through proper channels and follow company policy","Post the findings on social media"],"answer":2,"explain":"Ethical handling means verifying facts and following established policy and reporting channels, with due process for the employee."},{"id":"ol-039","sub":"Organizational Structure and Culture","diff":2,"q":"Centralized decision making means:","choices":["Decisions are made at lower levels by front-line staff","Decisions are concentrated at the top of the organization","Every department votes on each decision","Decisions are made by outside consultants"],"answer":1,"explain":"Centralization keeps authority at the top. Decentralization pushes it down the hierarchy."},{"id":"ol-040","sub":"Change Management and Conflict Resolution","diff":3,"q":"Which conflict management style seeks a solution that fully satisfies both parties?","choices":["Avoiding","Accommodating","Competing","Collaborating"],"answer":3,"explain":"Collaborating, also called integrative problem solving, looks for win-win outcomes that meet both sets of interests."},{"id":"ol-041","sub":"Leadership Concepts and Traits","diff":2,"q":"Which is a core characteristic of an effective leader''s vision?","choices":["A clear, inspiring direction for the future","Frequent changes to avoid commitment","Focus only on daily tasks","Secrecy about goals"],"answer":0,"explain":"A vision gives people a clear and motivating destination. Vision is about direction, not day-to-day operations."},{"id":"ol-042","sub":"Motivation and Leadership Theories","diff":2,"q":"Which theory proposes that people are motivated by a strong need for achievement, power, and affiliation?","choices":["Theory X","Two-factor theory","McClelland''s needs theory","Equity theory"],"answer":2,"explain":"McClelland''s needs theory identifies achievement, power, and affiliation as learned needs that drive behavior."},{"id":"ol-043","sub":"Communication and Teamwork","diff":2,"q":"Which barrier to communication is caused by a lack of shared language or excessive jargon?","choices":["Physical noise","Semantic barrier","Information overload","Emotional filtering"],"answer":1,"explain":"Semantic barriers arise when words mean different things to the sender and receiver."},{"id":"ol-044","sub":"Managerial Functions","diff":2,"q":"Which tool breaks a project into tasks, durations, and dependencies on a timeline?","choices":["SWOT analysis","Fishbone diagram","Pareto chart","Gantt chart"],"answer":3,"explain":"A Gantt chart displays scheduled tasks as bars on a timeline. A fishbone diagram identifies causes of a problem."},{"id":"ol-045","sub":"Decision Making and Problem Solving","diff":2,"q":"Which technique generates many ideas before any are evaluated?","choices":["Brainstorming","Cost-benefit analysis","Break-even analysis","Variance analysis"],"answer":0,"explain":"Brainstorming separates idea generation from evaluation to encourage a wide range of options."},{"id":"ol-046","sub":"Ethics and Social Responsibility","diff":2,"q":"Whistleblower protection is best described as:","choices":["Permission to ignore company policy","A bonus paid for reporting competitors","Legal safeguards for employees who report illegal or unethical conduct","A requirement to report all coworkers'' personal conduct"],"answer":2,"explain":"Whistleblower protections shield employees from retaliation when they report wrongdoing in good faith."},{"id":"ol-047","sub":"Organizational Structure and Culture","diff":2,"q":"Which organizational structure is typically the flattest?","choices":["Tall hierarchy","Flat structure with few management levels","Multi-divisional","Matrix"],"answer":1,"explain":"A flat structure has few layers between top management and front-line staff, which usually means a wide span of control."},{"id":"ol-048","sub":"Change Management and Conflict Resolution","diff":2,"q":"Resistance to change is most effectively reduced by:","choices":["Imposing the change quickly without explanation","Removing employees who resist","Reducing communication until the change is complete","Involving employees early and explaining the reasons"],"answer":3,"explain":"Participation and clear reasoning build buy-in. Imposition and silence tend to increase resistance."},{"id":"ol-049","sub":"Leadership Concepts and Traits","diff":3,"q":"Situational leadership theory suggests that:","choices":["The most effective leadership style depends on the followers'' readiness and the situation","One leadership style works in every situation","Leaders are born and cannot be developed","Leadership depends mainly on the leader''s appearance"],"answer":0,"explain":"Hersey and Blanchard''s model matches directive or supportive behavior to follower competence and commitment."},{"id":"ol-050","sub":"Motivation and Leadership Theories","diff":2,"q":"Which motivational approach ties rewards directly to individual performance?","choices":["Job rotation","Team lunch events","Merit pay","Open office layout"],"answer":2,"explain":"Merit pay links compensation to measured individual results, which is a direct extrinsic reward."},{"id":"ol-051","sub":"Communication and Teamwork","diff":1,"q":"Which is the best use of feedback in a team?","choices":["Only point out mistakes","Give specific, timely feedback on behavior and results","Save all feedback for annual reviews","Share feedback only with management"],"answer":1,"explain":"Effective feedback is specific, timely, and focused on behavior and results, and it is useful in both directions."},{"id":"ol-052","sub":"Managerial Functions","diff":1,"q":"Staffing as a management function includes:","choices":["Writing the company mission statement","Setting the annual revenue target","Auditing financial statements","Recruiting, selecting, training, and developing employees"],"answer":3,"explain":"Staffing covers filling and developing positions with qualified people."},{"id":"ol-053","sub":"Decision Making and Problem Solving","diff":3,"q":"Which decision tool compares expected monetary outcomes weighted by their probabilities?","choices":["Expected value analysis","Mind mapping","Force field analysis","Empathy mapping"],"answer":0,"explain":"Expected value multiplies each outcome by its probability and sums the results to compare options under uncertainty."},{"id":"ol-054","sub":"Ethics and Social Responsibility","diff":1,"q":"Which statement best reflects stakeholder theory?","choices":["Only shareholders matter to management","Management should focus only on profit","A business should consider the interests of all groups its actions affect","Customers are the only stakeholders"],"answer":2,"explain":"Stakeholder theory includes employees, customers, suppliers, communities, and owners, not shareholders alone."},{"id":"ol-055","sub":"Organizational Structure and Culture","diff":1,"q":"A chart showing job titles, reporting relationships, and lines of authority is called an:","choices":["Budget","Organizational chart","Strategic plan","Mission statement"],"answer":1,"explain":"An organizational chart shows the formal structure of authority and reporting."},{"id":"ol-056","sub":"Change Management and Conflict Resolution","diff":3,"q":"In change management, which step reinforces new behaviors so they become the standard?","choices":["Unfreezing","Diagnosing","Piloting","Refreezing"],"answer":3,"explain":"Refreezing in Lewin''s model locks in the new behavior through reinforcement, policies, and culture."},{"id":"ol-057","sub":"Leadership Concepts and Traits","diff":1,"q":"Which leadership quality is most closely tied to earning trust over time?","choices":["Consistency and integrity","Frequent reorganizations","Strict secrecy","Constant competition"],"answer":0,"explain":"Trust grows when leaders act consistently with their stated values."},{"id":"ol-058","sub":"Motivation and Leadership Theories","diff":3,"q":"Equity theory predicts that employees become dissatisfied when they perceive:","choices":["Their pay is above the industry average","Their manager is too friendly","Their input-to-outcome ratio is unfair compared with peers","Their workload is shared evenly"],"answer":2,"explain":"Equity theory compares a person''s inputs and outcomes with those of comparable others. Perceived unfairness reduces motivation."},{"id":"ol-059","sub":"Communication and Teamwork","diff":1,"q":"What is the main purpose of an agenda in a business meeting?","choices":["To record decisions after the meeting","To outline topics and goals in advance","To assign blame for missed deadlines","To limit attendance to managers"],"answer":1,"explain":"An agenda sets topics, goals, and timing so participants can prepare and the meeting stays focused."},{"id":"ol-060","sub":"Managerial Functions","diff":1,"q":"Which management function involves monitoring performance and taking corrective action?","choices":["Planning","Organizing","Leading","Controlling"],"answer":3,"explain":"Controlling is the feedback loop of measuring results against standards and correcting deviations."},{"id":"ol-061","sub":"Decision Making and Problem Solving","diff":1,"q":"Which tool identifies an organization''s strengths, weaknesses, opportunities, and threats?","choices":["SWOT analysis","PERT chart","Break-even chart","Balanced scorecard"],"answer":0,"explain":"SWOT pairs internal factors (strengths, weaknesses) with external factors (opportunities, threats)."},{"id":"ol-062","sub":"Ethics and Social Responsibility","diff":3,"q":"The Sarbanes-Oxley Act of 2002 primarily aimed to:","choices":["Regulate consumer credit cards","Set the federal minimum wage","Improve corporate financial disclosure and accountability","Create federal labor unions"],"answer":2,"explain":"SOX was a U.S. federal response to corporate accounting scandals, and it strengthened internal controls and executive responsibility."},{"id":"ol-063","sub":"Organizational Structure and Culture","diff":1,"q":"A company with separate divisions for each product line most likely uses which structure?","choices":["Functional","Divisional","Simple","Network"],"answer":1,"explain":"Divisional structures organize around products, markets, or regions, each with its own resources."},{"id":"ol-064","sub":"Change Management and Conflict Resolution","diff":1,"q":"Which is a common driver of organizational change?","choices":["Stable customer demand","Unchanged technology","Identical competitors","New technology or shifting market demand"],"answer":3,"explain":"External forces such as technology and market shifts are a main reason organizations must change."},{"id":"ol-065","sub":"Leadership Concepts and Traits","diff":1,"q":"Which is the best definition of leadership?","choices":["The process of influencing a group toward achieving goals","The formal authority to give orders","The title given to a senior manager","The ability to win every argument"],"answer":0,"explain":"Leadership is influence. Authority and title do not guarantee that people will follow."},{"id":"ol-066","sub":"Motivation and Leadership Theories","diff":1,"q":"In Herzberg''s theory, which of the following is a hygiene factor?","choices":["Achievement","Recognition","Company policy and supervision","Advancement"],"answer":2,"explain":"Hygiene factors such as policy, supervision, and working conditions prevent dissatisfaction but do not create motivation."},{"id":"ol-067","sub":"Communication and Teamwork","diff":1,"q":"A manager receives a message full of technical jargon from a remote team. Which step best ensures understanding?","choices":["Reply with the same jargon","Paraphrase the message and confirm understanding through feedback","Ignore the message until a meeting","Forward it to the CEO"],"answer":1,"explain":"Paraphrasing and asking for confirmation closes the feedback loop and catches misunderstandings early."},{"id":"ol-068","sub":"Managerial Functions","diff":1,"q":"Delegation means:","choices":["Giving up accountability for results","Assigning all tasks to the most senior staff","Doing all the work personally to ensure quality","Assigning tasks and authority while keeping accountability for outcomes"],"answer":3,"explain":"Delegation transfers authority for a task, but the manager remains accountable for results."},{"id":"ol-069","sub":"Decision Making and Problem Solving","diff":3,"q":"Which bias occurs when people favor information that supports their existing beliefs?","choices":["Confirmation bias","Halo effect","Anchoring bias","Recency bias"],"answer":0,"explain":"Confirmation bias leads decision makers to seek and weigh evidence that confirms what they already think."},{"id":"ol-070","sub":"Ethics and Social Responsibility","diff":1,"q":"Which principle means a company discloses material information fairly and truthfully to stakeholders?","choices":["Confidentiality","Autonomy","Transparency","Subsidiarity"],"answer":2,"explain":"Transparency means open, accurate disclosure. Confidentiality protects information, which can be appropriate but is a different principle."},{"id":"ol-071","sub":"Organizational Structure and Culture","diff":1,"q":"In a span of control analysis, a narrow span usually means:","choices":["Many subordinates per manager","Few subordinates per manager","Few management levels","Wide geographic coverage"],"answer":1,"explain":"A narrow span means each manager supervises few people, which usually creates more layers in a tall structure."},{"id":"ol-072","sub":"Change Management and Conflict Resolution","diff":3,"q":"Which phase of Tuckman''s model of team development features members testing roles and disagreeing?","choices":["Forming","Adjourning","Norming","Storming"],"answer":3,"explain":"Storming is the conflict phase. Forming is orientation, norming is agreement on norms, and performing is productive work."},{"id":"ol-073","sub":"Leadership Concepts and Traits","diff":1,"q":"Which leadership approach gives followers the most freedom with the least direction?","choices":["Laissez-faire","Autocratic","Bureaucratic","Transactional"],"answer":0,"explain":"Laissez-faire leaders step back and let the group decide and self-manage."},{"id":"ol-074","sub":"Motivation and Leadership Theories","diff":3,"q":"Which motivation theory holds that people act to reach goals they value and believe they can achieve?","choices":["Hierarchy of needs","Two-factor theory","Expectancy theory","Theory Y"],"answer":2,"explain":"Expectancy theory ties effort to the belief that effort produces performance and that performance produces valued rewards."},{"id":"ol-075","sub":"Communication and Teamwork","diff":1,"q":"What is the main purpose of an elevator pitch?","choices":["To close a sale immediately","To quickly and clearly communicate who you are and what you offer","To read a full report aloud","To negotiate salary terms"],"answer":1,"explain":"An elevator pitch is a short, clear introduction. It is meant to spark interest, not to close a deal."},{"id":"ol-076","sub":"Managerial Functions","diff":1,"q":"Which management function is primarily about influencing and motivating people toward goals?","choices":["Planning","Organizing","Controlling","Leading"],"answer":3,"explain":"Leading covers motivation, direction, and communication to align people with goals."},{"id":"ol-077","sub":"Decision Making and Problem Solving","diff":3,"q":"A decision tree is most useful for:","choices":["Mapping sequential choices and their possible outcomes","Tracking employee attendance","Designing a company logo","Recording meeting minutes"],"answer":0,"explain":"Decision trees branch by choice and chance to show possible paths and outcomes for a decision."},{"id":"ol-078","sub":"Ethics and Social Responsibility","diff":3,"q":"Which situation is an example of a conflict of interest for a purchasing agent?","choices":["Choosing the lowest qualified bidder","Documenting vendor quotes","Approving a contract with a supplier owned by a relative","Following the approved vendor list"],"answer":2,"explain":"A relationship with the supplier could bias the purchasing decision, which is what makes it a conflict of interest."},{"id":"ol-079","sub":"Organizational Structure and Culture","diff":1,"q":"Organizational culture is most often passed on to new employees through:","choices":["Stock option plans","Stories, rituals, and observed leader behavior","Annual tax filings","Vendor contracts"],"answer":1,"explain":"Culture is learned through stories, ceremonies, and what leaders model and reward."},{"id":"ol-080","sub":"Change Management and Conflict Resolution","diff":1,"q":"Which change management practice matters most when introducing new software?","choices":["Keeping it secret until launch","Skipping training to save time","Making it optional forever","Providing training and support before and after launch"],"answer":3,"explain":"User adoption depends on training and ongoing support, which is a core change management principle."},{"id":"ol-081","sub":"Leadership Concepts and Traits","diff":1,"q":"Which leadership quality describes holding oneself to a clear code of conduct even when no one is watching?","choices":["Integrity","Charisma","Delegation","Visibility"],"answer":0,"explain":"Integrity is consistent ethical conduct regardless of observation."},{"id":"ol-082","sub":"Motivation and Leadership Theories","diff":1,"q":"According to Maslow, what is the lowest level of the hierarchy?","choices":["Esteem","Safety","Physiological needs","Belonging"],"answer":2,"explain":"Physiological needs such as food, water, and shelter form the base of the pyramid."},{"id":"ol-083","sub":"Communication and Teamwork","diff":1,"q":"What is the best way to close a presentation?","choices":["Apologize for the content","Summarize the key points and state the call to action","End abruptly after the last slide","Read unrelated notes aloud"],"answer":1,"explain":"A strong close summarizes the main message and tells the audience what to do next."},{"id":"ol-084","sub":"Managerial Functions","diff":3,"q":"Which tool compares actual results against standards to find and explain gaps?","choices":["Mind map","Empathy map","Fishbone diagram","Variance analysis"],"answer":3,"explain":"Variance analysis calculates the difference between planned and actual results and investigates the cause."},{"id":"ol-085","sub":"Decision Making and Problem Solving","diff":1,"q":"Which problem-solving step involves generating several possible solutions?","choices":["Brainstorming alternatives","Implementing the plan","Evaluating results","Defining the root cause"],"answer":0,"explain":"After the problem is defined, generating alternatives is the step that precedes evaluation and selection."},{"id":"ol-086","sub":"Ethics and Social Responsibility","diff":1,"q":"Which statement best describes fiduciary duty?","choices":["A duty to maximize personal bonuses","A duty to avoid all risk","A legal obligation to act in the best interest of another party","A duty to share profits equally with employees"],"answer":2,"explain":"Fiduciaries such as directors and trustees must put the interests of the party they serve ahead of their own."},{"id":"ol-087","sub":"Organizational Structure and Culture","diff":3,"q":"A line-and-staff structure differs from a pure line structure because it adds:","choices":["Direct production workers","Specialist advisory staff","Elected employee councils","Public shareholders"],"answer":1,"explain":"Staff specialists advise line managers, who keep command authority over operations."},{"id":"ol-088","sub":"Change Management and Conflict Resolution","diff":3,"q":"Which best describes organizational resilience?","choices":["Never changing processes","Avoiding all risk","Keeping the same structure for decades","The ability to adapt and recover from disruption"],"answer":3,"explain":"Resilience is the capacity to absorb shocks, adapt, and recover while continuing core operations."},{"id":"ol-089","sub":"Leadership Concepts and Traits","diff":1,"q":"Emotional intelligence in leadership most directly involves:","choices":["Recognizing and managing one''s own emotions and those of others","Avoiding all emotional topics","Making decisions without feedback","Ranking employees by performance alone"],"answer":0,"explain":"Emotional intelligence includes self-awareness, self-management, empathy, and relationship skills."},{"id":"ol-090","sub":"Motivation and Leadership Theories","diff":1,"q":"Which type of reward is intrinsic?","choices":["A year-end bonus check","A promotion with a higher salary","Personal satisfaction from completing meaningful work","A gift card from the manager"],"answer":2,"explain":"Intrinsic rewards come from within the person, such as a sense of accomplishment. Pay and gifts are extrinsic."},{"id":"ol-091","sub":"Communication and Teamwork","diff":1,"q":"In negotiation, which approach focuses on mutual gain rather than winning at the other party''s expense?","choices":["Zero-sum bargaining","Integrative negotiation","Hard bargaining","Ultimatum tactics"],"answer":1,"explain":"Integrative negotiation expands value by exploring interests, which creates outcomes both sides can accept."},{"id":"ol-092","sub":"Managerial Functions","diff":1,"q":"Which is an example of the organizing function?","choices":["Setting a five-year goal","Monitoring monthly sales","Motivating a team","Creating a new department with defined reporting lines"],"answer":3,"explain":"Creating departments and reporting lines is organizing. The other options are planning, controlling, and leading."},{"id":"ol-093","sub":"Decision Making and Problem Solving","diff":3,"q":"Which decision-making model assumes complete information and a fully logical process?","choices":["Rational decision-making model","Garbage can model","Intuitive model","Satisficing model"],"answer":0,"explain":"The rational model assumes full information and optimal choice. The garbage can and satisficing models relax those assumptions."},{"id":"ol-094","sub":"Ethics and Social Responsibility","diff":1,"q":"Which best describes a code of ethics?","choices":["A list of employee vacation rules","A government tax form","A written statement of values and standards of conduct","A list of product prices"],"answer":2,"explain":"A code of ethics states the values and expected conduct for members of an organization."},{"id":"ol-095","sub":"Organizational Structure and Culture","diff":1,"q":"Which structure groups employees by the customer segment they serve?","choices":["Functional","Customer-based","Geographic","Process"],"answer":1,"explain":"Customer-based (or market-based) structures align teams with particular customer groups."},{"id":"ol-096","sub":"Change Management and Conflict Resolution","diff":1,"q":"Which concept describes employees'' initial reluctance to new processes?","choices":["Economies of scale","Span of control","Zero-based budgeting","Resistance to change"],"answer":3,"explain":"Resistance to change is the natural reluctance to give up familiar routines and is a normal part of change management."},{"id":"ol-097","sub":"Leadership Concepts and Traits","diff":1,"q":"A leader uses 360-degree feedback primarily to:","choices":["Gather input from peers, subordinates, and supervisors for development","Rank employees for layoffs","Set the annual budget","Choose a new office location"],"answer":0,"explain":"360-degree feedback collects multi-rater input to support self-awareness and development, not punitive decisions."},{"id":"ol-098","sub":"Motivation and Leadership Theories","diff":3,"q":"Theory Y managers assume that employees are:","choices":["Lazy and must be controlled","Motivated only by pay","Capable of self-direction and seek responsibility","Unable to contribute ideas"],"answer":2,"explain":"Theory Y is the optimistic view that people can be committed and self-directed when conditions allow."},{"id":"ol-099","sub":"Communication and Teamwork","diff":1,"q":"Which is the best example of active listening?","choices":["Planning your reply while the other person speaks","Restating the speaker''s point to confirm understanding","Interrupting to share your own experience","Checking your phone during the conversation"],"answer":1,"explain":"Active listening includes paraphrasing and checking understanding. Planning a reply or multitasking blocks it."},{"id":"ol-100","sub":"Managerial Functions","diff":3,"q":"A manager tracks weekly output against a target and adjusts staffing when output falls short. Which two functions are primarily involved?","choices":["Planning and leading","Organizing and staffing only","Leading and communicating","Controlling and organizing"],"answer":3,"explain":"Tracking against the target is controlling, and changing staffing levels and assignments is organizing."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'personal-finance', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"pf-001","sub":"Principles of Money","diff":1,"q":"Which form of payment draws funds directly from the payer''s checking account at the time of purchase?","choices":["Debit card","Credit card","Installment loan","Certificate of deposit"],"answer":0,"explain":"A debit card pulls money from the cardholder''s own deposit account at the point of sale. A credit card borrows from the issuer."},{"id":"pf-002","sub":"Principles of Money","diff":1,"q":"Which function of money allows prices of goods and services to be stated and compared?","choices":["Medium of exchange","Store of value","Unit of measure","Source of credit"],"answer":2,"explain":"Money serves as a unit of measure (common yardstick) so prices can be compared. Medium of exchange is what is used to pay."},{"id":"pf-003","sub":"Principles of Money","diff":2,"q":"A shopkeeper accepts a $20 bill because every other merchant also accepts it for goods. Which function of money does this best illustrate?","choices":["Store of value","Medium of exchange","Unit of measure","Legal tender for all debts"],"answer":1,"explain":"Money as a medium of exchange is accepted widely in trade. The trap is store of value, which concerns keeping purchasing power over time."},{"id":"pf-004","sub":"Principles of Money","diff":3,"q":"Which statement about the time value of money is correct?","choices":["A dollar received today is worth less than a dollar received next year when interest rates are positive.","A dollar received today is worth the same as a dollar received next year, regardless of interest rates.","Money received in the future is worth more than the same amount today, because of inflation.","A dollar received today can be invested to grow, so it is worth more than the same dollar received later."],"answer":3,"explain":"Money on hand today can earn interest, so it has greater value than the same amount received later. The other choices reverse or ignore this relationship."},{"id":"pf-005","sub":"Principles of Money","diff":1,"q":"What is the main difference between a debit card and a credit card?","choices":["Credit cards draw from a checking account, while debit cards are loans.","Debit cards always charge interest on purchases.","Debit cards require a credit check before approval.","Debit cards withdraw funds from the cardholder''s own bank account, while credit cards borrow from the issuer."],"answer":3,"explain":"Debit spends the cardholder''s own money. Credit creates a debt owed to the card issuer."},{"id":"pf-006","sub":"Principles of Money","diff":1,"q":"Which of the following is an example of passive income?","choices":["Hourly wages for a full-time job","Rental income from a property leased to tenants","Commission earned on sales","Tips from restaurant customers"],"answer":1,"explain":"Passive income comes from assets or arrangements that do not require ongoing work, such as rent. Wages, commissions and tips all require labour."},{"id":"pf-007","sub":"Principles of Money","diff":2,"q":"A salesperson earns a base salary of $30,000 plus 5% commission on sales. Which describes this pay structure?","choices":["A combination of salary and incentive pay","Salary only","Piece-rate pay only","Hourly wages with overtime"],"answer":0,"explain":"The base salary is fixed pay, and the commission is incentive pay tied to performance."},{"id":"pf-008","sub":"Principles of Money","diff":3,"q":"An employee earns $1,200 gross pay for a pay period. Federal and state income tax withholding plus FICA total $270. What is net pay for the period?","choices":["$270","$1,470","$930","$1,000"],"answer":2,"explain":"Net pay equals gross pay minus withholdings: $1,200 minus $270 is $930. The trap is $1,000, which subtracts only part of the withholdings."},{"id":"pf-009","sub":"Principles of Money","diff":1,"q":"Which document is a written order instructing a bank to pay a specific amount from the payer''s account?","choices":["Promissory note","Certificate of deposit","Check","Treasury bond"],"answer":2,"explain":"A check is a negotiable instrument directing the bank to pay the payee from the drawer''s account."},{"id":"pf-010","sub":"Principles of Money","diff":1,"q":"Which of the following is NOT currency in circulation?","choices":["$50 Federal Reserve note","Quarter coin","Dollar coin","Treasury bond"],"answer":3,"explain":"Treasury bonds are government debt securities, not money in circulation. The other items are legal currency."},{"id":"pf-011","sub":"Principles of Money","diff":2,"q":"Which best describes the purpose of consumer credit?","choices":["Letting a consumer buy goods or services now and repay later, usually with interest","Permanently transferring ownership of savings to a lender","Guaranteeing a fixed return on investments","Protecting the consumer against identity theft"],"answer":0,"explain":"Credit lets consumers use goods or services before paying, in exchange for interest or fees."},{"id":"pf-012","sub":"Principles of Money","diff":3,"q":"Which U.S. federal law requires lenders to disclose the APR and finance charges on consumer credit?","choices":["Fair Credit Reporting Act","Truth in Lending Act","Fair Debt Collection Practices Act","Equal Credit Opportunity Act"],"answer":1,"explain":"The Truth in Lending Act (Regulation Z) requires standardized credit cost disclosures. The FCRA covers credit reports."},{"id":"pf-013","sub":"Principles of Money","diff":1,"q":"Which U.S. federal agency was created after the 2008 financial crisis to enforce most consumer financial protection laws?","choices":["Federal Deposit Insurance Corporation","Consumer Financial Protection Bureau","Securities and Exchange Commission","Federal Trade Commission"],"answer":1,"explain":"The Consumer Financial Protection Bureau was created by the Dodd-Frank Act in 2010 to supervise consumer financial products."},{"id":"pf-014","sub":"Principles of Money","diff":1,"q":"A consumer''s debit card is lost and the loss is reported within two business days. What is the maximum liability under the Electronic Fund Transfer Act?","choices":["$50","$500","$0 in all cases","Unlimited"],"answer":0,"explain":"Under the EFTA, reporting within two business days caps liability at $50. Reporting later raises the cap to $500."},{"id":"pf-015","sub":"Principles of Money","diff":2,"q":"A $1,000 deposit earns 5% interest compounded annually. What is its value after one year?","choices":["$1,005","$950","$1,500","$1,050"],"answer":3,"explain":"$1,000 times 1.05 equals $1,050. The trap is adding 5% of the deposit incorrectly or using the wrong base."},{"id":"pf-016","sub":"Principles of Money","diff":3,"q":"Under the Fair Credit Billing Act, how many days does a consumer generally have to send a written notice of a billing error after the first statement showing it?","choices":["30 days","45 days","60 days","90 days"],"answer":2,"explain":"The FCBA gives 60 days to dispute a billing error in writing after the first statement with the error is sent."},{"id":"pf-017","sub":"Principles of Money","diff":1,"q":"What does the store-of-value function of money mean?","choices":["Money keeps its purchasing worth over time so it can be saved for later use","Money is used to measure the price of goods","Money is accepted by sellers in exchange for goods","Money is issued by private companies"],"answer":0,"explain":"Store of value means money can be saved and used later without losing its worth, though inflation erodes it."},{"id":"pf-018","sub":"Principles of Money","diff":1,"q":"Which of the following is a non-cash employee benefit?","choices":["Cash bonus","Hourly wage","Commission","Employer-paid health insurance"],"answer":3,"explain":"Health insurance paid by the employer is a fringe benefit, not cash compensation."},{"id":"pf-019","sub":"Principles of Money","diff":2,"q":"Which term describes income before any taxes or deductions are subtracted?","choices":["Net income","Disposable income","Gross income","Take-home pay"],"answer":2,"explain":"Gross income is the total before taxes and deductions. Net income and take-home pay are after them."},{"id":"pf-020","sub":"Principles of Money","diff":3,"q":"Which is an example of an electronic funds transfer?","choices":["Writing a personal check to a landlord","Paying for groceries with a debit card at point of sale","Depositing cash at a teller window","Buying a money order at a post office"],"answer":1,"explain":"A debit card purchase moves funds electronically from the account at the point of sale. The other options involve paper or cash."},{"id":"pf-021","sub":"Financial Needs and Goals","diff":1,"q":"Which step should come first in the financial planning process?","choices":["Investing in the stock market","Paying bills on time","Setting financial goals","Buying insurance"],"answer":2,"explain":"Goals guide every later decision, so they come first in the planning process."},{"id":"pf-022","sub":"Financial Needs and Goals","diff":1,"q":"Which of these is a short-term financial goal?","choices":["Retiring at age 65","Saving for a vacation in six months","Funding a child''s college in 18 years","Building an estate for heirs"],"answer":1,"explain":"Short-term goals are typically achievable within about one year. The others are long-term."},{"id":"pf-023","sub":"Financial Needs and Goals","diff":2,"q":"Which formula is used to calculate net worth?","choices":["Total income minus total expenses","Total assets plus total liabilities","Cash on hand plus investments","Total assets minus total liabilities"],"answer":3,"explain":"Net worth equals what you own minus what you owe. Adding liabilities instead of subtracting them is a common error."},{"id":"pf-024","sub":"Financial Needs and Goals","diff":3,"q":"A monthly budget shows after-tax income of $4,000, fixed expenses of $2,600, and planned variable expenses of $1,500. What is the result?","choices":["$100 deficit","$100 surplus","$900 surplus","$1,400 deficit"],"answer":0,"explain":"Total expenses are $4,100, so the budget runs $100 short. The trap is forgetting variable expenses."},{"id":"pf-025","sub":"Financial Needs and Goals","diff":1,"q":"What is the main purpose of an emergency fund?","choices":["Financing a vacation","Covering unexpected expenses such as job loss or medical bills","Investing in high-risk stocks","Paying for planned home improvements"],"answer":1,"explain":"An emergency fund is a reserve of liquid savings for unplanned events."},{"id":"pf-026","sub":"Financial Needs and Goals","diff":1,"q":"A common guideline for the size of an emergency fund is:","choices":["One week of expenses","One month of take-home pay","One year of gross income","Three to six months of living expenses"],"answer":3,"explain":"Financial educators commonly recommend three to six months of living expenses in an accessible account."},{"id":"pf-027","sub":"Financial Needs and Goals","diff":2,"q":"Which budgeting method assigns every dollar of income to a category until none is left unassigned?","choices":["Zero-based budgeting","Pay-yourself-first budgeting","50/30/20 rule","Net worth statement"],"answer":0,"explain":"In zero-based budgeting, income minus planned spending equals zero. The 50/30/20 rule is a percentage guideline, not a zero-balance plan."},{"id":"pf-028","sub":"Financial Needs and Goals","diff":2,"q":"Which expense is a fixed expense?","choices":["Groceries","Entertainment","Rent","Clothing"],"answer":2,"explain":"Fixed expenses stay the same each period. Rent is usually set by a lease."},{"id":"pf-029","sub":"Financial Needs and Goals","diff":1,"q":"Which financial statement lists assets, liabilities, and equity at a single point in time?","choices":["Income statement","Cash flow statement","Budget","Balance sheet"],"answer":3,"explain":"A balance sheet is a snapshot at one date. Income and cash flow statements cover a period."},{"id":"pf-030","sub":"Financial Needs and Goals","diff":1,"q":"Which of the following is a long-term financial goal?","choices":["Saving for retirement in 30 years","Buying a laptop next month","Paying a parking ticket this week","Buying groceries for the week"],"answer":0,"explain":"Long-term goals are typically more than five years away."},{"id":"pf-031","sub":"Financial Needs and Goals","diff":2,"q":"Which list correctly describes the SMART goal criteria?","choices":["Simple, modest, adjustable, reviewed, targeted","Specific, measurable, achievable, relevant, time-bound","Strategic, multiple, adaptable, risky, tiered","Small, mixed, approximate, rolling, tentative"],"answer":1,"explain":"SMART stands for specific, measurable, achievable, relevant and time-bound."},{"id":"pf-032","sub":"Financial Needs and Goals","diff":3,"q":"Which action most directly increases a person''s net worth?","choices":["Taking out a $30,000 car loan","Paying a $200 restaurant bill with a credit card","Saving $500 from a paycheck in a savings account","Spending $500 of savings on a trip"],"answer":2,"explain":"Saving income adds to assets with no offsetting liability. Borrowing or spending from savings does not raise net worth."},{"id":"pf-033","sub":"Financial Needs and Goals","diff":1,"q":"Which of these is a sinking fund?","choices":["Saving a fixed amount each month for an annual insurance premium","Borrowing against a retirement account","A standby credit line for emergencies","A money market account used for daily spending"],"answer":0,"explain":"A sinking fund sets aside money regularly for a known future expense."},{"id":"pf-034","sub":"Financial Needs and Goals","diff":1,"q":"Which best describes a budget?","choices":["A list of past transactions only","A plan showing how income will be spent and saved","A loan agreement with a lender","A federal tax form"],"answer":1,"explain":"A budget is a forward-looking plan for income, spending and saving."},{"id":"pf-035","sub":"Financial Needs and Goals","diff":2,"q":"An employer''s 401(k) match is best classified as:","choices":["A tax refund","A loan forgiveness","A cash bonus","A fringe benefit that supports retirement saving"],"answer":3,"explain":"An employer match is a non-wage benefit that supports retirement saving."},{"id":"pf-036","sub":"Financial-Services Providers","diff":3,"q":"Which provider is a depository institution that accepts deposits and makes loans to consumers and businesses?","choices":["Insurance broker","Stockbroker","Commercial bank","Pawn shop"],"answer":2,"explain":"Commercial banks take deposits and lend. Brokers and insurance agents do not hold deposits."},{"id":"pf-037","sub":"Financial-Services Providers","diff":1,"q":"Which description best fits a credit union?","choices":["A for-profit corporation owned by shareholders","A government agency that sets interest rates","A member-owned, not-for-profit cooperative","An investment bank that underwrites stock offerings"],"answer":2,"explain":"Credit unions are cooperatives owned by their members and return earnings to them as lower fees and better rates."},{"id":"pf-038","sub":"Financial-Services Providers","diff":1,"q":"Which provider is a broker-dealer that executes trades in securities for clients?","choices":["Brokerage firm","Credit union","Pawn shop","Payday lender"],"answer":0,"explain":"Brokerage firms buy and sell securities on behalf of clients."},{"id":"pf-039","sub":"Financial-Services Providers","diff":2,"q":"When choosing a bank, which check matters most for protecting your deposits?","choices":["How many branches it has","Whether deposits are insured by the FDIC","The design of its website","The size of its advertising budget"],"answer":1,"explain":"FDIC insurance protects deposits up to the legal limit if an insured bank fails."},{"id":"pf-040","sub":"Financial-Services Providers","diff":3,"q":"A consumer compares a payday loan with a credit union small-dollar loan. Which factor most clearly favours the credit union?","choices":["A fee of $15 for every $100 borrowed","An annual percentage rate of 390%","A requirement to post a post-dated check","A lower interest rate with repayment over several months"],"answer":3,"explain":"Payday loans are short, high-cost loans due in full on the next payday. Longer, lower-rate installment terms are the clearest advantage."},{"id":"pf-041","sub":"Investment Strategies","diff":1,"q":"Which type of investment represents ownership in a company?","choices":["Bond","Common stock","Certificate of deposit","Treasury bill"],"answer":1,"explain":"Common stock gives shareholders an ownership stake. Bonds are debt."},{"id":"pf-042","sub":"Investment Strategies","diff":2,"q":"A bond pays $50 per year in interest on a $1,000 face value. What is its coupon rate?","choices":["0.5%","2.5%","5%","10%"],"answer":2,"explain":"Coupon rate equals annual interest divided by face value: $50 divided by $1,000 is 5%."},{"id":"pf-043","sub":"Investment Strategies","diff":2,"q":"Which investment is generally considered the least risky?","choices":["U.S. Treasury bill","Small-cap growth stock","Cryptocurrency","Commodity futures"],"answer":0,"explain":"Treasury bills are backed by the U.S. government and carry very low default risk."},{"id":"pf-044","sub":"Investment Strategies","diff":3,"q":"Which factor is most important when selecting investments for a goal five years away?","choices":["Putting the entire amount into a single stock","Choosing last year''s top performer","Expecting guaranteed returns in all cases","Matching the investment to the time horizon and risk tolerance"],"answer":3,"explain":"The time horizon and risk tolerance determine how much volatility an investor can absorb."},{"id":"pf-045","sub":"Investment Strategies","diff":1,"q":"What does diversification mean?","choices":["Putting all money into one investment","Borrowing money to invest","Investing only in bonds","Spreading investments across different assets to reduce risk"],"answer":3,"explain":"Diversification reduces the impact of any single investment''s loss."},{"id":"pf-046","sub":"Financial Literacy","diff":2,"q":"Which statement about marginal tax rates is correct?","choices":["Each dollar of income is taxed at one flat rate.","The top bracket''s rate applies to all income once you reach it.","Only the portion of income within a bracket is taxed at that bracket''s rate.","Tax brackets apply only to capital gains."],"answer":2,"explain":"A progressive system taxes each bracket''s slice of income at that bracket''s rate. Higher income does not raise the rate on earlier dollars."},{"id":"pf-047","sub":"Financial Literacy","diff":2,"q":"On a pay stub, which item represents the employee''s share of Social Security and Medicare taxes?","choices":["Federal income tax","FICA","State disability insurance","Net pay"],"answer":1,"explain":"FICA covers Social Security and Medicare. Employers match the amount."},{"id":"pf-048","sub":"Financial Literacy","diff":3,"q":"Gross pay is $2,000 and total withholdings are $460. What is net pay?","choices":["$1,540","$1,460","$2,460","$1,640"],"answer":0,"explain":"Net pay is $2,000 minus $460, which equals $1,540."},{"id":"pf-049","sub":"Financial Literacy","diff":1,"q":"On a check, what is the payee line?","choices":["The person or business receiving the payment","The bank''s routing number","The date the check was written","The memo line"],"answer":0,"explain":"The payee is the person or business that receives the money."},{"id":"pf-050","sub":"Financial Literacy","diff":2,"q":"What must match when you write a check?","choices":["The date and memo","The routing number","The amount in numerals and in words","The account signature"],"answer":2,"explain":"The numerical and written amounts should agree to avoid disputes or altered checks."},{"id":"pf-051","sub":"Financial Literacy","diff":2,"q":"A check shows $250 in numerals but the written amount reads two hundred fifty-five dollars. Which amount generally controls?","choices":["The numerical amount","The amount shown on the bank statement","The average of the two amounts","The written amount"],"answer":3,"explain":"Under the Uniform Commercial Code, the written words generally control over numerals when they conflict."},{"id":"pf-052","sub":"Financial Literacy","diff":3,"q":"Your checkbook balance is $1,200. The bank statement shows $1,350, with an outstanding check of $200 and an unrecorded $50 service fee. What is the adjusted balance?","choices":["$1,100","$1,150","$1,200","$1,350"],"answer":1,"explain":"Bank side: $1,350 minus $200 is $1,150. Book side: $1,200 minus the $50 fee is $1,150. Both match."},{"id":"pf-053","sub":"Financial Literacy","diff":1,"q":"Generally, how long should you keep federal tax returns and supporting records?","choices":["30 days","One year","At least three years from the filing date","Until the home is sold"],"answer":2,"explain":"The IRS generally has three years to audit, so three years is the usual minimum. Some situations require longer."},{"id":"pf-054","sub":"Financial Literacy","diff":2,"q":"Which record is most useful for tracking where money was spent during a month?","choices":["Balance sheet","Pay stub","Form W-2","Transaction register"],"answer":3,"explain":"A transaction register records each deposit, withdrawal and payment in order."},{"id":"pf-055","sub":"Financial Literacy","diff":2,"q":"To deduct a charitable cash gift of $250 or more on a federal return, what is generally required?","choices":["An appraisal for every gift","A written acknowledgment from the charity","A notarized letter from the donor","The recipient''s Social Security number"],"answer":1,"explain":"The IRS requires a contemporaneous written acknowledgment from the charity for single cash gifts of $250 or more."},{"id":"pf-056","sub":"Financial Literacy","diff":3,"q":"A single filer has a $15,000 standard deduction and itemized deductions of $12,000. Which is more beneficial?","choices":["Take the standard deduction of $15,000","Itemize and reduce taxable income by $12,000","Take both the standard deduction and itemize","Itemize and add $3,000 to taxable income"],"answer":0,"explain":"Taxpayers generally take whichever is larger, and the larger one here is the standard deduction. Itemizing and standard deduction cannot be combined."},{"id":"pf-057","sub":"Financial Literacy","diff":1,"q":"Which is the safest practice for managing online bank accounts?","choices":["Sharing passwords with family members","Enabling multi-factor authentication","Using the same password for every site","Saving login details on a public computer"],"answer":1,"explain":"Multi-factor authentication stops most account takeovers even if a password is stolen."},{"id":"pf-058","sub":"Financial Literacy","diff":2,"q":"A $1,000 credit card balance carries 18% APR charged monthly (1.5% per month) with no new purchases. What is the first month''s interest?","choices":["$15","$18","$1.50","$180"],"answer":0,"explain":"The monthly rate is 18% divided by 12, or 1.5%. Applied to $1,000, the interest is $15. The trap is using $18, the annual rate in dollars."},{"id":"pf-059","sub":"Financial Literacy","diff":2,"q":"Why do cardholders pay interest on credit cards?","choices":["The issuer waives interest after 30 days","The cardholder pays the full statement balance each month","The cardholder carries a balance past the grace period","The card carries an annual fee"],"answer":2,"explain":"Interest starts when a balance is carried past the grace period. Paying the full statement balance usually avoids interest on purchases."},{"id":"pf-060","sub":"Financial Literacy","diff":3,"q":"A $3,000 balance at 24% APR requires a $60 minimum payment. Why does the balance fall so slowly?","choices":["The minimum is applied entirely to principal","The issuer refunds interest each month","Interest applies only to new purchases","Most of the minimum covers accrued interest, leaving little for principal"],"answer":3,"explain":"Monthly interest is $3,000 times 2%, or $60, so nearly all of the minimum covers interest and little reduces principal."},{"id":"pf-061","sub":"Financial Literacy","diff":1,"q":"Which is a common warning sign of identity theft?","choices":["Receiving a monthly statement you expected","Paying bills on time","A credit score that rose slightly","A credit card bill for purchases you did not make"],"answer":3,"explain":"Unfamiliar charges or accounts are a key sign. Expected statements and normal scores are not warnings."},{"id":"pf-062","sub":"Financial Literacy","diff":2,"q":"Under the Fair Credit Reporting Act, how often is a consumer entitled to a free credit report from each nationwide credit bureau?","choices":["Once every five years","Once every 12 months","Only after a loan denial","Once a month"],"answer":1,"explain":"The Fair Credit Reporting Act entitles consumers to one free report from each nationwide bureau every 12 months. The bureaus now also offer free weekly reports voluntarily, but that goes beyond the legal minimum."},{"id":"pf-063","sub":"Financial Literacy","diff":2,"q":"Which factor has the largest impact on a FICO score?","choices":["Number of credit inquiries","Types of credit in use","Payment history","Total income"],"answer":2,"explain":"Payment history is the largest factor, at about 35 percent. Income is not used in scoring."},{"id":"pf-064","sub":"Financial Literacy","diff":3,"q":"Which statement about the credit utilization ratio is correct?","choices":["It is total card balances divided by total credit limits, and lower is generally better","Higher ratios generally improve a credit score","It includes only mortgage balances","It is calculated from the borrower''s income"],"answer":0,"explain":"Utilization is revolving balances divided by limits. Keeping it low generally helps the score."},{"id":"pf-065","sub":"Financial Literacy","diff":1,"q":"What is the best first step before taking on a new loan?","choices":["Compare the total cost, including interest","Buy the item immediately","Borrow the maximum amount offered","Ignore the APR"],"answer":0,"explain":"Comparing total cost, including interest and fees, shows what the loan really costs."},{"id":"pf-066","sub":"Financial Literacy","diff":2,"q":"What is the principal of a loan?","choices":["The interest charged","The monthly payment amount","The origination fee","The original amount borrowed, excluding interest"],"answer":3,"explain":"Principal is the amount borrowed. Interest and fees are separate charges."},{"id":"pf-067","sub":"Financial Literacy","diff":2,"q":"Which debt-repayment method pays off the smallest balance first?","choices":["Debt consolidation","Debt snowball","Debt avalanche","Bankruptcy"],"answer":1,"explain":"The snowball method targets the smallest balance for quick wins. The avalanche method targets the highest rate."},{"id":"pf-068","sub":"Financial Literacy","diff":3,"q":"Using the avalanche method, which debt should receive extra payments first? Card A: $2,000 at 22%. Card B: $5,000 at 15%. Car loan: $8,000 at 6%.","choices":["The car loan","Card B","Card A","Split all payments equally"],"answer":2,"explain":"The avalanche method targets the highest interest rate first, which is Card A at 22%."},{"id":"pf-069","sub":"Financial Literacy","diff":1,"q":"Which bill is most important to pay on time to avoid losing housing?","choices":["Magazine subscription","Streaming service","Rent or mortgage","Gym membership"],"answer":2,"explain":"Missing rent or mortgage payments can lead to eviction or foreclosure, so it takes priority."},{"id":"pf-070","sub":"Financial Literacy","diff":2,"q":"Which U.S. federal law restricts how third-party debt collectors may contact consumers?","choices":["Fair Credit Reporting Act","Fair Debt Collection Practices Act","Equal Credit Opportunity Act","Truth in Lending Act"],"answer":1,"explain":"The FDCPA limits collector contact times and methods and bans harassment and false statements."},{"id":"pf-071","sub":"Financial Literacy","diff":2,"q":"Which retirement plan allows employees to contribute pre-tax income through payroll deduction?","choices":["Traditional 401(k) plan","Roth IRA with after-tax contributions","Savings bond","Payday loan account"],"answer":0,"explain":"Traditional 401(k) contributions reduce current taxable wages, and withdrawals in retirement are taxed as income."},{"id":"pf-072","sub":"Financial Literacy","diff":3,"q":"Which statement about a Roth IRA is correct?","choices":["Contributions are tax-deductible in the year made","Withdrawals of contributions are taxed as ordinary income","Required minimum distributions begin at age 25","Contributions use after-tax dollars, and qualified retirement withdrawals are tax-free"],"answer":3,"explain":"Roth contributions are made with after-tax money, and qualified withdrawals are tax-free. Contributions can be withdrawn without tax at any time."},{"id":"pf-073","sub":"Financial Literacy","diff":1,"q":"Which form does a student complete to apply for federal financial aid?","choices":["Form W-4","FAFSA","Form 1099-INT","Form 1098-E"],"answer":1,"explain":"The Free Application for Federal Student Aid (FAFSA) is required for federal grants and loans."},{"id":"pf-074","sub":"Financial Literacy","diff":2,"q":"Which type of education funding generally does NOT have to be repaid?","choices":["Subsidized student loan","Private student loan","Parent PLUS loan","Pell Grant"],"answer":3,"explain":"Pell Grants are need-based grants that do not need repayment. All the loan options must be repaid."},{"id":"pf-075","sub":"Financial Literacy","diff":2,"q":"Which document names a person who can manage finances if the owner becomes incapacitated?","choices":["Living will","Birth certificate","Durable power of attorney","Beneficiary designation form"],"answer":2,"explain":"A durable power of attorney stays in effect if the principal becomes incapacitated. A living will covers medical care."},{"id":"pf-076","sub":"Financial Literacy","diff":3,"q":"Which is a key advantage of a revocable living trust over a will?","choices":["It can avoid probate for assets titled in the trust","It cannot be changed","It eliminates all estate taxes automatically","It requires no property titles"],"answer":0,"explain":"Assets titled in the trust pass outside probate. A revocable trust can be changed, and it does not automatically remove estate tax."},{"id":"pf-077","sub":"Financial Literacy","diff":1,"q":"Which form does an employer send to an employee to report annual wages and withholding?","choices":["Form 1099-DIV","Form 1098","Form 1040-ES","Form W-2"],"answer":3,"explain":"Form W-2 reports wages and taxes withheld. Form 1099 is used for non-employee income."},{"id":"pf-078","sub":"Financial Literacy","diff":2,"q":"Which filing status generally offers the largest standard deduction?","choices":["Married filing jointly","Head of household","Single","Married filing separately"],"answer":0,"explain":"Married filing jointly generally has the largest standard deduction, which is double the single amount."},{"id":"pf-079","sub":"Financial Literacy","diff":2,"q":"Which tax item reduces tax owed dollar for dollar?","choices":["Deduction","Exemption","Credit","Standard deduction"],"answer":2,"explain":"A credit reduces tax directly. A deduction only reduces taxable income."},{"id":"pf-080","sub":"Financial Literacy","diff":3,"q":"A taxpayer in the 22% bracket has $1,000 of additional taxable income, all in that bracket. How much additional federal income tax is owed?","choices":["$100","$220","$180","$2,200"],"answer":1,"explain":"Tax is 22% of $1,000, which is $220. The trap is treating the rate as 2.2 times the amount."},{"id":"pf-081","sub":"Financial Literacy","diff":1,"q":"Which tax is paid on the value of goods and services at the point of purchase?","choices":["Sales tax","Estate tax","Payroll tax","Property tax"],"answer":0,"explain":"Sales tax is collected at the register on the taxable price of goods and services."},{"id":"pf-082","sub":"Financial Literacy","diff":2,"q":"Which agency collects federal income tax?","choices":["FDIC","Internal Revenue Service","Securities and Exchange Commission","Federal Trade Commission"],"answer":1,"explain":"The IRS administers and collects federal income taxes."},{"id":"pf-083","sub":"Financial Literacy","diff":2,"q":"Which statement about capital gains is correct?","choices":["A capital gain is a loss on a sold asset","Short-term gains are always taxed at a lower rate than long-term gains","Long-term gains on assets held more than one year generally get lower rates than ordinary income","Capital gains are never subject to federal tax"],"answer":2,"explain":"Assets held more than one year usually qualify for lower long-term rates. Short-term gains are taxed as ordinary income."},{"id":"pf-084","sub":"Financial Literacy","diff":3,"q":"Which statement correctly describes a traditional IRA?","choices":["Contributions are taxed upfront and withdrawals are tax-free","Earnings are taxed each year as they accrue","No contributions are allowed after age 30","Contributions may be deductible, and retirement withdrawals are taxed as ordinary income"],"answer":3,"explain":"Traditional IRA earnings grow tax-deferred. Contributions may be deductible, and withdrawals are taxed as ordinary income."},{"id":"pf-085","sub":"Financial Literacy","diff":1,"q":"Which U.S. federal law protects consumers against unfair practices in credit reporting?","choices":["Equal Credit Opportunity Act","Fair Debt Collection Practices Act","Fair Credit Reporting Act","Electronic Fund Transfer Act"],"answer":2,"explain":"The FCRA governs how credit bureaus collect, share and correct consumer credit information."},{"id":"pf-086","sub":"Financial Literacy","diff":2,"q":"Which law prohibits credit discrimination based on race, sex, or marital status?","choices":["Equal Credit Opportunity Act","Fair Credit Reporting Act","Truth in Lending Act","Fair Debt Collection Practices Act"],"answer":0,"explain":"The ECOA prohibits credit discrimination on several protected bases, including race, sex and marital status."},{"id":"pf-087","sub":"Financial Literacy","diff":2,"q":"Which statement about a secured loan is correct?","choices":["It requires no collateral","It always has a higher rate than unsecured loans","It is available only to businesses","It is backed by collateral the lender can seize on default"],"answer":3,"explain":"A secured loan is backed by collateral, such as a car or home. Rates are often lower, not higher."},{"id":"pf-088","sub":"Financial Literacy","diff":3,"q":"A borrower defaults on a car loan. Under the Uniform Commercial Code, what is the lender''s typical remedy?","choices":["File criminal charges","Repossess the collateral after giving required notice","Collect from the borrower''s employer without notice","Cancel the principal"],"answer":1,"explain":"A secured lender may repossess collateral after default, subject to notice rules under the UCC."},{"id":"pf-089","sub":"Financial Literacy","diff":1,"q":"Which action best protects against identity theft?","choices":["Posting your Social Security number on social media","Placing a credit freeze with each credit bureau","Writing PINs on your cards","Banking on public Wi-Fi without protection"],"answer":1,"explain":"A credit freeze blocks new credit checks, so thieves cannot open accounts in your name."},{"id":"pf-090","sub":"Financial Literacy","diff":2,"q":"What is a fraud alert on a credit report?","choices":["A permanent block on all credit","A lien placed on property","A notice asking creditors to verify identity before opening new credit, lasting one year","A bankruptcy notice"],"answer":2,"explain":"An initial fraud alert lasts one year and asks lenders to take extra steps to verify identity. It does not block all credit."},{"id":"pf-091","sub":"Financial Literacy","diff":2,"q":"Which statement describes a credit freeze?","choices":["It lasts seven years and cannot be lifted","It prevents you from getting your own credit report","It applies only to business credit","It restricts access to your credit report so new accounts are harder to open, and it is free to place and lift"],"answer":3,"explain":"Under U.S. law, freezes are free and can be lifted or placed at each bureau. You can still see your own report."},{"id":"pf-092","sub":"Financial Literacy","diff":3,"q":"A debt collector threatens arrest for unpaid debt. What is the most appropriate first step?","choices":["Request written validation of the debt under the FDCPA","Pay immediately to avoid arrest","Give the collector your online banking password","Ignore the calls entirely"],"answer":0,"explain":"Debt collectors cannot threaten arrest for civil debt. Requesting written validation is the consumer''s right under the FDCPA."},{"id":"pf-093","sub":"Financial Literacy","diff":1,"q":"What does a Form W-4 tell an employer?","choices":["How much interest to report","How much to claim as a refund","Where to file an estate return","How much federal income tax to withhold"],"answer":3,"explain":"Form W-4 sets the employee''s federal withholding based on filing status and adjustments."},{"id":"pf-094","sub":"Financial Literacy","diff":2,"q":"Which is a common purpose of Form 1099?","choices":["Reporting wages from an employer","Reporting mortgage interest paid","Reporting non-employee or investment income","Requesting a tax refund"],"answer":2,"explain":"Form 1099 series reports income such as freelance pay, interest and dividends. Wages use Form W-2."},{"id":"pf-095","sub":"Financial Literacy","diff":2,"q":"Which record-keeping practice best supports a tax audit?","choices":["Keeping receipts and statements for the required period, generally three years","Shredding all statements after one month","Storing records only on a phone","Relying on memory"],"answer":0,"explain":"Documentation is the basis for supporting deductions and income. Keeping it for the required period protects the taxpayer."},{"id":"pf-096","sub":"Risk Management","diff":3,"q":"Which term describes the amount a policyholder pays out of pocket before insurance begins to pay?","choices":["Premium","Deductible","Policy limit","Coinsurance"],"answer":1,"explain":"The deductible is the out-of-pocket amount before the insurer pays. The premium is the regular cost of coverage."},{"id":"pf-097","sub":"Risk Management","diff":1,"q":"What is a premium in insurance?","choices":["The amount paid to keep an insurance policy in force","The amount the insurer pays on a claim","The maximum payout under the policy","A fee paid to an insurance agent"],"answer":0,"explain":"The premium is the price of coverage, usually paid monthly or annually."},{"id":"pf-098","sub":"Risk Management","diff":2,"q":"Which insurance protects against liability for injuries you cause to others?","choices":["Collision coverage on your own car","Homeowner''s contents coverage","Liability coverage","Term life insurance"],"answer":2,"explain":"Liability coverage pays for legal defence and damages you owe to third parties."},{"id":"pf-099","sub":"Risk Management","diff":2,"q":"Which strategy transfers risk to another party?","choices":["Risk avoidance","Purchasing insurance","Retaining risk with no reserve","Risk reduction by driving slower"],"answer":1,"explain":"Insurance transfers the financial risk of a loss to the insurer in exchange for a premium. Avoidance and reduction change the risk itself."},{"id":"pf-100","sub":"Risk Management","diff":3,"q":"What is coinsurance in an insurance policy?","choices":["The insurer pays 100% of covered costs after the premium is paid","The insured pays a fixed monthly amount regardless of claims","The insurer pays nothing until the policy limit is reached","The insured pays a set percentage of covered costs after the deductible is met"],"answer":3,"explain":"Coinsurance is the insured''s share of covered costs after the deductible, such as 20 percent. It is not a fixed fee."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'securities-investments', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"sec-001","sub":"Investment Fundamentals","diff":1,"q":"An investor who needs her money in two years and cannot accept a loss should prioritize which investment objective?","choices":["Speculative trading","Aggressive growth","Capital preservation","Leveraged income"],"answer":2,"explain":"A short horizon and low loss tolerance point to capital preservation. The trap is choosing growth-oriented options that carry large drawdown risk."},{"id":"sec-002","sub":"Investment Fundamentals","diff":1,"q":"Which statement best describes the risk-return tradeoff?","choices":["Higher expected return generally requires accepting higher risk","Low-risk investments always produce the highest returns","Risk and expected return are unrelated for diversified portfolios","Holding cash eliminates all investment risk"],"answer":0,"explain":"Investors are compensated for bearing additional risk with higher expected returns, though outcomes are not guaranteed."},{"id":"sec-003","sub":"Investment Fundamentals","diff":1,"q":"Diversification across many unrelated securities primarily reduces which type of risk?","choices":["Systematic (market-wide) risk","Broker counterparty risk","Tax-law change risk","Unsystematic (company-specific) risk"],"answer":3,"explain":"Company-specific risk is diversifiable. Market-wide risk remains after diversification, which is the trap."},{"id":"sec-004","sub":"Investment Fundamentals","diff":2,"q":"What is the value at the end of 2 years of $1,000 invested at 8% per year, compounded annually?","choices":["$1,080.00","$1,166.40","$1,160.00","$1,240.00"],"answer":1,"explain":"1,000 x 1.08 x 1.08 = $1,166.40. The trap is simple interest, which gives $1,160."},{"id":"sec-005","sub":"Investment Fundamentals","diff":1,"q":"Using the rule of 72, approximately how many years does it take an investment earning 6% per year to double?","choices":["9 years","12 years","10 years","14 years"],"answer":1,"explain":"72 divided by 6 is 12. The rule is an approximation for compounding at a constant rate."},{"id":"sec-006","sub":"Investment Fundamentals","diff":1,"q":"Which investor can generally take on the most short-term price volatility?","choices":["A retiree who depends on portfolio withdrawals next month","A 64-year-old who needs all savings within 12 months","A household saving for a down payment due next year","A 30-year-old saving for retirement 35 years away"],"answer":3,"explain":"A long time horizon gives time to recover from short-term declines, so volatility is more tolerable."},{"id":"sec-007","sub":"Investment Fundamentals","diff":3,"q":"What is the present value of $500 received one year from now, discounted at 5% per year?","choices":["$476.19","$500.00","$487.50","$525.00"],"answer":0,"explain":"500 / 1.05 = $476.19. The trap is compounding forward to $525."},{"id":"sec-008","sub":"Investment Fundamentals","diff":1,"q":"Which of the following is the most liquid asset?","choices":["Private real estate","Restricted private equity stake","Money market fund shares","Collectible art"],"answer":2,"explain":"Money market fund shares can usually be redeemed quickly at close to their stated value. The others take time or a discount to sell."},{"id":"sec-009","sub":"Investment Fundamentals","diff":3,"q":"An investment earns a 7% nominal return in a year when inflation is 3%. What is the exact real return?","choices":["3.88%","4.00%","3.50%","10.00%"],"answer":0,"explain":"The exact real return is (1.07 / 1.03) - 1 = 3.88%. Subtracting inflation gives the 4% approximation, which is the trap."},{"id":"sec-010","sub":"Investment Fundamentals","diff":2,"q":"What is the main benefit of dollar-cost averaging?","choices":["It guarantees a higher return than lump-sum investing","It eliminates market risk entirely","It spreads purchases over time, reducing the impact of a poorly timed entry","It avoids all brokerage fees"],"answer":2,"explain":"Regular fixed-dollar purchases reduce the risk of investing everything at a market peak. It does not guarantee a better return."},{"id":"sec-011","sub":"Investment Wrappers, Taxation, and Trusts","diff":1,"q":"Which statement about a Roth IRA is correct under current U.S. federal rules?","choices":["Contributions are deductible and withdrawals are taxed as ordinary income","Contributions are made with after-tax dollars and qualified withdrawals are tax-free","Contributions are deductible but withdrawals are always penalty-free","Earnings are taxed annually as they accrue"],"answer":1,"explain":"Roth contributions are not deducted, so qualified distributions of contributions and earnings are not taxed again."},{"id":"sec-012","sub":"Investment Wrappers, Taxation, and Trusts","diff":1,"q":"To qualify as a long-term capital gain for U.S. tax purposes, an asset must be held for more than:","choices":["Six months","Five years","Three years","One year"],"answer":3,"explain":"Holding for more than one year gives long-term treatment. Holding for exactly one year does not qualify."},{"id":"sec-013","sub":"Investment Wrappers, Taxation, and Trusts","diff":2,"q":"Under the U.S. wash sale rule, a loss on a sale is disallowed if a substantially identical security is bought within:","choices":["7 days after the sale only","14 days before the sale only","60 days in total","30 days before or after the sale"],"answer":3,"explain":"The window is 30 days on each side of the sale, a 61-day span in total."},{"id":"sec-014","sub":"Investment Wrappers, Taxation, and Trusts","diff":2,"q":"Qualified dividends are generally taxed at:","choices":["Ordinary income rates","Preferential long-term capital gains rates","The state rate only","The 3.8% NIIT rate only"],"answer":1,"explain":"Qualified dividends get the lower long-term capital gains rates if the holding-period rules are met."},{"id":"sec-015","sub":"Investment Wrappers, Taxation, and Trusts","diff":1,"q":"Earnings in a 529 college savings plan grow:","choices":["Taxable annually at ordinary rates","Tax-free, but withdrawals are always taxed","Tax-deferred, and qualified education withdrawals are federally tax-free","Only in cash equivalents with no tax benefit"],"answer":2,"explain":"Growth is tax-deferred and qualified education withdrawals are federally tax-free. Non-qualified withdrawals are taxed on earnings."},{"id":"sec-016","sub":"Investment Wrappers, Taxation, and Trusts","diff":3,"q":"A revocable living trust generally:","choices":["Lets the grantor amend or revoke it, and the assets remain in the grantor''s taxable estate","Removes assets from the grantor''s estate immediately and permanently","Requires the trustee to be a bank","Gives creditor protection from the grantor''s personal debts"],"answer":0,"explain":"Because the grantor keeps control, the assets are generally still part of the taxable estate. The trap is assuming a trust always removes assets from the estate."},{"id":"sec-017","sub":"Investment Wrappers, Taxation, and Trusts","diff":1,"q":"Interest from most U.S. municipal bonds is generally exempt from:","choices":["Self-employment tax","Capital gains tax on a sale at a profit","Federal income tax","All federal and state taxes"],"answer":2,"explain":"Muni interest is usually federally tax-exempt. Gains on selling a muni at a profit are still taxable."},{"id":"sec-018","sub":"Investment Wrappers, Taxation, and Trusts","diff":2,"q":"When an heir inherits appreciated stock, the cost basis is generally:","choices":["The fair market value at the date of death","Zero","The donor''s original purchase price","The average price over the last year"],"answer":0,"explain":"The basis steps up to fair market value at death, which often eliminates tax on gains that built up before death."},{"id":"sec-019","sub":"Investment Wrappers, Taxation, and Trusts","diff":3,"q":"In a traditional 401(k), pre-tax contributions are later taxed how?","choices":["Withdrawals are tax-free after five years","Contributions are taxed when made, but withdrawals are not","Withdrawals are taxed at long-term capital gains rates","Withdrawals are taxed as ordinary income"],"answer":3,"explain":"The contributions were never taxed, so withdrawals are ordinary income. Capital gains rates do not apply to these distributions."},{"id":"sec-020","sub":"Investment Wrappers, Taxation, and Trusts","diff":3,"q":"An investor in the 32% federal bracket can buy a municipal bond yielding 4% tax-free. Its tax-equivalent yield is closest to:","choices":["4.00%","5.88%","6.80%","2.72%"],"answer":1,"explain":"Tax-equivalent yield = 4% / (1 - 0.32) = 5.88%. Multiplying by 0.68 gives 2.72%, which is the trap."},{"id":"sec-021","sub":"Investment Products and Funds","diff":1,"q":"Which statement best distinguishes an ETF from a traditional open-end mutual fund?","choices":["ETFs are priced once daily at NAV only","ETFs trade intraday on an exchange at market prices","ETFs cannot be held in a brokerage account","ETFs guarantee principal"],"answer":1,"explain":"ETF shares trade throughout the day like stocks. Open-end mutual funds are bought and redeemed at the end-of-day NAV."},{"id":"sec-022","sub":"Investment Products and Funds","diff":1,"q":"Money market mutual funds seek to maintain a stable net asset value of:","choices":["Whatever the market rate implies","$10.00 per share","$100.00 per share","$1.00 per share"],"answer":3,"explain":"Money market funds target a stable $1.00 NAV. The NAV is not guaranteed, though."},{"id":"sec-023","sub":"Investment Products and Funds","diff":1,"q":"Bank certificates of deposit are generally insured by the FDIC up to:","choices":["$250,000 per depositor, per bank, per ownership category","$100,000 per depositor, per bank","$500,000 per account","There is no FDIC coverage on CDs"],"answer":0,"explain":"The standard limit is $250,000 per depositor, per insured bank, per ownership category."},{"id":"sec-024","sub":"Investment Products and Funds","diff":2,"q":"Who bears the investment risk in a variable annuity?","choices":["The insurer, which guarantees all returns","The U.S. government through the FDIC","The contract owner","The state guaranty association"],"answer":2,"explain":"In a variable annuity, returns depend on the chosen subaccounts, so the owner bears the market risk. Insurance guarantees are limited."},{"id":"sec-025","sub":"Investment Products and Funds","diff":2,"q":"To keep its REIT status under U.S. tax law, a REIT must distribute at least what percent of taxable income to shareholders?","choices":["90%","50%","75%","100%"],"answer":0,"explain":"The statutory requirement is 90% of taxable income, which is the figure most often confused with other thresholds."},{"id":"sec-026","sub":"Investment Products and Funds","diff":1,"q":"As a target-date fund approaches its target date, its asset allocation typically:","choices":["Becomes more aggressive","Stays fixed forever","Shifts toward more conservative holdings","Moves entirely to cash on the first day"],"answer":2,"explain":"This shift is called the glide path. The fund becomes more conservative as the investor''s time horizon shortens."},{"id":"sec-027","sub":"Investment Products and Funds","diff":3,"q":"Closed-end fund shares trade at a price that can differ from their net asset value. This is best described as:","choices":["Always equal to NAV","A premium or discount to NAV","Guaranteed by the sponsor","Fixed by the SEC"],"answer":1,"explain":"Closed-end funds trade on exchanges at market prices, so they often trade at a premium or discount to NAV."},{"id":"sec-028","sub":"Investment Products and Funds","diff":2,"q":"A unit investment trust (UIT) is typically characterized by:","choices":["Active management and frequent trading","An open-ended share count with daily NAV","A managed portfolio that changes monthly","A fixed portfolio that terminates at a set date"],"answer":3,"explain":"A UIT holds a fixed, unmanaged portfolio and dissolves at a stated termination date."},{"id":"sec-029","sub":"Investment Products and Funds","diff":3,"q":"Under SEC Regulation D, an individual generally qualifies as an accredited investor with net worth over:","choices":["$5 million in liquid assets only","$500,000, including the primary residence","$250,000 in annual income only","$1 million, excluding the primary residence"],"answer":3,"explain":"The net-worth test excludes the primary residence. The income test is a separate route to accredited status."},{"id":"sec-030","sub":"Investment Products and Funds","diff":3,"q":"A 2x daily-leveraged ETF held through several volatile months will most likely:","choices":["Return exactly twice the index''s cumulative return","Diverge from twice the index''s cumulative return because daily rebalancing compounds","Return half the index''s cumulative return","Eliminate volatility drag"],"answer":1,"explain":"Daily resetting compounds returns, so the multi-period result can differ substantially from 2x the index over longer holding periods."},{"id":"sec-031","sub":"Investment Products and Funds","diff":1,"q":"Preferred stock typically differs from common stock because it:","choices":["Has unlimited upside and pays no dividend","Has voting rights only","Pays a fixed dividend and has priority over common in liquidation","Matures like a bond"],"answer":2,"explain":"Preferred stock pays a stated dividend and ranks ahead of common equity in liquidation. It usually has no maturity date."},{"id":"sec-032","sub":"Investment Products and Funds","diff":2,"q":"Ginnie Mae mortgage pass-through securities are backed by:","choices":["The full faith and credit of the U.S. government","Private mortgage insurance","A corporate guarantee","State bond insurance"],"answer":0,"explain":"Ginnie Mae guarantees are backed by the full faith and credit of the U.S. government, unlike Fannie Mae or Freddie Mac securities."},{"id":"sec-033","sub":"Investment Products and Funds","diff":3,"q":"Compared with an ETF, an exchange-traded note (ETN) carries:","choices":["No credit risk because it holds the assets directly","Government insurance on principal","Credit risk of the issuer, since it is unsecured debt","Lower tax efficiency only"],"answer":2,"explain":"An ETN is an unsecured debt obligation of its issuer, so investors face the issuer''s credit risk. An ETF holds the underlying assets."},{"id":"sec-034","sub":"Investment Products and Funds","diff":3,"q":"A principal-protected structured note''s guarantee is ultimately backed by:","choices":["The issuer''s creditworthiness","The SEC","FDIC insurance","The underlying index"],"answer":0,"explain":"Structured notes are debt of the issuer, so the principal protection is only as strong as the issuer''s credit."},{"id":"sec-035","sub":"Investment Products and Funds","diff":2,"q":"Which product is generally FDIC insured?","choices":["Money market mutual fund shares","Mutual fund shares","Variable annuity contract","Bank savings account"],"answer":3,"explain":"Bank deposits are FDIC insured. Mutual fund shares, money market fund shares and annuities are not."},{"id":"sec-036","sub":"Stock Market","diff":1,"q":"The New York Stock Exchange is best described as:","choices":["A dealer market with no central location","An auction market with designated market makers","An over-the-counter quote network","A market that lists only bonds"],"answer":1,"explain":"The NYSE uses a centralized auction process with designated market makers. Nasdaq is the dealer-style market in this comparison."},{"id":"sec-037","sub":"Stock Market","diff":1,"q":"Which order type guarantees a price but not execution?","choices":["Market order","Limit order","Stop order","Market-on-open order"],"answer":1,"explain":"A limit order executes only at the limit price or better, so it may never fill. A market order fills but not at a guaranteed price."},{"id":"sec-038","sub":"Stock Market","diff":3,"q":"Once its stop price is reached, a stop-loss order becomes:","choices":["A limit order at the stop price","A good-till-canceled order","A short sale","A market order"],"answer":3,"explain":"A stop order converts to a market order when triggered, so the fill price may differ from the stop price."},{"id":"sec-039","sub":"Stock Market","diff":1,"q":"A short sale profits when the stock price:","choices":["Falls","Stays unchanged","Rises and then falls back","Rises steadily"],"answer":0,"explain":"The investor borrows shares, sells them, and buys them back later. A falling price produces a gain."},{"id":"sec-040","sub":"Stock Market","diff":2,"q":"Under Regulation T, the initial margin requirement for buying stock on margin is:","choices":["75%","25%","50%","100%"],"answer":2,"explain":"Reg T sets initial margin at 50% of the purchase price. The 25% figure is the FINRA maintenance minimum, which is the trap."},{"id":"sec-041","sub":"Stock Market","diff":3,"q":"The Dow Jones Industrial Average is a:","choices":["Price-weighted index","Market-capitalization-weighted index","Equal-weighted index","Free-float index"],"answer":0,"explain":"The DJIA weights each stock by share price, so high-priced stocks move it more than their market size would suggest."},{"id":"sec-042","sub":"Stock Market","diff":2,"q":"The S&P 500 index is weighted by:","choices":["Share price","Equal weight per stock","Market capitalization","Trading volume"],"answer":2,"explain":"The S&P 500 is a float-adjusted market-capitalization index."},{"id":"sec-043","sub":"Stock Market","diff":1,"q":"The ask price is the price at which:","choices":["A dealer will buy a security from an investor","A dealer will sell a security to an investor","The security last traded","The security''s par value is set"],"answer":1,"explain":"The ask is what the investor pays. The bid is what the investor receives when selling, and the gap between them is the spread."},{"id":"sec-044","sub":"Stock Market","diff":3,"q":"A Level 1 market-wide circuit breaker is triggered when the S&P 500 falls by:","choices":["5% at any time","20% at any time","10% at any time","7% before 3:25 p.m. Eastern"],"answer":3,"explain":"Level 1 is a 7% decline before 3:25 p.m. Eastern, which produces a 15-minute halt. Level 3 (20%) halts trading for the rest of the day."},{"id":"sec-045","sub":"Stock Market","diff":2,"q":"A stock trading at $80 with earnings of $4 per share has a P/E ratio of:","choices":["5","16","40","20"],"answer":3,"explain":"P/E = price / earnings per share = 80 / 4 = 20. Dividing the other way gives 0.05."},{"id":"sec-046","sub":"Stocks Versus Other Investments","diff":1,"q":"In a corporate bankruptcy, which group is paid before common shareholders?","choices":["Preferred shareholders only","Bondholders and other creditors","Employees holding stock options only","No one; common shareholders are paid first"],"answer":1,"explain":"Creditors, including bondholders, rank ahead of all equity holders. Preferred stock ranks ahead of common but behind creditors."},{"id":"sec-047","sub":"Stocks Versus Other Investments","diff":1,"q":"Common stock dividends are:","choices":["Guaranteed by the issuing company","Fixed by contract at issuance","Declared at the discretion of the board and not guaranteed","Required by the Securities Act of 1933"],"answer":2,"explain":"Common dividends are discretionary and can be cut or eliminated. Preferred dividends are usually stated in advance."},{"id":"sec-048","sub":"Stocks Versus Other Investments","diff":3,"q":"Over long historical periods, which asset class has generally shown the highest volatility?","choices":["Common stocks","Investment-grade corporate bonds","Municipal bonds","Treasury bills"],"answer":0,"explain":"Common stocks have historically had the highest returns and the highest volatility of these options."},{"id":"sec-049","sub":"Stocks Versus Other Investments","diff":2,"q":"Preferred shareholders typically have:","choices":["Veto power over all board decisions","Full voting rights per share","Limited or no voting rights","Voting rights only in bankruptcy"],"answer":2,"explain":"Preferred stock usually carries limited or no voting power, which is the trade-off for its priority and fixed dividend."},{"id":"sec-050","sub":"Stocks Versus Other Investments","diff":1,"q":"Compared with direct real estate, publicly traded common stock is generally:","choices":["More liquid","Less liquid","Equally liquid","Not tradable"],"answer":0,"explain":"Listed shares can be sold within seconds during trading hours. Direct property sales can take months."},{"id":"sec-051","sub":"Mutual Funds","diff":1,"q":"A mutual fund''s net asset value (NAV) per share is calculated:","choices":["Only at the time of each share purchase","Continuously during market hours","Once a month","Once daily, after the market close"],"answer":3,"explain":"Open-end funds price shares once per day, after the close, by dividing net assets by shares outstanding."},{"id":"sec-052","sub":"Mutual Funds","diff":1,"q":"A front-end load is:","choices":["A fee charged when shares are redeemed","A sales charge deducted when shares are purchased","An annual management fee","A tax on dividends"],"answer":1,"explain":"A front-end load is paid at purchase, which reduces the amount actually invested. A back-end load is charged on redemption."},{"id":"sec-053","sub":"Mutual Funds","diff":2,"q":"A 12b-1 fee is used to pay for:","choices":["Fund audits required by the SEC","Marketing and distribution expenses","Brokerage commissions on portfolio trades","Custodian bank services only"],"answer":1,"explain":"12b-1 fees, named for the SEC rule, cover distribution and marketing costs and are part of the expense ratio."},{"id":"sec-054","sub":"Mutual Funds","diff":1,"q":"A fund with a 1.2% expense ratio costs an investor with $10,000 invested about how much per year?","choices":["$12","$1,200","$0","$120"],"answer":3,"explain":"1.2% of $10,000 is $120. The trap is moving the decimal point to get $12."},{"id":"sec-055","sub":"Mutual Funds","diff":2,"q":"Compared with actively managed funds, index funds generally have:","choices":["Lower expense ratios and lower turnover","Higher expense ratios and higher turnover","Guaranteed returns","No market exposure"],"answer":0,"explain":"Index funds track a benchmark with little trading, which keeps costs and turnover low."},{"id":"sec-056","sub":"Mutual Funds","diff":3,"q":"A mutual fund''s capital gains distribution that is reinvested is:","choices":["Not taxable until the shares are sold","Tax-exempt for all investors","Taxable in the year it is distributed","Taxed only at the state level"],"answer":2,"explain":"Reinvested distributions are still taxable income in the year paid. Reinvesting does not defer the tax."},{"id":"sec-057","sub":"Mutual Funds","diff":2,"q":"Breakpoints in mutual fund sales charges:","choices":["Reduce the front-end load on larger purchases","Apply only to no-load funds","Eliminate all sales charges","Increase the load for larger purchases"],"answer":0,"explain":"Breakpoints lower the sales charge percentage once a purchase reaches set dollar thresholds."},{"id":"sec-058","sub":"Mutual Funds","diff":1,"q":"Open-end mutual fund shares are redeemed at:","choices":["The last exchange trade price","The offering price including the load","The next calculated net asset value","The fund''s original purchase price"],"answer":2,"explain":"Redemptions are priced at the next NAV after the request, not at the last trade or the original purchase price."},{"id":"sec-059","sub":"Mutual Funds","diff":3,"q":"Class C mutual fund shares typically carry:","choices":["A large front-end load and no ongoing fees","A level annual 12b-1 fee and a contingent deferred sales charge for early redemption","No fees of any kind","Lower expense ratios than Class A shares"],"answer":1,"explain":"Class C shares have no front-end load but higher ongoing 12b-1 fees, and a short-term redemption charge applies."},{"id":"sec-060","sub":"Mutual Funds","diff":2,"q":"A fund with high portfolio turnover is most likely to generate:","choices":["Lower tax costs","No taxable distributions","Only long-term capital gains","More short-term capital gains taxed as ordinary income"],"answer":3,"explain":"Assets held one year or less produce short-term gains, which are taxed at ordinary income rates. This raises the fund''s tax cost for shareholders."},{"id":"sec-061","sub":"Basics of Bonds","diff":1,"q":"When market interest rates rise, the price of an existing fixed-rate bond generally:","choices":["Doubles","Rises","Stays the same","Falls"],"answer":3,"explain":"Bond prices move inversely to rates, because existing bonds must fall in price to match the yield on newly issued bonds."},{"id":"sec-062","sub":"Basics of Bonds","diff":1,"q":"A $1,000 par bond with a 5% annual coupon pays annual interest of:","choices":["$5","$50","$25","$500"],"answer":1,"explain":"5% of $1,000 par is $50 per year."},{"id":"sec-063","sub":"Basics of Bonds","diff":2,"q":"A $1,000 par, 5% coupon bond trades at $950. Its current yield is closest to:","choices":["5.00%","5.50%","5.26%","4.75%"],"answer":2,"explain":"Current yield = $50 / $950 = 5.26%. The 5.00% figure is the coupon rate, not the current yield."},{"id":"sec-064","sub":"Basics of Bonds","diff":3,"q":"Holding other factors equal, which bond has the greatest sensitivity to interest rate changes?","choices":["Long-term zero-coupon bond","Bond with a high coupon and short maturity","Two-year Treasury note","Short-term floating-rate note"],"answer":0,"explain":"Long maturity and no interim coupons give a zero-coupon bond the highest duration and so the highest price sensitivity."},{"id":"sec-065","sub":"Basics of Bonds","diff":1,"q":"A zero-coupon bond is typically sold:","choices":["At par with monthly interest","At a premium with semiannual coupons","At a discount to par, with no periodic interest","Only at auction at face value plus accrued interest"],"answer":2,"explain":"Investors earn the difference between the discounted purchase price and par at maturity, since no interest is paid along the way."},{"id":"sec-066","sub":"Basics of Bonds","diff":2,"q":"Under standard rating scales, which rating is investment grade?","choices":["BBB-","B-","BB+","CCC"],"answer":0,"explain":"BBB- (S&P) and Baa3 (Moody''s) are the lowest investment-grade ratings. BB+ is the first speculative grade."},{"id":"sec-067","sub":"Basics of Bonds","diff":2,"q":"Interest from U.S. Treasury bonds is exempt from:","choices":["Federal income tax","Capital gains tax","Estate tax","State and local income taxes"],"answer":3,"explain":"Treasury interest is taxable federally but exempt from state and local income taxes. Gains on sale are still taxable."},{"id":"sec-068","sub":"Basics of Bonds","diff":2,"q":"A callable bond''s main risk to the investor is:","choices":["Default risk only","The issuer may redeem early when rates fall, forcing reinvestment at lower rates","Interest rate risk with no reinvestment risk","Loss of principal to inflation-indexed adjustments"],"answer":1,"explain":"The issuer redeems when rates fall, so the investor must reinvest the principal at lower yields. This is call risk combined with reinvestment risk."},{"id":"sec-069","sub":"Basics of Bonds","diff":3,"q":"Yield to maturity assumes that:","choices":["Coupons are spent and the bond is sold at par after one year","Coupons are reinvested at the YTM rate and the bond is held to maturity","The bond''s price never changes","Taxes are paid at the state level only"],"answer":1,"explain":"YTM assumes all coupons are reinvested at the same yield and the bond is held to maturity. Those assumptions often fail in practice."},{"id":"sec-070","sub":"Basics of Bonds","diff":2,"q":"A bond with a coupon above current market rates trades at:","choices":["A discount","Zero value","Par value always","A premium"],"answer":3,"explain":"Investors pay more for the above-market coupon, so the price rises above par."},{"id":"sec-071","sub":"Basics of Bonds","diff":2,"q":"A 5% coupon bond priced when market rates are 6% trades at:","choices":["A discount to par","Par","A premium to par","Twice its face value"],"answer":0,"explain":"A below-market coupon makes the bond worth less than par, so it trades at a discount."},{"id":"sec-072","sub":"Basics of Bonds","diff":3,"q":"Reinvestment risk is greatest for a bondholder when:","choices":["Interest rates rise and the investor holds a long bond","Bond prices are stable","Interest rates fall after coupons are received","The bond is a zero-coupon issue held to maturity"],"answer":2,"explain":"Falling rates force coupons to be reinvested at lower yields. Zero-coupon bonds avoid this risk because they have no coupons to reinvest."},{"id":"sec-073","sub":"Basics of Bonds","diff":3,"q":"Which bond has the highest interest rate risk?","choices":["A 30-year zero-coupon bond","A 2-year zero-coupon bond","A 5-year coupon bond with a high coupon","A floating-rate note"],"answer":0,"explain":"The longest-duration bond has the most price sensitivity to rate changes. Floating-rate notes reset their coupons, so their price sensitivity is low."},{"id":"sec-074","sub":"Basics of Bonds","diff":1,"q":"A general obligation municipal bond is backed primarily by:","choices":["A bank letter of credit only","Revenue from a specific toll road","The issuer''s taxing power","A federal guarantee"],"answer":2,"explain":"GO bonds are backed by the issuer''s full taxing power. Revenue bonds rely on the revenue of a specific project."},{"id":"sec-075","sub":"Basics of Bonds","diff":2,"q":"In bankruptcy, which debt ranks highest?","choices":["Subordinated debentures","Senior secured debt","Unsecured junior notes","Common equity"],"answer":1,"explain":"Secured creditors with collateral are paid first, ahead of unsecured and subordinated debt, and well ahead of equity."},{"id":"sec-076","sub":"Basics of Bonds","diff":3,"q":"Treasury Inflation-Protected Securities (TIPS) adjust their:","choices":["Coupon rate only","Yield to maturity directly","Credit rating","Principal based on changes in the CPI"],"answer":3,"explain":"TIPS principal rises and falls with the CPI, and coupons are paid on the adjusted principal."},{"id":"sec-077","sub":"Basics of Bonds","diff":2,"q":"A floating-rate note''s coupon typically:","choices":["Is fixed for the bond''s life","Equals the issuer''s stock dividend","Is paid only at maturity","Resets periodically to a benchmark rate plus a spread"],"answer":3,"explain":"The coupon follows a benchmark such as SOFR plus a fixed spread, which keeps the price close to par."},{"id":"sec-078","sub":"Basics of Bonds","diff":2,"q":"A bond ladder reduces risk by:","choices":["Guaranteeing the highest yield","Staggering maturities so bonds mature at regular intervals","Eliminating default risk","Holding only zero-coupon bonds of one maturity"],"answer":1,"explain":"Staggered maturities let the investor reinvest a portion regularly, which smooths the effect of rate changes."},{"id":"sec-079","sub":"Basics of Bonds","diff":3,"q":"A bond bought between coupon dates settles with the buyer paying:","choices":["Only the clean price","Only the par value","The clean price plus accrued interest to the seller","Nothing extra; the seller keeps the accrued interest"],"answer":2,"explain":"The buyer pays accrued interest to the seller, who earned it, and the buyer collects the full coupon later."},{"id":"sec-080","sub":"Basics of Bonds","diff":2,"q":"A bond''s price is most likely to rise when:","choices":["Market yields for similar bonds fall","The issuer''s credit rating is downgraded","Inflation expectations increase sharply","Market yields for similar bonds rise"],"answer":0,"explain":"Falling market yields raise the value of existing fixed coupons. Rating downgrades and inflation expectations generally push yields up."},{"id":"sec-081","sub":"Derivatives","diff":1,"q":"A call option gives the holder the right, but not the obligation, to:","choices":["Buy the underlying at the market price only","Sell the underlying asset at the strike price","Buy the underlying asset at the strike price","Receive dividends from the issuer"],"answer":2,"explain":"A call is the right to buy at the strike. The put is the right to sell at the strike."},{"id":"sec-082","sub":"Derivatives","diff":1,"q":"A put option gives the holder the right to:","choices":["Sell the underlying asset at the strike price","Buy 100 shares at market","Collect interest on the premium","Convert bonds into stock"],"answer":0,"explain":"A put is the right to sell at the strike price, which gains value when the underlying falls."},{"id":"sec-083","sub":"Derivatives","diff":2,"q":"A call with a $50 strike on a stock trading at $55 has an intrinsic value of:","choices":["$0","$55","$50","$5"],"answer":3,"explain":"Intrinsic value of a call = max(stock price - strike, 0) = $5."},{"id":"sec-084","sub":"Derivatives","diff":2,"q":"A covered call strategy involves:","choices":["Buying a put on shares you do not own","Owning shares and selling a call on those shares","Buying calls on shares you are short","Short selling shares and buying calls"],"answer":1,"explain":"The shares you own cover the obligation if the call is exercised. The strategy limits upside in exchange for premium income."},{"id":"sec-085","sub":"Derivatives","diff":3,"q":"Futures positions are marked to market:","choices":["Once at contract expiration","Daily, with gains and losses settled through margin accounts","Only when the contract is delivered","Annually by the exchange"],"answer":1,"explain":"Daily settlement is a defining feature of futures and is what distinguishes them from forwards."},{"id":"sec-086","sub":"Derivatives","diff":2,"q":"Compared with futures contracts, forward contracts are typically:","choices":["Settled with daily margin","Standardized and exchange-traded","Guaranteed by a central clearinghouse","Privately negotiated over-the-counter agreements"],"answer":3,"explain":"Forwards are customized private agreements with counterparty risk. Futures are standardized and cleared."},{"id":"sec-087","sub":"Derivatives","diff":2,"q":"An investor who owns stock and buys a put on that stock is using a:","choices":["Protective put","Short hedge","Covered call","Straddle"],"answer":0,"explain":"The put sets a floor on the value of the held shares, which is the definition of a protective put."},{"id":"sec-088","sub":"Derivatives","diff":3,"q":"All else equal, an option''s time value:","choices":["Increases as expiration approaches","Stays constant until expiration","Decreases as expiration approaches","Is unaffected by time"],"answer":2,"explain":"Time decay (theta) erodes time value as expiration nears, and the decay accelerates near expiry."},{"id":"sec-089","sub":"Derivatives","diff":3,"q":"An investor buys 100 shares at $100 and a $100 strike put for $4 per share. If the stock falls to $60 at expiration, the net loss per share is:","choices":["$4","$40","$36","$0"],"answer":0,"explain":"The put pays $40, which offsets the $40 share loss. The only net cost is the $4 premium, so the loss is $4 per share."},{"id":"sec-090","sub":"Derivatives","diff":2,"q":"A wheat farmer who sells wheat futures to lock in a price is acting as a:","choices":["Speculator","Arbitrageur","Hedger","Underwriter"],"answer":2,"explain":"A hedger uses futures to reduce exposure to an existing price risk. A speculator takes on risk for profit."},{"id":"sec-091","sub":"Financial Services Regulation","diff":1,"q":"The U.S. Securities and Exchange Commission was created by which act?","choices":["Securities Act of 1933","Securities Exchange Act of 1934","Investment Advisers Act of 1940","Sarbanes-Oxley Act of 2002"],"answer":1,"explain":"The Exchange Act of 1934 created the SEC. The 1933 Act governs new issues and the registration of securities."},{"id":"sec-092","sub":"Financial Services Regulation","diff":1,"q":"The Securities Act of 1933 primarily requires:","choices":["Exchange listing for all stocks","Federal insurance of brokerage accounts","Licensing of individual investment advisers only","Registration and prospectus disclosure for new securities offerings"],"answer":3,"explain":"The 1933 Act is the primary-market law: issuers register offerings and provide a prospectus."},{"id":"sec-093","sub":"Financial Services Regulation","diff":1,"q":"FINRA is best described as:","choices":["A federal government agency","A bank regulator","A mutual fund custodian","A self-regulatory organization overseeing broker-dealers"],"answer":3,"explain":"FINRA is a private, SEC-overseen self-regulatory organization for broker-dealers and registered representatives."},{"id":"sec-094","sub":"Financial Services Regulation","diff":2,"q":"SIPC protects customers of a failed brokerage up to:","choices":["$250,000 per customer, all cash","$500,000 per customer, including up to $250,000 in cash","$1 million per account","Unlimited for all accounts"],"answer":1,"explain":"SIPC covers missing securities and cash up to $500,000, of which cash is capped at $250,000. It does not protect against market losses."},{"id":"sec-095","sub":"Financial Services Regulation","diff":2,"q":"Regulation Best Interest requires broker-dealers to act in the:","choices":["Best interest of the firm","Interest of the exchange","Best interest of the retail customer when making a recommendation","Interest of the issuer"],"answer":2,"explain":"Reg BI raises the standard for retail recommendations above suitability, requiring the broker to put the customer''s interest first at the time of the recommendation."},{"id":"sec-096","sub":"Financial Services Regulation","diff":2,"q":"Which SEC rule is the general antifraud provision most often used to prosecute insider trading?","choices":["Rule 10b-5","Regulation D","Rule 144","Regulation FD"],"answer":0,"explain":"Rule 10b-5 prohibits fraud in connection with securities trading and is the basis for most insider trading cases."},{"id":"sec-097","sub":"Financial Services Regulation","diff":2,"q":"The Sarbanes-Oxley Act of 2002 requires CEOs and CFOs to:","choices":["Own at least 5% of company stock","Register as broker-dealers","Certify the accuracy of periodic financial reports","Refrain from serving on the audit committee"],"answer":2,"explain":"SOX Section 302 and 906 require personal certification of periodic reports, with criminal penalties for false certifications."},{"id":"sec-098","sub":"Financial Services Regulation","diff":2,"q":"Under the Investment Advisers Act of 1940, registered investment advisers owe clients:","choices":["A fiduciary duty","Only a suitability duty","No duty of care","A duty only when managing retirement accounts"],"answer":0,"explain":"Advisers owe a fiduciary duty of loyalty and care. The suitability standard is the lower broker-dealer standard, which is the trap."},{"id":"sec-099","sub":"Financial Services Regulation","diff":2,"q":"The Investment Company Act of 1940 primarily regulates:","choices":["Corporate bond issuance","Bank deposit insurance","Commodity futures exchanges","Mutual funds and other investment companies"],"answer":3,"explain":"The 1940 Investment Company Act sets the rules for mutual funds, closed-end funds and UITs."},{"id":"sec-100","sub":"Financial Services Regulation","diff":2,"q":"State securities laws are commonly called:","choices":["Green sheet laws","Blue sky laws","Silver rules","Gold standard statutes"],"answer":1,"explain":"Blue sky laws are state-level securities regulations, which supplement federal law. The name comes from fraud that was said to sell ''blue sky''."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

insert into public.fbla_questions (id, event, sub, diff, q, choices, answer, explain)
select x.id, 'sports-entertainment-management', x.sub, x.diff, x.q, x.choices, x.answer, x.explain
from jsonb_to_recordset('[{"id":"sem-001","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A regional team finds that family buyers cut back sharply when prices rise, while corporate buyers buy suites almost regardless of price. Which pricing approach best fits these findings?","choices":["Charge different prices to each segment, such as family discounts alongside premium-priced corporate suite packages","Set one uniform price for all buyers so the pricing structure stays simple","Raise every price to the level corporate buyers are willing to pay","Price every seat at the arena average cost per seat to cover costs"],"answer":0,"explain":"Segmented (differential) pricing matches price to each segment''s different sensitivity to price. The trap is assuming one price keeps things simpler at the cost of the segments."},{"id":"sem-002","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A team pays $12 to produce a cap that it sells for $30. What is the markup on cost?","choices":["60%","150%","250%","40%"],"answer":1,"explain":"Markup on cost is ($30 - $12) / $12 = 150%. The 60% figure is the margin on the selling price, a different measure."},{"id":"sem-003","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":1,"q":"A league groups its fans by how often they attend games, such as heavy, moderate and light users. Which type of market segmentation is this?","choices":["Geographic segmentation","Demographic segmentation","Psychographic segmentation","Behavioral segmentation"],"answer":3,"explain":"Grouping buyers by how they act (attendance or purchase behavior) is behavioral segmentation. Psychographic segmentation uses lifestyle and values."},{"id":"sem-004","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A marketing team reviews fan surveys and attendance trends to guide next season''s plans. Which marketing function is the team performing?","choices":["Financing","Risk taking","Gathering market information","Standardization and grading"],"answer":2,"explain":"Collecting and analyzing market information is one of the traditional marketing functions and supports every planning decision."},{"id":"sem-005","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":1,"q":"A stadium''s mobile app has stopped growing. Sales have leveled off and several competing apps now offer similar features. In which stage of the product life cycle is the app most likely?","choices":["Introduction","Growth","Maturity","Decline"],"answer":2,"explain":"Plateauing sales with intense competition describes maturity. Decline would require falling sales, which the scenario does not state."},{"id":"sem-006","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A team''s fans choose ticket packages largely based on advice from friends and online reviews. Which factor best explains this buyer behavior?","choices":["Price elasticity of supply","The product life cycle stage","A shortage of available seats","Social influence from reference groups"],"answer":3,"explain":"Buyer behavior is shaped by reference groups and word of mouth. The scenario describes influence from others, not supply constraints."},{"id":"sem-007","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A club adds its logo to a new sports drink, a product outside its original category. Which branding strategy is this?","choices":["Multibranding","Private labeling","Brand extension","Co-branding with a rival league"],"answer":2,"explain":"Using an established brand name on a new product category is a brand extension. Co-branding combines two brands on one product."},{"id":"sem-008","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":3,"q":"An arena sells season tickets for $600 each and sells 2,000 seats, for $1,200,000 in revenue. It cuts the price to $500 and sells 2,600 seats. What happens to total revenue?","choices":["It rises by $100,000","It falls by $100,000","It rises by $200,000","It stays at $1,200,000"],"answer":0,"explain":"New revenue is $500 x 2,600 = $1,300,000, up $100,000. Quantity rises 30% for a 16.7% price cut, so demand is elastic and total revenue rises."},{"id":"sem-009","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":3,"q":"A sports drink brand wants to be seen as the first choice for marathon runners rather than casual fans. Which marketing activity is this?","choices":["Market segmentation by age","Penetration pricing","Positioning the brand in the target market''s mind","Test marketing in new regions"],"answer":2,"explain":"Positioning concerns the image a product holds in customers'' minds relative to competitors. Segmentation identifies the group; positioning shapes perception of the brand."},{"id":"sem-010","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":1,"q":"Which of the following belongs in a marketing plan?","choices":["A situation analysis with marketing objectives and strategies","The arena''s construction budget for new seats","The team''s player contract terms","The box office staffing schedule for one week"],"answer":0,"explain":"A marketing plan includes a situation analysis, objectives, strategies and tactics. The distractors are operational or financial items outside the plan."},{"id":"sem-011","sub":"Sports and Entertainment Marketing/Strategic Marketing","diff":2,"q":"A team sets its ticket price slightly below competitors'' prices to attract new fans quickly and win share, planning to raise prices later. Which pricing strategy is this?","choices":["Price skimming","Prestige pricing","Penetration pricing","Bundle pricing"],"answer":2,"explain":"Penetration pricing sets a low entry price to gain share quickly. Skimming does the opposite, starting high and lowering over time."},{"id":"sem-012","sub":"Facility and Event Management","diff":1,"q":"A city is choosing a site for a 15,000-seat arena. Which factor is a core site-selection criterion?","choices":["Access by highway and public transit, with enough parking for peak event days","The number of employees the team plans to hire","The team''s current merchandise inventory","The ticket prices set for opening night"],"answer":0,"explain":"Venue selection weighs accessibility, parking and the local market. Staffing, inventory and pricing decisions come after the site is chosen."},{"id":"sem-013","sub":"Facility and Event Management","diff":3,"q":"An event has $60,000 in fixed costs. Tickets sell for $40 and the variable cost per attendee is $10. How many attendees are needed to break even?","choices":["1,500","6,000","2,500","2,000"],"answer":3,"explain":"Break-even = fixed costs / (price - variable cost per attendee) = $60,000 / $30 = 2,000. Dividing fixed costs by the price alone (1,500) ignores variable costs."},{"id":"sem-014","sub":"Facility and Event Management","diff":2,"q":"A stadium buys event cancellation insurance for a concert. Which risk-management strategy is this?","choices":["Risk avoidance","Risk retention","Risk reduction","Risk transfer"],"answer":3,"explain":"Insurance shifts the financial consequence of a loss to another party, which is risk transfer. Risk reduction lowers the chance or severity of a loss."},{"id":"sem-015","sub":"Facility and Event Management","diff":2,"q":"Staff expect the heaviest arrival rush at a stadium''s gates 30 minutes before kickoff. Which action best applies the principle of safety?","choices":["Raise gate prices to spread out arrivals","Open extra entry lanes and staff scanning points for the expected arrival peak","Close the gates until 10 minutes before kickoff","Sell more general admission tickets than the venue has room for"],"answer":1,"explain":"Planning capacity for the peak flow reduces crowd-crush risk. The other options either create or increase the crowding danger."},{"id":"sem-016","sub":"Facility and Event Management","diff":3,"q":"A festival projects $500,000 in ticket revenue and $200,000 in sponsorship revenue. Its expenses are projected at $650,000. What is the projected result?","choices":["A $150,000 deficit","A $50,000 surplus","A $50,000 deficit","An $850,000 surplus"],"answer":1,"explain":"Total revenue of $700,000 less $650,000 in expenses leaves a $50,000 surplus. Sign errors and omitting one revenue source produce the other options."},{"id":"sem-017","sub":"Facility and Event Management","diff":2,"q":"A city wants to fund a new arena without raising taxes on residents, so it issues bonds repaid from hotel and car rental taxes. What type of financing is this?","choices":["Common stock sold by the city","Unsecured personal loans to the team owner","Revenue bonds backed by dedicated tax revenue","An unrestricted federal grant for luxury suites"],"answer":2,"explain":"Revenue bonds are repaid from a specific income stream, here dedicated tourism taxes. The other options are not a recognized way for a city to finance a facility this way."},{"id":"sem-018","sub":"Facility and Event Management","diff":2,"q":"A concession stand sells a hot dog and a drink as a combo for $9, when the items cost $10 separately. Why do operators use this approach?","choices":["It removes the need to track inventory","It eliminates food cost entirely","It increases the average spend per customer","It lets the venue skip sales tax"],"answer":2,"explain":"Bundles raise average transaction size even when the bundle price is lower than the sum of the parts. The other options misstate what bundling does."},{"id":"sem-019","sub":"Facility and Event Management","diff":3,"q":"A championship weekend needs security, medical, transport and ticketing teams to coordinate across several agencies. Which management approach best organizes this work?","choices":["A single integrated operations plan with one lead responsible for communication","Separate budgets for each agency, with no shared schedule","Delaying coordination until the day of the event","Letting each vendor set its own safety procedures"],"answer":0,"explain":"Major events need one integrated plan, a clear chain of command and shared communication. Uncoordinated or late planning is the trap."},{"id":"sem-020","sub":"Facility and Event Management","diff":1,"q":"A stadium adopts a written opening-day checklist for every staff member. What is the main purpose?","choices":["To replace the need for staff training","To ensure consistent, repeatable and safe operating procedures","To reduce the venue''s insurance premium directly","To increase the number of seats sold"],"answer":1,"explain":"Standard operating procedures provide consistency and safety. The other options overstate what a checklist does."},{"id":"sem-021","sub":"Facility and Event Management","diff":1,"q":"Before a city selects venues for a new event series, which step should come first?","choices":["Sign the venue lease","Set the event''s objectives, mission and budget","Hire the ticketing vendor","Print the advertising posters"],"answer":1,"explain":"Planning starts with the development phase: defining objectives, mission and budget before choosing venues or vendors."},{"id":"sem-022","sub":"Facility and Event Management","diff":1,"q":"After a charity 5K, event staff send thank-you messages and results to every participant. Why is this follow-up important?","choices":["It is required by the sponsors'' contracts","It lowers the permit cost of the next event","It replaces the need for a post-event budget review","It builds loyalty and encourages participants to return for future events"],"answer":3,"explain":"Post-event recognition supports retention and service for future events. The other options invent legal or cost effects the scenario does not imply."},{"id":"sem-023","sub":"Human Resource Management (Labor Relations)","diff":1,"q":"A stadium needs 40 ushers for weekend games and has only 25 on its roster. Which HR function is most directly involved?","choices":["Employer relations","Compensation and benefits","Labor-law compliance audits","Planning and staffing"],"answer":3,"explain":"Forecasting staffing needs and recruiting to fill them is the planning and staffing function of human resources."},{"id":"sem-024","sub":"Human Resource Management (Labor Relations)","diff":1,"q":"In a professional sports organization, who negotiates a player''s contract terms on the player''s behalf?","choices":["The team''s scout","The general manager","The team''s owner","The player''s agent"],"answer":3,"explain":"Agents represent players in contract negotiations. Scouts evaluate talent, general managers make roster decisions, and owners hold the franchise."},{"id":"sem-025","sub":"Human Resource Management (Labor Relations)","diff":2,"q":"A venue manager approves refunds and also reconciles the cash drawers that the same person handles. Which HR principle is being violated?","choices":["Job orientation","Separation of duties","Benchmarking","Continuous professional development"],"answer":1,"explain":"Separating authorization from custody and recordkeeping prevents fraud and error. Orientation and development are unrelated to this control."},{"id":"sem-026","sub":"Human Resource Management (Labor Relations)","diff":3,"q":"Under the National Labor Relations Act, which action by an employer during a union organizing drive would be an unfair labor practice?","choices":["Negotiating wages with a certified union","Firing employees for joining the union","Publishing the company''s benefit summary","Hiring seasonal workers for peak weekends"],"answer":1,"explain":"The NLRA protects employees'' right to organize, so firing them for union activity is an unfair labor practice. Lawful negotiation and normal hiring are not."},{"id":"sem-027","sub":"Human Resource Management (Labor Relations)","diff":2,"q":"A team''s HR manager compares its staff turnover and hiring costs with three top franchises to set goals. What technique is this?","choices":["Scenario building","Separation of duties","Benchmarking","Collective bargaining"],"answer":2,"explain":"Benchmarking measures performance against leading peers. Scenario building explores possible futures rather than current comparisons."},{"id":"sem-028","sub":"Human Resource Management (Labor Relations)","diff":3,"q":"A stadium''s seasonal event staff quit after each season. Which strategy best improves retention?","choices":["Post job openings only on the final day of the season","Offer training pathways and a return-season bonus","Cut hours to the legal minimum","Remove all supervisory roles"],"answer":1,"explain":"Retention improves when workers see a path forward and a reason to return. The distractors increase turnover or ignore the retention problem."},{"id":"sem-029","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":1,"q":"A team gives the first 5,000 fans a free bobblehead at the gate. Which element of the promotion mix is this?","choices":["Publicity","Sales promotion","Personal selling","Advertising"],"answer":1,"explain":"Short-term incentives such as giveaways are sales promotions. Publicity is unpaid media coverage."},{"id":"sem-030","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":1,"q":"An athlete is paid a fee to appear in a television ad for a sports drink. What is this arrangement called?","choices":["Endorsement","Sponsorship","Product placement","Licensing"],"answer":0,"explain":"An endorsement pays a person to promote a product. Sponsorship supports an event or team, and product placement shows a brand within content."},{"id":"sem-031","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":2,"q":"A company pays for the naming rights to a stadium. What is the main benefit to the sponsor?","choices":["Free tickets for its executives every season","Exemption from local advertising taxes","Control over the league''s rulebook","Brand exposure to the event''s audience and association with the team''s image"],"answer":3,"explain":"Sponsors buy visibility and image transfer. The other options are not standard benefits of naming rights."},{"id":"sem-032","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":1,"q":"A new arena opening receives a front-page story in the local paper at no cost. What promotional tool produced this coverage?","choices":["Advertising","Personal selling","Sales promotion","Publicity"],"answer":3,"explain":"Publicity is unpaid media coverage. Advertising is paid placement, so this coverage is not advertising even though it helps the brand."},{"id":"sem-033","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":3,"q":"Which sequence correctly lists the steps in developing an effective advertising campaign?","choices":["Choose media, create the message, then set objectives","Evaluate results, set the budget, then choose a target audience","Create the message, evaluate results, then set the budget","Set objectives and target audience, set the budget, create the message and choose media, then evaluate results"],"answer":3,"explain":"Campaigns start with objectives and audience, then budget, message and media, and finally evaluation. Starting with media or evaluation is out of order."},{"id":"sem-034","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":1,"q":"A film shows a team''s branded sports drink on the table during a scene, for a fee paid to the filmmaker. What is this practice called?","choices":["Product placement","Endorsement","Sponsorship","Publicity"],"answer":0,"explain":"Product placement inserts a brand into entertainment content. An endorsement features a person speaking for the product."},{"id":"sem-035","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":3,"q":"A minor league club holds a Halloween-themed game each October, with sponsor logos on the giveaways. What is the main promotional value of seasonal themed events?","choices":["They guarantee higher ticket prices all season","They create repeat attendance and give sponsors a fresh reason to feature their brands","They eliminate the need for regular advertising","They lower the club''s fixed costs"],"answer":1,"explain":"Themed events drive repeat visits and sponsor visibility. The other options overstate what a single theme can do."},{"id":"sem-036","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":3,"q":"A sponsor pays $250,000 for a season of signage and wants to compare it with other media. Which measure best evaluates the value of this spend?","choices":["Total cost divided by the number of team logos","Cost per thousand impressions compared with alternative media","Ticket revenue earned from the sponsor''s guests","The sponsor''s share price on opening day"],"answer":1,"explain":"CPM (cost per thousand impressions) allows a like-for-like comparison of media costs. The others are not standard media evaluation measures."},{"id":"sem-037","sub":"Promotion, Advertising, and Sponsorship for Sports and Entertainment Industry","diff":1,"q":"A team pays its players salaries to compete in a league, and fans buy tickets to watch. Which category of sports does this describe?","choices":["Professional sports","Collegiate athletics","Amateur sports","Sports camps"],"answer":0,"explain":"Players paid salaries in a commercial league are professionals. Collegiate and amateur sports do not pay players this way, and camps are instructional."},{"id":"sem-038","sub":"Financing and Economic Input","diff":1,"q":"A championship final sells out while the number of seats stays fixed and demand grows. What happens to the market price of tickets?","choices":["It falls","It rises","It stays the same","It falls to zero"],"answer":1,"explain":"With supply fixed, higher demand pushes prices up. Rising demand does not drive prices to zero."},{"id":"sem-039","sub":"Financing and Economic Input","diff":2,"q":"A community sports league is organized as a 501(c)(3) nonprofit. Which advantage does this status give?","choices":["Freedom from all state regulation","The right to distribute profits to members","Exemption from federal income tax and eligibility for tax-deductible donations","Automatic access to broadcast rights"],"answer":2,"explain":"Section 501(c)(3) status exempts qualifying organizations from federal income tax and lets donors deduct gifts. It does not remove state oversight or allow profit distribution."},{"id":"sem-040","sub":"Financing and Economic Input","diff":1,"q":"An arena sells naming rights to a corporation for $2 million a year. How should this be classified for the arena?","choices":["An operating expense","A revenue source","A capital asset","A liability"],"answer":1,"explain":"Cash the arena receives for granting rights is revenue. It is not an expense, asset or liability of the arena."},{"id":"sem-041","sub":"Financing and Economic Input","diff":2,"q":"A venue reports revenue of $800,000, cost of goods sold of $300,000 and operating expenses of $350,000. What is operating income?","choices":["$450,000","$200,000","$150,000","$500,000"],"answer":2,"explain":"Operating income = $800,000 - $300,000 - $350,000 = $150,000. The $450,000 option leaves out cost of goods sold."},{"id":"sem-042","sub":"Financing and Economic Input","diff":2,"q":"A team reports total assets of $10 million and total liabilities of $6 million. What is owner''s equity?","choices":["$16 million","$6 million","$4 million","$10 million"],"answer":2,"explain":"Assets = liabilities + owner''s equity, so equity = $10M - $6M = $4M."},{"id":"sem-043","sub":"Financing and Economic Input","diff":2,"q":"Which budgeting technique requires every expense to be justified from zero each budget cycle, rather than adjusted from last year''s amounts?","choices":["Incremental budgeting","Flexible budgeting","Static budgeting","Zero-based budgeting"],"answer":3,"explain":"Zero-based budgeting rebuilds each budget from scratch. Incremental budgeting starts from the prior year and adjusts it."},{"id":"sem-044","sub":"Financing and Economic Input","diff":3,"q":"A city''s report claims a tournament generated $40 million in economic impact. It counts all spending, including money local residents would have spent in town anyway. What is the main flaw?","choices":["It ignores the multiplier effect of spending","It uses too few years of data","It does not net out substitution effects, where the spending would have happened locally anyway","It counts only ticket revenue and not sponsorships"],"answer":2,"explain":"Credible impact studies subtract spending that merely shifts from other local activities. The multiplier is a legitimate part of the analysis, so ignoring it is not the flaw."},{"id":"sem-045","sub":"Financing and Economic Input","diff":1,"q":"A facility''s annual lease payment is the same whether or not any events are held. How should this cost be classified?","choices":["Fixed cost","Variable cost","Contra-revenue","Owner''s equity"],"answer":0,"explain":"A cost that does not change with activity in the short run is fixed. Variable costs rise with event volume."},{"id":"sem-046","sub":"Financing and Economic Input","diff":3,"q":"A rural minor league team earns most of its revenue in summer. Why should its owner forecast cash flow monthly rather than only annually?","choices":["Off-season months can produce cash shortfalls even when the full year is profitable","Monthly forecasts are required by the U.S. tax code","Summer revenue is recorded as a liability until the season ends","Monthly forecasts replace the need for a balance sheet"],"answer":0,"explain":"Profit is measured over the year, but cash must cover bills in the months with little income. The other options misstate accounting or tax rules."},{"id":"sem-047","sub":"Financing and Economic Input","diff":3,"q":"Which term describes the process in which an initial spending increase generates further rounds of spending in the local economy?","choices":["Substitution effect","Opportunity cost","Multiplier effect","Price elasticity"],"answer":2,"explain":"The multiplier effect explains how each round of spending creates income that is spent again. Substitution is the opposite concern in impact studies."},{"id":"sem-048","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":2,"q":"What is the main difference between a ticket broker and a ticket scalper?","choices":["A broker sells only at face value, while a scalper sells above face value","A scalper is licensed by the venue, while a broker is not","A broker works only with season-ticket holders, while a scalper works with the public","A broker is a licensed reseller that follows venue and local rules, while a scalper resells tickets illegally or in violation of local law"],"answer":3,"explain":"Licensed brokers operate legally within the rules. Scalpers operate outside them. Reversing the licensing or pricing roles is the trap."},{"id":"sem-049","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":3,"q":"A venue raises ticket prices closer to game day as seats sell out and demand grows. Which pricing approach is this?","choices":["Cost-plus pricing","Price skimming","Dynamic (demand-based) pricing","Price ceiling"],"answer":2,"explain":"Dynamic pricing adjusts price to real-time demand. Cost-plus pricing sets price from cost, and a price ceiling is a government limit."},{"id":"sem-050","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":2,"q":"A venue sets its premium seats at a very high launch price for early buyers, then lowers the price over time as more buyers enter. Which strategy is this?","choices":["Penetration pricing","Bundle pricing","Price skimming","Prestige pricing"],"answer":2,"explain":"Skimming captures buyers willing to pay the most first, then lowers prices to reach price-sensitive buyers. Penetration does the reverse."},{"id":"sem-051","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":3,"q":"Before setting a price for a new event package, which step should a planner take first?","choices":["Print the price on all advertising","Define pricing objectives and estimate costs and likely demand","Match the rival venue''s price exactly","Set the price after the event is held"],"answer":1,"explain":"Pricing starts with objectives, cost and demand estimates. Copying a competitor or pricing after the fact skips the analysis."},{"id":"sem-052","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":3,"q":"In the sales process, which step comes directly before the presentation?","choices":["The approach, the first contact with the prospect","Closing the sale","Post-sale follow-up","Handling objections after the presentation"],"answer":0,"explain":"The sequence runs prospecting, preapproach, approach, presentation, then objections and close. The approach precedes the presentation."},{"id":"sem-053","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":1,"q":"A corporate client buys 20 suites to thank clients and motivate its employees. What is this use of sports and entertainment called?","choices":["Public domain licensing","Ticket brokering","Cause marketing","Corporate hospitality"],"answer":3,"explain":"Corporate hospitality uses events to entertain clients and reward staff. The other options are different business practices."},{"id":"sem-054","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":2,"q":"A city imposes a legal maximum on the price of parking near a stadium on game days. What type of government influence on pricing is this?","choices":["A price ceiling","A price floor","A subsidy paid to the venue","A sales tax paid by the venue"],"answer":0,"explain":"A legal maximum price is a price ceiling. A price floor sets a minimum, and a subsidy or tax does not set the price directly."},{"id":"sem-055","sub":"Planning, Distribution, Marketing, Pricing, and Selling Sports and Entertainment Events","diff":3,"q":"During a recession, which entertainment spending is typically most at risk of decline?","choices":["Premium luxury suite and VIP package purchases","Local youth league registrations","Basic outdoor park admission","Community parade attendance"],"answer":0,"explain":"Discretionary, high-priced spending falls first in a downturn, while low-cost and community activities hold up better."},{"id":"sem-056","sub":"Sports Law","diff":1,"q":"Which U.S. federal law requires public accommodations, including stadiums and arenas, to provide accessible seating for people with disabilities?","choices":["Title IX of the Education Amendments of 1972","The Sherman Antitrust Act","The Americans with Disabilities Act (ADA)","The Copyright Act of 1976"],"answer":2,"explain":"Title III of the ADA covers places of public accommodation, including sports and entertainment venues."},{"id":"sem-057","sub":"Sports Law","diff":2,"q":"Title IX of the Education Amendments of 1972 primarily prohibits what?","choices":["Racial segregation in public venues","Sex-based discrimination in federally funded education programs, including athletics","Employment discrimination based on age","Unfair labor practices by unions"],"answer":1,"explain":"Title IX bans sex discrimination in federally funded education programs, including school and college athletics."},{"id":"sem-058","sub":"Sports Law","diff":3,"q":"A promoter uses a copyrighted song in a video ad without permission. Which exclusive right of the copyright owner is most directly infringed?","choices":["The right to set the song''s ticket price","The right to reproduce and publicly perform the work","The right to collect the venue''s concession revenue","The right to name the promoter''s company"],"answer":1,"explain":"Copyright gives the owner exclusive rights to reproduce, distribute and publicly perform the work. The distractors are not copyright rights."},{"id":"sem-059","sub":"Sports Law","diff":1,"q":"Under U.S. common law, which three elements are generally required for a valid contract?","choices":["Offer, signature and notarization","Acceptance, witnesses and a seal","Offer, acceptance and consideration","Consideration, a written copy and a fee"],"answer":2,"explain":"A valid contract generally needs an offer, acceptance and consideration (something of value exchanged). Notarization and seals are not general requirements."},{"id":"sem-060","sub":"Sports Law","diff":3,"q":"A league rule forbids its teams from negotiating with outside broadcasters, which reduces competition and raises prices. Which body of law is primarily at issue?","choices":["Antitrust law, including the Sherman Act","Labor law under the NLRA only","Copyright law","Title IX"],"answer":0,"explain":"Restraints that reduce competition among firms raise antitrust concerns under the Sherman Act. Labor law and copyright do not address this market restraint."},{"id":"sem-061","sub":"Sports Law","diff":1,"q":"A union''s members collectively refuse to work to pressure an employer. What is this action called?","choices":["A strike","A lockout","An arbitration","A grievance"],"answer":0,"explain":"A strike is a collective work stoppage by employees. A lockout is initiated by the employer, and arbitration and grievances are dispute procedures."},{"id":"sem-062","sub":"Communication in Sports and Entertainment (Media)","diff":1,"q":"Which statement best describes publicity?","choices":["Paid placement of a message in media","Unpaid media coverage of an organization or event","A sales incentive offered to customers","A contract to use a person''s image"],"answer":1,"explain":"Publicity is earned, unpaid media coverage. Paid placement is advertising."},{"id":"sem-063","sub":"Communication in Sports and Entertainment (Media)","diff":2,"q":"A team hires a popular athlete to front its campaign. What is the main benefit the brand gains from this celebrity endorsement?","choices":["Exemption from advertising regulation","Guaranteed ticket sales for each game","Lower production costs for the broadcast","Transfer of the celebrity''s credibility and appeal to the brand"],"answer":3,"explain":"Endorsements work by transferring a celebrity''s credibility and appeal to the brand. The other options are not benefits of endorsement."},{"id":"sem-064","sub":"Communication in Sports and Entertainment (Media)","diff":3,"q":"A star player is arrested for a DUI on the night before a playoff game. What is the best first communication step for the team?","choices":["Say nothing until the court case is resolved","Blame the media for the coverage","Post highlight videos to change the focus","Issue a timely, honest statement that acknowledges the facts and describes next steps"],"answer":3,"explain":"Crisis communication works best when the organization is prompt, honest and clear about next steps. Silence or deflection erodes trust."},{"id":"sem-065","sub":"Communication in Sports and Entertainment (Media)","diff":1,"q":"Which media channel gives a team the most direct control over its message?","choices":["Its own website and social media accounts","Local television news coverage","A newspaper sports column","Fan blogs run by outside writers"],"answer":0,"explain":"Owned channels let the organization decide content and timing. Earned media is controlled by journalists and writers."},{"id":"sem-066","sub":"Ethics","diff":2,"q":"A team employee bets on the team''s games. Which ethical concern is most directly raised?","choices":["Conflict of interest and threat to the integrity of competition","Excessive advertising spending","Failure to pay the employee overtime","Poor seating arrangements for fans"],"answer":0,"explain":"An insider betting on outcomes creates a conflict of interest and threatens the integrity of the competition. The other concerns are real but not the central ethical issue."},{"id":"sem-067","sub":"Ethics","diff":1,"q":"An arena donates part of its concession profits to a youth sports program. Which concept does this best illustrate?","choices":["Price discrimination","Vertical integration","Market segmentation","Corporate social responsibility"],"answer":3,"explain":"Voluntary action that benefits society beyond legal requirements is corporate social responsibility."},{"id":"sem-068","sub":"Ethics","diff":2,"q":"A venue''s advertising shows premium seats with unobstructed views, but many of those seats have pillars that block the view. What is the likely consequence of this behavior?","choices":["A permanent increase in ticket sales","Automatic exemption from local regulation","Lower operating costs","Loss of customer trust and possible legal liability for misleading advertising"],"answer":3,"explain":"Misleading advertising damages trust and can create legal exposure. The other options describe benefits that unethical behavior does not produce."},{"id":"sem-069","sub":"Licensing","diff":1,"q":"A team''s licensee pays the team 8% of the wholesale price of each licensed jersey it sells. What is this payment called?","choices":["A royalty","A dividend","A franchise fee","A commission on tickets"],"answer":0,"explain":"A royalty is a payment, usually a percentage of sales, for the right to use intellectual property."},{"id":"sem-070","sub":"Licensing","diff":2,"q":"A video game publisher pays a team a fee to use its logos and team names in a game. What arrangement is this?","choices":["A sponsorship of the publisher''s events","A product licensing agreement","An endorsement contract for the team''s coach","A joint venture to build a stadium"],"answer":1,"explain":"Granting permission to use logos and names for a fee is a licensing agreement. The other arrangements involve different rights or purposes."},{"id":"sem-071","sub":"Licensing","diff":3,"q":"A team earns $1,200,000 in royalties at an 8% royalty rate. What were the licensed sales?","choices":["$9,600,000","$96,000,000","$15,000,000","$150,000,000"],"answer":2,"explain":"Licensed sales = royalties / rate = $1,200,000 / 0.08 = $15,000,000."},{"id":"sem-072","sub":"Sports Governance","diff":1,"q":"Which body governs member four-year colleges and universities in Divisions I, II and III of U.S. collegiate athletics?","choices":["The NFL","The NBA","The NCAA","The PGA Tour"],"answer":2,"explain":"The NCAA sets rules for its member colleges and universities across its three divisions. The others govern professional leagues or tours."},{"id":"sem-073","sub":"Sports Governance","diff":2,"q":"A two-year community college wants its teams to compete under a national governing body for junior colleges. Which organization should it join?","choices":["The NAIA","The NFHS","The NJCAA","USA Hockey"],"answer":2,"explain":"The NJCAA governs athletics for U.S. two-year colleges. The NAIA serves small four-year institutions."},{"id":"sem-074","sub":"Sports Governance","diff":1,"q":"Which role enforces a professional league''s rules and resolves disputes among its member teams?","choices":["The team''s general manager","The players'' union president","The league commissioner","The head of a team''s ticketing department"],"answer":2,"explain":"The commissioner is the league''s chief executive, responsible for enforcing rules and settling disputes among teams."},{"id":"sem-075","sub":"Sports Governance","diff":2,"q":"A league limits its official beverage sponsorship to one company per category. What is the main benefit of this exclusivity?","choices":["It removes the need for any sponsorship revenue","It lets the league avoid all antitrust review","It lets each team set sponsorship prices alone","It protects the sponsor''s investment by keeping competitors from diluting the brand"],"answer":3,"explain":"Category exclusivity protects what the sponsor pays for. The other options misstate what the rule does."},{"id":"sem-076","sub":"Careers","diff":1,"q":"Which item belongs in a career portfolio for a sports management applicant?","choices":["A list of personal social media passwords","A full personal medical history","A résumé with work samples and a cover letter","A copy of a current employer''s confidential budget"],"answer":2,"explain":"A career portfolio presents qualifications: résumé, cover letter and work samples. The other items are private or confidential."},{"id":"sem-077","sub":"Careers","diff":1,"q":"A recent graduate wants to enter the sports and entertainment industry. Which entry-level position is most typical?","choices":["Chief executive of a professional league","Ticket operations or event assistant","General manager of a professional franchise","Owner of a major arena"],"answer":1,"explain":"Entry-level roles in event and ticket operations build experience. The other positions require years of experience."},{"id":"sem-078","sub":"Careers","diff":2,"q":"A candidate lacks industry experience for a sports marketing job. Which strategy best overcomes this barrier?","choices":["Apply only to positions that require no experience","Omit the education section of the résumé","Complete a volunteer role or internship that builds relevant event experience","Wait until the posting closes before applying"],"answer":2,"explain":"Relevant volunteer work and internships address the experience gap directly. The other options avoid the problem."},{"id":"sem-079","sub":"Marketing/Management Information Technology and Research","diff":1,"q":"A stadium uses one system that links ticketing, concession sales and attendance. What is the main purpose of this management information system?","choices":["To replace all human staff","To set the official league schedule","To sell advertising directly to fans","To give managers timely information to support decisions"],"answer":3,"explain":"An MIS collects and organizes data so managers can make timely, informed decisions."},{"id":"sem-080","sub":"Marketing/Management Information Technology and Research","diff":2,"q":"A team wants every fan in its database to have an equal chance of being surveyed. Which sampling method does this?","choices":["Simple random sampling","Quota sampling","Convenience sampling","Judgment sampling"],"answer":0,"explain":"Simple random sampling gives every member of the population an equal chance of selection. The other methods do not."},{"id":"sem-081","sub":"Marketing/Management Information Technology and Research","diff":2,"q":"Offering a 10% discount this Tuesday to boost weekday attendance is an example of what?","choices":["A corporate strategy","A marketing tactic supporting a broader strategy","A mission statement","A permanent pricing policy"],"answer":1,"explain":"Tactics are short-term actions that support a strategy. A one-day discount is not a permanent policy."},{"id":"sem-082","sub":"Marketing/Management Information Technology and Research","diff":3,"q":"A club wants to test whether a new pregame promotion raises attendance. Which research design is best?","choices":["A controlled experiment comparing games with and without the promotion","A focus group after the season ends","A review of last season''s ticket sales","A single survey of season-ticket holders"],"answer":0,"explain":"A controlled comparison isolates the promotion''s effect. The other designs cannot show cause and effect."},{"id":"sem-083","sub":"Marketing/Management Information Technology and Research","diff":1,"q":"Which is an electronic method of collecting fan data?","choices":["An online survey or app-based poll","A paper questionnaire mailed to fans","A phone call from the ticket office","A handwritten suggestion box"],"answer":0,"explain":"Online surveys and app polls collect data electronically. The other methods are paper-based or personal."},{"id":"sem-084","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":1,"q":"A manager makes decisions alone and gives staff little input. Which leadership style is this?","choices":["Autocratic","Democratic","Open (laissez-faire)","Situational"],"answer":0,"explain":"The autocratic style centralizes decisions with the leader. The democratic style invites staff input."},{"id":"sem-085","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":3,"q":"A new event coordinator needs close direction, while a veteran needs only occasional check-ins. Which leadership approach fits this?","choices":["Situational leadership","Autocratic leadership for both","Open leadership for both","Democratic voting on every task"],"answer":0,"explain":"Situational leadership adjusts the leader''s style to each follower''s readiness. Using one style for both ignores the difference."},{"id":"sem-086","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":2,"q":"In Herzberg''s motivation theory, which factor is a motivator rather than a hygiene factor?","choices":["Salary paid on time","A safe working environment","Company work policies","Recognition for achievement"],"answer":3,"explain":"Motivators such as recognition and achievement increase satisfaction. Hygiene factors such as pay, safety and policies prevent dissatisfaction."},{"id":"sem-087","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":1,"q":"A team is formed from marketing, ticketing and operations staff to plan a championship parade. What type of team is this?","choices":["A virtual team","A standing departmental team","A self-managed production team","A cross-functional team"],"answer":3,"explain":"Members drawn from several functions form a cross-functional team. A virtual team is defined by remote collaboration, which the scenario does not describe."},{"id":"sem-088","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":3,"q":"A group has unclear goals, and its members avoid disagreement to keep the peace. Which is the most likely reason the team will fail?","choices":["Too much diversity of thought","Unclear goals and roles, combined with suppressed conflict","Too many written procedures","Excessive recognition of member achievements"],"answer":1,"explain":"Teams fail when goals and roles are unclear and healthy conflict is avoided. The distractors are not typical causes of failure."},{"id":"sem-089","sub":"Leadership and Managing Groups and Teams in the Sports and Entertainment Industry","diff":2,"q":"What is a key disadvantage of group decision making?","choices":["Groups are unable to reach any decision","Groups cannot share information","Groups cannot consider alternatives","Groupthink can suppress dissent and lead to poor choices"],"answer":3,"explain":"Groupthink, the suppression of dissent in the pursuit of harmony, is a major risk of group decisions. The other options are not typical disadvantages."},{"id":"sem-090","sub":"Management Strategies and Strategic Planning Tools","diff":1,"q":"A league decides to expand into two new countries. Which level of strategy does this decision represent?","choices":["Corporate strategy","Business strategy","Functional strategy","Tactical strategy"],"answer":0,"explain":"Corporate strategy defines the overall scope of the enterprise, including which markets it enters. Business-level strategy concerns competing within one unit."},{"id":"sem-091","sub":"Management Strategies and Strategic Planning Tools","diff":1,"q":"In a SWOT analysis of an arena, a new competitor arena opening nearby is classified as what?","choices":["A strength","A threat","A weakness","An opportunity"],"answer":1,"explain":"An external factor that could hurt the arena is a threat. Strengths and weaknesses are internal."},{"id":"sem-092","sub":"Management Strategies and Strategic Planning Tools","diff":2,"q":"Which sequence correctly describes the strategic management process?","choices":["Implement first, then formulate, then evaluate","Formulate the strategy, implement it, then evaluate and control","Evaluate, implement, then formulate","Formulate, evaluate, then implement"],"answer":1,"explain":"The strategic management process runs formulation, implementation, then evaluation and control. Implementing before formulating reverses the logic."},{"id":"sem-093","sub":"Management Strategies and Strategic Planning Tools","diff":3,"q":"A premium arena adds budget family concession packages that conflict with its luxury image. What does this illustrate?","choices":["Strong functional strategy alignment","A lack of strategic fit between the new offering and the venue''s positioning","A successful blue ocean strategy","A reduction in fixed costs"],"answer":1,"explain":"Strategic fit means new offerings support the organization''s positioning. A conflicting offering weakens the brand even if it adds sales."},{"id":"sem-094","sub":"Management Strategies and Strategic Planning Tools","diff":2,"q":"Which strategic planning tool plots business units by market growth rate and relative market share?","choices":["The break-even chart","The balance sheet","The organizational chart","The BCG growth-share matrix"],"answer":3,"explain":"The BCG matrix classifies units as stars, cash cows, question marks or dogs using growth and share. The other tools serve different purposes."},{"id":"sem-095","sub":"Basic Functions of Management","diff":1,"q":"Which set lists the four basic functions of management?","choices":["Marketing, financing, producing and selling","Hiring, training, paying and firing","Forecasting, budgeting, advertising and reporting","Planning, organizing, leading and controlling"],"answer":3,"explain":"The four functions of management are planning, organizing, leading (directing) and controlling."},{"id":"sem-096","sub":"Basic Functions of Management","diff":3,"q":"A stadium sets a target of 95% on-time gate openings, tracks results, and adjusts staffing when the target is missed. Which control step is the staffing adjustment?","choices":["Establishing standards","Monitoring results","Taking corrective action","Setting the mission"],"answer":2,"explain":"Control runs establish standards, monitor results and compare them, then correct deviations. Adjusting staffing is the correction step."},{"id":"sem-097","sub":"Basic Functions of Management","diff":1,"q":"In the decision-making process, which step comes first?","choices":["Identify and define the problem","Choose the best alternative","Implement the decision","Evaluate the results"],"answer":0,"explain":"Good decisions start by defining the problem. Choosing, implementing and evaluating come later in the process."},{"id":"sem-098","sub":"Basic Functions of Management","diff":2,"q":"A manager delegates the event budget to an assistant but keeps final approval authority. What does the manager retain after delegating?","choices":["No responsibility, since the task was delegated","Only the right to change the assistant''s title","Ultimate accountability for the outcome","Full personal liability for every expense line"],"answer":2,"explain":"Authority can be delegated, but the manager stays accountable for results. Delegation does not remove responsibility."},{"id":"sem-099","sub":"Basic Functions of Management","diff":3,"q":"Which description best defines economic efficiency for an entertainment event?","choices":["Maximizing the number of free tickets given away","Spending the full budget each year","Charging the highest price the market will bear","Producing the event''s output at the lowest possible cost"],"answer":3,"explain":"Economic efficiency means getting the most output from given resources, which is achieved at the lowest cost for that output."},{"id":"sem-100","sub":"Basic Functions of Management","diff":2,"q":"A venue group uses a divisional structure with separate arena, hotel and concessions units. What is the main advantage?","choices":["Each unit avoids all reporting requirements","Each unit can focus on its market and be held accountable for its results","The group no longer needs a chief executive","All units share one budget line"],"answer":1,"explain":"Divisional structures let each unit focus on its market and be measured on its own results. The other options describe drawbacks or misreadings."}]'::jsonb)
  as x(id text, sub text, diff smallint, q text, choices jsonb, answer smallint, explain text)
on conflict (id) do update set event = excluded.event, sub = excluded.sub, diff = excluded.diff,
  q = excluded.q, choices = excluded.choices, answer = excluded.answer, explain = excluded.explain;

